; [MS 245] ==== SOME EXPLANATION. ====
; [MS 246]
; [MS 247]
; [MS 248] M6502 BASIC CONFIGURES BASIC AS FOLLOWS
; [MS 249]
; [MS 250] LOW LOCATIONS
; [MS 251] PAGE	ZERO
; [MS 252]
; [MS 253] STARTUP:
; [MS 254] INITIALLY A JMP TO INITIALIZATION CODE BUT
; [MS 255] CHANGED TO A JMP TO "READY".
; [MS 256] RESTARTING THE MACHINE AT LOC 0 DURING PROGRAM
; [MS 257] EXECUTION CAN LEAVE THINGS MESSED UP.
; [MS 258]
; [MS 259] LOC OF FAC TO INTEGER AND INTEGER TO FAC
; [MS 260] ROUTINES.
; [MS 261]
; [MS 262] "DIRECT" MEMORY:
; [MS 263] THESE ARE THE MOST COMMONLY USED LOCATIONS.
; [MS 264] THEY HOLD BOOKKEEPING INFO AND ALL OTHER
; [MS 265] FREQUENTLY USED INFORMATION.
; [MS 266] ALL TEMPORARIES, FLAGS, POINTERS, THE BUFFER AREA,
; [MS 267] THE FLOATING ACCUMULATOR, AND ANYTHING ELSE THAT
; [MS 268] IS USED TO STORE A CHANGING VALUE SHOULD BE LOCATED
; [MS 269] IN THIS AREA. CARE MUST BE MADE IN MOVING LOCATIONS
; [MS 270] IN THIS AREA SINCE THE JUXTAPOSITION OF TWO LOCATIONS
; [MS 271] IS OFTEN DEPENDED UPON.
; [MS 272]
; [MS 273] STILL IN RAM WE HAVE THE BEGINNING OF THE "CHRGET"
; [MS 274] SUBROUTINE. IT IS HERE SO [TXTPTR] CAN BE THE
; [MS 275] EXTENDED ADDRESS OF A LOAD INSTRUCTION.
; [MS 276] THIS SAVES HAVING TO BOTHER ANY REGISTERS.
; [MS 277]
; [MS 278] PAGE	ONE
; [MS 279] THE STACK.
; [MS 280]
; [MS 281] STORAGE PAGE TWO AND ON
; [MS 282] IN RAM VERSIONS THESE DATA STRUCTURES COME AT THE
; [MS 283] END OF BASIC. IN ROM VERSON THEY ARE AT RAMLOC WHICH
; [MS 284] CAN EITHER BE ABOVE OR BELOW ROMLOC, WHICH IS WHERE
; [MS 285] BASIC ITSELF RESIDES.
; [MS 286]
; [MS 287] A ZERO.
; [MS 288] [TXTTAB]	POINTER TO NEXT LINE'S POINTER.
; [MS 289] LINE # OF THIS LINE (2 BYTES).
; [MS 290] CHARACTERS ON THIS LINE.
; [MS 291] ZERO.
; [MS 292] POINTER AT NEXT LINE'S POINTER
; [MS 293] (POINTED TO BY THE ABOVE POINTER).
; [MS 294] ... REPEATS ...
; [MS 295] LAST LINE:	POINTER AT ZERO POINTER.
; [MS 296] LINE # OF THIS LINE.
; [MS 297] CHARACTERS ON THIS LINE.
; [MS 298] ZERO.
; [MS 299] DOUBLE ZERO (POINTED TO BY THE ABOVE POINTER).
; [MS 300] [VARTAB]	SIMPLE VARIABLES. 6 BYTES PER VALUE.
; [MS 301] 2 BYTES GIVE THE NAME, 4 BYTES THE VALUE.
; [MS 302] ... REPEATS ...
; [MS 303] [ARYTAB]	ARRAY VARIABLES. 2 BYTES NAME, 2 BYTE
; [MS 304] LENGTH, NUMBER OF DIMENSIONS , EXTENT OF
; [MS 305] EACH DIMENSION (2BYTES/), VALUES
; [MS 306] ... REPEATS ...
; [MS 307] [STREND]	FREE SPACE.
; [MS 308] ... REPEATS ...
; [MS 309] [FRETOP]	STRING SPACE IN USE.
; [MS 310] ... REPEATS ...
; [MS 311] [MEMSIZ]	HIGHEST MACHINE LOCATION.
; [MS 312] UNUSED EXCEPT BY THE VAL FUNCTION.
; [MS 313]
; [MS 314] ROM -- CONSTANTS AND CODE.
; [MS 315]
; [MS 316] FUNCTION DISPATCH ADDRESSES (AT ROMLOC)
; [MS 317] "FUNDSP" CONTAINS THE ADDRESSES OF THE
; [MS 318] FUNCTION ROUTINES IN THE ORDER OF THE
; [MS 319] FUNCTION NAMES IN THE CRUNCH LIST.
; [MS 320] THE FUNCTIONS THAT TAKE MORE THAN ONE ARGUMENT
; [MS 321] ARE AT THE END. SEE THE EXPLANATION AT "ISFUN".
; [MS 322]
; [MS 323] THE OPERATOR LIST
; [MS 324] THE "OPTAB" LIST CONTAINS AN OPERATOR'S PRECEDENCE
; [MS 325] FOLLOWED BY THE ADDRESS OF THE ROUTINE TO PERFORM
; [MS 326] THE OPERATION. THE INDEX INTO THE
; [MS 327] OPERATOR LIST IS MADE BY SUBTRACTING OFF THE CRUNCH VALUE
; [MS 328] OF THE LOWEST NUMBERED OPERATOR. THE ORDER
; [MS 329] OF OPERATORS IN THE CRUNCH LIST AND IN "OPTAB" IS IDENTICAL.
; [MS 330] THE PRECEDENCES ARE ARBITRARY EXCEPT FOR THEIR
; [MS 331] COMPARATIVE SIZES. NOTE THAT THE PRECEDENCE FOR
; [MS 332] UNARY OPERATORS SUCH AS "NOT" AND NEGATION ARE
; [MS 333] SETUP SPECIALLY WITHOUT USING THE LIST.
; [MS 334]
; [MS 335] THE RESERVED WORD OR CRUNCH LIST
; [MS 336] WHEN A COMMAND OR PROGRAM LINE IS TYPED IN
; [MS 337] IT IS STORED IN "BUF". AS SOON AS THE WHOLE LINE
; [MS 338] HAS BEEN TYPED IN ("INLIN" RETURNS) "CRUNCH" IS
; [MS 339] CALLED TO CONVERT ALL RESERVED WORDS TO THEIR
; [MS 340] CRUNCHED VALUES. THIS REDUCES THE SIZE OF THE
; [MS 341] PROGRAM AND SPEEDS UP EXECUTION BY ALLOWING
; [MS 342] LIST DISPATCHES TO PERFORM FUNCTIONS, STATEMENTS,
; [MS 343] AND OPERATIONS. THIS IS BECAUSE ALL THE STATEMENT
; [MS 344] NAMES ARE STORED CONSECUTIVELY IN THE CRUNCH LIST.
; [MS 345] WHEN A MATCH IS FOUND BETWEEN A STRING
; [MS 346] OF CHARACTERS AND A WORD IN THE CRUNCH LIST
; [MS 347] THE ENTIRE TEXT OF THE MATCHED WORD IS TAKEN OUT OF
; [MS 348] THE INPUT LINE AND A RESERVED WORD TOKEN IS PUT
; [MS 349] IN ITS PLACE. A RESERVED WORD TOKEN IS ALWAYS EQUAL
; [MS 350] TO OCTAL 200 PLUS THE POSITION OF THE MATCHED WORD
; [MS 351] IN THE CRUNCH LIST.
; [MS 352]
; [MS 353] STATEMENT DISPATCH ADDRESSES
; [MS 354] WHEN A STATEMENT IS TO BE EXECUTED, THE FIRST
; [MS 355] CHARACTER OF THE STATEMENT IS EXAMINED
; [MS 356] TO SEE IF IT IS LESS THAN THE RESERVED
; [MS 357] WORD TOKEN FOR THE LOWEST NUMBERED STATEMENT NAME.
; [MS 358] IF SO, THE "LET" CODE IS CALLED TO
; [MS 359] TREAT THE STATEMENT AS AN ASSIGNMENT STATEMENT.
; [MS 360] OTHERWISE A CHECK IS MADE TO MAKE SURE THE
; [MS 361] RESERVED WORD NUMBER IS NOT TOO LARGE TO BE A
; [MS 362] STATEMENT TYPE NUMBER. IF NOT THE ADDRESS
; [MS 363] TO DISPATCH TO IS FETCHED FROM "STMDSP" (THE STATEMENT
; [MS 364] DISPATCH LIST) USING THE RESERVED WORD
; [MS 365] NUMBER FOR THE STATEMENT TO CALCULATE AN INDEX INTO
; [MS 366] THE LIST.
; [MS 367]
; [MS 368] ERROR MESSAGES
; [MS 369] WHEN AN ERROR CONDITION IS DETECTED,
; [MS 370] [ACCX] MUST BE SET UP TO INDICATE WHICH ERROR
; [MS 371] MESSAGE IS APPROPRIATE AND A BRANCH MUST BE MADE
; [MS 372] TO "ERROR". THE STACK WILL BE RESET AND ALL
; [MS 373] PROGRAM CONTEXT WILL BE LOST. VARIABLES
; [MS 374] VALUES AND THE ACTUAL PROGRAM REMAIN INTACT.
; [MS 375] ONLY THE VALUE OF [ACCX] IS IMPORTANT WHEN
; [MS 376] THE BRANCH IS MADE TO ERROR. [ACCX] IS USED AS AN
; [MS 377] INDEX INTO "ERRTAB" WHICH GIVES THE TWO
; [MS 378] CHARACTER ERROR MESSAGE THAT WILL BE PRINTED ON THE
; [MS 379] USER'S TERMINAL.
; [MS 380]
; [MS 381]
; [MS 382] TEXTUAL MESSAGES
; [MS 383] CONSTANT MESSAGES ARE STORED HERE. UNLESS
; [MS 384] THE CODE TO CHECK IF A STRING MUST BE COPIED
; [MS 385] IS CHANGED THESE STRINGS MUST BE STORED ABOVE
; [MS 386] PAGE ZERO, OR ELSE THEY WILL BE COPIED BEFORE
; [MS 387] THEY ARE PRINTED.
; [MS 388]
; [MS 389] FNDFOR
; [MS 390] MOST SMALL ROUTINES ARE FAIRLY SIMPLE
; [MS 391] AND ARE DOCUMENTED IN PLACE. "FNDFOR" IS
; [MS 392] USED FOR FINDING "FOR" ENTRIES ON
; [MS 393] THE STACK. WHENEVER A "FOR" IS EXECUTED, A
; [MS 394] 16-BYTE ENTRY IS PUSHED ONTO THE STACK.
; [MS 395] BEFORE THIS IS DONE, HOWEVER, A CHECK
; [MS 396] MUST BE MADE TO SEE IF THERE
; [MS 397] ARE ANY "FOR" ENTRIES ALREADY ON THE STACK
; [MS 398] FOR THE SAME LOOP VARIABLE. IF SO, THAT "FOR" ENTRY
; [MS 399] AND ALL OTHER "FOR" ENTRIES THAT WERE MADE AFTER IT
; [MS 400] ARE ELIMINATED FROM THE STACK. THIS IS SO A
; [MS 401] PROGRAM THAT JUMPS OUT OF THE MIDDLE
; [MS 402] OF A "FOR" LOOP AND THEN RESTARTS THE LOOP AGAIN
; [MS 403] AND AGAIN WON'T USE UP 18 BYTES OF STACK
; [MS 404] SPACE EVERY TIME. THE "NEXT" CODE ALSO
; [MS 405] CALLS "FNDFOR" TO SEARCH FOR A "FOR" ENTRY WITH
; [MS 406] THE LOOP VARIABLE IN
; [MS 407] THE "NEXT". AT WHATEVER POINT A MATCH IS FOUND
; [MS 408] THE STACK IS RESET. IF NO MATCH IS FOUND A
; [MS 409] "NEXT WITHOUT FOR"  ERROR OCCURS. GOSUB EXECUTION
; [MS 410] ALSO PUTS A 5-BYTE ENTRY ON STACK.
; [MS 411] WHEN A RETURN IS EXECUTED "FNDFOR" IS
; [MS 412] CALLED WITH A VARIABLE POINTER THAT CAN'T
; [MS 413] BE MATCHED. WHEN "FNDFOR" HAS RUN
; [MS 414] THROUGH ALL THE "FOR" ENTRIES ON THE STACK
; [MS 415] IT RETURNS AND THE RETURN CODE MAKES
; [MS 416] SURE THE ENTRY THAT WAS STOPPED
; [MS 417] ON IS A GOSUB ENTRY. THIS ASSURES THAT
; [MS 418] IF YOU GOSUB TO A SECTION OF CODE
; [MS 419] IN WHICH A FOR LOOP IS ENTERED BUT NEVER
; [MS 420] EXITED THE RETURN WILL STILL BE
; [MS 421] ABLE TO FIND THE MOST RECENT
; [MS 422] GOSUB ENTRY. THE "RETURN" CODE ELIMINATES THE
; [MS 423] "GOSUB" ENTRY AND ALL "FOR" ENTRIES MADE AFTER
; [MS 424] THE GOSUB ENTRY.
; [MS 425]
; [MS 426] NON-RUNTIME STUFF
; [MS 427] THE CODE TO INPUT A LINE, CRUNCH IT, GIVE ERRORS,
; [MS 428] FIND A SPECIFIC LINE IN THE PROGRAM,
; [MS 429] PERFORM A "NEW", "CLEAR", AND "LIST" ARE
; [MS 430] ALL IN THIS AREA. GIVEN THE EXPLANATION OF
; [MS 431] PROGRAM STORAGE SET FORTH ABOVE, THESE ARE
; [MS 432] ALL STRAIGHTFORWARD.
; [MS 433]
; [MS 434] NEWSTT
; [MS 435] WHENEVER A STATEMENT FINISHES EXECUTION IT
; [MS 436] DOES A "RTS" WHICH TAKES
; [MS 437] EXECUTION BACK TO "NEWSTT". STATEMENTS THAT
; [MS 438] CREATE OR LOOK AT SEMI-PERMANENT STACK ENTRIES
; [MS 439] MUST GET RID OF THE RETURN ADDRESS OF "NEWSTT" AND
; [MS 440] JMP TO "NEWSTT" WHEN DONE. "NEWSTT" ALWAYS
; [MS 441] CHRGETS THE FIRST CHARACTER AFTER THE STATEMENT
; [MS 442] NAME BEFORE DISPATCHING. WHEN RETURNING
; [MS 443] BACK TO "NEWSTT" THE ONLY THING THAT
; [MS 444] MUST BE SET UP IS THE TEXT POINTER IN
; [MS 445] "TXTPTR". "NEWSTT" WILL CHECK TO MAKE SURE
; [MS 446] "TXTPTR" IS POINTING TO A STATEMENT TERMINATOR.
; [MS 447] IF A STATEMENT SHOULDN'T BE PERFORMED UNLESS
; [MS 448] IT IS PROPERLY FORMATTED (I.E. "NEW") IT CAN
; [MS 449] SIMPLY DO A RETURN AFTER READING ALL OF
; [MS 450] ITS ARGUMENTS. SINCE THE ZERO FLAG
; [MS 451] BEING OFF INDICATES THERE IS NOT
; [MS 452] A STATEMENT TERMINATOR "NEWSTT" WILL
; [MS 453] DO THE JMP TO THE "SYNTAX ERROR"
; [MS 454] ROUTINE. IF A STATEMENT SHOULD BE STARTED
; [MS 455] OVER IT CAN DO LDWD OLDTXT, STWD TXTPTR RTS SINCE THE TEXT PNTR
; [MS 456] AT "NEWSTT" IS ALWAYS STORED IN "OLDTXT".
; [MS 457] THE ^C CODE STORES [CURLIN] (THE
; [MS 458] CURRENT LINE NUMBER) IN "OLDLIN" SINCE THE ^C CHECK
; [MS 459] IS MADE BEFORE THE STATEMENT POINTED TO IS
; [MS 460] EXECUTED. "STOP" AND "END" STORE THE TEXT POINTER
; [MS 461] FROM "TXTPTR", WHICH POINTS AT THEIR TERMINATING
; [MS 462] CHARACTER, IN "OLDTXT".
; [MS 463]
; [MS 464] STATEMENT CODE
; [MS 465] THE INDIVIDUAL STATEMENT CODE COMES
; [MS 466] NEXT. THE APPROACH USED IN EXECUTING EACH
; [MS 467] STATEMENT IS DOCUMENTED IN THE STATEMENT CODE
; [MS 468] ITSELF.
; [MS 469]
; [MS 470] FRMEVL, THE FORMULA EVALUATOR
; [MS 471] GIVEN A TEXT POINTER POINTING TO THE STARTING
; [MS 472] CHARACTER OF A FORMULA, "FRMEVL"
; [MS 473] EVALUATES THE FORMULA AND LEAVES
; [MS 474] THE VALUE IN THE FLOATING ACCUMULATOR (FAC).
; [MS 475] "TXTPTR" IS RETURNED POINTING TO THE FIRST CHARACTER
; [MS 476] THAT COULD NOT BE INTERPRETED AS PART OF THE
; [MS 477] FORMULA. THE ALGORITHM USES THE STACK
; [MS 478] TO STORE TEMPORARY RESULTS:
; [MS 479]
; [MS 480] 0. PUT A DUMMY PRECEDENCE OF ZERO ON
; [MS 481] THE STACK.
; [MS 482] 1. READ LEXEME (CONSTANT,FUNCTION,
; [MS 483] VARIABLE,FORMULA IN PARENS)
; [MS 484] AND TAKE THE LAST PRECEDENCE VALUE
; [MS 485] OFF THE STACK.
; [MS 486] 2. SEE IF THE NEXT CHARACTER IS AN OPERATOR.
; [MS 487] IF NOT, CHECK PREVIOUS ONE. THIS MAY CAUSE
; [MS 488] OPERATOR APPLICATION OR AN ACTUAL
; [MS 489] RETURN FROM "FRMEVL".
; [MS 490] 3. IF IT IS, SEE WHAT PRECEDENCE IT HAS
; [MS 491] AND COMPARE IT TO THE PRECEDENCE
; [MS 492] OF THE LAST OPERATOR ON THE STACK.
; [MS 493] 4. IF = OR LESS REMEMBER THE OPERATOR
; [MS 494] POINTER OF THIS OPERATOR
; [MS 495] AND BRANCH TO "QCHNUM" TO CAUSE
; [MS 496] APPLICATION OF THE LAST OPERATOR.
; [MS 497] EVENTUALLY RETURN TO STEP 2
; [MS 498] BY RETURNING TO JUST AFTER "DOPREC".
; [MS 499] 5. IF GREATER PUT THE LAST PRECEDENCE
; [MS 500] BACK ON, SAVE THE OPERATOR ADDRESS,
; [MS 501] CURRENT TEMPORARY RESULT,
; [MS 502] AND PRECEDENCE AND RETURN TO STEP 1.
; [MS 503]
; [MS 504] RELATIONAL OPERATORS ARE ALL HANDLED THROUGH
; [MS 505] A COMMON ROUTINE. SPECIAL
; [MS 506] CARE IS TAKEN TO DETECT TYPE MISMATCHES SUCH AS 3+"F".
; [MS 507]
; [MS 508] EVAL -- THE ROUTINE TO READ A LEXEME
; [MS 509] "EVAL" CHECKS FOR THE DIFFERENT TYPES OF
; [MS 510] ENTITIES IT IS SUPPOSED TO DETECT.
; [MS 511] LEADING PLUSES ARE IGNORED,
; [MS 512] DIGITS AND "." CAUSE "FIN" (FLOATING INPUT)
; [MS 513] TO BE CALLED. FUNCTION NAMES CAUSE THE
; [MS 514] FORMULA INSIDE THE PARENTHESES TO BE EVALUATED
; [MS 515] AND THE FUNCTION ROUTINE TO BE CALLED. VARIABLE
; [MS 516] NAMES CAUSE "PTRGET" TO BE CALLED TO GET A POINTER
; [MS 517] TO THE VALUE, AND THEN THE VALUE IS PUT INTO
; [MS 518] THE FAC. AN OPEN PARENTHESIS CAUSES "FRMEVL"
; [MS 519] TO BE CALLED (RECURSIVELY), AND THE ")" TO
; [MS 520] BE CHECKED FOR. UNARY OPERATORS (NOT AND
; [MS 521] NEGATION)  PUT THEIR PRECEDENCE ON THE STACK
; [MS 522] AND ENTER FORMULA EVALUATION AT STEP 1, SO
; [MS 523] THAT EVERYTHING UP TO AN OPERATOR GREATER THAN
; [MS 524] THEIR PRECEDENCE OR THE END OF THE FORMULA
; [MS 525] WILL BE EVALUATED.
; [MS 526]
; [MS 527] DIMENSION AND VARIABLE SEARCHING
; [MS 528] SPACE IS ALLOCATED FOR VARIABLES AS THEY ARE
; [MS 529] ENCOUNTERED. THUS "DIM" STATEMENTS MUST BE
; [MS 530] EXECUTED TO HAVE EFFECT. 6 BYTES ARE ALLOCATED
; [MS 531] FOR EACH SIMPLE VARIABLE, WHETHER IT IS A STRING,
; [MS 532] NUMBER OR USER DEFINED FUNCTION. THE FIRST TWO
; [MS 533] BYTES GIVE THE NAME OF THE VARIABLE AND THE LAST FOUR
; [MS 534] GIVE ITS VALUE. [VARTAB] GIVES THE FIRST LOCATION
; [MS 535] WHERE A SIMPLE VARIABLE NAME IS FOUND AND [ARYTAB]
; [MS 536] GIVES THE LOCATION TO STOP SEARCHING FOR SIMPLE
; [MS 537] VARIABLES. A "FOR" ENTRY HAS A TEXT POINTER
; [MS 538] AND A POINTER TO A VARIABLE VALUE SO NEITHER
; [MS 539] THE PROGRAM OR THE SIMPLE VARIABLES CAN BE
; [MS 540] MOVED WHILE THERE ARE ACTIVE "FOR" ENTRIES ON THE STACK.
; [MS 541] USER DEFINED FUNCTION VALUES ALSO CONTAIN
; [MS 542] POINTERS INTO SIMPLE VARIABLE SPACE SO NO USER-DEFINED
; [MS 543] FUNCTION VALUES CAN BE RETAINED IF SIMPLE VARIABLES
; [MS 544] ARE MOVED. ADDING A SIMPLE VARIABLE IS JUST
; [MS 545] ADDING SIX TO [ARYTAB] AND [STREND], BLOCK TRANSFERING
; [MS 546] THE ARRAY VARIABLES UP BY SIX AND MAKING SURE THE
; [MS 547] NEW [STREND] IS NOT TOO CLOSE TO THE STRINGS.
; [MS 548] THIS MOVEMENT OF ARRAY VARIABLES MEANS
; [MS 549] THAT NO POINTER TO AN ARRAY WILL STAY VALID WHEN
; [MS 550] NEW SIMPLE VARIABLES CAN BE ENCOUNTERED. THIS IS
; [MS 551] WHY ARRAY VARIABLES ARE NOT ALLOWED FOR "FOR"
; [MS 552] LOOP VARIABLES. SETTING UP A NEW ARRAY VARIABLE
; [MS 553] MERELY INVOLVES BUILDING THE DESCRIPTOR,
; [MS 554] UPDATING [STREND], AND MAKING SURE THERE IS
; [MS 555] STILL ENOUGH ROOM BETWEEN [STREND] AND STRING SPACE.
; [MS 556] "PTRGET", THE ROUTINE WHICH RETURNS A POINTER
; [MS 557] TO A VARIABLE VALUE, HAS TWO IMPORTANT FLAGS. ONE IS
; [MS 558] "DIMFLG" WHICH INDICATES WHETHER "DIM" CALLED "PTRGET"
; [MS 559] OR NOT. IF SO, NO PRIOR ENTRY FOR THE VARIABLE IN
; [MS 560] QUESTION SHOULD BE FOUND, AND THE INDEX INDICATES
; [MS 561] HOW MUCH SPACE TO SET ASIDE. SIMPLE VARIABLES CAN
; [MS 562] BE "DIMENSIONED", BUT THE ONLY EFFECT WILL BE TO
; [MS 563] SET ASIDE SPACE FOR THE VARIABLE IF IT HASN'T BEEN
; [MS 564] ENCOUNTERED YET. THE OTHER IMPORTANT FLAG IS "SUBFLG"
; [MS 565] WHICH INDICATES WHETHER A SUBSCRIPTED VARIABLE SHOULD BE
; [MS 566] ALLOWED IN THE CURRENT CONTEXT. IF [SUBFLG] IS NON-ZERO
; [MS 567] THE OPEN PARENTHESIS FOR A SUBSCRIPTED VARIABLE
; [MS 568] WILL NOT BE SCANNED BY "PTRGET", AND "PTRGET" WILL RETURN
; [MS 569] WITH A TEXT POINTER POINTING TO THE "(", IF
; [MS 570] THERE WAS ONE.
; [MS 571] STRINGS
; [MS 572] IN THE VARIABLE TABLES STRINGS ARE STORED JUST LIKE
; [MS 573] NUMERIC VARIABLES. SIMPLE STRINGS HAVE THREE VALUE
; [MS 574] BYTES WHICH ARE INITIALIZED TO ALL ZEROS (WHICH
; [MS 575] REPRESENTS THE NULL STRING). THE ONLY DIFFERENCE
; [MS 576] IN HANDLING IS THAT WHEN "PTRGET" SEES A "$" AFTER THE
; [MS 577] NAME OF A VARIABLE, "PTRGET" SETS [VALTYP]
; [MS 578] TO NEGATIVE ONE AND TURNS
; [MS 579] ON THE MSB (MOST-SIGNIFIGANT-BIT) OF THE VALUE OF
; [MS 580] THE FIRST CHARACTER OF THE VARIABLE NAME.
; [MS 581] HAVING THIS BIT ON IN THE NAME OF THE VARIABLE ENSURES
; [MS 582] THAT THE SEARCH ROUTINE WILL NOT MATCH
; [MS 583] 'A' WITH 'A$' OR 'A$' WITH 'A'. THE MEANING OF
; [MS 584] THE THREE VALUE BYTES ARE:
; [MS 585] LOW
; [MS 586] LENGTH OF THE STRING
; [MS 587] LOW 8 BITS
; [MS 588] HIGH 8 BITS  OF THE ADDRESS
; [MS 589] OF THE CHARACTERS IN THE
; [MS 590] STRING IF LENGTH.NE.0.
; [MS 591] MEANINGLESS OTHERWISE.
; [MS 592] HIGH
; [MS 593] THE VALUE OF A STRING VARIABLE (THESE 3 BYTES)
; [MS 594] IS CALLED THE STRING DESCRIPTOR TO DISTINGUISH
; [MS 595] IT FROM THE ACTUAL STRING DATA. WHENEVER A
; [MS 596] STRING CONSTANT IS ENCOUNTERED IN A FORMULA OR AS
; [MS 597] PART OF AN INPUT STRING, OR AS PART OF DATA, "STRLIT"
; [MS 598] IS CALLED, CAUSING A DESCRIPTOR TO BE BUILT FOR
; [MS 599] THE STRING. WHEN ASSIGNMENT IS MADE TO A STRING POINTING INTO
; [MS 600] "BUF" THE VALUE IS COPIED INTO STRING SPACE SINCE [BUF]
; [MS 601] IS ALWAYS CHANGING.
; [MS 602]
; [MS 603] STRING FUNCTIONS AND THE ONE STRING OPERATOR "+"
; [MS 604] ALWAYS RETURN THEIR VALUES IN STRING SPACE.
; [MS 605] ASSIGNING A STRING A CONSTANT VALUE IN A PROGRAM
; [MS 606] THROUGH A "READ" OR ASSIGNMENT STATEMENT
; [MS 607] WILL NOT USE ANY STRING SPACE SINCE
; [MS 608] THE STRING DESCRIPTOR  WILL POINT INTO THE
; [MS 609] PROGRAM ITSELF. IN GENERAL, COPYING IS DONE
; [MS 610] WHEN A STRING VALUE IS IN "BUF", OR IT IS IN STRING
; [MS 611] SPACE AND THERE IS AN ACTIVE POINTER TO IT.
; [MS 612] THUS F$=G$ WILL CAUSE COPYING IF G$ HAS ITS
; [MS 613] STRING DATA IN STRING SPACE. F$=CHR$(7)
; [MS 614] WILL USE ONE BYTE OF STRING SPACE TO STORE THE
; [MS 615] NEW ONE CHARACTER STRING CREATED BY "CHR$", BUT
; [MS 616] THE ASSIGNMENT ITSELF WILL CAUSE NO COPYING SINCE
; [MS 617] THE ONLY POINTER AT THE NEW STRING IS A
; [MS 618] TEMPORARY DESCRIPTOR CREATED BY "FRMEVL" WHICH WILL
; [MS 619] GO AWAY AS SOON AS THE ASSIGNMENT IS DONE.
; [MS 620] IT IS THE NATURE OF GARBAGE COLLECTION THAT
; [MS 621] DISALLOWS HAVING TWO STRING DESCRIPTORS POINT TO THE SAME
; [MS 622] AREA IN STRING SPACE. STRING FUNCTIONS AND OPERATORS
; [MS 623] MUST PROCEED AS FOLLOWS:
; [MS 624] 1) FIGURE OUT THE LENGTH OF THEIR RESULT.
; [MS 625]
; [MS 626] 2) CALL "GETSPA" TO FIND SPACE FOR THEIR
; [MS 627] RESULT. THE ARGUMENTS TO THE FUNCTION
; [MS 628] OR OPERATOR MAY CHANGE SINCE GARBAGE COLLECTION
; [MS 629] MAY BE INVOKED. THE ONLY THING THAT CAN
; [MS 630] BE SAVED DURING THE CALL TO "GETSPA" IS A POINTER
; [MS 631] TO THE DESCRIPTORS OF THE ARGUMENTS.
; [MS 632] 3) CONSTRUCT THE RESULT DESCRIPTOR IN "DSCTMP".
; [MS 633] "GETSPA" RETURNS THE LOCATION OF THE AVAILABLE
; [MS 634] SPACE.
; [MS 635] 4) CREATE THE NEW VALUE BY COPYING PARTS
; [MS 636] OF THE ARGUMENTS OR WHATEVER.
; [MS 637] 5) FREE UP THE ARGUMENTS BY CALLING "FRETMP".
; [MS 638] 6) JUMP TO "PUTNEW" TO GET THE DESCRIPTOR IN
; [MS 639] "DSCTMP" TRANSFERRED INTO A NEW STRING TEMPORARY.
; [MS 640]
; [MS 641] THE REASON FOR STRING TEMPORARIES IS THAT GARBAGE
; [MS 642] COLLECTION HAS TO KNOW ABOUT ALL ACTIVE STRING DESCRIPTORS
; [MS 643] SO IT KNOWS WHAT IS AND ISN'T IN USE. STRING TEMPORARIES ARE
; [MS 644] USED TO STORE THE DESCRIPTORS OF STRING EXPRESSIONS.
; [MS 645]
; [MS 646] INSTEAD OF HAVING AN ACTUAL VALUE STORED IN THE
; [MS 647] FAC, AND HAVING THE VALUE OF A TEMPORARY RESULT
; [MS 648] BEING SAVED ON THE STACK, AS HAPPENS WITH NUMERIC
; [MS 649] VARIABLES, STRINGS HAVE THE POINTER TO A STRING DESCRIPTOR
; [MS 650] STORED IN THE FAC, AND IT IS THIS POINTER
; [MS 651] THAT GETS SAVED ON THE STACK BY FORMULA EVALUATION.
; [MS 652] STRING FUNCTIONS CANNOT FREE THEIR ARGUMENTS UP RIGHT
; [MS 653] AWAY SINCE "GETSPA" MAY FORCE
; [MS 654] GARBAGE COLLECTION AND THE ARGUMENT STRINGS
; [MS 655] MAY BE OVER-WRITTEN SINCE GARBAGE COLLECTION
; [MS 656] WILL NOT BE ABLE TO FIND AN ACTIVE POINTER TO
; [MS 657] THEM. FUNCTION AND OPERATOR RESULTS ARE BUILT IN
; [MS 658] "DSCTMP" SINCE STRING TEMPORARIES ARE ALLOCATED
; [MS 659] (PUTNEW) AND DEALLOCATED (FRETMP) IN A FIFO ORDERING
; [MS 660] (I.E. A STACK) SO THE NEW TEMPORARY CANNOT
; [MS 661] BE SET UP UNTIL THE OLD ONE(S) ARE FREED. TRYING
; [MS 662] TO BUILD A RESULT IN A TEMPORARY AFTER
; [MS 663] FREEING UP THE ARGUMENT TEMPORARIES COULD RESULT
; [MS 664] IN ONE OF THE ARGUMENT TEMPORARIES BEING OVERWRITTEN
; [MS 665] TOO SOON BY THE NEW RESULT.
; [MS 666]
; [MS 667] STRING SPACE IS ALLOCATED AT THE VERY TOP
; [MS 668] OF MEMORY. "MEMSIZ" POINTS BEYOND THE LAST LOCATION OF
; [MS 669] STRING SPACE. STRINGS ARE STORED IN HIGH LOCATIONS
; [MS 670] FIRST. WHENEVER STRING SPACE IS ALLOCATED (GETSPA).
; [MS 671] [FRETOP], WHICH IS INITIALIZED TO [MEMSIZ], IS UPDATED
; [MS 672] TO GIVE THE HIGHEST LOCATION IN STRING SPACE
; [MS 673] THAT IS NOT IN USE. THE RESULT IS THAT
; [MS 674] [FRETOP] GETS SMALLER AND SMALLER, UNTIL SOME
; [MS 675] ALLOCATION WOULD MAKE [FRETOP] LESS THAN OR EQUAL TO
; [MS 676] [STREND]. THIS MEANS STRING SPACE HAS RUN INTO THE
; [MS 677] THE ARRAYS AND THAT GARBAGE COLLECTION MUST BE CALLED.
; [MS 678]
; [MS 679] GARBAGE COLLECTION:
; [MS 680] 0. [MINPTR]=[STREND] [FRETOP]=[MEMSIZ]
; [MS 681] 1. [REMMIN]=0
; [MS 682] 2. FOR EACH STRING DESCRIPTOR
; [MS 683] (TEMPORARIES, SIMPLE STRINGS, STRING ARRAYS)
; [MS 684] IF THE STRING IS NOT NULL AND ITS POINTER IS
; [MS 685] .GT.MINPTR AND .LT.FRETOP,
; [MS 686] [MINPTR]=THIS STRING DESCRIPTOR'S POINTER,
; [MS 687] [REMMIN]=POINTER AT THIS STRING DESCRIPTOR.
; [MS 688] END.
; [MS 689] 3. IF REMMIN.NE.0 (WE FOUND AN UNCOLLECTED STRING),
; [MS 690] BLOCK TRANSFER THE STRING DATA POINTED
; [MS 691] TO IN THE STRING DESCRIPTOR POINTED TO BY "REMMIN"
; [MS 692] SO THAT THE LAST BYTE OF STRING DATA IS AT
; [MS 693] [FRETOP]. UPDATE [FRETOP] SO THAT IT
; [MS 694] POINTS TO THE LOCATION JUST BELOW THE ONE
; [MS 695] THE STRING DATA WAS MOVED INTO. UPDATE
; [MS 696] THE POINTER IN THE DESCRIPTOR SO IT POINTS
; [MS 697] TO THE NEW LOCATION OF THE STRING DATA.
; [MS 698] GO TO STEP 1.
; [MS 699]
; [MS 700] AFTER CALLING GARBAGE COLLECTION "GETSPA" AGAIN CHECKS
; [MS 701] TO SEE IF [ACCA] CHARACTERS ARE AVAILABLE BETWEEN
; [MS 702] [STREND] AND [FRETOP]; IF NOT, AN "OUT OF STRING"
; [MS 703] ERROR IS INVOKED.
; [MS 704]
; [MS 705] MATH PACKAGE
; [MS 706] THE MATH PACKAGE CONTAINS FLOATING INPUT (FIN),
; [MS 707] FLOATING OUTPUT (FOUT), FLOATING COMPARE (FCOMP)
; [MS 708] ... AND ALL THE NUMERIC OPERATORS AND FUNCTIONS.
; [MS 709] THE FORMATS, CONVENTIONS AND ENTRY POINTS ARE ALL
; [MS 710] DESCRIBED IN THE MATH PACKAGE ITSELF.
; [MS 711]
; [MS 712] INIT -- THE INITIALIZATION ROUTINE
; [MS 713] THE AMOUNT OF MEMORY,
; [MS 714] TERMINAL WIDTH, AND WHICH FUNCTIONS TO BE RETAINED
; [MS 715] ARE ASCERTAINED FROM THE USER. A ZERO IS PUT DOWN
; [MS 716] AT THE FIRST LOCATION NOT USED BY THE MATH-PACKAGE
; [MS 717] AND [TXTTAB] IS SET UP TO POINT AT THE NEXT LOCATION.
; [MS 718] THIS DETERMINES WHERE PROGRAM STORAGE WILL START.
; [MS 719] SPECIAL CHECKS ARE MADE TO MAKE SURE
; [MS 720] ALL QUESTIONS IN "INIT" ARE ANSWERED REASONABLY, SINCE
; [MS 721] ONCE "INIT" FINISHES, THE LOCATIONS IT USES ARE
; [MS 722] USED FOR PROGRAM STORAGE. THE LAST THING "INIT" DOES IS
; [MS 723] CHANGE LOCATION ZERO TO BE A JUMP TO "READY" INSTEAD
; [MS 724] OF "INIT". ONCE THIS IS DONE THERE IS NO WAY TO RESTART
; [MS 725] "INIT".
; [MS 726] HIGH LOCATIONS
; [MS 727]
; [MS 728]
; [MS 730] ==== PAGE ZERO. ====

START:                                  ; [MS 732]
        jmp INIT                        ; [MS 732] INITIALIZE - SETUP CERTAIN LOCATIONS
; [MS 733] AND DELETE FUNCTIONS IF NOT NEEDED,
; [MS 734] AND CHANGE THIS TO "JMP READY"
; [MS 735] IN CASE USER RESTARTS AT LOC ZERO.
RDYJSR:                                 ; [MS 736]
        jmp INIT                        ; [MS 736] CHANGED TO "JMP STROUT" BY "INIT"
; [MS 737] TO HANDLE ERRORS.
        .res 2                          ; [MS 738] [OURS] was ADRAYI: $06-$09 are left free for programs, as in Applesoft (Applesoft II manual, Appendix L lists no use)
; [MS 739] ROUTINE TO TURN THE FAC INTO A
; [MS 740] TWO BYTE SIGNED INTEGER IN [Y,A]
        .res 2                          ; [MS 741] [OURS] was ADRGAY (see above)
; [MS 742] ROUTINE TO CONVERT [Y,A] TO A FLOATING
; [MS 743] POINT NUMBER IN THE FAC.

USRPOK:                                 ; [MS 745]
        jmp FCERR                       ; [MS 745] SET UP ORIG BY INIT.
; [MS 746]
; [MS 747] THIS IS THE "VOLATILE" STORAGE AREA AND NONE OF IT
; [MS 748] CAN BE KEPT IN ROM. ANY CONSTANTS IN THIS AREA CANNOT
; [MS 749] BE KEPT IN A ROM, BUT MUST BE LOADED IN BY THE
; [MS 750] PROGRAM INSTRUCTIONS IN ROM.
; [MS 751]
; [MS 752] --- GENERAL RAM ---:
CHARAC:                                 ; [MS 753]
        .res 1                          ; [MS 753] A DELIMITING CHARACTER.
INTEGR = CHARAC                         ; [MS 754] A ONE-BYTE INTEGER FROM "QINT".
ENDCHR:                                 ; [MS 755]
        .res 1                          ; [MS 755] THE OTHER DELIMITING CHARACTER.
COUNT:                                  ; [MS 756]
        .res 1                          ; [MS 756] A GENERAL COUNTER.

; [MS 758] --- FLAGS ---:
DIMFLG:                                 ; [MS 759]
        .res 1                          ; [MS 759] IN GETTING A POINTER TO A VARIABLE
; [MS 760] IT IS IMPORTANT TO REMEMBER WHETHER IT
; [MS 761] IS BEING DONE FOR "DIM" OR NOT.
; [MS 762] DIMFLG AND VALTYP MUST BE
; [MS 763] CONSECUTIVE LOCATIONS.
KIMY = DIMFLG                           ; [MS 764] PLACE TO PRESERVE Y DURING OUT.
VALTYP:                                 ; [MS 765]
        .res 1                          ; [MS 765] THE TYPE INDICATOR.
; [MS 766] 0=NUMERIC 1=STRING.

INTFLG:                                 ; [MS 768]
        .res 1                          ; [MS 768] TELLS IF INTEGER.
DORES:                                  ; [MS 769]
        .res 1                          ; [MS 769] WHETHER CAN OR CAN'T CRUNCH RES'D WORDS.
; [MS 770] TURNED ON WHEN "DATA"
; [MS 771] BEING SCANNED BY CRUNCH SO UNQUOTED
; [MS 772] STRINGS WON'T BE CRUNCHED.
GARBFL = DORES                          ; [MS 773] WHETHER TO DO GARBAGE COLLECTION.
SUBFLG:                                 ; [MS 774]
        .res 1                          ; [MS 774] FLAG WHETHER SUB'D VARIABLE ALLOWED.
; [MS 775] "FOR" AND USER-DEFINED FUNCTION
; [MS 776] POINTER FETCHING TURN
; [MS 777] THIS ON BEFORE CALLING "PTRGET"
; [MS 778] SO ARRAYS WON'T BE DETECTED.
; [MS 779] "STKINI" AND "PTRGET" CLEAR IT.
; [MS 780] ALSO DISALLOWS INTEGERS THERE.
INPFLG:                                 ; [MS 781]
        .res 1                          ; [MS 781] FLAGS WHETHER WE ARE DOING "INPUT"
; [MS 782] OR "READ".
TANSGN:                                 ; [MS 783]
        .res 1                          ; [MS 783] USED IN DETERMINING SIGN OF TANGENT.

CNTWFL:                                 ; [MS 785]
        .res 1                          ; [MS 785] SUPPRESS OUTPUT FLAG.
; [MS 786] NON-ZERO MEANS SUPPRESS.
; [MS 787] RESET BY "INPUT", READY AND ERRORS.
; [MS 788] COMPLEMENTED BY INPUT OF ^O.

        .org $50                        ; [MS 790] ROOM FOR APPLE PAGE 0 STUFF.
; [MS 791] --- RAM DEALING WITH TERMINAL HANDLING ---:
; [MS 793] HOLDS CHANNEL NUMBER.
; [MS 795] NUMBER OF NULLS TO PRINT.

TRMPOS = $24                            ; [MS 797] [OURS] [RM] the Monitor's CH: Applesoft keeps no print-head count of its own; POS and TAB work from the cursor (Applesoft II manual, POS, TAB) and the Monitor wraps lines
; [MS 798] [OURS] LINWID and NCMWID are gone with TRMPOS, so LINNUM lands on $50 as in Applesoft (Appendix L)
; [MS 800] NO MORE FIELDS.
LINNUM:                                 ; [MS 801]
        .byte 0                         ; [MS 801] LOCATION TO STORE LINE NUMBER BEFORE BUF
; [MS 802] SO THAT "BLTUC" CAN STORE IT ALL AWAY AT ONCE.
        .byte 44                        ; [MS 803] A COMMA (PRELOAD OR FROM ROM)
; [MS 804] USED BY INPUT STATEMENT SINCE THE
; [MS 805] DATA POINTER ALWAYS STARTS ON A
; [MS 806] COMMA OR TERMINATOR.
; [MS 808] TYPE IN STORED HERE.
; [MS 809] DIRECT STATEMENTS EXECUTE OUT OF
; [MS 810] HERE. REMEMBER "INPUT" SMASHES BUF.
; [MS 811] MUST BE ON PAGE ZERO
; [MS 812] OR ASSIGNMENT OF STRING
; [MS 813] VALUES IN DIRECT STATEMENTS WON'T COPY
; [MS 814] INTO STRING SPACE -- WHICH IT MUST.
; [MS 815] N.B. TWO NONZERO BYTES MUST PRECEDE "BUFLNM".

; [MS 817] --- STORAGE FOR TEMPORARY THINGS ---:
TEMPPT:                                 ; [MS 818]
        .res 1                          ; [MS 818] POINTER AT FIRST FREE TEMP DESCRIPTOR.
; [MS 819] INITIALIZED TO POINT TO TEMPST.
LASTPT:                                 ; [MS 820]
        .res 2                          ; [MS 820] POINTER TO LAST-USED STRING TEMPORARY.
TEMPST:                                 ; [MS 821]
        .res STRSIZ*NUMTMP              ; [MS 821] STORAGE FOR NUMTMP TEMP DESCRIPTORS.
INDEX1:                                 ; [MS 822]
        .res 2                          ; [MS 822] INDEXES.
INDEX = INDEX1                          ; [MS 823]
INDEX2:                                 ; [MS 824]
        .res 2                          ; [MS 824]
RESHO:                                  ; [MS 825]
        .res 1                          ; [MS 825] RESULT OF MULTIPLIER AND DIVIDER.

RESMOH:                                 ; [MS 827]
        .res 1                          ; [MS 827] ONE MORE BYTE.
RESMO:                                  ; [MS 828]
        .res 1                          ; [MS 828]
RESLO:                                  ; [MS 829]
        .res 1                          ; [MS 829]
ADDEND = RESMO                          ; [MS 830] TEMPORARY USED BY "UMULT".
        .byte 0                         ; [MS 831] OVERFLOW FOR RES.

; [MS 833] --- POINTERS INTO DYNAMIC DATA STRUCTURES ---;
TXTTAB:                                 ; [MS 834]
        .res 2                          ; [MS 834] POINTER TO BEGINNING OF TEXT.
; [MS 835] DOESN'T CHANGE AFTER BEING
; [MS 836] SETUP BY "INIT".
VARTAB:                                 ; [MS 837]
        .res 2                          ; [MS 837] POINTER TO START OF SIMPLE
; [MS 838] VARIABLE SPACE.
; [MS 839] UPDATED WHENEVER THE SIZE OF THE
; [MS 840] PROGRAM CHANGES, SET TO [TXTTAB]
; [MS 841] BY "SCRATCH" ("NEW").
ARYTAB:                                 ; [MS 842]
        .res 2                          ; [MS 842] POINTER TO BEGINNING OF ARRAY
; [MS 843] TABLE.
; [MS 844] INCREMENTED BY 6 WHENEVER
; [MS 845] A NEW SIMPLE VARIABLE IS FOUND, AND
; [MS 846] SET TO [VARTAB] BY "CLEARC".
STREND:                                 ; [MS 847]
        .res 2                          ; [MS 847] END OF STORAGE IN USE.
; [MS 848] INCREASED WHENEVER A NEW ARRAY
; [MS 849] OR SIMPLE VARIABLE IS ENCOUNTERED.
; [MS 850] SET TO [VARTAB] BY "CLEARC".
FRETOP:                                 ; [MS 851]
        .res 2                          ; [MS 851] TOP OF STRING FREE SPACE.
FRESPC:                                 ; [MS 852]
        .res 2                          ; [MS 852] POINTER TO NEW STRING.
MEMSIZ:                                 ; [MS 853]
        .res 2                          ; [MS 853] HIGHEST LOCATION IN MEMORY.

; [MS 855] --- LINE NUMBERS AND TEXTUAL POINTERS ---:
CURLIN:                                 ; [MS 856]
        .res 2                          ; [MS 856] CURRENT LINE #.
; [MS 857] SET TO 0,255 FOR DIRECT STATEMENTS.
OLDLIN:                                 ; [MS 858]
        .res 2                          ; [MS 858] OLD LINE NUMBER (SETUP BY ^C,"STOP"
; [MS 859] OR "END" IN A PROGRAM).
POKER = LINNUM                          ; [MS 860] SET UP LOCATION USED BY POKE.
; [MS 861] TEMPORARY FOR INPUT AND READ CODE
OLDTXT:                                 ; [MS 862]
        .res 2                          ; [MS 862] OLD TEXT POINTER.
; [MS 863] POINTS AT STATEMENT TO BE EXEC'D NEXT.
DATLIN:                                 ; [MS 864]
        .res 2                          ; [MS 864] DATA LINE # -- REMEMBER FOR ERRORS.
DATPTR:                                 ; [MS 865]
        .res 2                          ; [MS 865] POINTER TO DATA. INITIALIZED TO POINT
; [MS 866] AT THE ZERO IN FRONT OF [TXTTAB]
; [MS 867] BY "RESTORE" WHICH IS CALLED BY "CLEARC".
; [MS 868] UPDATED BY EXECUTION OF A "READ".
INPPTR:                                 ; [MS 869]
        .res 2                          ; [MS 869] THIS REMEMBERS WHERE INPUT IS COMING FROM.

; [MS 871] --- STUFF USED IN EVALUATIONS ---:
VARNAM:                                 ; [MS 872]
        .res 2                          ; [MS 872] VARIABLE'S NAME IS STORED HERE.
VARPNT:                                 ; [MS 873]
        .res 2                          ; [MS 873] POINTER TO VARIABLE IN MEMORY.
FDECPT = VARPNT                         ; [MS 874] POINTER INTO POWER OF TENS OF "FOUT".
FORPNT:                                 ; [MS 875]
        .res 2                          ; [MS 875] A VARIABLE'S POINTER FOR "FOR" LOOPS
; [MS 876] AND "LET" STATEMENTS.
LSTPNT = FORPNT                         ; [MS 877] PNTR TO LIST STRING.
ANDMSK = FORPNT                         ; [MS 878] THE MASK USED BY WAIT FOR ANDING.
EORMSK = FORPNT+1                       ; [MS 879] THE MASK FOR EORING IN WAIT.
OPPTR:                                  ; [MS 880]
        .res 2                          ; [MS 880] POINTER TO CURRENT OP'S ENTRY IN "OPTAB".
VARTXT = OPPTR                          ; [MS 881] POINTER INTO LIST OF VARIABLES.
OPMASK:                                 ; [MS 882]
        .res 1                          ; [MS 882] MASK CREATED BY CURRENT OPERATOR.
DOMASK = TANSGN                         ; [MS 883] MASK IN USE BY RELATION OPERATIONS.
DEFPNT:                                 ; [MS 884]
        .res 2                          ; [MS 884] POINTER USED IN FUNCTION DEFINITION.
GRBPNT = DEFPNT                         ; [MS 885] ANOTHER USED IN GARBAGE COLLECTION.
DSCPNT:                                 ; [MS 886]
        .res 2                          ; [MS 886] POINTER TO A STRING DESCRIPTOR.
        .res 1                          ; [MS 887] FOR TEMPF3.
FOUR6:                                  ; [MS 888]
        .byte STRSIZ                    ; [MS 888] VARIABLE CONSTANT USED BY GARB COLLECT.

; [MS 890] --- ET CETERA ---:
JMPER:                                  ; [MS 891]
        jmp 60000                       ; [MS 891]
SIZE = JMPER+1                          ; [MS 892]
OLDOV = JMPER+2                         ; [MS 893] THE OLD OVERFLOW.
TEMPF3 = DEFPNT                         ; [MS 894] A THIRD FAC TEMPORARY (4 BYTES).
TEMPF1:                                 ; [MS 895]
        .byte 0                         ; [MS 896] FOR TEMPF1S EXTRA BYTE.
HIGHDS:                                 ; [MS 897]
        .res 2                          ; [MS 897] DESINATION OF HIGHEST ELEMENT IN BLT.
HIGHTR:                                 ; [MS 898]
        .res 2                          ; [MS 898] SOURCE OF HIGHEST ELEMENT TO MOVE.
TEMPF2:                                 ; [MS 899]
        .byte 0                         ; [MS 900] FOR TEMPF2S EXTRA BYTE.
LOWDS:                                  ; [MS 901]
        .res 2                          ; [MS 901] LOCATION OF LAST BYTE TRANSFERRED INTO.
LOWTR:                                  ; [MS 902]
        .res 2                          ; [MS 902] LAST THING TO MOVE IN BLT.
ARYPNT = HIGHDS                         ; [MS 903] A POINTER USED IN ARRAY BUILDING.
GRBTOP = LOWTR                          ; [MS 904] A POINTER USED IN GARBAGE COLLECTION.
DECCNT = LOWDS                          ; [MS 905] NUMBER OF PLACES BEFORE DECIMAL POINT.
TENEXP = LOWDS+1                        ; [MS 906] HAS A DPT BEEN INPUT?
DPTFLG = LOWTR                          ; [MS 907] BASE TEN EXPONENT.
EXPSGN = LOWTR+1                        ; [MS 908] SIGN OF BASE TEN EXPONENT.

; [MS 910] --- THE FLOATING ACCUMULATOR ---:
FAC:                                    ; [MS 911]
FACEXP:                                 ; [MS 912]
        .byte 0                         ; [MS 912]
FACHO:                                  ; [MS 913]
        .byte 0                         ; [MS 913] MOST SIGNIFICANT BYTE OF MANTISSA.

FACMOH:                                 ; [MS 915]
        .byte 0                         ; [MS 915] ONE MORE.
FACMO:                                  ; [MS 916]
        .byte 0                         ; [MS 916] MIDDLE ORDER OF MANTISSA.
FACLO:                                  ; [MS 917]
        .byte 0                         ; [MS 917] LEAST SIG BYTE OF MANTISSA.
FACSGN:                                 ; [MS 918]
        .byte 0                         ; [MS 918] SIGN OF FAC (0 OR -1) WHEN UNPACKED.
SGNFLG:                                 ; [MS 919]
        .byte 0                         ; [MS 919] SIGN OF FAC IS PRESERVED BERE BY "FIN".
DEGREE = SGNFLG                         ; [MS 920] A COUNT USED BY POLYNOMIALS.
DSCTMP = FAC                            ; [MS 921] THIS IS WHERE TEMP DESCS ARE BUILT.
INDICE = FACMO                          ; [MS 922] INDICE IS SET UP HERE BY "QINT".
BITS:                                   ; [MS 923]
        .byte 0                         ; [MS 923] SOMETHING FOR "SHIFTR" TO USE.

; [MS 925] --- THE FLOATING ARGUMENT (UNPACKED) ---:
ARGEXP:                                 ; [MS 926]
        .byte 0                         ; [MS 926]
ARGHO:                                  ; [MS 927]
        .byte 0                         ; [MS 927]
ARGMOH:                                 ; [MS 928]
        .byte 0                         ; [MS 928]
ARGMO:                                  ; [MS 929]
        .byte 0                         ; [MS 929]
ARGLO:                                  ; [MS 930]
        .byte 0                         ; [MS 930]
ARGSGN:                                 ; [MS 931]
        .byte 0                         ; [MS 931]

ARISGN:                                 ; [MS 933]
        .byte 0                         ; [MS 933] A SIGN REFLECTING THE RESULT.
FACOV:                                  ; [MS 934]
        .byte 0                         ; [MS 934] OVERFLOW BYTE OF THE FAC.
STRNG1 = ARISGN                         ; [MS 935] POINTER TO A STRING OR DESCRIPTOR.

FBUFPT:                                 ; [MS 937]
        .res 2                          ; [MS 937] POINTER INTO FBUFFR USED BY FOUT.
BUFPTR = FBUFPT                         ; [MS 938] POINTER TO BUF USED BY "CRUNCH".
STRNG2 = FBUFPT                         ; [MS 939] POINTER TO STRING OR DESC.
POLYPT = FBUFPT                         ; [MS 940] POINTER INTO POLYNOMIAL COEFFICIENTS.
CURTOL = FBUFPT                         ; [MS 941] ABSOLUTE LINEAR INDEX IS FORMED HERE.
PRGEND:                                 ; [OURS] [RM] end of program, $AF-$B0 (Applesoft II manual, Appendix L; DOS 3.3 source ASEOP); LOMEM: does not move it
        .res 2                          ; [OURS]
; [MS 943] ==== RAM CODE. ====
; [MS 944] THIS CODE GETS CHANGED THROUGHOUT EXECUTION.
; [MS 945] IT IS MADE TO BE FAST THIS WAY.
; [MS 946] ALSO, [X] AND [Y] ARE NOT DISTURBED
; [MS 947]
; [MS 948] "CHRGET" USING [TXTPTR] AS THE CURRENT TEXT PNTR
; [MS 949] FETCHES A NEW CHARACTER INTO ACCA AFTER INCREMENTING [TXTPTR]
; [MS 950] AND SETS CONDITION CODES ACCORDING TO WHAT'S IN ACCA.
; [MS 951] NOT C=	NUMERIC	  ("0" THRU "9")
; [MS 952] Z=	":" OR END-OF-LINE (A NULL)
; [MS 953]
; [MS 954] [ACCA] = NEW CHAR.
; [MS 955] [TXTPTR]=[TXTPTR]+1
; [MS 956]
; [MS 957] THE FOLLOWING EXISTS IN ROM IF ROM EXISTS AND IS LOADED
; [MS 958] DOWN HERE BY INIT. OTHERWISE IT IS JUST LOADED INTO THIS
; [MS 959] RAM LIKE ALL THE REST OF RAM IS LOADED.
; [MS 960]
CHRGET:                                 ; [MS 961]
        inc CHRGET+7                    ; [MS 961] INCREMENT THE WHOLE TXTPTR.
        bne CHRGOT                      ; [MS 962]
        inc CHRGET+8                    ; [MS 963]
CHRGOT:                                 ; [MS 964]
        lda 60000                       ; [MS 964] A LOAD WITH AN EXT ADDR.
TXTPTR = CHRGOT+1                       ; [MS 965]
        cmp #' '                        ; [MS 966] SKIP SPACES.
        beq CHRGET                      ; [MS 967]
QNUM:                                   ; [MS 968]
        cmp #':'                        ; [MS 968] IS IT A ":"?
        bcs CHRRTS                      ; [MS 969] IT IS .GE. ":"
        sec                             ; [MS 970]
        sbc #'0'                        ; [MS 971] ALL CHARS .GT. "9" HAVE RET'D SO
        sec                             ; [MS 972]
        sbc #256-'0'                    ; [MS 973] SEE IF NUMERIC.
; [MS 974] TURN CARRY ON IF NUMERIC.
; [MS 975] ALSO, SETZ IF NULL.
CHRRTS:                                 ; [MS 976]
        rts                             ; [MS 976] RETURN TO CALLER.

RNDX:                                   ; [MS 978]
        .byte 128                       ; [MS 978] LOADED OR FROM ROM.
        .byte 79                        ; [MS 979] THE INITIAL RANDOM NUMBER.
        .byte 199                       ; [MS 980]
        .byte 82                        ; [MS 981]
        .byte 89                        ; [MS 982] ONE MORE BYTE.

        .reloc                          ; [MS 984]
; [OURS] [RM] Applesoft's zero page (Applesoft II manual, Appendix L; DOS 3.3 source for $67 $69 $6F $73 $76 $AF $D6 $D8):
; a wrong layout does not assemble.
        .assert USRPOK = $0A, error, "USR jump at $A-$C"
        .assert CHARAC = $0D, error, "counters and flags from $D"
        .assert CNTWFL <= $17, error, "counters and flags end at $17"
        .assert LINNUM = $50, error, "pointers from $50"
        .assert RESHO = $62, error, "multiply result $62-$66"
        .assert TXTTAB = $67, error, "start of program $67"
        .assert VARTAB = $69, error, "start of variables $69"
        .assert ARYTAB = $6B, error, "start of arrays $6B"
        .assert STREND = $6D, error, "end of numeric storage $6D"
        .assert FRETOP = $6F, error, "start of strings $6F"
        .assert FRESPC = $71, error, "general pointer $71"
        .assert MEMSIZ = $73, error, "top of memory $73"
        .assert CURLIN = $75, error, "current line $75"
        .assert OLDLIN = $77, error, "old line $77"
        .assert OLDTXT = $79, error, "old text pointer $79"
        .assert DATLIN = $7B, error, "DATA line $7B"
        .assert DATPTR = $7D, error, "DATA pointer $7D"
        .assert INPPTR = $7F, error, "INPUT source $7F"
        .assert VARNAM = $81, error, "variable name $81"
        .assert VARPNT = $83, error, "variable value $83"
        .assert FAC = $9D, error, "FAC $9D-$A3"
        .assert ARGEXP = $A5, error, "ARG $A5-$AB"
        .assert PRGEND = $AF, error, "end of program $AF"
        .assert CHRGET = $B1, error, "CHRGET $B1-$C8"
        .assert TXTPTR = $B8, error, "TXTPTR $B8-$B9"
        .assert RNDX = $C9, error, "random number $C9-$CD"

ERRFLG = $D8                            ; [OURS] [RM] bit 7 set: ONERR GOTO is on (PEEK(216)>127, POKE 216,0) (Applesoft II manual 1981 (A2L0006), ONERR GOTO, RESUME and Appendix J; the 1978 edition says the same)
ERRLIN = $DA                            ; [OURS] [RM] the line where the error happened (PEEK(218)+256*PEEK(219))
ERRPOS = $DC                            ; [OURS] [RM] where that statement starts, for RESUME ($D8-$DF "ONERR pointers / scratch")
ERRNUM = $DE                            ; [OURS] [RM] the error code (PEEK(222)): 0 NEXT WITHOUT FOR ... 254 bad INPUT response
ERRSTK = $DF                            ; [OURS] [RM] the stack pointer at that statement (the manual's fix routine LDX $DF / TXS)
TXTPSV = $F4                            ; [OURS] [RM] the ONERR GOTO's place in the program ($F4-$F8 "ONERR pointers")
CURLSV = $F6                            ; [OURS] [RM] its line
REMSTK = $F8                            ; [OURS] [RM] the stack pointer at the ONERR statement
        .segment "BPG1"                 ; [MS 984] ORG 255; PAGE 1 STUFF COMING UP.
        .org $FF                        ; [MS 984]
LOFBUF:                                 ; [MS 985]
        .res 1                          ; [MS 985] THE LOW FAC BUFFER. COPYABLE.
; [MS 986] ---  PAGE ZERO/ONE BOUNDARY ---.
; [MS 987] MUST HAVE 13 CONTIGUOUS BYTES.
FBUFFR:                                 ; [MS 988]
        .res 3*ADDPRC+13                ; [MS 988] BUFFER FOR "FOUT".
; [MS 989] ON PAGE 1 SO THAT STRING IS NOT COPIED.

; [MS 991] STACK IS LOCATED HERE. IE FROM THE END OF FBUFFR TO STKEND.
; [MS 993] ==== DISPATCH TABLES, RESERVED WORDS, AND ERROR TEXTS. ====

        .reloc                          ; [MS 995]
        .segment "BASIC"                ; [MS 995] ORG ROMLOC
        .org $D000                      ; [OURS] assembled at its real address, so entry points can be pinned (PIN below)
; [OURS] Applesoft's documented entry points must sit at their own addresses: DOS 3.3 and programs (Oregon
; Trail's loader among them) JSR or JMP there. Each gets a 3-byte JMP to our routine. PINJ is for a spot that
; nothing falls into (after an RTS or JMP); PINF also jumps over the entry, for the middle of a routine. Both
; pad with $02 and refuse to assemble if our code has already run past the address.
; [OURS] ALIGN addr: the next byte lands on addr, Applesoft's address for the routine that follows (only where
; nothing falls through): pads with $02 and refuses to assemble if our code has already run past it.
.macro ALIGN addr
        .assert * <= addr, error, "BASIC's code runs past an Applesoft address it must keep"
        .if addr > *
        .res addr - *, $02
        .endif
.endmacro
.macro PINJ addr, target
        .assert * <= addr, error, "BASIC's code runs over a pinned entry point"
        .if addr > *
        .res addr - *, $02
        .endif
        jmp target
.endmacro
.macro FALLTO addr
        .assert * <= addr, error, "BASIC's code runs past an Applesoft address it must keep"
        .if addr > *
        .res addr - *, $EA
        .endif
.endmacro
.macro PINF addr, target
        .local over
        jmp over
        .assert * <= addr, error, "BASIC's code runs over a pinned entry point"
        .if addr > *
        .res addr - *, $02
        .endif
        jmp target
over:
.endmacro
        jmp INIT                        ; [OURS] cold start at $D000 (D000G in the Monitor) until B2 puts it at $E000

STMDSP:                                 ; [MS 997] [OURS] [RM] statements $80-$BF in Applesoft's order (Applesoft II manual, Appendix F);
; [OURS] Microsoft's statements keep their code; Applesoft's own each go to a trap ($02) of their own until written, so the missing-routine log names them
        .word END-1                     ; [MS 997-1052] $80 END
        .word FOR-1                     ; [MS 997-1052] $81 FOR
        .word NEXT-1                    ; [MS 997-1052] $82 NEXT
        .word DATA-1                    ; [MS 997-1052] $83 DATA
