        .byte "VA", 'L'|$80             ; [OURS] $E5
        .byte "AS", 'C'|$80             ; [OURS] $E6
        .byte "CHR", '$'|$80            ; [OURS] $E7
        .byte "LEFT", '$'|$80           ; [OURS] $E8
        .byte "RIGHT", '$'|$80          ; [OURS] $E9
        .byte "MID", '$'|$80            ; [OURS] $EA
        .byte 0                         ; [MS 1245] MARKS END OF RESERVED WORD LIST
; [OURS] the token numbers Microsoft's code uses, now Applesoft's (Appendix F)
ENDTK = $80                             ; [OURS] END
FORTK = $81                             ; [OURS] FOR
DATATK = $83                            ; [OURS] DATA
GOTOTK = $AB                            ; [OURS] GOTO
GOSUTK = $B0                            ; [OURS] GOSUB
REMTK = $B2                             ; [OURS] REM
PRINTK = $BA                            ; [OURS] PRINT
SCRATK = $BF                            ; [OURS] NEW
TABTK = $C0                             ; [OURS] TAB(
TOTK = $C1                              ; [OURS] TO
FNTK = $C2                              ; [OURS] FN
SPCTK = $C3                             ; [OURS] SPC(
THENTK = $C4                            ; [OURS] THEN
ATTK = $C5                              ; [OURS] AT
NOTTK = $C6                             ; [OURS] NOT
STEPTK = $C7                            ; [OURS] STEP
PLUSTK = $C8                            ; [OURS] +
MINUTK = $C9                            ; [OURS] -
GREATK = $CF                            ; [OURS] >
EQULTK = $D0                            ; [OURS] =
LESSTK = $D1                            ; [OURS] <
ONEFUN = $D2                            ; [OURS] SGN
LASNUM = $E7                            ; [OURS] CHR$

; [MS 1287] UNDEFINED FUNCTION.


Q .set 0                                ; [MS 1290] 0
; [MS 1291] NOTE: THIS ERROR COUNT TECHNIQUE WILL NOT WORK IF THERE ARE MORE
