        .byte "NEXT WITHOUT FO", 'R'|$80 ; [MS 1293]
ERRNF = 0                               ; [MS 1294] Q
Q .set 16                               ; [MS 1295] Q+16
        .byte "SYNTA", 'X'|$80          ; [MS 1296]
ERRSN = 16                              ; [MS 1297] Q
Q .set 22                               ; [MS 1298] Q+6
        .byte "RETURN WITHOUT GOSU", 'B'|$80 ; [MS 1299]
ERRRG = 22                              ; [MS 1300] Q
Q .set 42                               ; [MS 1301] Q+20
        .byte "OUT OF DAT", 'A'|$80     ; [MS 1302]
ERROD = 42                              ; [MS 1303] Q
Q .set 53                               ; [MS 1304] Q+11
        .byte "ILLEGAL QUANTIT", 'Y'|$80 ; [MS 1305]
ERRFC = 53                              ; [MS 1306] Q
Q .set 69                               ; [MS 1307] Q+16
        .byte "OVERFLO", 'W'|$80        ; [MS 1308]
ERROV = 69                              ; [MS 1309] Q
Q .set 77                               ; [MS 1310] Q+8
        .byte "OUT OF MEMOR", 'Y'|$80   ; [MS 1311]
ERROM = 77                              ; [MS 1312] Q
Q .set 90                               ; [MS 1313] Q+13
        .byte "UNDEF'D STATEMEN", 'T'|$80 ; [MS 1314]
ERRUS = 90                              ; [MS 1315] Q
