ERRDD = 120                             ; [MS 1321] Q
Q .set 133                              ; [MS 1322] Q+13
        .byte "DIVISION BY ZER", 'O'|$80 ; [MS 1323]
ERRDV0 = 133                            ; [MS 1324] Q
Q .set 149                              ; [MS 1325] Q+16
        .byte "ILLEGAL DIREC", 'T'|$80  ; [MS 1326]
ERRID = 149                             ; [MS 1327] Q
Q .set 163                              ; [MS 1328] Q+14
        .byte "TYPE MISMATC", 'H'|$80   ; [MS 1329]
ERRTM = 163                             ; [MS 1330] Q
Q .set 176                              ; [MS 1331] Q+13
        .byte "STRING TOO LON", 'G'|$80 ; [MS 1332]
ERRLS = 176                             ; [MS 1333] Q
Q .set 191                              ; [MS 1334] Q+15

        .byte "FORMULA TOO COMPLE", 'X'|$80 ; [MS 1339]
ERRST = 191                             ; [MS 1340] Q
Q .set 210                              ; [MS 1341] Q+19
        .byte "CAN'T CONTINU", 'E'|$80  ; [MS 1342]
ERRCN = 210                             ; [MS 1343] Q
