        .byte "UNDEF'D FUNCTIO", 'N'|$80 ; [MS 1345]
ERRUF = 224                             ; [MS 1346] Q

; [MS 1348]
; [MS 1349] NEEDED FOR MESSAGES IN ALL VERSIONS.
; [MS 1350]
ERR:                                    ; [MS 1351]
        .byte " ERROR"                  ; [MS 1351]
        .byte 0                         ; [MS 1352]
INTXT:                                  ; [MS 1353]
        .byte " IN "                    ; [MS 1353]
        .byte 0                         ; [MS 1354]
REDDY:                                  ; [MS 1355]
        .byte 13                        ; [MS 1355 ACRLF]
;       .byte 10                        ; [MS 1355 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line


        .byte "OK"                      ; [MS 1359]
        .byte 13                        ; [MS 1360 ACRLF]
;       .byte 10                        ; [MS 1360 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
        .byte 0                         ; [MS 1361]
BRKTXT:                                 ; [MS 1362]
        .byte 13                        ; [MS 1362 ACRLF]
;       .byte 10                        ; [MS 1362 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
        .byte "BREAK"                   ; [MS 1363]
