; [MS 1366] ==== GENERAL STORAGE MANAGEMENT ROUTINES. ====
; [MS 1367]
; [MS 1368] FIND A "FOR" ENTRY ON THE STACK VIA "VARPNT".
; [MS 1369]
FORSIZ = 2*ADDPRC+16                    ; [MS 1370]
FNDFOR:                                 ; [MS 1371]
        tsx                             ; [MS 1371] LOAD XREG WITH STK PNTR.
        inx                             ; [MS 1372]
        inx                             ; [MS 1372]
        inx                             ; [MS 1372]
        inx                             ; [MS 1372] IGNORE ADR(NEWSTT) AND RTS ADDR.
FFLOOP:                                 ; [MS 1373]
        lda 257,x                       ; [MS 1373] GET STACK ENTRY.
        cmp #FORTK                      ; [MS 1374] IS IT A "FOR" TOKEN?
        bne FFRTS                       ; [MS 1375] NO, NO "FOR" LOOPS WITH THIS PNTR.
        lda FORPNT+1                    ; [MS 1376] GET HIGH.
        bne CMPFOR                      ; [MS 1377]
        lda 258,x                       ; [MS 1378] PNTR IS ZERO, SO ASSUME THIS ONE.
        sta FORPNT                      ; [MS 1379]
        lda 259,x                       ; [MS 1380]
        sta FORPNT+1                    ; [MS 1381]
CMPFOR:                                 ; [MS 1382]
        cmp 259,x                       ; [MS 1382]
        bne ADDFRS                      ; [MS 1383] NOT THIS ONE.
        lda FORPNT                      ; [MS 1384] GET DOWN.
        cmp 258,x                       ; [MS 1385]
        beq FFRTS                       ; [MS 1386] WE GOT IT! WE GOT IT!
ADDFRS:                                 ; [MS 1387]
        txa                             ; [MS 1387]
        clc                             ; [MS 1388] ADD 16 TO X.
        adc #FORSIZ                     ; [MS 1389]
        tax                             ; [MS 1390] RESULT BACK INTO X.
        bne FFLOOP                      ; [MS 1391]
FFRTS:                                  ; [MS 1392]
        rts                             ; [MS 1392] RETURN TO CALLER.

; [MS 1394]
; [MS 1395] THIS IS THE BLOCK TRANSFER ROUTINE.
; [MS 1396] IT MAKES SPACE BY SHOVING EVERYTHING FORWARD.
; [MS 1397]
; [MS 1398] ON ENTRY:
; [MS 1399] [Y,A]=[HIGHDS]    (FOR REASON).
; [MS 1400] [HIGHDS]= DESTINATION OF [HIGH ADDRESS].
; [MS 1401] [LOWTR]= LOWEST ADDR TO BE TRANSFERRED.
; [MS 1402] [HIGHTR]= HIGHEST ADDR TO BE TRANSFERRED.
; [MS 1403]
; [MS 1404] A CHECK IS MADE TO ASCERTAIN THAT A REASONABLE
; [MS 1405] AMOUNT OF SPACE REMAINS BETWEEN THE BOTTOM
; [MS 1406] OF THE STRINGS AND THE HIGHEST LOCATION TRANSFERRED INTO.
; [MS 1407]
; [MS 1408] ON EXIT:
; [MS 1409] [LOWTR] ARE UNCHANGED.
; [MS 1410] [HIGHTR]=[LOWTR]-200 OCTAL.
; [MS 1411] [HIGHDS]=LOWEST ADDR TRANSFERRED INTO MINUS 200 OCTAL.
; [MS 1412]
BLTU:                                   ; [MS 1413]
        jsr REASON                      ; [MS 1413] ASCERTAIN THAT STRING SPACE WON'T
; [MS 1414] BE OVERRUN.
        sta STREND                      ; [MS 1415 STWD]
        sty STREND+1                    ; [MS 1415 STWD]
BLTUC:                                  ; [MS 1416]
        sec                             ; [MS 1416] PREPARE TO SUBTRACT.
        lda HIGHTR                      ; [MS 1417]
        sbc LOWTR                       ; [MS 1418] COMPUTE NUMBER OF THINGS TO MOVE.
        sta INDEX                       ; [MS 1419] SAVE FOR LATER.
        tay                             ; [MS 1420]
        lda HIGHTR+1                    ; [MS 1421]
        sbc LOWTR+1                     ; [MS 1422]
        tax                             ; [MS 1423] PUT IT IN A COUNTER REGISTER.
        inx                             ; [MS 1424] SO THAT COUNTER ALGORITHM WORKS.
        tya                             ; [MS 1425] SEE IF LOW PART OF COUNT IS ZERO.
        beq DECBLT                      ; [MS 1426] YES, GO START MOVING BLOCKS.
        lda HIGHTR                      ; [MS 1427] NO, MUST MODIFY BASE ADDR.
        sec                             ; [MS 1428]
        sbc INDEX                       ; [MS 1429] BORROW IS OFF SINCE [HIGHTR].GT.[LOWTR].
        sta HIGHTR                      ; [MS 1430] SAVE MODIFIED BASE ADDR.
        bcs BLT1                        ; [MS 1431] IF NO BORROW, GO SHOVE IT.
        dec HIGHTR+1                    ; [MS 1432] BORROW IMPLIES SUB 1 FROM HIGH ORDER.
        sec                             ; [MS 1433]
BLT1:                                   ; [MS 1434]
        lda HIGHDS                      ; [MS 1434] MOD BASE OF DEST ADDR.
        sbc INDEX                       ; [MS 1435]
        sta HIGHDS                      ; [MS 1436]
        bcs MOREN1                      ; [MS 1437] NO BORROW.
        dec HIGHDS+1                    ; [MS 1438] DECREMENT HIGH ORDER BYTE.
        bcc MOREN1                      ; [MS 1439] ALWAYS SKIP.
BLTLP:                                  ; [MS 1440]
        lda (HIGHTR),y                  ; [MS 1440] FETCH BYTE TO MOVE
        sta (HIGHDS),y                  ; [MS 1441] MOVE IT IN, MOVE IT OUT.
MOREN1:                                 ; [MS 1442]
        dey                             ; [MS 1442]
        bne BLTLP                       ; [MS 1443]
        lda (HIGHTR),y                  ; [MS 1444] MOVE LAST OF THE BLOCK.
        sta (HIGHDS),y                  ; [MS 1445]
DECBLT:                                 ; [MS 1446]
        dec HIGHTR+1                    ; [MS 1446]
        dec HIGHDS+1                    ; [MS 1447] START ON NEW BLOCKS.
        dex                             ; [MS 1448]
        bne MOREN1                      ; [MS 1449]
        rts                             ; [MS 1450] RETURN TO CALLER.

; [MS 1452]
; [MS 1453] THIS ROUTINE IS USED TO ASCERTAIN THAT A GIVEN
; [MS 1454] NUMBER OF LOCS REMAIN AVAILABLE FOR THE STACK.
; [MS 1455] THE CALL IS:
; [MS 1456] LDAI	NUMBER OF 2-BYTE ENTRIES NEEDED.
; [MS 1457] JSR	GETSTK
; [MS 1458]
; [MS 1459] THIS ROUTINE MUST BE CALLED BY ANY ROUTINE WHICH PUTS
; [MS 1460] AN ARBITRARY AMOUNT OF STUFF ON THE STACK,
; [MS 1461] I.E., ANY RECURSIVE ROUTINE LIKE "FRMEVL".
; [MS 1462] IT IS ALSO CALLED BY ROUTINES SUCH AS "GOSUB" AND "FOR"
; [MS 1463] WHICH MAKE PERMANENT ENTRIES ON THE STACK.
; [MS 1464]
; [MS 1465] ROUTINES WHICH MERELY USE AND FREE UP THE GUARANTEED
; [MS 1466] NUMLEV LOCATIONS NEED NOT CALL THIS.
; [MS 1467]
; [MS 1468]
; [MS 1469] ON EXIT:
; [MS 1470] [A] AND [X] HAVE BEEN MODIFIED.
; [MS 1471]
GETSTK:                                 ; [MS 1472]
        asl a                           ; [MS 1472] MULT [A] BY 2. NB, CLEARS C BIT.
        adc #2*NUMLEV+(3*ADDPRC)+13     ; [MS 1473] MAKE SURE 2*NUMLEV+13 LOCS
; [MS 1474] (13 BECAUSE OF FBUFFR)
        bcs OMERR                       ; [MS 1475] WILL REMAIN IN STACK.
        sta INDEX                       ; [MS 1476]
        tsx                             ; [MS 1477] GET STACKED.
        cpx INDEX                       ; [MS 1478] COMPARE.
        bcc OMERR                       ; [MS 1479] IF STACK.LE.INDEX1, OM.
        rts                             ; [MS 1480]

; [MS 1482]
; [MS 1483] [Y,A] IS A CERTAIN ADDRESS. "REASON" MAKES SURE
; [MS 1484] IT IS LESS THAN [FRETOP].
; [MS 1485]
REASON:                                 ; [MS 1486]
        cpy FRETOP+1                    ; [MS 1486]
        bcc REARTS                      ; [MS 1487]
        bne TRYMOR                      ; [MS 1488] GO GARB COLLECT.
        cmp FRETOP                      ; [MS 1489]
        bcc REARTS                      ; [MS 1490]
TRYMOR:                                 ; [MS 1491]
        pha                             ; [MS 1491]
        ldx #8+ADDPRC                   ; [MS 1492] IF TEMPF2 HAS ZERO IN BETWEEN.
        tya                             ; [MS 1493]
REASAV:                                 ; [MS 1494]
        pha                             ; [MS 1494]
        lda HIGHDS-1,x                  ; [MS 1495] SAVE HIGHDS ON STACK.
        dex                             ; [MS 1496]
        bpl REASAV                      ; [MS 1497] PUT 8 OF THEM ON STK.
        jsr GARBA2                      ; [MS 1498] GO GARB COLLECT.
        ldx #256-8-ADDPRC               ; [MS 1499]
REASTO:                                 ; [MS 1500]
        pla                             ; [MS 1500]
        sta HIGHDS+8+ADDPRC,x           ; [MS 1501] RESTORE AFTER GARB COLLECT.
        inx                             ; [MS 1502]
        bmi REASTO                      ; [MS 1503]
        pla                             ; [MS 1504]
        tay                             ; [MS 1505]
        pla                             ; [MS 1506] RESTORE A AND Y.
        cpy FRETOP+1                    ; [MS 1507] COMPARE HIGHS
        bcc REARTS                      ; [MS 1508]
        PINF $D412, ERROR         ; [OURS] [RM] $D412: ERROR, the error handler with X = the error number (Oregon Trail's & library JMPs here)
        bne OMERR                       ; [MS 1509] HIGHER IS BAD.
        cmp FRETOP                      ; [MS 1510] AND THE LOWS.
        bcs OMERR                       ; [MS 1511]
REARTS:                                 ; [MS 1512]
        rts                             ; [MS 1512]

; [MS 1515] ==== ERROR HANDLER, READY, TERMINAL INPUT, COMPACTIFY, NEW, REINIT. ====
OMERR:                                  ; [MS 1516]
        ldx #ERROM                      ; [MS 1516]
ERRNRM:                                 ; [MS 1517] Microsoft's ERROR; ours (ERROR, at the end) checks ONERR GOTO first

        lsr CNTWFL                      ; [MS 1519] FORCE OUTPUT.

ERRCRD:                                 ; [MS 1526]
        lda TRMPOS                      ; [MS 1526] [OURS] a return first only if the cursor is not at the left,
        beq ERRCR1                      ; [OURS] so no blank line before the message (Applesoft II manual, error format)
        jsr CRDO                        ; [MS 1526] OUTPUT CRLF.
ERRCR1:                                 ; [OURS]
        jsr OUTQST                      ; [MS 1527] PRINT A QUESTION MARK
; [MS 1532] OUTPUT IT.

GETERR:                                 ; [MS 1534]
        lda ERRTAB,x                    ; [MS 1534]
        pha                             ; [MS 1535]
        and #127                        ; [MS 1536] GET RID OF HIGH BIT.
        jsr OUTDO                       ; [MS 1537] OUTPUT IT.
        inx                             ; [MS 1538]
        pla                             ; [MS 1539] LAST CHAR OF MESSAGE?
        bpl GETERR                      ; [MS 1540] NO. GO GET NEXT AND OUTPUT IT.
TYPERR:                                 ; [MS 1541]
        jsr STKINI                      ; [MS 1541] RESET THE STACK AND FLAGS.
        lda #<ERR                       ; [MS 1542 LDWDI]
        ldy #>ERR                       ; [MS 1542 LDWDI] GET PNTR TO " ERROR".
ERRFIN:                                 ; [MS 1543]
        jsr STROUT                      ; [MS 1543] OUTPUT IT.
        ldy CURLIN+1                    ; [MS 1544]
        iny                             ; [MS 1545] WAS NUMBER 64000?
        beq READY                       ; [MS 1546] YES, DON'T TYPE LINE NUMBER.
        jsr INPRT                       ; [MS 1547]
READY:                                  ; [MS 1548]

        lsr CNTWFL                      ; [MS 1550] TURN OUTPUT BACK ON IF SUPRESSED
;       lda #<REDDY                     ; [MS 1551 LDWDI] [OURS] [RM] Applesoft prints no "OK"
;       ldy #>REDDY                     ; [MS 1551 LDWDI] SAY "OK". [OURS]

        lda TRMPOS                      ; [OURS] the "]" prompt starts a line of its own:
        beq MAIN                        ; [OURS] a return first only if the cursor is not at the left
        jsr CRDO                        ; [OURS]
; [MS 1555] NO INIT ERRORS POSSIBLE.
MAIN:                                   ; [MS 1556]
        ldx #']'|$80                    ; [OURS] Applesoft's "]" prompt, for program lines only
        jsr INLINP                      ; [MS 1556] [OURS] was jsr INLIN. GET A LINE FROM TERMINAL.
        stx TXTPTR                      ; [MS 1557 STXY]
        sty TXTPTR+1                    ; [MS 1557 STXY]
        jsr CHRGET                      ; [MS 1558]
        tax                             ; [MS 1559] SET ZERO FLAG BASED ON [A]
; [MS 1560] THIS DISTINGUISHES ":" AND 0
        beq MAIN                        ; [MS 1561] IF BLANK LINE, GET ANOTHER.
        ldx #255                        ; [MS 1562] SET DIRECT LINE NUMBER.
        stx CURLIN+1                    ; [MS 1563]
        bcc MAIN1                       ; [MS 1564] IS A LINE NUMBER. NOT DIRECT.
        jsr CRUNCH                      ; [MS 1565] COMPACTIFY.
        jmp GONE                        ; [MS 1566] EXECUTE IT.
MAIN1:                                  ; [MS 1567]
        jsr LINGET                      ; [MS 1567] READ LINE NUMBER INTO "LINNUM".
        jsr CRUNCH                      ; [MS 1568]
        sty COUNT                       ; [MS 1569] RETAIN CHARACTER COUNT.
        jsr FNDLIN                      ; [MS 1570]
        bcc NODEL                       ; [MS 1571] NO MATCH, SO DON'T DELETE.
        ldy #1                          ; [MS 1572]
        lda (LOWTR),y                   ; [MS 1573]
        sta INDEX1+1                    ; [MS 1574]
        lda VARTAB                      ; [MS 1575]
        sta INDEX1                      ; [MS 1576]
        lda LOWTR+1                     ; [MS 1577] SET TRANSFER TO.
        sta INDEX2+1                    ; [MS 1578]
        lda LOWTR                       ; [MS 1579]
        dey                             ; [MS 1580]
        sbc (LOWTR),y                   ; [MS 1581] COMPUTE NEGATIVE LENGTH.
        clc                             ; [MS 1582]
        adc VARTAB                      ; [MS 1583] COMPUTE NEW VARTAB.
        sta VARTAB                      ; [MS 1584]
        sta PRGEND                        ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        sta INDEX2                      ; [MS 1585] SET LOW OF TRANS TO.
        lda VARTAB+1                    ; [MS 1586]
        adc #255                        ; [MS 1587]
        sta VARTAB+1                    ; [MS 1588] COMPUTE HIGH OF VARTAB.
        sta PRGEND+1                      ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        sbc LOWTR+1                     ; [MS 1589] COMPUTE NUMBER OF BLOCKS TO MOVE.
        tax                             ; [MS 1590]
        sec                             ; [MS 1591]
        lda LOWTR                       ; [MS 1592]
        sbc VARTAB                      ; [MS 1593] COMPUTE OFFSET.
        tay                             ; [MS 1594]
        bcs QDECT1                      ; [MS 1595] IF VARTAB.LE.LOWTR,
        inx                             ; [MS 1596] DECR DUE TO CARRY, AND
        dec INDEX2+1                    ; [MS 1597] DECREMENT STORE SO CARRY WORKS.
QDECT1:                                 ; [MS 1598]
        clc                             ; [MS 1598]
        adc INDEX1                      ; [MS 1599]
        bcc MLOOP                       ; [MS 1600]
        dec INDEX1+1                    ; [MS 1601]
        clc                             ; [MS 1602] FOR LATER ADCQ
MLOOP:                                  ; [MS 1603]
        lda (INDEX1),y                  ; [MS 1603]
        sta (INDEX2),y                  ; [MS 1604]
        iny                             ; [MS 1605]
        bne MLOOP                       ; [MS 1606] BLOCK DONE?
        inc INDEX1+1                    ; [MS 1607]
        inc INDEX2+1                    ; [MS 1608]
        dex                             ; [MS 1609]
        bne MLOOP                       ; [MS 1610] DO ANOTHER BLOCK. ALWAYS.
NODEL:                                  ; [MS 1611]
        jsr RUNC                        ; [MS 1611] RESET ALL VARIABLE INFO SO GARBAGE
; [MS 1612] COLLECTION CAUSED BY REASON WILL WORK
        jsr LNKPRG                      ; [MS 1613] FIX UP THE LINKS
        lda BUF                         ; [MS 1614] SEE IF ANYTHNG THERE
        beq MAIN                        ; [MS 1615]
        clc                             ; [MS 1616]
        lda VARTAB                      ; [MS 1617]
        sta HIGHTR                      ; [MS 1618] SETUP HIGHTR.
        adc COUNT                       ; [MS 1619] ADD LENGTH OF LINE TO INSERT.
        sta HIGHDS                      ; [MS 1620] THIS GIVES DEST ADDR.
        ldy VARTAB+1                    ; [MS 1621]
        sty HIGHTR+1                    ; [MS 1622] SAME FOR HIGH ORDERS.
        bcc NODELC                      ; [MS 1623]
        iny                             ; [MS 1624]
NODELC:                                 ; [MS 1625]
        sty HIGHDS+1                    ; [MS 1625]
        jsr BLTU                        ; [MS 1626]

        lda LINNUM                      ; [MS 1628 LDWD]
        ldy LINNUM+1                    ; [MS 1628 LDWD] POSITION THE BINARY LINE NUMBER
        sta BUF-2                       ; [MS 1629 STWD]
        sty 0+(BUF-2)+1                 ; [MS 1629 STWD] IN FRONT OF BUF
        lda STREND                      ; [MS 1630 LDWD]
        ldy STREND+1                    ; [MS 1630 LDWD]
        sta VARTAB                      ; [MS 1631 STWD]
        sty VARTAB+1                    ; [MS 1631 STWD]
        sta PRGEND                      ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        sty PRGEND+1                    ; [OURS]
        ldy COUNT                       ; [MS 1632]
STOLOP:                                 ; [MS 1634] [OURS] was DEY / BPL STOLOP: a signed loop, so a line of 128 bytes or more was
        dey                             ; [MS 1633] never copied in (the Apple build takes 240-character lines; Applesoft stores up to 239)
        lda BUF-4,y                     ; [MS 1634]
        sta (LOWTR),y                   ; [MS 1635]
        tya                             ; [OURS] down to and including byte 0
        bne STOLOP                      ; [OURS]
FINI:                                   ; [MS 1638]
        jsr RUNC                        ; [MS 1638] DO CLEAR & SET UP STACK.
; [MS 1639] AND SET [TXTPTR] TO [TXTTAB]-1.
        jsr LNKPRG                      ; [MS 1640] FIX UP PROGRAM LINKS
        jmp MAIN                        ; [MS 1641]
LNKPRG:                                 ; [MS 1642]
        lda TXTTAB                      ; [MS 1642 LDWD]
        ldy TXTTAB+1                    ; [MS 1642 LDWD] SET [INDEX] TO [TXTTAB].
        sta INDEX                       ; [MS 1643 STWD]
        sty INDEX+1                     ; [MS 1643 STWD]
        clc                             ; [MS 1644]
; [MS 1645]
; [MS 1646] CHEAD GOES THROUGH PROGRAM STORAGE AND FIXES
; [MS 1647] UP ALL THE LINKS. THE END OF EACH LINE IS FOUND
; [MS 1648] BY SEARCHING FOR THE ZERO AT THE END.
; [MS 1649] THE DOUBLE ZERO LINK IS USED TO DETECT THE END OF THE PROGRAM.
; [MS 1650]
CHEAD:                                  ; [MS 1651]
        ldy #1                          ; [MS 1651]
        lda (INDEX),y                   ; [MS 1652] ARRIVED AT DOUBLE ZEROES?
        beq LNKRTS                      ; [MS 1653]
        ldy #4                          ; [MS 1654]
CZLOOP:                                 ; [MS 1655]
        iny                             ; [MS 1655] THERE IS AT LEAST ONE BYTE.
        lda (INDEX),y                   ; [MS 1656]
        bne CZLOOP                      ; [MS 1657] NO, CONTINUE SEARCHING.
        iny                             ; [MS 1658] GO ONE BEYOND.
        tya                             ; [MS 1659]
        adc INDEX                       ; [MS 1660]
        tax                             ; [MS 1661]
        ldy #0                          ; [MS 1662]
        sta (INDEX),y                   ; [MS 1663]
        lda INDEX+1                     ; [MS 1664]
        adc #0                          ; [MS 1665]
        iny                             ; [MS 1666]
        sta (INDEX),y                   ; [MS 1667]
        stx INDEX                       ; [MS 1668]
        sta INDEX+1                     ; [MS 1669]
        bcc CHEAD                       ; [MS 1670 BCCA] ALWAYS BRANCHES.
LNKRTS:                                 ; [MS 1671]
        rts                             ; [MS 1671]
; [MS 1672]
; [MS 1673] THIS IS THE LINE INPUT ROUTINE.
; [MS 1674] IT READS CHARACTERS INTO BUF USING BACKARROW (UNDERSCORE, OR
; [MS 1675] SHIFT O) AS THE DELETE CHARACTER AND @ AS THE
; [MS 1676] LINE DELETE CHARACTER. IF MORE THAN BUFLEN CHARACTERS
; [MS 1677] ARE TYPED, NO ECHOING IS DONE UNTIL A BACKARROW OR @ OR CR
; [MS 1678] IS TYPED. CONTROL-G WILL BE TYPED FOR EACH EXTRA CHARACTER.
; [MS 1679] THE ROUTINE IS ENTERED AT INLIN.
; [MS 1680]

INLIN:                                  ; [MS 1682]
        ldx #128                        ; [MS 1682] NO PROMPT CHARACTER
INLINP:                                 ; [OURS] enter here with the prompt character in X (MAIN)
        stx CQPRMP                      ; [MS 1683]
        jsr CQINLN                      ; [MS 1684] GET A LINE ONTO PAGE 2
        cpx #240-1                      ; [MS 1685]
        bcc GDBUFS                      ; [MS 1686] [OURS] was bcs, which clamps every line SHORTER than 239 to 239. NOT TOO MANY CHARACTERS
        ldx #240-1                      ; [MS 1687]
GDBUFS:                                 ; [MS 1688]
        lda #0                          ; [MS 1688] PUT A ZERO AT THE END
        sta BUF,x                       ; [MS 1689]
        txa                             ; [MS 1690]
        beq NOCHR                       ; [MS 1691]
LOPBHT:                                 ; [MS 1692]
        lda BUF-1,x                     ; [MS 1692]
        and #127                        ; [MS 1693]
        sta BUF-1,x                     ; [MS 1694]
        dex                             ; [MS 1695]
        bne LOPBHT                      ; [MS 1696]
NOCHR:                                  ; [MS 1697]
        lda #0                          ; [MS 1697]
        ldx #<((BUF-1))                 ; [MS 1698 LDXYI]
        ldy #>((BUF-1))                 ; [MS 1698 LDXYI] POINT AT THE BEGINNING
        rts                             ; [MS 1699]
; [MS 1741] GO TO FININL FAR, FAR AWAY.
INCHR:                                  ; [MS 1742]
; [MS 1744] FOR COMMODORE.

; [MS 1754] 1E5A FOR MOS TECH.

        jsr CQINCH                      ; [MS 1756] FD0C FOR APPLE COMPUTER.
        and #127                        ; [MS 1757]
; [MS 1759] GET A CHARACTER FROM SIMULATOR



        cmp #CONTW                      ; [MS 1765] SUPPRESS OUTPUT CHARACTER (^W).
        bne INCRTS                      ; [MS 1766] NO, RETURN.
        pha                             ; [MS 1767]
        lda CNTWFL                      ; [MS 1768 COM]
        eor #$FF                        ; [MS 1768 COM]
        sta CNTWFL                      ; [MS 1768 COM] COMPLEMENT ITS STATE.
        pla                             ; [MS 1769]
INCRTS:                                 ; [MS 1770]
        rts                             ; [MS 1770] END OF INCHR.

; [MS 1772]
; [MS 1773] ALL "RESERVED" WORDS ARE TRANSLATED INTO SINGLE
; [MS 1774] BYTES WITH THE MSB ON. THIS SAVES SPACE AND TIME
; [MS 1775] BY ALLOWING FOR TABLE DISPATCH DURING EXECUTION.
; [MS 1776] THEREFORE ALL STATEMENTS APPEAR TOGETHER IN THE
; [MS 1777] RESERVED WORD LIST IN THE SAME ORDER THEY
; [MS 1778] APPEAR IN STMDSP.
; [MS 1779]
BUFOFS .set 0                           ; [MS 1780] 0; THE AMOUNT TO OFFSET THE LOW BYTE
; [MS 1781] OF THE TEXT POINTER TO GET TO BUF
; [MS 1782] AFTER TXTPTR HAS BEEN SETUP TO POINT INTO BUF

BUFOFS .set 512                         ; [MS 1784] <BUF/256>*256
; [OURS] CRUNCH moved to the end of BASIC (before the hi-res entry points), so FNDLIN, CLEAR, STKINI,
; [OURS] FOR, NEWSTT and GOSUB can sit on Applesoft's addresses (Oregon Trail's & library calls them).
LISTRT:                                 ; [MS 1865]
        rts                             ; [MS 1865] RETURN TO CALLER.
        ALIGN $D61A                     ; [OURS] [RM] FNDLIN at Applesoft's $D61A (Oregon Trail's & library calls it)
;       PINJ $D665, RUNC                ; [OURS] [RM] $D665: get ready to RUN: TXTPTR to the start, variables cleared, A = 0 back (DOS 3.3 source ASRUN1: JSR $D665, STA ASONERR, JMP $D7D2; Oregon Trail's loader does the same)
; [MS 1866]
; [MS 1867] FNDLIN SEARCHES THE PROGRAM TEXT FOR THE LINE
; [MS 1868] WHOSE NUMBER IS PASSED IN "LINNUM".
; [MS 1869] THERE ARE TWO POSSIBLE RETURNS:
; [MS 1870]
; [MS 1871] 1) CARRY SET.
; [MS 1872] LOWTR POINTS TO THE LINK FIELD IN THE LINE
; [MS 1873] WHICH IS THE ONE SEARCHED FOR.
; [MS 1874]
; [MS 1875] 2) CARRY NOT SET.
; [MS 1876] LINE NOT FOUND. [LOWTR] POINTS TO THE LINE IN THE
; [MS 1877] PROGRAM GREATER THAN THE ONE SOUGHT AFTER.
; [MS 1878]
FNDLIN:                                 ; [MS 1879]
        lda TXTTAB                      ; [MS 1879 LDWX]
        ldx TXTTAB+1                    ; [MS 1879 LDWX] LOAD [X,A] WITH [TXTTAB]
FNDLNC:                                 ; [MS 1880]
        ldy #1                          ; [MS 1880]
        sta LOWTR                       ; [MS 1881 STWX]
        stx LOWTR+1                     ; [MS 1881 STWX] STORE [X,A] INTO LOWTR
        lda (LOWTR),y                   ; [MS 1882] SEE IF LINK IS 0
        beq FLINRT                      ; [MS 1883]
        iny                             ; [MS 1884]
        iny                             ; [MS 1885]
        lda LINNUM+1                    ; [MS 1886] COMP HIGH ORDERS OF LINE NUMBERS.
        cmp (LOWTR),y                   ; [MS 1887]
        bcc FLNRTS                      ; [MS 1888] NO SUCH LINE NUMBER.
        beq FNDLO1                      ; [MS 1889]
        dey                             ; [MS 1890]
        bne AFFRTS                      ; [MS 1891] ALWAYS BRANCH.
FNDLO1:                                 ; [MS 1892]
        lda LINNUM                      ; [MS 1892]
        dey                             ; [MS 1893]
        cmp (LOWTR),y                   ; [MS 1894] COMPARE LOW ORDERS.
        bcc FLNRTS                      ; [MS 1895] NO SUCH NUMBER.
        beq FLNRTS                      ; [MS 1896] GO TIT.
AFFRTS:                                 ; [MS 1897]
        dey                             ; [MS 1897]
        lda (LOWTR),y                   ; [MS 1898] FETCH LINK.
        tax                             ; [MS 1899]
        dey                             ; [MS 1900]
        lda (LOWTR),y                   ; [MS 1901]
        bcs FNDLNC                      ; [MS 1902] ALWAYS BRANCHES.
FLINRT:                                 ; [MS 1903]
        clc                             ; [MS 1903] C MAY BE HIGH.
FLNRTS:                                 ; [MS 1904]
        rts                             ; [MS 1904] RETURN TO CALLER.
; [MS 1905]
; [MS 1906] THE "NEW" COMMAND CLEARS THE PROGRAM TEXT AS WELL
; [MS 1907] AS VARIABLE SPACE.
; [MS 1908]
SCRATH:                                 ; [MS 1909]
        bne FLNRTS                      ; [MS 1909] MAKE SURE THERE IS A TERMINATOR.
SCRTCH:                                 ; [MS 1910]
        lda #0                          ; [MS 1910] GET A CLEARER.
        tay                             ; [MS 1911] SET UP INDEX.
        sta (TXTTAB),y                  ; [MS 1912] CLEAR	FIRST LINK.
        iny                             ; [MS 1913]
        sta (TXTTAB),y                  ; [MS 1914]
        lda TXTTAB                      ; [MS 1915]
        clc                             ; [MS 1916]
        adc #2                          ; [MS 1917]
        sta VARTAB                      ; [MS 1918] SETUP [VARTAB].
        sta PRGEND                        ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        lda TXTTAB+1                    ; [MS 1919]
        adc #0                          ; [MS 1920]
        sta VARTAB+1                    ; [MS 1921]
        sta PRGEND+1                      ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        FALLTO $D665                    ; [OURS] [RM] NOPs so RUNC lands on $D665 (DOS 3.3's and Oregon Trail's JSR $D665)
RUNC:                                   ; [MS 1922]
        jsr STXTPT                      ; [MS 1922]
        lda #0                          ; [MS 1923] SET ZERO FLAG
; [MS 1924]
; [MS 1925] THIS CODE IS FOR THE CLEAR COMMAND.
; [MS 1926]
CLEAR:                                  ; [MS 1927]
        bne STKRTS                      ; [MS 1927] SYNTAX ERROR IF NO TERMINATOR.
; [MS 1928]
; [MS 1929] CLEAR INITIALIZES THE VARIABLE AND
; [MS 1930] ARRAY SPACE BY RESETING ARYTAB (THE END OF SIMPLE VARIABLE SPACE)
; [MS 1931] AND STREND (THE END OF ARRAY STORAGE). IT FALLS INTO "STKINI"
; [MS 1932] WHICH RESETS THE STACK.
; [MS 1933]
CLEARC:                                 ; [MS 1934]
        lda MEMSIZ                      ; [MS 1934 LDWD]
        ldy MEMSIZ+1                    ; [MS 1934 LDWD] FREE UP STRING SPACE.
        sta FRETOP                      ; [MS 1935 STWD]
        sty FRETOP+1                    ; [MS 1935 STWD]
; [MS 1937] CLOSE ALL OPEN FILES.
        lda VARTAB                      ; [MS 1938 LDWD]
        ldy VARTAB+1                    ; [MS 1938 LDWD] LIBERATE THE
        sta ARYTAB                      ; [MS 1939 STWD]
        sty ARYTAB+1                    ; [MS 1939 STWD] VARIABLES AND
        sta STREND                      ; [MS 1940 STWD]
        sty STREND+1                    ; [MS 1940 STWD] ARRAYS.
FLOAD:                                  ; [MS 1941]
        jsr RESTOR                      ; [MS 1941] RESTORE DATA.
; [MS 1942]
; [MS 1943] STKINI RESETS THE STACK POINTER ELIMINATING
; [MS 1944] GOSUB AND FOR CONTEXT. STRING TEMPORARIES ARE FREED
; [MS 1945] UP, SUBFLG IS RESET. CONTINUING IS PROHIBITED.
; [MS 1946] AND A DUMMY ENTRY IS LEFT AT THE BOTTOM OF THE STACK SO "FNDFOR" WILL ALWAYS
; [MS 1947] FIND A NON-"FOR" ENTRY AT THE BOTTOM OF THE STACK.
; [MS 1948]
STKINI:                                 ; [MS 1949]
        ldx #TEMPST                     ; [MS 1949] INITIALIZE STRING TEMPORARIES.
        stx TEMPPT                      ; [MS 1950]
        pla                             ; [MS 1951] SETUP RETURN ADDRESS.
        tay                             ; [MS 1952]
        pla                             ; [MS 1953]
        ldx #507-257                    ; [MS 1954]
        txs                             ; [MS 1955]
        pha                             ; [MS 1956]
        tya                             ; [MS 1957]
        pha                             ; [MS 1958]
        lda #0                          ; [MS 1959]
        sta OLDTXT+1                    ; [MS 1960] DISALLOWING CONTINUING
        sta SUBFLG                      ; [MS 1961] ALLOW SUBSCRIPTS.
STKRTS:                                 ; [MS 1962]
        rts                             ; [MS 1962]

STXTPT:                                 ; [MS 1964]
        clc                             ; [MS 1964]
        lda TXTTAB                      ; [MS 1965]
        adc #255                        ; [MS 1966]
        sta TXTPTR                      ; [MS 1967]
        lda TXTTAB+1                    ; [MS 1968]
        adc #255                        ; [MS 1969]
        sta TXTPTR+1                    ; [MS 1970] SETUP TEXT POINTER.
        rts                             ; [MS 1971]
; [MS 1973] ==== THE "LIST" COMMAND. ====

LIST:                                   ; [MS 1975]
        bcc GOLST                       ; [MS 1975] IT IS A DIGIT.
        beq GOLST                       ; [MS 1976] IT IS A TERMINATOR.
        cmp #MINUTK                     ; [MS 1977] DASH PRECEDING?
        bne STKRTS                      ; [MS 1978] NO, SO SYNTAX ERROR.
GOLST:                                  ; [MS 1979]
        jsr LINGET                      ; [MS 1979] GET LINE NUMBER INTO NUMLIN.
        jsr FNDLIN                      ; [MS 1980] FIND LINE .GE. [NUMLIN].
        jsr CHRGOT                      ; [MS 1981] GET LAST CHARACTER.
        beq LSTEND                      ; [MS 1982] IF END OF LINE, # IS THE END.
        cmp #MINUTK                     ; [MS 1983] DASH?
        bne FLNRTS                      ; [MS 1984] IF NOT, SYNTAX ERROR.
        jsr CHRGET                      ; [MS 1985] GET NEXT CHAR.
        jsr LINGET                      ; [MS 1986] GET END #.
        bne FLNRTS                      ; [MS 1987] IF NOT TERMINATOR, ERROR.
LSTEND:                                 ; [MS 1988]
        pla                             ; [MS 1988]
        pla                             ; [MS 1989] GET RID OF "NEWSTT" RTS ADDR.
        lda LINNUM                      ; [MS 1990] SEE IF IT WAS EXISTENT.
        ora LINNUM+1                    ; [MS 1991]
        bne LIST4                       ; [MS 1992] IT WAS TYPED.
        lda #255                        ; [MS 1993]
        sta LINNUM                      ; [MS 1994]
        sta LINNUM+1                    ; [MS 1995] MAKE IT HUGE.
LIST4:                                  ; [MS 1996]
        ldy #1                          ; [MS 1996]

        lda (LOWTR),y                   ; [MS 1999] IS LINK ZERO?
        beq GRODY                       ; [MS 2000] YES, GO TO READY.

        jsr ISCNTC                      ; [MS 2002] LISTEN FOR CONT-C.
        jsr CRDO                        ; [MS 2003] PRINT CRLF TO START WITH.
        iny                             ; [MS 2004]
        lda (LOWTR),y                   ; [MS 2005]
        tax                             ; [MS 2006]
        iny                             ; [MS 2007]
        lda (LOWTR),y                   ; [MS 2008] GET LINE NUMBER.
        cmp LINNUM+1                    ; [MS 2009] SEE IF BEYOND LAST.
        bne TSTDUN                      ; [MS 2010] GO DETERMINE RELATION.
        cpx LINNUM                      ; [MS 2011] WAS EQUAL SO TEST LOW ORDER.
        beq TYPLIN                      ; [MS 2012] EQUAL, SO LIST IT.
TSTDUN:                                 ; [MS 2013]
        bcs GRODY                       ; [MS 2013] IF LINE IS GR THAN LAST, THEN DUNE.
TYPLIN:                                 ; [MS 2014]
        sty LSTPNT                      ; [MS 2014]
        jsr LINPRT                      ; [MS 2015] PRINT AS INT WITHOUT LEADING SPACE.
        lda #' '                        ; [MS 2016] ALWAYS PRINT SPACE AFTER NUMBER.
PRIT4:                                  ; [MS 2017]
        ldy LSTPNT                      ; [MS 2017] GET POINTER TO LINE BACK.
        and #127                        ; [MS 2018]
PLOOP:                                  ; [MS 2019]
        jsr OUTDO                       ; [MS 2019] PRINT CHAR.
; [MS 2023] IF QUOTE, COMPLEMENT FLAG.
PLOOP1:                                 ; [MS 2024]
        iny                             ; [MS 2024]
        beq GRODY                       ; [MS 2025] IF WE HAVE PRINTED 256 CHARACTERS
; [MS 2026] THE PROGRAM MUST BE MISFORMATED IN
; [MS 2027] MEMORY DUE TO A BAD LOAD OR BAD
; [MS 2028] HARDWARE. LET THE GUY RECOVER
        lda (LOWTR),y                   ; [MS 2029] GET NEXT CHAR. IS IT ZERO?
        bne QPLOP                       ; [MS 2030] YES. END OF LINE.
        tay                             ; [MS 2031]
        lda (LOWTR),y                   ; [MS 2032]
        tax                             ; [MS 2033]
        iny                             ; [MS 2034]
        lda (LOWTR),y                   ; [MS 2035]
        stx LOWTR                       ; [MS 2036]
        sta LOWTR+1                     ; [MS 2037]
        bne LIST4                       ; [MS 2038] BRANCH IF SOMETHING TO LIST.
GRODY:                                  ; [MS 2039]
        jmp READY                       ; [MS 2039]
; [MS 2040] IS IT A TOKEN?
QPLOP:                                  ; [MS 2041]
        bpl PLOOP                       ; [MS 2041] NO, HEAD FOR PRINTER.
; [MS 2046-2062] [OURS] the keyword is found through a pointer (the list is longer than 256 bytes), and
; printed with a space before and after it, as Applesoft lists ("10  HOME : PRINT"; the manual: an extra space after REM)
        sty LSTPNT                      ; [MS 2050] SAVE POINTER TO LINE.
        and #$7F                        ; [OURS]
        tax                             ; [OURS] X = how many keywords to pass
        lda #<RESLST                    ; [OURS]
        sta INDEX                       ; [OURS]
        lda #>RESLST                    ; [OURS]
        sta INDEX+1                     ; [OURS]
        txa                             ; [OURS]
        beq QPPRT                       ; [OURS]
QPSKP:                                  ; [OURS]
        ldy #0                          ; [OURS]
QPSK1:                                  ; [OURS]
        lda (INDEX),y                   ; [OURS]
        bmi QPSK2                       ; [OURS] its last letter
        iny                             ; [OURS]
        bne QPSK1                       ; [OURS] always
QPSK2:                                  ; [OURS]
        iny                             ; [OURS]
        tya                             ; [OURS]
        clc                             ; [OURS]
        adc INDEX                       ; [OURS]
        sta INDEX                       ; [OURS]
        bcc QPSK3                       ; [OURS]
        inc INDEX+1                     ; [OURS]
QPSK3:                                  ; [OURS]
        dex                             ; [OURS]
        bne QPSKP                       ; [OURS]
QPPRT:                                  ; [OURS]
        lda #' '                        ; [OURS] a space before the keyword
        jsr OUTDO                       ; [OURS]
        ldy #0                          ; [OURS]
QPPR1:                                  ; [OURS]
        lda (INDEX),y                   ; [MS 2059]
        bmi QPPR2                       ; [MS 2060] END OF RESERVED WORD.
        jsr OUTDO                       ; [MS 2061] PRINT IT.
        iny                             ; [OURS]
        bne QPPR1                       ; [OURS] always
QPPR2:                                  ; [OURS]
        jsr OUTDO                       ; [OURS] its last letter (OUTDO masks bit 7)
        lda #' '                        ; [OURS] and a space after
        jmp PRIT4                       ; [MS 2060] carry on with the line
; [MS 2064] ==== THE "FOR" STATEMENT. ====
; [MS 2065]
; [MS 2066] A "FOR" ENTRY ON THE STACK HAS THE FOLLOWING FORMAT:
; [MS 2067]
; [MS 2068] LOW ADDRESS
; [MS 2069] TOKEN (FORTK) 1 BYTE
; [MS 2070] A POINTER TO THE LOOP VARIABLE 2 BYTES
; [MS 2071] THE STEP 4+ADDPRC BYTES
; [MS 2072] A BYTE REFLECTING THE SIGN OF THE INCREMENT 1 BYTE
; [MS 2073] THE UPPER VALUE 4+ADDPRC BYTES
; [MS 2074] THE LINE NUMBER OF THE "FOR" STATEMENT 2 BYTES
; [MS 2075] A TEXT POINTER INTO THE "FOR" STATEMENT 2 BYTES
; [MS 2076] HIGH ADDRESS
; [MS 2077]
; [MS 2078] TOTAL 16+2*ADDPRC BYTES.
; [MS 2079]

        ALIGN $D766                     ; [OURS] [RM] FOR at Applesoft's $D766: Microsoft's FOR has Applesoft's length, so NEWSTT follows on $D7D2
FOR:                                    ; [MS 2081]
        lda #128                        ; [MS 2081] DON'T RECOGNIZE
        sta SUBFLG                      ; [MS 2082] SUBSCRIPTED VARIABLES.
        jsr LET                         ; [MS 2083] READ THE VARIABLE AND ASSIGN IT
; [MS 2084] THE CORRECT INITIAL VALUE AND STORE
; [MS 2085] A POINTER TO THE VARIABLE IN VARPNT.
        jsr FNDFOR                      ; [MS 2086] PNTR IS IN VARPNT, AND FORPNT.
        bne NOTOL                       ; [MS 2087] IF NO MATCH, DON'T ELIMINATE ANYTHING.
        txa                             ; [MS 2088] MAKE IT ARITHMETICAL.
        adc #FORSIZ-3                   ; [MS 2089] ELIMINATE ALMOST ALL.
        tax                             ; [MS 2090] NOTE C=1, THEN PLA, PLA.
        txs                             ; [MS 2091] MANIFEST.
NOTOL:                                  ; [MS 2092]
        pla                             ; [MS 2092] GET RID OF NEWSTT RETURN ADDRESS
        pla                             ; [MS 2093] IN CASE THIS IS A TOTALLY NEW ENTRY.
        lda #8+ADDPRC                   ; [MS 2094]
        jsr GETSTK                      ; [MS 2095] MAKE SURE 16 BYTES ARE AVAILABLE.
        jsr DATAN                       ; [MS 2096] GET A COUNT IN [Y] OF THE NUMBER OF
; [MS 2097] CHACRACTERS LEFT IN THE "FOR" STATEMENT
; [MS 2098] [TXTPTR] IS UNAFFECTED.
;       PINF $D7D2, NEWSTT              ; [OURS] [RM] $D7D2: NEWSTT, run the next statement (DOS 3.3 source ASRUN1; Oregon Trail's loader JMPs here)  (no longer needed: NEWSTT is on $D7D2 itself)
        clc                             ; [MS 2099] PREP TO ADD.
        tya                             ; [MS 2100] SAVE IT FOR PUSHING.
        adc TXTPTR                      ; [MS 2101]
        pha                             ; [MS 2102]
        lda TXTPTR+1                    ; [MS 2103]
        adc #0                          ; [MS 2104]
        pha                             ; [MS 2105]
        lda CURLIN+1                    ; [MS 2106 PSHWD]
        pha                             ; [MS 2106 PSHWD]
        lda CURLIN                      ; [MS 2106 PSHWD]
        pha                             ; [MS 2106 PSHWD] PUT LINE NUMBER ON STACK.
        lda #TOTK                       ; [MS 2107 SYNCHK]
        jsr SYNCHR                      ; [MS 2107 SYNCHK] "TO" IS NECESSARY.
        jsr CHKNUM                      ; [MS 2108] VALUE MUST BE A NUMBER.
        jsr FRMNUM                      ; [MS 2109] GET UPPER VALUE INTO FAC.
        lda FACSGN                      ; [MS 2110] PACK FAC.
        ora #127                        ; [MS 2111]
        and FACHO                       ; [MS 2112]
        sta FACHO                       ; [MS 2113] SET PACKED SIGN BIT.
        lda #<LDFONE                    ; [MS 2114 LDWDI]
        ldy #>LDFONE                    ; [MS 2114 LDWDI]
        sta INDEX1                      ; [MS 2115 STWD]
        sty INDEX1+1                    ; [MS 2115 STWD]
        jmp FORPSH                      ; [MS 2116] PUT FAC ONTO STACK, PACKED.
LDFONE:                                 ; [MS 2117]
        lda #<FONE                      ; [MS 2117 LDWDI]
        ldy #>FONE                      ; [MS 2117 LDWDI] PUT 1.0 INTO FAC.
        jsr MOVFM                       ; [MS 2118]
        jsr CHRGOT                      ; [MS 2119]
        cmp #STEPTK                     ; [MS 2120] A STEP IS GIVEN?
        bne ONEON                       ; [MS 2121] NO. ASSUME 1.0.
        jsr CHRGET                      ; [MS 2122] YES. ADVANCE POINTER.
        jsr FRMNUM                      ; [MS 2123] READ THE STEP.
ONEON:                                  ; [MS 2124]
        jsr SIGN                        ; [MS 2124] GET SIGN IN ACCA.
        jsr PUSHF                       ; [MS 2125] PUSH FAC ONTO STACK (THRU A).
        lda FORPNT+1                    ; [MS 2126 PSHWD]
        pha                             ; [MS 2126 PSHWD]
        lda FORPNT                      ; [MS 2126 PSHWD]
        pha                             ; [MS 2126 PSHWD] PUT PNTR TO VARIABLE ON STACK.
NXTCON:                                 ; [MS 2127]
        lda #FORTK                      ; [MS 2127] PUT A FORTK ONTO STACK.
        pha                             ; [MS 2128]
; [MS 2129] BNEA	NEWSTT		;SIMULATE BNE TO NEWSTT. JUST FALL IN.
; [MS 2131] ==== NEW STATEMENT FETCHER. ====
; [MS 2132]
; [MS 2133] BACK HERE FOR NEW STATEMENT. CHARACTER POINTED TO BY TXTPTR
; [MS 2134] IS ":" OR END-OF-LINE. THE ADDRESS OF THIS LOC IS LEFT
; [MS 2135] ON THE STACK WHEN A STATEMENT IS EXECUTED SO THAT
; [MS 2136] IT CAN MERELY DO A RTS WHEN IT IS DONE.
; [MS 2137]
NEWSTT:                                 ; [MS 2138]
        tsx                             ; [OURS] [RM] the stack pointer before each statement in $F8 (Applesoft II manual,
        stx REMSTK                      ; [OURS] [RM] Appendix L: $F4-$F8 ONERR pointers; Oregon Trail's library does the same, then JMPs to $D7D8)
        jsr ISCNTC                      ; [MS 2139] LISTEN FOR CONTROL-C.
NEWSTC:                                 ; [OURS] [RM] $D7D8: the next statement, without the stack save or Ctrl-C check
        lda TXTPTR                      ; [MS 2140 LDWD]
        ldy TXTPTR+1                    ; [MS 2140 LDWD] LOOK AT CURRENT CHARACTER.

        cpy #2                          ; [MS 2142] SEE IF IT WAS DIRECT BY CHECK FOR BUF'S PAGE NUMBER
        beq DIRCON                      ; [MS 2143]
        sta OLDTXT                      ; [MS 2144 STWD]
        sty OLDTXT+1                    ; [MS 2144 STWD] SAVE IN CASE OF RESTART BY INPUT.
DIRCON:                                 ; [MS 2145]
        ldy #0                          ; [MS 2146]

        lda (TXTPTR),y                  ; [MS 2148]
        bne MORSTS                      ; [MS 2149] NOT NULL -- CHECK WHAT IT IS
        ldy #2                          ; [MS 2150] LOOK AT LINK.
        lda (TXTPTR),y                  ; [MS 2151] IS LINK 0?
        clc                             ; [MS 2152] CLEAR CARRY FOR ENDCON AND MATH THAT FOLLOWS
        bne *+5                         ; [MS 2153 JEQ]
        jmp ENDCON                      ; [MS 2153 JEQ] YES - RAN OFF THE END.
        iny                             ; [MS 2154] PUT LINE NUMBER IN CURLIN.
        lda (TXTPTR),y                  ; [MS 2155]
        sta CURLIN                      ; [MS 2156]
        iny                             ; [MS 2157]
        lda (TXTPTR),y                  ; [MS 2158]
        sta CURLIN+1                    ; [MS 2159]
        tya                             ; [MS 2160]
        adc TXTPTR                      ; [MS 2161]
        sta TXTPTR                      ; [MS 2162]
        bcc GONE                        ; [MS 2163]
        inc TXTPTR+1                    ; [MS 2164]
GONE:                                   ; [MS 2165]
        jsr CHRGET                      ; [MS 2165] GET THE STATEMENT TYPE.
        jsr GONE3                       ; [MS 2166]
GONERT:                                 ; [OURS] GONE3's return: HANDLERR finds the failing statement's stack level by it
        jmp NEWSTT                      ; [MS 2167]
GONE3:                                  ; [MS 2168]
        beq ISCRTS                      ; [MS 2168] IF TERMINATOR, TRY AGAIN.
; [MS 2169] NO NEED TO SET UP CARRY SINCE IT WILL
; [MS 2170] BE ON IF NON-NUMERIC AND NUMERICS
; [MS 2171] WILL CAUSE A SYNTAX ERROR LIKE THEY SHOULD
GONE2:                                  ; [MS 2172]
        sbc #ENDTK                      ; [MS 2172] " ON ... GOTO AND GOSUB" COME HERE.
        bcc GLET                        ; [MS 2173]
        cmp #SCRATK-ENDTK+1             ; [MS 2174]
        bcs SNERRX                      ; [MS 2175] SOME RES'D WORD BUT NOT
; [MS 2176] A STATEMENT RES'D WORD.
        asl a                           ; [MS 2177] MULTIPLY BY TWO.
        tay                             ; [MS 2178] MAKE AN INDEX.
        lda STMDSP+1,y                  ; [MS 2179]
        pha                             ; [MS 2180]
        lda STMDSP,y                    ; [MS 2181]
        pha                             ; [MS 2182] PUT DISP ADDR ONTO STACK.
        jmp CHRGET                      ; [MS 2183]
GLET:                                   ; [MS 2184]
        jmp LET                         ; [MS 2184] MUST BE A LET
MORSTS:                                 ; [MS 2185]
        cmp #':'                        ; [MS 2185]
        beq GONE                        ; [MS 2186] IF A ":" CONTINUE STATEMENT
SNERR1:                                 ; [MS 2187]
        jmp SNERR                       ; [MS 2187] NEITHER 0 OR ":" SO SYNTAX ERROR
SNERRX:                                 ; [MS 2188]
        jmp SNERR                       ; [OURS] Applesoft has no GO keyword, so no GO TO form (Microsoft's lines below are unused)
;       cmp #GOTK-ENDTK                 ; [MS 2188] [OURS] unused (no GO TO)
;       bne SNERR1                      ; [MS 2189] [OURS] unused (no GO TO)
;       jsr CHRGET                      ; [MS 2190] READ IN THE CHARACTER AFTER "GO " [OURS] unused (no GO TO)
;       lda #TOTK                       ; [MS 2191 SYNCHK] [OURS] unused (no GO TO)
;       jsr SYNCHR                      ; [MS 2191 SYNCHK] [OURS] unused (no GO TO)
;       jmp GOTO                        ; [MS 2192] [OURS] unused (no GO TO)
; [MS 2194] ==== RESTORE,STOP,END,CONTINUE,NULL,CLEAR. ====

RESTOR:                                 ; [MS 2196]
        sec                             ; [MS 2196]
        lda TXTTAB                      ; [MS 2197]
        sbc #1                          ; [MS 2198]
        ldy TXTTAB+1                    ; [MS 2199]
        bcs RESFIN                      ; [MS 2200]
        dey                             ; [MS 2201]
RESFIN:                                 ; [MS 2202]
        sta DATPTR                      ; [MS 2202 STWD]
        sty DATPTR+1                    ; [MS 2202 STWD] READ FINISHES COME TO "RESFIN".
ISCRTS:                                 ; [MS 2203]
        rts                             ; [MS 2203]


; [MS 2218] WAS IT A CONTROL-C??


ISCNTC:                                 ; [MS 2221]
        lda $C000                       ; [MS 2221] CHECK THE CHARACTER
        cmp #$83                        ; [MS 2222]
        beq ISCCAP                      ; [MS 2223]
        rts                             ; [MS 2224]
ISCCAP:                                 ; [MS 2225]
        jsr INCHR                       ; [MS 2225]
        cmp #$03                        ; [MS 2226] [OURS] was #$83: INCHR has already cleared bit 7, so Ctrl-C never matched
STOP:                                   ; [MS 2227]
        bcs STOPC                       ; [MS 2227] MAKE [C] NONZERO AS A FLAG.
END:                                    ; [MS 2228]
        clc                             ; [MS 2228]
STOPC:                                  ; [MS 2229]
        bne CONTRT                      ; [MS 2229] RETURN IF NOT CONT-C OR
; [MS 2230] IF NO TERMINATOR FOR STOP OR END.
; [MS 2231] [C]=0 SO WILL NOT PRINT "BREAK".
        lda TXTPTR                      ; [MS 2232 LDWD]
        ldy TXTPTR+1                    ; [MS 2232 LDWD]

        ldx CURLIN+1                    ; [MS 2234]
        inx                             ; [MS 2235]
        beq DIRIS                       ; [MS 2236]
        sta OLDTXT                      ; [MS 2237 STWD]
        sty OLDTXT+1                    ; [MS 2237 STWD]
STPEND:                                 ; [MS 2238]
        lda CURLIN                      ; [MS 2238 LDWD]
        ldy CURLIN+1                    ; [MS 2238 LDWD]
        sta OLDLIN                      ; [MS 2239 STWD]
        sty OLDLIN+1                    ; [MS 2239 STWD]
DIRIS:                                  ; [MS 2240]
        pla                             ; [MS 2240] POP OFF NEWSTT ADDR.
        pla                             ; [MS 2241]
ENDCON:                                 ; [MS 2242]
        lda #<BRKTXT                    ; [MS 2242 LDWDI]
        ldy #>BRKTXT                    ; [MS 2242 LDWDI]

        ldx #0                          ; [MS 2244]
        stx CNTWFL                      ; [MS 2245]
        bcc GORDY                       ; [MS 2246] CARRY CLEAR SO DON'T PRINT "BREAK".
        jmp ERRFIN                      ; [MS 2247]
GORDY:                                  ; [MS 2248]
        jmp READY                       ; [MS 2248] TYPE "READY".


CONT:                                   ; [MS 2255]
        bne CONTRT                      ; [MS 2255] MAKE SURE THERE IS A TERMINATOR.
        ldx #ERRCN                      ; [MS 2256] CONTINUE ERROR.
        ldy OLDTXT+1                    ; [MS 2257] A STORED TXTPTR OF ZERO IS SETUP
; [MS 2258] BY STKINI AND INDICATES THERE IS
; [MS 2259] NOTHING TO CONTINUE.
        bne *+5                         ; [MS 2260 JEQ]
        jmp ERROR                       ; [MS 2260 JEQ] "STOP", "END", TYPING CRLF TO
; [MS 2261] "INPUT" AND  ^C SETUP OLDTXT.
        lda OLDTXT                      ; [MS 2262]
        sta TXTPTR                      ; [MS 2263 STWD]
        sty TXTPTR+1                    ; [MS 2263 STWD]
        lda OLDLIN                      ; [MS 2264 LDWD]
        ldy OLDLIN+1                    ; [MS 2264 LDWD]
        sta CURLIN                      ; [MS 2265 STWD]
        sty CURLIN+1                    ; [MS 2265 STWD]
CONTRT:                                 ; [MS 2266]
        rts                             ; [MS 2266] RETURN TO CALLER.


; [MS 2279] ==== LOAD AND SAVE SUBROUTINES. ====

; [OURS] SAVE and LOAD moved to the end of BASIC (after HFNS), to make room for pinned entry points.
; [MS 2365] ==== RUN,GOTO,GOSUB,RETURN. ====
RUN:                                    ; [MS 2366]
        bne *+5                         ; [MS 2366 JEQ]
        jmp RUNC                        ; [MS 2366 JEQ] IF NO LINE # ARGUMENT.
        jsr CLEARC                      ; [MS 2367] CLEAN UP -- RESET THE STACK.
        jmp RUNC2                       ; [MS 2368] MUST REPLACE RTS ADDR.
; [MS 2369]
; [MS 2370] A GOSUB ENTRY ON THE STACK HAS THE FOLLOWING FORMAT:
; [MS 2371]
; [MS 2372] LOW ADDRESS:
; [MS 2373] THE GOSUTK ONE BYTE
; [MS 2374] THE LINE NUMBER OF THE GOSUB STATEMENT TWO BYTES
; [MS 2375] A POINTER INTO THE TEXT OF THE GOSUB TWO BYTES
; [MS 2376]
; [MS 2377] HIGH ADDRESS.
; [MS 2378]
; [MS 2379] TOTAL FIVE BYTES.
; [MS 2380]
        ALIGN $D921                     ; [OURS] [RM] GOSUB at Applesoft's $D921: GOTO follows on $D93E (Oregon Trail's library JSRs to $D941)
GOSUB:                                  ; [MS 2381]
        lda #3                          ; [MS 2381]
        jsr GETSTK                      ; [MS 2382] MAKE SURE THERE IS ROOM.
        lda TXTPTR+1                    ; [MS 2383 PSHWD]
        pha                             ; [MS 2383 PSHWD]
        lda TXTPTR                      ; [MS 2383 PSHWD]
        pha                             ; [MS 2383 PSHWD] PUSH ON THE TEXT POINTER.
        lda CURLIN+1                    ; [MS 2384 PSHWD]
        pha                             ; [MS 2384 PSHWD]
        lda CURLIN                      ; [MS 2384 PSHWD]
        pha                             ; [MS 2384 PSHWD] PUSH ON THE CURRENT LINE NUMBER.
        lda #GOSUTK                     ; [MS 2385]
        pha                             ; [MS 2386] PUSH ON A GOSUB TOKEN.
RUNC2:                                  ; [MS 2387]
        jsr CHRGOT                      ; [MS 2387] GET CHARACTER AND SET CODES FOR LINGET.
        jsr GOTO                        ; [MS 2388] USE RTS SCHEME TO "NEWSTT".
        jmp NEWSTT                      ; [MS 2389]

        .assert GOSUB = $D921, error, "GOSUB moved"
GOTO:                                   ; [MS 2391]
        jsr LINGET                      ; [MS 2391] PICK UP THE LINE NUMBER IN "LINNUM".
GOTOLN:                                 ; [OURS] [RM] $D941: GOTO the line already in LINNUM (Oregon Trail's library JSRs here)
        jsr REMN                        ; [MS 2392] SKIP TO END OF LINE.
        lda CURLIN+1                    ; [MS 2393]
        cmp LINNUM+1                    ; [MS 2394]
        bcs LUK4IT                      ; [MS 2395]
        tya                             ; [MS 2396]
        sec                             ; [MS 2397]
        adc TXTPTR                      ; [MS 2398]
        ldx TXTPTR+1                    ; [MS 2399]
        bcc LUKALL                      ; [MS 2400]
        inx                             ; [MS 2401]
        bcs LUKALL                      ; [MS 2402 BCSA] ALWAYS GOES.
LUK4IT:                                 ; [MS 2403]
        lda TXTTAB                      ; [MS 2403 LDWX]
        ldx TXTTAB+1                    ; [MS 2403 LDWX]
LUKALL:                                 ; [MS 2404]
        jsr FNDLNC                      ; [MS 2404] [X,A] ARE ALL SET UP.
QFOUND:                                 ; [MS 2405]
        bcc USERR                       ; [MS 2405] GOTO LINE IS NONEXISTANT.
        lda LOWTR                       ; [MS 2406]
        sbc #1                          ; [MS 2407]
        sta TXTPTR                      ; [MS 2408]
        lda LOWTR+1                     ; [MS 2409]
        sbc #0                          ; [MS 2410]
        sta TXTPTR+1                    ; [MS 2411]
GORTS:                                  ; [MS 2412]
        rts                             ; [MS 2412] PROCESS THE STATEMENT.
; [MS 2413]
; [MS 2414] "RETURN" RESTORES THE LINE NUMBER AND TEXT PNTR FROM THE STACK
; [MS 2415] AND ELIMINATES ALL THE "FOR" ENTRIES IN FRONT OF THE "GOSUB" ENTRY.
; [MS 2416]
RETURN:                                 ; [MS 2417]
        bne GORTS                       ; [MS 2417] NO TERMINATOR=BLOW HIM UP.
        lda #255                        ; [MS 2418]
        sta FORPNT+1                    ; [MS 2419] MAKE SURE THE VARIABLE'S PNTR
; [MS 2420] NEVER GETS MATCHED.
        jsr FNDFOR                      ; [MS 2421] GO PAST ALL THE "FOR" ENTRIES.
        txs                             ; [MS 2422]
        cmp #GOSUTK                     ; [MS 2423] RETURN WITHOUT GOSUB?
        beq RETU1                       ; [MS 2424]
        ldx #ERRRG                      ; [MS 2425]
        .byte $2C                       ; [MS 2426 SKIP2]
USERR:                                  ; [MS 2427]
        ldx #ERRUS                      ; [MS 2427] NO MATCH SO "US" ERROR.
        jmp ERROR                       ; [MS 2428] YES.
SNERR2:                                 ; [MS 2429]
        jmp SNERR                       ; [MS 2429]
RETU1:                                  ; [MS 2430]
        pla                             ; [MS 2430] REMOVE GOSUTK.
        pla                             ; [MS 2431 PULWD]
        sta CURLIN                      ; [MS 2431 PULWD]
        pla                             ; [MS 2431 PULWD]
        sta CURLIN+1                    ; [MS 2431 PULWD] GET LINE NUMBER "GOSUB" WAS FROM.
        pla                             ; [MS 2432 PULWD]
        sta TXTPTR                      ; [MS 2432 PULWD]
        pla                             ; [MS 2432 PULWD]
        sta TXTPTR+1                    ; [MS 2432 PULWD] GET TEXT PNTR FROM "GOSUB".
DATA:                                   ; [MS 2433]
        jsr DATAN                       ; [MS 2433] SKIP TO END OF STATEMENT,
; [MS 2434] SINCE WHEN "GOSUB" STUCK THE TEXT  PNTR
; [MS 2435] ONTO THE STACK, THE LINE NUMBER ARG
; [MS 2436] HADN'T BEEN READ YET.
ADDON:                                  ; [MS 2437]
        tya                             ; [MS 2437]
        clc                             ; [MS 2438]
        adc TXTPTR                      ; [MS 2439]
        sta TXTPTR                      ; [MS 2440]
        bcc REMRTS                      ; [MS 2441]
        inc TXTPTR+1                    ; [MS 2442]
REMRTS:                                 ; [MS 2443]
        rts                             ; [MS 2443] "NEWSTT" RTS ADDR IS STILL THERE.

DATAN:                                  ; [MS 2445]
        ldx #':'                        ; [MS 2445] "DATA" TERMINATES ON ":" AND NULL.
        .byte $2C                       ; [MS 2446 SKIP2]
REMN:                                   ; [MS 2447]
        ldx #0                          ; [MS 2447] THE ONLY TERMINATOR IS NULL.
        stx CHARAC                      ; [MS 2448] PRESERVE IT.
        ldy #0                          ; [MS 2449] THIS MAKES CHARAC=0 AFTER SWAP.
        sty ENDCHR                      ; [MS 2450]
EXCHQT:                                 ; [MS 2451]
        lda ENDCHR                      ; [MS 2451]
        ldx CHARAC                      ; [MS 2452]
        sta CHARAC                      ; [MS 2453]
        stx ENDCHR                      ; [MS 2454]
REMER:                                  ; [MS 2455]
        lda (TXTPTR),y                  ; [MS 2455]
        beq REMRTS                      ; [MS 2456] NULL ALWAYS TERMINATES.
        cmp ENDCHR                      ; [MS 2457] IS IT THE OTHER TERMINATOR?
        beq REMRTS                      ; [MS 2458] YES, IT'S FINISHED.
        iny                             ; [MS 2459] PROGRESS TO NEXT CHARACTER.
        cmp #34                         ; [MS 2460] IS IT A QUOTE?
        bne REMER                       ; [MS 2461] NO, JUST CONTINUE.
        beq EXCHQT                      ; [MS 2462 BEQA] YES, TIME TO TRADE.
; [MS 2464] ==== "IF ... THEN" CODE. ====
IF:                                     ; [MS 2465]
        jsr FRMEVL                      ; [MS 2465] EVALUATE A FORMULA.
        jsr CHRGOT                      ; [MS 2466] GET CURRENT CHARACTER.
        cmp #GOTOTK                     ; [MS 2467] IS TERMINATING CHARACTER A GOTOTK?
        beq OKGOTO                      ; [MS 2468] YES.
        lda #THENTK                     ; [MS 2469 SYNCHK]
        jsr SYNCHR                      ; [MS 2469 SYNCHK] NO, IT MUST BE "THEN".
OKGOTO:                                 ; [MS 2470]
        lda FACEXP                      ; [MS 2470] 0=FALSE. ALL OTHERS TRUE.
        bne DOCOND                      ; [MS 2471] TRUE !
REM:                                    ; [MS 2472]
        jsr REMN                        ; [MS 2472] SKIP REST OF STATEMENT.
        beq ADDON                       ; [MS 2473 BEQA] WILL ALWAYS BRANCH.
DOCOND:                                 ; [MS 2474]
        jsr CHRGOT                      ; [MS 2474] TEST CURRENT CHARACTER.
        bcs DOCO                        ; [MS 2475] IF A NUMBER, GOTO IT.
        jmp GOTO                        ; [MS 2476]
DOCO:                                   ; [MS 2477]
        jmp GONE3                       ; [MS 2477] INTERPRET NEW STATEMENT.
; [MS 2479] ==== "ON ... GO TO ..." CODE. ====
ONGOTO:                                 ; [MS 2480]
        jsr GETBYT                      ; [MS 2480] GET VALUE IN FACLO.
        pha                             ; [MS 2481] SAVE FOR LATER.
        cmp #GOSUTK                     ; [MS 2482] AN "ON ... GOSUB" PERHAPS?
        beq ONGLOP                      ; [MS 2483] YES.
SNERR3:                                 ; [MS 2484]
        cmp #GOTOTK                     ; [MS 2484] MUST BE "GOTOTK".
        bne SNERR2                      ; [MS 2485]
ONGLOP:                                 ; [MS 2486]
        dec FACLO                       ; [MS 2486]
        bne ONGLP1                      ; [MS 2487] SKIP ANOTHER LINE NUMBER.
        pla                             ; [MS 2488] GET DISPATCH CHARACTER.
        jmp GONE2                       ; [MS 2489]
ONGLP1:                                 ; [MS 2490]
        jsr CHRGET                      ; [MS 2490] ADVANCE AND SET CODES.
        jsr LINGET                      ; [MS 2491]
        cmp #44                         ; [MS 2492] IS IT A COMMA?
        beq ONGLOP                      ; [MS 2493]
        pla                             ; [MS 2494] REMOVE STACK ENTRY (TOKEN).
ONGRTS:                                 ; [MS 2495]
        rts                             ; [MS 2495] EITHER END-OF-LINE OR SYNTAX ERROR.
; [MS 2497] ==== LINGET -- READ A LINE NUMBER INTO LINNUM ====
; [MS 2498]
; [MS 2499] "LINGET" READS A LINE NUMBER FROM THE CURRENT TEXT POSITION.
; [MS 2500]
; [MS 2501] LINE NUMBERS RANGE FROM 0 TO 64000-1.
; [MS 2502]
; [MS 2503] THE ANSWER IS RETURNED IN "LINNUM".
; [MS 2504] "TXTPTR" IS UPDATED TO POINT TO THE TERMINATING CHARCTER
; [MS 2505] AND [A] = THE TERMINATING CHARACTER WITH CONDITION
; [MS 2506] CODES SET UP TO REFLECT ITS VALUE.
; [MS 2507]
LINGET:                                 ; [MS 2508]
        ldx #0                          ; [MS 2508]
        stx LINNUM                      ; [MS 2509] INITIALIZE LINE NUMBER TO ZERO.
        stx LINNUM+1                    ; [MS 2510]
MORLIN:                                 ; [MS 2511]
        bcs ONGRTS                      ; [MS 2511] IT IS NOT A DIGIT.
        sbc #'0'-1                      ; [MS 2512] -1 SINCE C=0.
        sta CHARAC                      ; [MS 2513] SAVE CHARACTER.
        lda LINNUM+1                    ; [MS 2514]
        sta INDEX                       ; [MS 2515]
        cmp #25                         ; [MS 2516] LINE NUMBER WILL BE .LT. 64000?
        bcs SNERR3                      ; [MS 2517]
        lda LINNUM                      ; [MS 2518]
        asl a                           ; [MS 2519] MULTIPLY BY 10.
        rol INDEX                       ; [MS 2520]
        asl a                           ; [MS 2521]
        rol INDEX                       ; [MS 2522]
        adc LINNUM                      ; [MS 2523]
        sta LINNUM                      ; [MS 2524]
        lda INDEX                       ; [MS 2525]
        adc LINNUM+1                    ; [MS 2526]
        sta LINNUM+1                    ; [MS 2527]
        asl LINNUM                      ; [MS 2528]
        rol LINNUM+1                    ; [MS 2529]
        lda LINNUM                      ; [MS 2530]
        adc CHARAC                      ; [MS 2531] ADD IN DIGIT.
        sta LINNUM                      ; [MS 2532]
        bcc NXTLGC                      ; [MS 2533]
        inc LINNUM+1                    ; [MS 2534]
NXTLGC:                                 ; [MS 2535]
        jsr CHRGET                      ; [MS 2535]
        jmp MORLIN                      ; [MS 2536]

; [MS 2539] ==== "LET" CODE. ====
        ALIGN $DA46                     ; [OURS] [RM] LET at Applesoft's $DA46: Microsoft's LET has Applesoft's length, so INPCOM
                                        ; [OURS] lands on $DA7B (Oregon Trail's & INP jumps there) and PRINT on $DAD5
LET:                                    ; [MS 2540]
        jsr PTRGET                      ; [MS 2540] GET PNTR TO VARIABLE INTO "VARPNT".
        sta FORPNT                      ; [MS 2541 STWD]
        sty FORPNT+1                    ; [MS 2541 STWD] PRESERVE POINTER.
        lda #EQULTK                     ; [MS 2542 SYNCHK]
        jsr SYNCHR                      ; [MS 2542 SYNCHK] "=" IS NECESSARY.

        lda INTFLG                      ; [MS 2544] SAVE FOR LATER.
        pha                             ; [MS 2545]
        lda VALTYP                      ; [MS 2546] RETAIN THE VARIABLE'S VALUE TYPE.
        pha                             ; [MS 2547]
        jsr FRMEVL                      ; [MS 2548] GET VALUE OF FORMULA INTO "FAC".
        pla                             ; [MS 2549]
        rol a                           ; [MS 2550] CARRY SET FOR STRING, OFF FOR
; [MS 2551] NUMERIC.
        jsr CHKVAL                      ; [MS 2552] MAKE SURE "VALTYP" MATCHES CARRY.
; [MS 2553] AND SET ZERO FLAG FOR NUMERIC.
        bne COPSTR                      ; [MS 2554] IF NUMERIC, COPY IT.
COPNUM:                                 ; [MS 2555]

        pla                             ; [MS 2557] GET NUMBER TYPE.
QINTGR:                                 ; [MS 2558]
        bpl COPFLT                      ; [MS 2558] STORE A FLTING NUMBER.
        jsr ROUND                       ; [MS 2559] ROUND INTEGER.
        jsr AYINT                       ; [MS 2560] MAKE 2-BYTE NUMBER.
        ldy #0                          ; [MS 2561]
        lda FACMO                       ; [MS 2562] GET HIGH.
        sta (FORPNT),y                  ; [MS 2563] STORE IT.
        iny                             ; [MS 2564]
        lda FACLO                       ; [MS 2565] GET LOW.
        sta (FORPNT),y                  ; [MS 2566]
        rts                             ; [MS 2567]
COPFLT:                                 ; [MS 2568]
        jmp MOVVF                       ; [MS 2568] PUT NUMBER @FORPNT.

COPSTR:                                 ; [MS 2570]
        pla                             ; [MS 2571] IF STRING, NO INTFLG.
INPCOM:                                 ; [MS 2572]
; [MS 2614] ADD IN DIGIT TO FAC.

GETSPT:                                 ; [MS 2616]
        ldy #2                          ; [MS 2616] GET PNTR TO DESCRIPTOR.
        lda (FACMO),y                   ; [MS 2617]
        cmp FRETOP+1                    ; [MS 2618] SEE IF IT POINTS INTO STRING SPACE.
        bcc DNTCPY                      ; [MS 2619] IF [FRETOP],GT.[2&3,FACMO], DON'T COPY.
        bne QVARIA                      ; [MS 2620] IT IS LESS.
        dey                             ; [MS 2621]
        lda (FACMO),y                   ; [MS 2622]
        cmp FRETOP                      ; [MS 2623] COMPARE LOW ORDERS.
        bcc DNTCPY                      ; [MS 2624]
QVARIA:                                 ; [MS 2625]
        ldy FACLO                       ; [MS 2625]
        cpy VARTAB+1                    ; [MS 2626] IF [VARTAB].GT.[FACMO], DON'T COPY.
        bcc DNTCPY                      ; [MS 2627]
        bne COPY                        ; [MS 2628] IT IS LESS.
        lda FACMO                       ; [MS 2629]
        cmp VARTAB                      ; [MS 2630] COMPARE LOW ORDERS.
        bcs COPY                        ; [MS 2631]
DNTCPY:                                 ; [MS 2632]
        lda FACMO                       ; [MS 2632 LDWD]
        ldy FACMO+1                     ; [MS 2632 LDWD]
        jmp COPYZC                      ; [MS 2633]
COPY:                                   ; [MS 2634]
        ldy #0                          ; [MS 2634]
        lda (FACMO),y                   ; [MS 2635]
        jsr STRINI                      ; [MS 2636] GET ROOM TO COPY STRING INTO.
        lda DSCPNT                      ; [MS 2637 LDWD]
        ldy DSCPNT+1                    ; [MS 2637 LDWD] GET POINTER TO OLD DESCRIPTOR, SO
        sta STRNG1                      ; [MS 2638 STWD]
        sty STRNG1+1                    ; [MS 2638 STWD] MOVINS CAN FIND STRING.
        jsr MOVINS                      ; [MS 2639] COPY IT.
        lda #<DSCTMP                    ; [MS 2640 LDWDI]
        ldy #>DSCTMP                    ; [MS 2640 LDWDI] GET POINTER TO OLD DESCRIPTOR.
COPYZC:                                 ; [MS 2641]
        sta DSCPNT                      ; [MS 2641 STWD]
        sty DSCPNT+1                    ; [MS 2641 STWD] REMEMBER POINTER TO DESCRIPTOR.
        jsr FRETMS                      ; [MS 2642] FREE UP THE TEMPORARY WITHOUT
; [MS 2643] FREEING UP ANY STRING SPACE.
        ldy #0                          ; [MS 2644]
        lda (DSCPNT),y                  ; [MS 2645]
        sta (FORPNT),y                  ; [MS 2646]
        iny                             ; [MS 2647] POINT TO STRING PNTR.
        lda (DSCPNT),y                  ; [MS 2648]
        sta (FORPNT),y                  ; [MS 2649]
        iny                             ; [MS 2650]
        lda (DSCPNT),y                  ; [MS 2651]
        sta (FORPNT),y                  ; [MS 2652]
        rts                             ; [MS 2653]
; [MS 2655] ==== PRINT CODE. ====

STRDON:                                 ; [MS 2667]
        jsr STRPRT                      ; [MS 2667]
NEWCHR:                                 ; [MS 2668]
        jsr CHRGOT                      ; [MS 2668] REGET LAST CHARACTER.
PRINT:                                  ; [MS 2669]
        beq CRDO                        ; [MS 2669] TERMINATOR SO TYPE CRLF.
PRINTC:                                 ; [MS 2670]
        beq PRTRTS                      ; [MS 2670] HERE AFTER SEEING TAB(X) OR , OR ;
; [MS 2671] IN WHICH CASE A TERMINATOR DOES NOT
; [MS 2672] MEAN TYPE A CRLF BUT JUST RTS.
        cmp #TABTK                      ; [MS 2673] TAB FUNCTION?
        beq TABER                       ; [MS 2674] YES.
        cmp #SPCTK                      ; [MS 2675] SPACE FUNCTION?
        clc                             ; [MS 2676]
        beq TABER                       ; [MS 2677]
        cmp #44                         ; [MS 2678] A COMMA?
        beq COMPRT                      ; [MS 2679] YES.
        cmp #59                         ; [MS 2680] A SEMICOLON?
        beq NOTABR                      ; [MS 2681] YES.
        jsr FRMEVL                      ; [MS 2682] EVALUATE THE FORMULA.
        bit VALTYP                      ; [MS 2683] A STRING?
        bmi STRDON                      ; [MS 2684] YES.
        jsr FOUT                        ; [MS 2685]
        jsr STRLIT                      ; [MS 2686] BUILD DESCRIPTOR.

;       ldy #0                          ; [MS 2688] GET THE POINTER. [OURS] no line-width check: the Monitor wraps
;       lda (FACMO),y                   ; [MS 2689] [OURS] no line-width check: the Monitor wraps
;       clc                             ; [MS 2690] [OURS] no line-width check: the Monitor wraps
;       adc TRMPOS                      ; [MS 2691] MAKE SURE LEN+POS.LT.WIDTH. [OURS] no line-width check: the Monitor wraps
;       cmp LINWID                      ; [MS 2692] GREATER THAN LINE LENGTH? [OURS] no line-width check: the Monitor wraps
; [MS 2693] REMEMBER SPACE PRINTED AFTER NUMBER.
;       bcc LINCHK                      ; [MS 2694] GO TYPE. [OURS] no line-width check: the Monitor wraps
;       jsr CRDO                        ; [MS 2695] YES, TYPE CRLF FIRST. [OURS] no line-width check: the Monitor wraps
LINCHK:                                 ; [MS 2696]
        jsr STRPRT                      ; [MS 2696] PRINT THE NUMBER.
;       jsr OUTSPC                      ; [MS 2697] PRINT A SPACE [OURS] [RM] Applesoft prints no space after a number
        jmp NEWCHR                      ; [MS 2698] [OURS] was BNEA after OUTSPC

CRDO:                                   ; [MS 2711]

        lda #13                         ; [MS 2713] MAKE TRMPOS LESS THAN LINE LENGTH.
;       sta TRMPOS                      ; [MS 2714] [OURS] the Monitor sets CH on a return
; [MS 2720] X AND Y MUST BE PRESERVED.
        jsr OUTDO                       ; [MS 2721]
;       lda #10                         ; [MS 2722] [OURS] no LF after CR (Applesoft sends CR only)
;       jsr OUTDO                       ; [MS 2723] [OURS]
CRFIN:                                  ; [MS 2724]



        lda #0                          ; [MS 2731]
;       sta TRMPOS                      ; [MS 2732] [OURS]
        eor #255                        ; [MS 2733]

PRTRTS:                                 ; [MS 2746]
        rts                             ; [MS 2746]

COMPRT:                                 ; [MS 2748]
        lda TRMPOS                      ; [MS 2748]
NCMPOS = 14                             ; [MS 2749] <<<LINLEN/CLMWID>-1>*CLMWID>; CLMWID BEYOND WHICH THERE ARE

; [MS 2751] NO MORE COMMA FIELDS.
        cmp #16                         ; [OURS] [RM] tab fields start at positions 1, 17 and 33 (Applesoft II manual, PRINT)
        bcc CMFLD2                      ; [OURS] in field 1: on to position 17
        cmp #24                         ; [OURS] [RM] field 3 only if nothing is printed in positions 24-32
        bcc CMFLD3                      ; [OURS]

;       bcc MORCOM                      ; [MS 2754] [OURS]
        jsr CRDO                        ; [MS 2755] TYPE CRLF.
        jmp NOTABR                      ; [MS 2756] AND QUIT IF BEYOND LAST FIELD.
CMFLD2:                                 ; [OURS] carry clear: 16-CH spaces
        eor #$FF                        ; [OURS]
        adc #17                         ; [OURS]
        bne ASPAC                       ; [OURS] always
CMFLD3:                                 ; [OURS] carry clear: 32-CH spaces
        eor #$FF                        ; [OURS]
        adc #33                         ; [OURS]
        bne ASPAC                       ; [OURS] always
; [MS 2757] MORCOM (Microsoft's every-14-columns comma) is no longer used:
;       sec                             ; [MS 2757] [OURS]
MORCO1:                                 ; [MS 2758]
;       sbc #CLMWID                     ; [MS 2758] GET [A] MODULUS CLMWID. [OURS]
;       bcs MORCO1                      ; [MS 2759] [OURS]
;       eor #255                        ; [MS 2760] FILL PRINT POS OUT TO EVEN CLMWID SO [OURS]
;       adc #1                          ; [MS 2761] [OURS]
;       bne ASPAC                       ; [MS 2762] PRINT [A] SPACES. [OURS]

TABER:                                  ; [MS 2764]
        php                             ; [MS 2764] REMEMBER IF SPC OR TAB FUNCTION.
        jsr GTBYTC                      ; [MS 2765] GET VALUE INTO ACCX.
        cmp #41                         ; [MS 2766]
        bne SNERR4                      ; [MS 2767]
        plp                             ; [MS 2768]
        bcc XSPAC                       ; [MS 2769] PRINT [X] SPACES.
        txa                             ; [MS 2770]
        clc                             ; [OURS] [RM] TAB(n) moves to position n counting from 1, so column n-1 (Applesoft II manual, TAB)
        sbc TRMPOS                      ; [MS 2771]
        bcc NOTABR                      ; [MS 2772] NEGATIVE, DON'T PRINT ANY.
ASPAC:                                  ; [MS 2773]
        tax                             ; [MS 2773]
XSPAC:                                  ; [MS 2774]
        inx                             ; [MS 2774]
XSPAC2:                                 ; [MS 2775]
        dex                             ; [MS 2775] DECREMENT THE COUNT.
        bne XSPAC1                      ; [MS 2776]
NOTABR:                                 ; [MS 2777]
        jsr CHRGET                      ; [MS 2777] REGET LAST CHARACTER.
        jmp PRINTC                      ; [MS 2778] DON'T CALL CRDO.
XSPAC1:                                 ; [MS 2779]
        jsr OUTSPC                      ; [MS 2779]
        bne XSPAC2                      ; [MS 2780 BNEA]
; [MS 2781]
; [MS 2782] PRINT THE STRING POINTED TO BY [Y,A] WHICH ENDS WITH A ZERO.
; [MS 2783] IF THE STRING IS BELOW DSCTMP IT WILL BE COPIED INTO STRING SPACE.
; [MS 2784]
STROUT:                                 ; [MS 2785]
        jsr STRLIT                      ; [MS 2785] GET A STRING LITERAL.
; [MS 2786]
; [MS 2787] PRINT THE STRING WHOSE DESCRIPTOR IS POINTED TO BY FACMO.
; [MS 2788]
STRPRT:                                 ; [MS 2789]
        jsr FREFAC                      ; [MS 2789] RETURN TEMP POINTER.
        tax                             ; [MS 2790] PUT COUNT INTO COUNTER.
        ldy #0                          ; [MS 2791]
        inx                             ; [MS 2792] MOVE ONE AHEAD.
STRPR2:                                 ; [MS 2793]
        dex                             ; [MS 2793]
        beq PRTRTS                      ; [MS 2794] ALL DONE.
        lda (INDEX),y                   ; [MS 2795] PNTR TO ACT STRNG SET BY FREFAC.
        jsr OUTDO                       ; [MS 2796]
        iny                             ; [MS 2797]
        cmp #13                         ; [MS 2798]
        bne STRPR2                      ; [MS 2799]
        jsr CRFIN                       ; [MS 2800] TYPE REST OF CARRIAGE RETURN.
        jmp STRPR2                      ; [MS 2801] AND ON AND ON.
; [MS 2802]
; [MS 2803] OUTDO OUTPUTS THE CHARACTER IN ACCA, USING CNTWFL
; [MS 2804] (SUPPRESS OR NOT), TRMPOS (PRINT HEAD POSITION),
; [MS 2805] TIMING, ETCQ. NO REGISTERS ARE CHANGED.
; [MS 2806]
OUTSPC:                                 ; [MS 2807]

        lda #' '                        ; [MS 2809]
; [MS 2815] COMMODORE'S SKIP CHARACTER.
        .byte $2C                       ; [MS 2816 SKIP2]
OUTQST:                                 ; [MS 2817]
        lda #'?'                        ; [MS 2817]
OUTDO:                                  ; [MS 2818]
        bit CNTWFL                      ; [MS 2819] SHOULDN'T AFFECT CHANNEL I/O!
        bmi OUTRTS                      ; [MS 2820]

        pha                             ; [MS 2822]
;       cmp #32                         ; [MS 2823] IS THIS A PRINTING CHAR? [OURS] the Monitor tracks the column and wraps
;       bcc TRYOUT                      ; [MS 2824] NO, DON'T INCLUDE IT IN TRMPOS. [OURS] the Monitor tracks the column and wraps
;       lda TRMPOS                      ; [MS 2825] [OURS] the Monitor tracks the column and wraps
;       cmp LINWID                      ; [MS 2826] LENGTH = TERMINAL WIDTH? [OURS] the Monitor tracks the column and wraps
;       bne OUTDO1                      ; [MS 2827] [OURS] the Monitor tracks the column and wraps
;       jsr CRDO                        ; [MS 2828] YES, TYPE CRLF [OURS] the Monitor tracks the column and wraps
OUTDO1:                                 ; [MS 2829]

INCTRM:                                 ; [MS 2833]
;       inc TRMPOS                      ; [MS 2833] INCREMENT COUNT. [OURS] the Monitor tracks the column and wraps
TRYOUT:                                 ; [MS 2834]
        pla                             ; [MS 2834] RESTORE THE A REGISTER

; [MS 2837] PRESERVE Y.
        ora #$80                        ; [MS 2838] TURN ON B7 FOR APPLE.

OUTLOC:                                 ; [MS 2840]
        jsr OUTFL                       ; [MS 2840] [OURS] was jsr OUTCH: OUTFL adds FLASH's mask first. OUTPUT THE CHARACTER.
; [MS 2842] GET Y BACK.

        and #$7F                        ; [MS 2844] GET [A] BACK FROM APPLE.

; [MS 2847] CALL SIMULATOR OUTPUT ROUTINE
OUTRTS:                                 ; [MS 2848]
        and #255                        ; [MS 2848] SET Z=0.
GETRTS:                                 ; [MS 2849]
        rts                             ; [MS 2849]

; [MS 2852] ==== INPUT AND READ CODE. ====
; [MS 2853]
; [MS 2854] HERE WHEN THE DATA THAT WAS TYPED IN OR IN "DATA" STATEMENTS
; [MS 2855] IS IMPROPERLY FORMATTED. FOR "INPUT" WE START AGAIN.
; [MS 2856] FOR "READ" WE GIVE A SYNTAX ERROR AT THE DATA LINE.
; [MS 2857]
TRMNOK:                                 ; [MS 2858]
        lda INPFLG                      ; [MS 2858]
        beq TRMNO1                      ; [MS 2859] IF INPUT TRY AGAIN.

        bmi GETDTL                      ; [MS 2861]
        ldy #255                        ; [MS 2862] MAKE IT LOOK DIRECT.
        bne STCURL                      ; [MS 2863 BNEA] ALWAYS GOES.
GETDTL:                                 ; [MS 2864]
        lda DATLIN                      ; [MS 2865 LDWD]
        ldy DATLIN+1                    ; [MS 2865 LDWD] GET DATA LINE NUMBER.
STCURL:                                 ; [MS 2866]
        sta CURLIN                      ; [MS 2866 STWD]
        sty CURLIN+1                    ; [MS 2866 STWD] MAKE IT CURRENT LINE.
SNERR4:                                 ; [MS 2867]
        jmp SNERR                       ; [MS 2867]
TRMNO1:                                 ; [MS 2868]
        jmp DOAGIN                      ; [OURS] DOAGIN is out of line (end of BASIC): ONERR GOTO's error 254 made it longer

GET:                                    ; [MS 2880]
        jsr ERRDIR                      ; [MS 2880] DIRECT IS NOT OK.

GETTTY:                                 ; [MS 2889]
        ldx #<(BUF+1)                   ; [MS 2889 LDXYI]
        ldy #>(BUF+1)                   ; [MS 2889 LDXYI] POINT TO 0.

        lda #0                          ; [MS 2891] TO STUFF AND TO POINT.
        sta BUF+1                       ; [MS 2892]
; [MS 2894] ZERO IT.
        lda #64                         ; [MS 2895] TURN ON V-BIT.
        jsr INPCO1                      ; [MS 2896] DO THE GET.
; [MS 2899] RELEASE.
        rts                             ; [MS 2900]


INPUT:                                  ; [MS 2913]
        lsr CNTWFL                      ; [MS 2914] BE TALKATIVE.
        cmp #34                         ; [MS 2915] A QUOTE?
        bne NOTQTI                      ; [MS 2916] NO MESSAGE.
        jsr STRTXT                      ; [MS 2917] LITERALIZE THE STRING IN TEXT
        lda #59                         ; [MS 2918 SYNCHK]
        jsr SYNCHR                      ; [MS 2918 SYNCHK] MUST END WITH SEMICOLON.
        jsr STRPRT                      ; [MS 2919] PRINT IT OUT.
        jsr ERRDIR                      ; [OURS] as NOTQTI does
        lda #44                         ; [OURS]
        sta BUF-1                       ; [OURS]
        jsr INLIN                       ; [OURS] [RM] the prompt string is printed exactly as given, no "?" (Applesoft II manual, INPUT)
        jmp INPGOT                      ; [OURS]
NOTQTI:                                 ; [MS 2920]
        jsr ERRDIR                      ; [MS 2920] USE COMMON ROUTINE SINCE DEF DIRECT
        lda #44                         ; [MS 2921] GET COMMA.
        sta BUF-1                       ; [MS 2922]
; [MS 2923] IS ALSO ILLEGAL.
GETAGN:                                 ; [MS 2924]
        jsr QINLIN                      ; [MS 2924] TYPE "?" AND INPUT A LINE OF TEXT.

INPGOT:                                 ; [OURS]
        lda BUF                         ; [MS 2934] ANYTHING INPUT?
        bne INPCON                      ; [MS 2935] YES, CONTINUE.
; [MS 2938] IF NOT TERMINAL.
;       clc                             ; [MS 2939] MAKE SURE DONT PRINT BREAK [OURS]
        jsr OUTQST                      ; [MS 2940] [OURS] [RM] was jmp STPEND (an empty answer stopped the program): Applesoft prints "??" and waits (Applesoft II manual, INPUT)
        jmp GETAGN                      ; [OURS] QINLIN adds the second "?"
QINLIN:                                 ; [MS 2941]

        jsr OUTQST                      ; [MS 2945]
;       jsr OUTSPC                      ; [MS 2946] [OURS] [RM] INPUT prints a question mark alone (Applesoft II manual, INPUT)
GINLIN:                                 ; [MS 2947]
        jmp INLIN                       ; [MS 2947]
READ:                                   ; [MS 2948]
        ldx DATPTR                      ; [MS 2948 LDXY]
        ldy DATPTR+1                    ; [MS 2948 LDXY] GET LAST DATA LOCATION.
        .byte $A9                       ; [MS 2949] LDAI TYA TO MAKE IT NONZERO.

        tya                             ; [MS 2952]

        .byte $2C                       ; [MS 2954 SKIP2]
INPCON:                                 ; [MS 2955]
        lda #0                          ; [MS 2955] SET FLAG THAT THIS IS INPUT
INPCO1:                                 ; [MS 2956]
        sta INPFLG                      ; [MS 2956] STORE THE FLAG.
; [MS 2957]
; [MS 2958] IN THE PROCESSING OF DATA AND READ STATEMENTS:
; [MS 2959] ONE POINTER POINTS TO THE DATA (IE, THE NUMBERS BEING FETCHED)
; [MS 2960] AND ANOTHER POINTS TO THE LIST OF VARIABLES.
; [MS 2961]
; [MS 2962] THE POINTER INTO THE DATA ALWAYS STARTS POINTING TO A
; [MS 2963] TERMINATOR -- A , : OR END-OF-LINE.
; [MS 2964]
; [MS 2965] AT THIS POINT TXTPTR POINTS TO LIST OF VARIABLES AND
; [MS 2966] [Y,X] POINTS TO DATA OR INPUT LINE.
; [MS 2967]
        stx INPPTR                      ; [MS 2968 STXY]
        sty INPPTR+1                    ; [MS 2968 STXY]
INLOOP:                                 ; [MS 2969]
        jsr PTRGET                      ; [MS 2969] READ VARIABLE LIST.
        sta FORPNT                      ; [MS 2970 STWD]
        sty FORPNT+1                    ; [MS 2970 STWD] SAVE POINTER FOR "LET" STRING STUFFING.
; [MS 2971] RETURNS PNTR TOP VAR IN VARPNT.
        lda TXTPTR                      ; [MS 2972 LDWD]
        ldy TXTPTR+1                    ; [MS 2972 LDWD] SAVE TEXT PNTR.
        sta VARTXT                      ; [MS 2973 STWD]
        sty VARTXT+1                    ; [MS 2973 STWD]
        ldx INPPTR                      ; [MS 2974 LDXY]
        ldy INPPTR+1                    ; [MS 2974 LDXY]
        stx TXTPTR                      ; [MS 2975 STXY]
        sty TXTPTR+1                    ; [MS 2975 STXY]
        jsr CHRGOT                      ; [MS 2976] GET IT AND SET Z IF TERM.
        bne DATBK1                      ; [MS 2977]
        bit INPFLG                      ; [MS 2978]

        bvc QDATA                       ; [MS 2980]
        jsr CZGETL                      ; [MS 2981] DON'T WANT INCHR. JUST ONE.

        and #127                        ; [MS 2983]
        sta BUF                         ; [MS 2984] MAKE IT FIRST CHARACTER.
        ldx #<((BUF-1))                 ; [MS 2985 LDXYI]
        ldy #>((BUF-1))                 ; [MS 2985 LDXYI] POINT JUST BEFORE IT.


        bne DATBK                       ; [MS 2989 BNEA] GO PROCESS.
QDATA:                                  ; [MS 2990]
        bmi DATLOP                      ; [MS 2990] SEARCH FOR ANOTHER DATA STATEMENT.

        jsr OUTQST                      ; [MS 2994]
GETNTH:                                 ; [MS 2995]
        jsr QINLIN                      ; [MS 2995] GET ANOTHER LINE.
DATBK:                                  ; [MS 2996]
        stx TXTPTR                      ; [MS 2996 STXY]
        sty TXTPTR+1                    ; [MS 2996 STXY] SET FOR "CHRGET".
DATBK1:                                 ; [MS 2997]
        jsr CHRGET                      ; [MS 2997]
        bit VALTYP                      ; [MS 2998] GET VALUE TYPE.
        bpl NUMINS                      ; [MS 2999] INPUT A NUMBER IF NUMERIC.

        bit INPFLG                      ; [MS 3001] GET?
        bvc SETQUT                      ; [MS 3002] NO, GO SET QUOTE.
        inx                             ; [MS 3003]
        stx TXTPTR                      ; [MS 3004]
        lda #0                          ; [MS 3005] ZERO TERMINATORS.
        sta CHARAC                      ; [MS 3006]
        beq RESETC                      ; [MS 3007 BEQA]
SETQUT:                                 ; [MS 3008]
        sta CHARAC                      ; [MS 3008] ASSUME QUOTED STRING.
        cmp #34                         ; [MS 3009] TERMINATORS OK?
        beq NOWGET                      ; [MS 3010] YES.
        lda #':'                        ; [MS 3011] SET TERMINATORS TO ":" AND
        sta CHARAC                      ; [MS 3012]
        lda #44                         ; [MS 3013] COMMA.
RESETC:                                 ; [MS 3014]
        clc                             ; [MS 3014]
NOWGET:                                 ; [MS 3015]
        sta ENDCHR                      ; [MS 3015]
        lda TXTPTR                      ; [MS 3016 LDWD]
        ldy TXTPTR+1                    ; [MS 3016 LDWD]
        adc #0                          ; [MS 3017] C IS SET PROPERLY ABOVE.
        bcc NOWGE1                      ; [MS 3018]
        iny                             ; [MS 3019]
NOWGE1:                                 ; [MS 3020]
        jsr STRLT2                      ; [MS 3020] MAKE A STRING DESCRIPTOR FOR THE VALUE
; [MS 3021] AND COPY IF NECESSARY.
        jsr ST2TXT                      ; [MS 3022] SET TEXT POINTER.
        jsr INPCOM                      ; [MS 3023] DO ASSIGNMENT.
        jmp STRDN2                      ; [MS 3024]
NUMINS:                                 ; [MS 3025]
        jsr FIN                         ; [MS 3025]


        lda INTFLG                      ; [MS 3029] SET CODES ON FLAG.
        jsr QINTGR                      ; [MS 3030] GO DECIDE ON FLOAT.
STRDN2:                                 ; [MS 3031]
        jsr CHRGOT                      ; [MS 3031] READ LAST CHARACTER.
        beq TRMOK                       ; [MS 3032] ":" OR EOL IS OK.
        cmp #44                         ; [MS 3033] A COMMA?
        beq *+5                         ; [MS 3034 JNE]
        jmp TRMNOK                      ; [MS 3034 JNE]
TRMOK:                                  ; [MS 3035]
        lda TXTPTR                      ; [MS 3035 LDWD]
        ldy TXTPTR+1                    ; [MS 3035 LDWD]
        sta INPPTR                      ; [MS 3036 STWD]
        sty INPPTR+1                    ; [MS 3036 STWD] SAVE FOR MORE READS.
        lda VARTXT                      ; [MS 3037 LDWD]
        ldy VARTXT+1                    ; [MS 3037 LDWD]
        sta TXTPTR                      ; [MS 3038 STWD]
        sty TXTPTR+1                    ; [MS 3038 STWD] POINT TO VARIABLE LIST.
        jsr CHRGOT                      ; [MS 3039] LOOK AT LAST VARIABLE LIST CHARACTER.
        beq VAREND                      ; [MS 3040] THAT'S THE END OF THE LIST.
        jsr CHKCOM                      ; [MS 3041] NOT END. CHECK FOR COMMA.
        jmp INLOOP                      ; [MS 3042]
; [MS 3043]
; [MS 3044] SUBROUTINE TO FIND DATA
; [MS 3045] THE SEARCH IS MADE BY USING THE EXECUTION CODE FOR DATA TO
; [MS 3046] SKIP OVER STATEMENTS. THE START WORD OF EACH STATEMENT
; [MS 3047] IS COMPARED WITH "DATATK". EACH NEW LINE NUMBER
; [MS 3048] IS STORED IN "DATLIN" SO THAT IF AN ERROR OCCURS
; [MS 3049] WHILE READING DATA THE ERROR MESSAGE CAN GIVE THE LINE
; [MS 3050] NUMBER OF THE ILL-FORMATTED DATA.
; [MS 3051]
DATLOP:                                 ; [MS 3052]
        jsr DATAN                       ; [MS 3052] SKIP SOME TEXT.
        iny                             ; [MS 3053]
        tax                             ; [MS 3054] END OF LINE?
        bne NOWLIN                      ; [MS 3055] SHO AIN'T.
        ldx #ERROD                      ; [MS 3056] YES = "NO DATA" ERROR.
        iny                             ; [MS 3057]
        lda (TXTPTR),y                  ; [MS 3058]
        bne *+5                         ; [MS 3059] [OURS] as a jump: NEXT (and ERRGO5) now sit past the room
        jmp ERROR                       ; [MS 3059] [OURS] kept for pins at $DCF9, out of branch range (X = ERROD)
        iny                             ; [MS 3060]
        lda (TXTPTR),y                  ; [MS 3061] GET HIGH BYTE OF LINE NUMBER.
        sta DATLIN                      ; [MS 3062]
        iny                             ; [MS 3063]
        lda (TXTPTR),y                  ; [MS 3064] GET LOW BYTE.
        iny                             ; [MS 3065]
        sta DATLIN+1                    ; [MS 3066]
NOWLIN:                                 ; [MS 3067]
        lda (TXTPTR),y                  ; [MS 3067] HOW IS IT?
        tax                             ; [MS 3068]
        jsr ADDON                       ; [MS 3069] ADD [Y] TO [TXTPTR].
        cpx #DATATK                     ; [MS 3070] IS IT A "DATA" STATEMENT.
        bne DATLOP                      ; [MS 3071] NOT QUITE RIGHT. KEEP LOOKING.
        jmp DATBK1                      ; [MS 3072] THIS IS THE ONE !
VAREND:                                 ; [MS 3073]
        lda INPPTR                      ; [MS 3073 LDWD]
        ldy INPPTR+1                    ; [MS 3073 LDWD] PUT AWAY A NEW DATA PNTR MAYBE.
        ldx INPFLG                      ; [MS 3074]
        bpl VARY0                       ; [MS 3075]
        jmp RESFIN                      ; [MS 3076]
VARY0:                                  ; [MS 3077]
        ldy #0                          ; [MS 3077]
        lda (INPPTR),y                  ; [MS 3078] LAST DATA CHR COULD HAVE BEEN
; [MS 3079] COMMA OR COLON BUT SHOULD BE NULL.
        beq INPRTS                      ; [MS 3080] IT IS NULL.

        lda #<EXIGNT                    ; [MS 3084 LDWDI]
        ldy #>EXIGNT                    ; [MS 3084 LDWDI]
        jmp STROUT                      ; [MS 3085] TYPE "?EXTRA IGNORED"
INPRTS:                                 ; [MS 3086]
        rts                             ; [MS 3086] DO NEXT STATEMENT.
EXIGNT:                                 ; [MS 3087]
        .byte "?EXTRA IGNORED"          ; [MS 3087]
        .byte 13                        ; [MS 3088 ACRLF]
;       .byte 10                        ; [MS 3088 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
        .byte 0                         ; [MS 3089]
TRYAGN:                                 ; [MS 3090]
        .byte "?REENTER"                ; [MS 3090] [OURS] [RM] was "?REDO FROM START" (Applesoft II manual, INPUT)
        .byte 13                        ; [MS 3091 ACRLF]
;       .byte 10                        ; [MS 3091 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
        .byte 0                         ; [MS 3092]
; [MS 3094] ==== THE NEXT CODE IS THE "NEXT CODE" ====
; [MS 3095]
; [MS 3096] A "FOR" ENTRY ON THE STACK HAS THE FOLLOWING FORMAT:
; [MS 3097]
; [MS 3098] LOW ADDRESS
; [MS 3099] TOKEN (FORTK) 1 BYTE
; [MS 3100] A POINTER TO THE LOOP VARIABLE 2 BYTES
; [MS 3101] THE STEP 4+ADDPRC BYTES
; [MS 3102] A BYTE REFLECTING THE SIGN OF THE INCREMENT 1 BYTE
; [MS 3103] THE UPPER VALUE (PACKED) 4+ADDPRC BYTES
; [MS 3104] THE LINE NUMBER OF THE "FOR" STATEMENT 2 BYTES
; [MS 3105] A TEXT POINTER INTO THE "FOR" STATEMENT 2 BYTES
; [MS 3106] HIGH ADDRESS
; [MS 3107]
; [MS 3108] TOTAL 16+2*ADDPRC BYTES.
; [MS 3109]
        ALIGN $DCF9                     ; [OURS] [RM] NEXT at Applesoft's $DCF9; the bytes before it are room for pins above
NEXT:                                   ; [MS 3110]
        bne GETFOR                      ; [MS 3110]
        ldy #0                          ; [MS 3111] WITHOUT ARG CALL "FNDFOR" WITH
        beq STXFOR                      ; [MS 3112 BEQA] [FORPNT]=0.
GETFOR:                                 ; [MS 3113]
        jsr PTRGET                      ; [MS 3113] GET A POINTER TO LOOP VARIABLE
STXFOR:                                 ; [MS 3114]
        sta FORPNT                      ; [MS 3114 STWD]
        sty FORPNT+1                    ; [MS 3114 STWD] INTO "FORPNT".
        jsr FNDFOR                      ; [MS 3115] FIND THE MATCHING ENTRY IF ANY.
        beq HAVFOR                      ; [MS 3116]
        ldx #ERRNF                      ; [MS 3117] "NEXT WITHOUT FOR".
ERRGO5:                                 ; [MS 3118]
        bne NERRG4                      ; [MS 3118] [OURS] as a jump: out of branch range past the entry-point block
        jmp ERRGO4                      ; [MS 3118]
NERRG4:                                 ; [OURS]
HAVFOR:                                 ; [MS 3119]
        txs                             ; [MS 3119] SETUP STACK. CHOP FIRST.
        txa                             ; [MS 3120]
        clc                             ; [MS 3121]
        adc #4                          ; [MS 3122] POINT TO INCREMENT
        pha                             ; [MS 3123] SAVE THIS POINTER TO RESTORE TO [A]
        adc #5+ADDPRC                   ; [MS 3124] POINT TO UPPER LIMIT
        sta INDEX2                      ; [MS 3125] SAVE AS INDEX
        pla                             ; [MS 3126] RESTORE POINTER TO INCREMENT
        ldy #1                          ; [MS 3127] SET HI ADDR OF THING TO MOVE.
        jsr MOVFM                       ; [MS 3128] GET QUANTITY INTO THE FAC.
        tsx                             ; [MS 3129]
        lda 257+7+ADDPRC,x              ; [MS 3130] SET SIGN CORRECTLY.
        sta FACSGN                      ; [MS 3131]
        lda FORPNT                      ; [MS 3132 LDWD]
        ldy FORPNT+1                    ; [MS 3132 LDWD]
        jsr FADD                        ; [MS 3133] ADD INC TO LOOP VARIABLE.
        jsr MOVVF                       ; [MS 3134] PACK THE FAC INTO MEMORY.
        ldy #1                          ; [MS 3135]
        jsr FCOMPN                      ; [MS 3136] COMPARE FAC WITH UPPER VALUE.
        tsx                             ; [MS 3137]
        sec                             ; [MS 3138]
        sbc 257+7+ADDPRC,x              ; [MS 3139] SUBTRACT SIGN OF INC FROM SIGN OF
; [MS 3140] OF (CURRENT VALUE-FINAL VALUE).
        beq LOOPDN                      ; [MS 3141] IF SIGN (FINAL-CURRENT)-SIGN STEP=0
; [MS 3142] THEN LOOP IS DONE.
        lda 2*ADDPRC+12+257,x           ; [MS 3143]
        sta CURLIN                      ; [MS 3144] STORE LINE NUMBER OF "FOR" STATEMENT.
        lda 257+13+(2*ADDPRC),x         ; [MS 3145]
        sta CURLIN+1                    ; [MS 3146]
        jmp NXSTB                       ; [OURS] step over the block of Applesoft entry points below
; [OURS] [RM] Applesoft's entry points from $DD67 to $DD7B (& routines call them; Oregon Trail's call FRMNUM
; and FRMEVL): FRMNUM a JMP; CHKNUM and CHKSTR in Microsoft's own shape (CLC, BIT-skip, SEC, CHKVAL);
; FRMEVL a JMP.
        ALIGN $DD67
; [OURS] Microsoft's FRMNUM, CHKNUM, CHKSTR and CHKVAL, moved here: Applesoft's own code here has the
; same shape, so they fill $DD67-$DD7A exactly and FRMEVL's address follows.
FRMNUM:                                 ; [MS 3169]
        jsr FRMEVL                      ; [MS 3169]
CHKNUM:                                 ; [MS 3170]
        clc                             ; [MS 3170]
        .byte $24                       ; [MS 3171 SKIP1]
CHKSTR:                                 ; [MS 3172]
        sec                             ; [MS 3172] SET CARRY.
CHKVAL:                                 ; [MS 3173]
        bit VALTYP                      ; [MS 3173] WILL NOT F UP "VALTYP".
        bmi DOCSTR                      ; [MS 3174]
        bcs CHKERR                      ; [MS 3175]
CHKOK:                                  ; [MS 3176]
        rts                             ; [MS 3176]
DOCSTR:                                 ; [MS 3177]
        bcs CHKOK                       ; [MS 3177]
CHKERR:                                 ; [MS 3178]
        ldx #ERRTM                      ; [MS 3178]
ERRGO4:                                 ; [MS 3179]
        jmp ERROR                       ; [MS 3179]
        .assert FRMNUM = $DD67 .and CHKNUM = $DD6A .and CHKSTR = $DD6C, error, "FRMNUM block"
        ALIGN $DD7B
        jmp FRMEVL                      ; [OURS] [RM] $DD7B FRMEVL: evaluate any expression
NXSTB:                                  ; [OURS]
        lda 2*ADDPRC+15+257,x           ; [MS 3147]
        sta TXTPTR                      ; [MS 3148] STORE TEXT PNTR INTO "FOR" STATEMENT.
        lda 2*ADDPRC+14+257,x           ; [MS 3149]
        sta TXTPTR+1                    ; [MS 3150]
NEWSGO:                                 ; [MS 3151]
        jmp NEWSTT                      ; [MS 3151] PROCESS NEXT STATEMENT.
LOOPDN:                                 ; [MS 3152]
        txa                             ; [MS 3152]
        adc #2*ADDPRC+15                ; [MS 3153] ADDS 16 WITH CARRY.
        tax                             ; [MS 3154]
        txs                             ; [MS 3155] NEW STACK PNTR.
        jsr CHRGOT                      ; [MS 3156]
        cmp #44                         ; [MS 3157] COMMA AT END?
        bne NEWSGO                      ; [MS 3158]
        jsr CHRGET                      ; [MS 3159]
        jsr GETFOR                      ; [MS 3160] DO NEXT BUT DON'T ALLOW BLANK VARIABLE
; [MS 3161] PNTR. [VARPNT] IS THE STK PNTR WHICH
; [MS 3162] NEVER MATCHES ANY POINTER.
; [MS 3163] JSR TO PUT ON DUMMY NEWSTT ADDR.
; [MS 3164] ==== FORMULA EVALUATION CODE. ====
; [MS 3165]
; [MS 3166] THESE ROUTINES CHECK FOR CERTAIN "VALTYP".
; [MS 3167] [C] IS NOT PRESERVED.
; [MS 3168]
        jmp FRMNUM                      ; [OURS] Microsoft fell into FRMNUM here (its JSR GETFOR above only puts a dummy return
                                        ; [OURS] address on the stack); FRMNUM now sits on Applesoft's $DD67, so the same path by a JMP
; [MS 3180]
; [MS 3181] THE FORMULA EVALUATOR STARTS WITH
; [MS 3182] [TXTPTR] POINTING TO THE FIRST CHARACTER OF THE FORMULA.
; [MS 3183] AT THE END [TXTPTR] POINTS TO THE TERMINATOR.
; [MS 3184] THE RESULT IS LEFT IN THE FAC.
; [MS 3185] ON RETURN [A] DOES NOT REFLECT THE TERMINATOR.
; [MS 3186]
; [MS 3187] THE FORMULA EVALUATOR USES THE OPERATOR LIST (OPTAB)
; [MS 3188] TO DETERMINE PRECEDENCE AND DISPATCH ADDRESSES FOR
; [MS 3189] EACH OPERATOR.
; [MS 3190] A TEMPORARY RESULT ON THE STACK HAS THE FOLLOWING FORMAT.
; [MS 3191] THE ADDRESS OF THE OPERATOR ROUTINE.
; [MS 3192] THE FLOATING POINT TEMPORARY RESULT.
; [MS 3193] THE PRECEDENCE OF THE OPERATOR.
; [MS 3194]
FRMEVL:                                 ; [MS 3195]
        ldx TXTPTR                      ; [MS 3195]
        bne FRMEV1                      ; [MS 3196]
        dec TXTPTR+1                    ; [MS 3197]
FRMEV1:                                 ; [MS 3198]
        dec TXTPTR                      ; [MS 3198]
        ldx #0                          ; [MS 3199] INITIAL DUMMY PRECEDENCE IS 0.
        .byte $24                       ; [MS 3200 SKIP1]
LPOPER:                                 ; [MS 3201]
        pha                             ; [MS 3201] SAVE LOW PRECEDENCE. (MASK.)
        txa                             ; [MS 3202]
        pha                             ; [MS 3203] SAVE HIGH PRECEDENCE.
        lda #1                          ; [MS 3204]
        jsr GETSTK                      ; [MS 3205] MAKE SURE THERE IS ROOM FOR
; [MS 3206] RECURSIVE CALLS.
        jsr EVAL                        ; [MS 3207] EVALUATE SOMETHING.
        lda #0                          ; [MS 3208 CLR]
        sta OPMASK                      ; [MS 3208 CLR] PREPARE TO BUILD MASK MAYBE.
TSTOP:                                  ; [MS 3209]
        jsr CHRGOT                      ; [MS 3209] REGET LAST CHARACTER.
LOPREL:                                 ; [MS 3210]
        sec                             ; [MS 3210] PREP TO SUBTRACT.
        sbc #GREATK                     ; [MS 3211] IS CURRENT CHARACTER A RELATION?
        bcc ENDREL                      ; [MS 3212] NO. RELATIONS ALL THROUGH.
        cmp #LESSTK-GREATK+1            ; [MS 3213] REALLY RELATIONAL?
        bcs ENDREL                      ; [MS 3214] NO -- JUST BIG.
        cmp #1                          ; [MS 3215] RESET CARRY FOR ZERO ONLY.
        rol a                           ; [MS 3216] 0 TO 1, 1 TO 2, 2 TO 4.
        eor #1                          ; [MS 3217]
        eor OPMASK                      ; [MS 3218] BRING IN THE OLD BITS.
        cmp OPMASK                      ; [MS 3219] MAKE SURE THE NEW MASK IS BIGGER.
        bcc SNERR5                      ; [MS 3220] SYNTAX ERROR. BECAUSE TWO OF THE SAME.
        sta OPMASK                      ; [MS 3221] SAVE MASK.
        jsr CHRGET                      ; [MS 3222]
        jmp LOPREL                      ; [MS 3223] GET THE NEXT CANDIDATE.
ENDREL:                                 ; [MS 3224]
        ldx OPMASK                      ; [MS 3224] WERE THERE ANY?
        bne FINREL                      ; [MS 3225] YES, HANDLE AS SPECIAL OP.
        bcs QOP                         ; [MS 3226] NOT AN OPERATOR.
        adc #GREATK-PLUSTK              ; [MS 3227]
        bcc QOP                         ; [MS 3228] NOT AN OPERATOR.
        adc VALTYP                      ; [MS 3229] [C]=1.
        bne *+5                         ; [MS 3230 JEQ]
        jmp CAT                         ; [MS 3230 JEQ] ONLY IF [A]=0 AND [VALTYP]=-1 (A STR).
        adc #$FF                        ; [MS 3231] GET BACK ORIGINAL [A].
        sta INDEX1                      ; [MS 3232]
        asl a                           ; [MS 3233] MULTIPLY BY 2.
        adc INDEX1                      ; [MS 3234] BY THREE.
        tay                             ; [MS 3235] SET UP FOR LATER.
QPREC:                                  ; [MS 3236]
        pla                             ; [MS 3236] GET PREVIOUS PRECEDENCE.
        cmp OPTAB,y                     ; [MS 3237] IS OLD PRECEDENCE GREATER OR EQUAL?
        bcs QCHNUM                      ; [MS 3238] YES, GO OPERATE.
        jsr CHKNUM                      ; [MS 3239] CAN'T BE STRING HERE.
DOPREC:                                 ; [MS 3240]
        pha                             ; [MS 3240] SAVE OLD PRECEDENCE.
NEGPRC:                                 ; [MS 3241]
        jsr DOPRE1                      ; [MS 3241] SET A RETURN ADDRESS FOR OP.
        pla                             ; [MS 3242] PULL OFF PREVIOUS PRECEDENCE.
        ldy OPPTR                       ; [MS 3243] GET POINTER TO OP.
        bpl QPREC1                      ; [MS 3244] THAT'S A REAL OPERATOR.
        tax                             ; [MS 3245] DONE ?
        beq QOPGO                       ; [MS 3246] DONE !
        bne PULSTK                      ; [MS 3247]
FINREL:                                 ; [MS 3248]
        lsr VALTYP                      ; [MS 3248] GET VALUE TYPE INTO "C".
        txa                             ; [MS 3249]
        rol a                           ; [MS 3250] PUT VALTYP INTO LOW ORDER BIT OF MASK.
        ldx TXTPTR                      ; [MS 3251] DECREMENT TEXT POINTER.
        bne FINRE2                      ; [MS 3252]
        dec TXTPTR+1                    ; [MS 3253]
FINRE2:                                 ; [MS 3254]
        dec TXTPTR                      ; [MS 3254]
        ldy #<(PTDORL-OPTAB)            ; [MS 3255] MAKE [YREG] POINT AT OPERATOR ENTRY.
        sta OPMASK                      ; [MS 3256] SAVE THE OPERATION MASK.
        bne QPREC                       ; [MS 3257] SAVE IT ALL. BR ALWAYS.
; [MS 3258] NOTE B7(VALTYP)=0 SO CHKNUM CALL IS OK.
QPREC1:                                 ; [MS 3259]
        cmp OPTAB,y                     ; [MS 3259] LAST PRECEDENCE IS GREATER?
        bcs PULSTK                      ; [MS 3260] YES, GO OPERATE.
        bcc DOPREC                      ; [MS 3261] NO SAVE ARGUMENT AND GET OTHER OPERAND.
DOPRE1:                                 ; [MS 3262]
        lda OPTAB+2,y                   ; [MS 3262]
        pha                             ; [MS 3263] DISP ADDR GOES ONTO STACK.
        lda OPTAB+1,y                   ; [MS 3264]
        pha                             ; [MS 3265]
        jsr PUSHF1                      ; [MS 3266] SAVE FAC ON STACK UNPACKED.
        lda OPMASK                      ; [MS 3267] [ACCA] MAY BE MASK FOR REL.
        jmp LPOPER                      ; [MS 3268]
SNERR5:                                 ; [MS 3269]
        jmp SNERR                       ; [MS 3269] GO TO AN ERROR.
PUSHF1:                                 ; [MS 3270]
        lda FACSGN                      ; [MS 3270]
        ldx OPTAB,y                     ; [MS 3271] GET HIGH PRECEDENCE.
PUSHF:                                  ; [MS 3272]
        tay                             ; [MS 3272] GET POINTER INTO STACK.
        pla                             ; [MS 3273]
        sta INDEX1                      ; [MS 3274]
        inc INDEX1                      ; [MS 3275]
        pla                             ; [MS 3276]
        sta INDEX1+1                    ; [MS 3277]
        tya                             ; [MS 3278]
; [MS 3279] STORE FAC ON STACK UNPACKED.
        pha                             ; [MS 3280] START WITH SIGN SET UP.
FORPSH:                                 ; [MS 3281]
        jsr ROUND                       ; [MS 3281] PUT ROUNDED FAC ON STACK.
        lda FACLO                       ; [MS 3282] ENTRY POINT TO SKIP STORING SIGN.
        pha                             ; [MS 3283]
        lda FACMO                       ; [MS 3284]
        pha                             ; [MS 3285]

        lda FACMOH                      ; [MS 3287]
        pha                             ; [MS 3288]
        lda FACHO                       ; [MS 3289]
        pha                             ; [MS 3290]
        lda FACEXP                      ; [MS 3291]
        pha                             ; [MS 3292]
        jmp (INDEX1)                    ; [MS 3293] RETURN.
QOP:                                    ; [MS 3294]
        ldy #255                        ; [MS 3294]
        pla                             ; [MS 3295] GET HIGH PRECEDENCE OF LAST OP.
QOPGO:                                  ; [MS 3296]
        beq QOPRTS                      ; [MS 3296] DONE !
QCHNUM:                                 ; [MS 3297]
        cmp #100                        ; [MS 3297] RELATIONAL OPERATOR?
        beq UNPSTK                      ; [MS 3298] YES, DON'T CHECK OPERAND.
        jsr CHKNUM                      ; [MS 3299] MUST BE NUMBER.
UNPSTK:                                 ; [MS 3300]
        sty OPPTR                       ; [MS 3300] SAVE OPERATOR'S POINTER FOR NEXT TIME.
PULSTK:                                 ; [MS 3301]
        pla                             ; [MS 3301] GET MASK FOR REL OP IF IT IS ONE.
        lsr a                           ; [MS 3302] SETUP [C] FOR DOREL'S "CHKVAL".
        sta DOMASK                      ; [MS 3303] SAVE FOR "DOCMP".
        pla                             ; [MS 3304] UNPACK STACK INTO ARG.
        sta ARGEXP                      ; [MS 3305]
        pla                             ; [MS 3306]
        sta ARGHO                       ; [MS 3307]

        pla                             ; [MS 3309]
        sta ARGMOH                      ; [MS 3310]
        pla                             ; [MS 3311]
        sta ARGMO                       ; [MS 3312]
        pla                             ; [MS 3313]
        sta ARGLO                       ; [MS 3314]
        pla                             ; [MS 3315]
        sta ARGSGN                      ; [MS 3316]
        eor FACSGN                      ; [MS 3317] GET PROBABLE RESULT SIGN.
        sta ARISGN                      ; [MS 3318] ARITHMETIC SIGN. USED BY
; [MS 3319] ADD, SUB, MULT, DIV.
QOPRTS:                                 ; [MS 3320]
        lda FACEXP                      ; [MS 3320] GET IT AND SET CODES.
UNPRTS:                                 ; [MS 3321]
        rts                             ; [MS 3321] RETURN.

EVAL:                                   ; [MS 3323]
        lda #0                          ; [MS 3323 CLR]
        sta VALTYP                      ; [MS 3323 CLR] ASSUME VALUE WILL BE NUMERIC.
EVAL0:                                  ; [MS 3324]
        jsr CHRGET                      ; [MS 3324] GET A CHARACTER.
        bcs EVAL2                       ; [MS 3325]
EVAL1:                                  ; [MS 3326]
        jmp FIN                         ; [MS 3326] IT IS A NUMBER.
EVAL2:                                  ; [MS 3327]
        jsr ISLETC                      ; [MS 3327] VARIABLE NAME?
        bcc NOTVAR                      ; [MS 3328] [OURS] as a jump: out of branch range past the entry-point block
        jmp ISVAR                       ; [MS 3328] YES.
NOTVAR:                                 ; [OURS]

QDOT:                                   ; [MS 3340]
        cmp #'.'                        ; [MS 3340] LEADING CHARACTER OF CONSTANT?
        beq EVAL1                       ; [MS 3341]
        cmp #MINUTK                     ; [MS 3342] NEGATION?
        beq DOMIN                       ; [MS 3343] SHO IS.
        cmp #PLUSTK                     ; [MS 3344]
        beq EVAL0                       ; [MS 3345]
        jmp EVSTB                       ; [OURS] step over the block of Applesoft entry points below
; [OURS] [RM] Applesoft's entry points from $DEB2 to $DEC9, as one block in their own shape (Microsoft's code
; for them is the same: LDA the character, BIT-skip, ..., SYNCHR). Programs' & routines call these; Oregon
; Trail's calls SYNCHR. PARCHK and SNERR are JMPs to ours.
        ALIGN $DEB2
        jmp PARCHK                      ; [OURS] [RM] $DEB2 PARCHK: evaluate a formula in parentheses
        .byte $02, $02, $02             ; [OURS]
        .assert * = $DEB8, error, "CHKCLS"
        lda #')'                        ; [OURS] [RM] $DEB8 CHKCLS: the next character must be ")"
        .byte $2C                       ; [OURS] BIT abs: skip the next two bytes
        .assert * = $DEBB, error, "CHKOPN"
        lda #'('                        ; [OURS] [RM] $DEBB CHKOPN: "("
        .byte $2C                       ; [OURS]
        .assert * = $DEBE, error, "CHKCOM"
        lda #','                        ; [OURS] [RM] $DEBE CHKCOM: ","
        .assert * = $DEC0, error, "SYNCHR"
        jmp SYNCHR                      ; [OURS] [RM] $DEC0 SYNCHR: the next character must be the one in A
        .byte $02, $02, $02, $02, $02, $02   ; [OURS]
        .assert * = $DEC9, error, "SNERR"
        jmp SNERR                       ; [OURS] [RM] $DEC9 SNERR: ?SYNTAX ERROR
EVSTB:                                  ; [OURS]
        cmp #34                         ; [MS 3346] A QUOTE? A STRING?
        bne EVAL3                       ; [MS 3347]
STRTXT:                                 ; [MS 3348]
        lda TXTPTR                      ; [MS 3348 LDWD]
        ldy TXTPTR+1                    ; [MS 3348 LDWD]
        adc #0                          ; [MS 3349] TO INC, ADD C=1.
        bcc STRTX2                      ; [MS 3350]
        iny                             ; [MS 3351]
STRTX2:                                 ; [MS 3352]
        jsr STRLIT                      ; [MS 3352] YES. GO PROCESS IT.
        jmp ST2TXT                      ; [MS 3353]
EVAL3:                                  ; [MS 3354]
        cmp #NOTTK                      ; [MS 3354] CHECK FOR "NOT" OPERATOR.
        bne EVAL4                       ; [MS 3355]
        ldy #<(NOTTAB-OPTAB)            ; [MS 3356] "NOT" HAS PRECEDENCE 90.
        bne GONPRC                      ; [MS 3357] GO DO ITS EVALUATION.
; [MS 3365] AND RETURN.
EVAL4:                                  ; [MS 3366]
        cmp #FNTK                       ; [MS 3366] USER-DEFINED FUNCTION?
        bne *+5                         ; [MS 3367 JEQ]
        jmp FNDOER                      ; [MS 3367 JEQ]
        cmp #ONEFUN                     ; [MS 3368] A FUNCTION NAME?
        bcc PARCHK                      ; [MS 3369] FUNCTIONS ARE THE HIGHEST NUMBERED
        jmp ISFUN                       ; [MS 3370] CHARACTERS SO NO NEED TO CHECK
; [MS 3371] AN UPPER-BOUND.
PARCHK:                                 ; [MS 3372]
        jsr CHKOPN                      ; [MS 3372] ONLY POSSIBILITY LEFT IS
        jsr FRMEVL                      ; [MS 3373] A FORMULA IN PARENTHESIS.
; [MS 3374] RECURSIVELY EVALUATE THE FORMULA.
CHKCLS:                                 ; [MS 3375]
        lda #41                         ; [MS 3375] CHECK FOR A RIGHT PARENTHESE
        .byte $2C                       ; [MS 3376 SKIP2]
CHKOPN:                                 ; [MS 3377]
        lda #40                         ; [MS 3377]
        .byte $2C                       ; [MS 3378 SKIP2]
CHKCOM:                                 ; [MS 3379]
        lda #44                         ; [MS 3379]
; [MS 3380]
; [MS 3381] "SYNCHK" LOOKS AT THE CURRENT CHARACTER TO MAKE SURE IT
; [MS 3382] IS THE SPECIFIC THING LOADED INTO ACCA JUST BEFORE THE CALL TO
; [MS 3383] "SYNCHK". IF NOT, IT CALLS THE "SYNTAX ERROR" ROUTINE.
; [MS 3384] OTHERWISE IT GOBBLES THE NEXT CHAR AND RETURNS,
; [MS 3385]
; [MS 3386] [A]=NEW CHAR AND TXTPTR IS ADVANCED BY "CHRGET".
; [MS 3387]
SYNCHR:                                 ; [MS 3388]
        ldy #0                          ; [MS 3388]
        cmp (TXTPTR),y                  ; [MS 3389] CHARACTERS EQUAL?
        bne SNERR                       ; [MS 3390]
CHRGO5:                                 ; [MS 3391]
        jmp CHRGET                      ; [MS 3391]
SNERR:                                  ; [MS 3392]
        ldx #ERRSN                      ; [MS 3392] "SYNTAX ERROR"
        jmp ERROR                       ; [MS 3393]
DOMIN:                                  ; [MS 3394]
        ldy #<(NEGTAB-OPTAB)            ; [MS 3394] A PRECEDENCE BELOW "^".
GONPRC:                                 ; [MS 3395]
        pla                             ; [MS 3395] GET RID OF RTS ADDR.
        pla                             ; [MS 3396]
        jmp NEGPRC                      ; [MS 3397] EVALUTE FOR NEGATION.

ISVAR:                                  ; [MS 3399]
        jsr PTRGET                      ; [MS 3399] GET A PNTR TO VARIABLE.
ISVRET:                                 ; [MS 3400]
        sta FACMO                       ; [MS 3400 STWD]
        sty FACMO+1                     ; [MS 3400 STWD]
; [MS 3402] CHECK TIME,TIME$,STATUS.
        ldx VALTYP                      ; [MS 3403]
        beq GOOO                        ; [MS 3404] THE STRING IS SET UP.
        ldx #0                          ; [MS 3405]
        stx FACOV                       ; [MS 3406]

STRRTS:                                 ; [MS 3423]
        rts                             ; [MS 3423]
GOOO:                                   ; [MS 3424]

        ldx INTFLG                      ; [MS 3426]
        bpl GOOOOO                      ; [MS 3427]
        ldy #0                          ; [MS 3428]
        lda (FACMO),y                   ; [MS 3429] FETCH HIGH.
        tax                             ; [MS 3430]
        iny                             ; [MS 3431]
        lda (FACMO),y                   ; [MS 3432]
        tay                             ; [MS 3433] PUT LOW IN Y.
        txa                             ; [MS 3434] GET HIGH IN A.
        jmp GIVAYF                      ; [MS 3435] FLOAT AND RETURN.
GOOOOO:                                 ; [MS 3436]

QSTATV:                                 ; [MS 3454]


        jmp MOVFM                       ; [MS 3465] MOVE ACTUAL VALUE IN.
; [MS 3466] AND RETURN.

ISFUN:                                  ; [MS 3468]
        asl a                           ; [MS 3468] MULTIPLY BY TWO.
        pha                             ; [MS 3469]
        tax                             ; [MS 3470]
        jsr CHRGET                      ; [MS 3471] SET UP FOR SYNCHK.
        cpx #2*LASNUM-256+1             ; [MS 3472] IS IT PAST "LASNUM"?
        bcc OKNORM                      ; [MS 3473] NO, MUST BE NORMAL FUNCTION.
; [MS 3474]
; [MS 3475] MOST FUNCTIONS TAKE A SINGLE ARGUMENT.
; [MS 3476] THE RETURN ADDRESS OF THESE FUNCTIONS IS "CHKNUM"
; [MS 3477] WHICH ASCERTAINS THAT [VALTYP]=0  (NUMERIC).
; [MS 3478] NORMAL FUNCTIONS THAT RETURN STRING RESULTS
; [MS 3479] (E.G., CHR$) MUST POP OFF THAT RETURN ADDR AND
; [MS 3480] RETURN DIRECTLY TO "FRMEVL".
; [MS 3481]
; [MS 3482] THE SO-CALLED "FUNNY" FUNCTIONS CAN TAKE MORE THAN ONE ARGUMENT,
; [MS 3483] THE FIRST OF WHICH MUST BE STRING AND THE SECOND OF WHICH
; [MS 3484] MUST BE A NUMBER BETWEEN 0 AND 255.
; [MS 3485] THE CLOSED PARENTHESIS MUST BE CHECKED AND RETURN IS DIRECTLY
; [MS 3486] TO "FRMEVL" WITH THE TEXT PNTR POINTING BEYOND THE ")".
; [MS 3487] THE POINTER TO THE DESCRIPTOR OF THE STRING ARGUMENT
; [MS 3488] IS STORED ON THE STACK UNDERNEATH THE VALUE OF THE
; [MS 3489] INTEGER ARGUMENT.
; [MS 3490]
        jsr CHKOPN                      ; [MS 3491] CHECK FOR AN OPEN PARENTHESE
        jsr FRMEVL                      ; [MS 3492] EAT OPEN PAREN AND FIRST ARG.
        jsr CHKCOM                      ; [MS 3493] TWO ARGS SO COMMA MUST DELIMIT.
        jsr CHKSTR                      ; [MS 3494] MAKE SURE FIRST WAS STRING.
        pla                             ; [MS 3495] GET FUNCTION NUMBER.
        tax                             ; [MS 3496]
        lda FACMO+1                     ; [MS 3497 PSHWD]
        pha                             ; [MS 3497 PSHWD]
        lda FACMO                       ; [MS 3497 PSHWD]
        pha                             ; [MS 3497 PSHWD] SAVE POINTER AT STRING DESCRIPTOR
        txa                             ; [MS 3498]
        pha                             ; [MS 3499] RESAVE FUNCTION NUMBER.
; [MS 3500] THIS MUST BE ON STACK SINCE RECURSIVE.
        jsr GETBYT                      ; [MS 3501] [X]=VALUE OF FORMULA.
        pla                             ; [MS 3502] GET FUNCTION NUMBER.
        tay                             ; [MS 3503]
        txa                             ; [MS 3504]
        pha                             ; [MS 3505]
        jmp FINGO                       ; [MS 3506] DISPATCH TO FUNCTION.
OKNORM:                                 ; [MS 3507]
        jsr PARCHK                      ; [MS 3507] READ A FORMULA SURROUNDED BY PARENS.
        pla                             ; [MS 3508] GET DISPATCH FUNCTION.
        tay                             ; [MS 3509]
FINGO:                                  ; [MS 3510]
        lda FUNDSP-2*ONEFUN+256,y       ; [MS 3510] MODIFY DISPATCH ADDRESS.
        sta JMPER+1                     ; [MS 3511]
        lda FUNDSP-2*ONEFUN+257,y       ; [MS 3512]
        sta JMPER+2                     ; [MS 3513]
        jsr JMPER                       ; [MS 3514] DISPATCH!
; [MS 3515] STRING FUNCTIONS REMOVE THIS RET ADDR.
        jmp CHKNUM                      ; [MS 3516] CHECK IT FOR NUMERICNESS AND RETURN.


; [MS 3542]
; [MS 3543] TIME TO PERFORM A RELATIONAL OPERATOR.
; [MS 3544] [DOMASK] CONTAINS THE BITS AS TO WHICH RELATIONAL
; [MS 3545] OPERATOR IT WAS. CARRY BIT ON=STRING COMPARE.
; [MS 3546]
DOREL:                                  ; [MS 3547]
        jsr CHKVAL                      ; [MS 3547] CHECK FOR MATCH.
        bcs STRCMP                      ; [MS 3548] IT IS A STRING.
        lda ARGSGN                      ; [MS 3549] PACK ARG FOR FCOMP.
        ora #127                        ; [MS 3550]
        and ARGHO                       ; [MS 3551]
        sta ARGHO                       ; [MS 3552]
        lda #<ARGEXP                    ; [MS 3553 LDWDI]
        ldy #>ARGEXP                    ; [MS 3553 LDWDI]
        jsr FCOMP                       ; [MS 3554]
        tax                             ; [MS 3555]
        jmp QCOMP                       ; [MS 3556]
STRCMP:                                 ; [MS 3557]
        lda #0                          ; [MS 3557 CLR]
        sta VALTYP                      ; [MS 3557 CLR] RESULT WILL BE NUMERIC.
        dec OPMASK                      ; [MS 3558] TURN OFF VALTYP WHICH WAS STRING.
        jsr FREFAC                      ; [MS 3559] FREE THE FACLO STRING.
        sta DSCTMP                      ; [MS 3560] SAVE FOR LATER.
        stx DSCTMP+1                    ; [MS 3561 STXY]
        sty 0+(DSCTMP+1)+1              ; [MS 3561 STXY]
        lda ARGMO                       ; [MS 3562 LDWD]
        ldy ARGMO+1                     ; [MS 3562 LDWD] GET POINTER TO OTHER STRING.
        jsr FRETMP                      ; [MS 3563] FREES FIRST DESC POINTER.
        stx ARGMO                       ; [MS 3564 STXY]
        sty ARGMO+1                     ; [MS 3564 STXY]
        tax                             ; [MS 3565] COPY COUNT INTO X.
        sec                             ; [MS 3566]
        sbc DSCTMP                      ; [MS 3567] WHICH IS GREATER. IF 0, ALL SET UP.
        beq STASGN                      ; [MS 3568] JUST PUT SIGN OF DIFFERENCE AWAY.
        lda #1                          ; [MS 3569]
        bcc STASGN                      ; [MS 3570] SIGN IS POSITIVE.
        ldx DSCTMP                      ; [MS 3571] LENGTH OF FAC IS SHORTER.
        lda #$FF                        ; [MS 3572] GET A MINUS 1 FOR NEGATIVES.
STASGN:                                 ; [MS 3573]
        sta FACSGN                      ; [MS 3573] KEEP FOR LATER.
        ldy #255                        ; [MS 3574] SET POINTER TO FIRST STRING. (ARG.)
        inx                             ; [MS 3575] TO LOOP PROPERLY.
NXTCMP:                                 ; [MS 3576]
        iny                             ; [MS 3576]
        dex                             ; [MS 3577] ANY CHARACTERS LEFT TO COMPARE?
        bne GETCMP                      ; [MS 3578] NOT DONE YET.
        ldx FACSGN                      ; [MS 3579] USE SIGN OF LENGTH DIFFERENCE
; [MS 3580] SINCE ALL CHARACTERS ARE THE SAME.
QCOMP:                                  ; [MS 3581]
        bmi DOCMP                       ; [MS 3581] C IS ALWAYS SET THEN.
        clc                             ; [MS 3582]
        PINF $DFE3, PTRGET        ; [OURS] [RM] $DFE3: PTRGET, find or make the variable named at TXTPTR; pointer back in VARPNT and A,Y (Oregon Trail's & library calls it)
        bcc DOCMP                       ; [MS 3583] ALWAYS BRANCH.
        PINJ $E000, INIT                ; [OURS] [RM] $E000: BASIC's cold start. DOS 3.3 tests $E000 for $4C (a JMP) to tell Applesoft from
        jmp BASWRM                      ; [OURS] [RM] $E003: warm start. Integer BASIC, and so does Oregon Trail (DOS source AITSTL);
                                        ; [OURS] [RM] $E003 is the Autostart soft entry vector's normal value (Apple II Reference Manual 1979)
GETCMP:                                 ; [MS 3584]
        lda (ARGMO),y                   ; [MS 3584] GET NEXT CHAR TO COMPARE.
        cmp (DSCTMP+1),y                ; [MS 3585] SAME?
        beq NXTCMP                      ; [MS 3586] YEP. TRY FURTHER.
        ldx #$FF                        ; [MS 3587] SET A POSITIVE DIFFERENCE.
        bcs DOCMP                       ; [MS 3588] PUT STACK BACK TOGETHER.
        ldx #1                          ; [MS 3589] SET A NEGATIVE DIFFERENCE.
DOCMP:                                  ; [MS 3590]
        inx                             ; [MS 3590] -1 TO 1, 0 TO 2, 1 TO 4.
        txa                             ; [MS 3591]
        rol a                           ; [MS 3592]
        and DOMASK                      ; [MS 3593]
        beq GOFLOT                      ; [MS 3594]
        lda #1                          ; [MS 3595] [OURS] [RM] was #$FF (true = -1): "relational and logical expressions have value 1 if true, 0 if false" (Applesoft II manual)
GOFLOT:                                 ; [MS 3596]
        jmp FLOAT                       ; [MS 3596] FLOAT THE ONE-BYTE RESULT INTO FAC.

; [MS 3599] ==== DIMENSION AND VARIABLE SEARCHING. ====
; [MS 3600]
; [MS 3601] THE "DIM" CODE SETS [DIMFLG] AND THEN FALLS INTO THE VARIABLE SEARCH
; [MS 3602] ROUTINE, WHICH LOOKS AT DIMFLG AT THREE DIFFERENT POINTS.
; [MS 3603] 1) IF AN ENTRY IS FOUND, "DIMFLG" BEING ON INDICATES
; [MS 3604] A "DOUBLY" DIMENSIONED VARIABLE.
; [MS 3605] 2) WHEN A NEW ENTRY IS BEING BUILT "DIMFLG" BEING ON
; [MS 3606] INDICTAES THE INDICES SHOULD BE USED FOR THE
; [MS 3607] SIZE OF EACH INDEX. OTHERWISE THE DEFAULT OF TEN
; [MS 3608] IS USED.
; [MS 3609] 3) WHEN THE BUILD ENTRY CODE FINISHES, ONLY IF "DIMFLG" IS OFF
; [MS 3610] WILL INDEXING BE DONE.
; [MS 3611]
; [MS 3619]
; [MS 3620] ROUTINE TO READ THE VARIABLE NAME AT THE CURRENT TEXT POSITION
; [MS 3621] AND  PUT A POINTER TO ITS VALUE IN VARPNT. [TXTPTR]
; [MS 3622] POINTS TO THE TERMINATING CHARCTER.. NOT THAT EVALUATING SUBSCRIPTS
; [MS 3623] IN A VARIABLE NAME CAN CAUSE RECURSIVE CALLS TO "PTRGET" SO AT
; [MS 3624] THAT POINT ALL VALUES MUST BE STORED ON THE STACK.
; [MS 3625]
PTRGET:                                 ; [MS 3626]
        ldx #0                          ; [MS 3626] MAKE [ACCX]=0.
        jsr CHRGOT                      ; [MS 3627] RETRIEVE LAST CHARACTER.
PTRGT1:                                 ; [MS 3628]
        stx DIMFLG                      ; [MS 3628] STORE FLAG AWAY.
PTRGT2:                                 ; [MS 3629]
        sta VARNAM                      ; [MS 3629]
        jsr CHRGOT                      ; [MS 3630] GET CURRENT CHARACTER
; [MS 3631] MAYBE WITH FUNCTION BIT OFF.
        jsr ISLETC                      ; [MS 3632] CHECK FOR LETTER.
        bcs PTRGT3                      ; [MS 3633] MUST HAVE A LETTER.
INTERR:                                 ; [MS 3634]
        jmp SNERR                       ; [MS 3634]
PTRGT3:                                 ; [MS 3635]
        ldx #0                          ; [MS 3635] ASSUME NO SECOND CHARACTER.
        stx VALTYP                      ; [MS 3636] DEFAULT IS NUMERIC.

        stx INTFLG                      ; [MS 3638] ASSUME FLOATING.
        jsr CHRGET                      ; [MS 3639] GET FOLLOWING CHARACTER.
        bcc ISSEC                       ; [MS 3640] CARRY RESET BY CHRGET IF NUMERIC.
        jsr ISLETC                      ; [MS 3641] SET CARRY IF NOT ALPHABETIC.
        bcc NOSEC                       ; [MS 3642] ALLOW ALPHABETICS.
ISSEC:                                  ; [MS 3643]
        tax                             ; [MS 3643] IT IS A NUMBER -- SAVE IN ACCX.
EATEM:                                  ; [MS 3644]
        jsr CHRGET                      ; [MS 3644] LOOK AT NEXT CHARACTER.
        bcc EATEM                       ; [MS 3645] SKIP NUMERICS.
        jsr ISLETC                      ; [MS 3646]
        bcs EATEM                       ; [MS 3647] SKIP ALPHABETICS.
NOSEC:                                  ; [MS 3648]
        cmp #'$'                        ; [MS 3648] IS IT A STRING?
        bne NOTSTR                      ; [MS 3649] IF NOT, [VALTYP]=0.
        lda #$FF                        ; [MS 3650] SET [VALTYP]=255 (STRING !).
        sta VALTYP                      ; [MS 3651]

        bne TURNON                      ; [MS 3653 BNEA] ALWAYS GOES.
NOTSTR:                                 ; [MS 3654]
        cmp #'%'                        ; [MS 3654] INTEGER VARIABLE?
        bne STRNAM                      ; [MS 3655] NO.
        lda SUBFLG                      ; [MS 3656]
        bne INTERR                      ; [MS 3657]
        lda #128                        ; [MS 3658]
        sta INTFLG                      ; [MS 3659] SET FLAG.
        ora VARNAM                      ; [MS 3660] TURN ON BOTH HIGH BITS.
        sta VARNAM                      ; [MS 3661]
TURNON:                                 ; [MS 3662]
        txa                             ; [MS 3662]
        ora #128                        ; [MS 3663] TURN ON MSB OF SECOND CHARACTER.
        tax                             ; [MS 3664]
        jsr CHRGET                      ; [MS 3665] GET CHARACTER AFTER $.

STRNAM:                                 ; [MS 3668]
        stx VARNAM+1                    ; [MS 3668] STORE AWAY SECOND CHARACTER.
        sec                             ; [MS 3669]
        ora SUBFLG                      ; [MS 3670] ADD FLAG WHETHER TO ALLOW ARRAYS.
        sbc #40                         ; [MS 3671] (CHECK FOR "(") WON'T MATCH IF SUBFLG SET.
        bne *+5                         ; [MS 3672 JEQ]
        jmp ISARY                       ; [MS 3672 JEQ] IT IS!
        lda #0                          ; [MS 3673 CLR]
        sta SUBFLG                      ; [MS 3673 CLR] ALLOW SUBSCRIPTS AGAIN.
        lda VARTAB                      ; [MS 3674] PLACE TO START SEARCH.
        ldx VARTAB+1                    ; [MS 3675]
        ldy #0                          ; [MS 3676]
STXFND:                                 ; [MS 3677]
        stx LOWTR+1                     ; [MS 3677]
LOPFND:                                 ; [MS 3678]
        sta LOWTR                       ; [MS 3678]
        cpx ARYTAB+1                    ; [MS 3679] AT END OF TABLE YET?
        bne LOPFN                       ; [MS 3680]
        cmp ARYTAB                      ; [MS 3681]
        beq NOTFNS                      ; [MS 3682] YES. WE COULDN'T FIND IT.
LOPFN:                                  ; [MS 3683]
        lda VARNAM                      ; [MS 3683]
        cmp (LOWTR),y                   ; [MS 3684] COMPARE HIGH ORDERS.
        bne NOTIT                       ; [MS 3685] NO COMPARISON.
        lda VARNAM+1                    ; [MS 3686]
        iny                             ; [MS 3687]
        cmp (LOWTR),y                   ; [MS 3688] AND THE LOW PART?
        beq FINPTR                      ; [MS 3689] THAT'S IT ! THAT'S IT !
        dey                             ; [MS 3690]
NOTIT:                                  ; [MS 3691]
        clc                             ; [MS 3691]
        lda LOWTR                       ; [MS 3692]
        adc #6+ADDPRC                   ; [MS 3693] MAKES NO DIF AMONG TYPES.
        bcc LOPFND                      ; [MS 3694]
        inx                             ; [MS 3695]
        bne STXFND                      ; [MS 3696 BNEA] ALWAYS BRANCHES.

; [MS 3698]
; [MS 3699] TEST FOR A LETTER.	/ CARRY OFF= NOT A LETTER.
; [MS 3700] CARRY ON= A LETTER.
; [MS 3701]
ISLETC:                                 ; [MS 3702]
        cmp #'A'                        ; [MS 3702]
        bcc ISLRTS                      ; [MS 3703] IF LESS THAN "A", RET.
        sbc #'Z'+1                      ; [MS 3704]
        sec                             ; [MS 3705]
        sbc #256-'Z'-1                  ; [MS 3706] RESET CARRY IF [A] .GT. "Z".
ISLRTS:                                 ; [MS 3707]
        rts                             ; [MS 3707] RETURN TO CALLER.

NOTFNS:                                 ; [MS 3709]
        pla                             ; [MS 3709] CHECK WHO'S CALLING.
        pha                             ; [MS 3710] RESTORE IT.
        cmp #<(ISVRET-1-(ISVRET-1)/256*256) ; [MS 3711] IS EVAL CALLING?
        bne NOTEVL                      ; [MS 3712] NO, CARRY ON.

        tsx                             ; [MS 3714]
        lda 258,x                       ; [MS 3715]
        cmp #<(((ISVRET-1)/256))        ; [MS 3716]
        bne NOTEVL                      ; [MS 3717]
LDZR:                                   ; [MS 3718]
        lda #<ZERO                      ; [MS 3718 LDWDI]
        ldy #>ZERO                      ; [MS 3718 LDWDI] SET UP PNTR TO SIMULATED ZERO.
        rts                             ; [MS 3719] FOR STRINGS OR NUMERIC.
; [MS 3720] AND FOR INTEGERS TOO.
NOTEVL:                                 ; [MS 3721]



QSTAVR:                                 ; [MS 3733]

VAROK:                                  ; [MS 3739]
        lda ARYTAB                      ; [MS 3739 LDWD]
        ldy ARYTAB+1                    ; [MS 3739 LDWD]
        sta LOWTR                       ; [MS 3740 STWD]
        sty LOWTR+1                     ; [MS 3740 STWD] LOWEST THING TO MOVE.
        lda STREND                      ; [MS 3741 LDWD]
        ldy STREND+1                    ; [MS 3741 LDWD] GET HIGHEST ADDR TO MOVE.
        sta HIGHTR                      ; [MS 3742 STWD]
        sty HIGHTR+1                    ; [MS 3742 STWD]
        clc                             ; [MS 3743]
        adc #6+ADDPRC                   ; [MS 3744]
        bcc NOTEVE                      ; [MS 3745]
        iny                             ; [MS 3746]
NOTEVE:                                 ; [MS 3747]
        sta HIGHDS                      ; [MS 3747 STWD]
        sty HIGHDS+1                    ; [MS 3747 STWD] PLACE TO STUFF IT.
        jsr BLTU                        ; [MS 3748] MOVE IT ALL.
; [MS 3749] NOTE [Y,A] HAS [HIGHDS] FOR REASON.
        lda HIGHDS                      ; [MS 3750 LDWD]
        ldy HIGHDS+1                    ; [MS 3750 LDWD] AND SET UP
        iny                             ; [MS 3751]
        sta ARYTAB                      ; [MS 3752 STWD]
        sty ARYTAB+1                    ; [MS 3752 STWD] NEW START OF ARRAY TABLE.
        ldy #0                          ; [MS 3753] GET ADDR OF VARIABLE ENTRY.
        lda VARNAM                      ; [MS 3754]
        sta (LOWTR),y                   ; [MS 3755]
        iny                             ; [MS 3756]
        lda VARNAM+1                    ; [MS 3757]
        sta (LOWTR),y                   ; [MS 3758] STORE NAME OF VARIABLE.
        lda #0                          ; [MS 3759]
        iny                             ; [MS 3760]
        sta (LOWTR),y                   ; [MS 3761]
        iny                             ; [MS 3762]
        sta (LOWTR),y                   ; [MS 3763]
        iny                             ; [MS 3764]
        sta (LOWTR),y                   ; [MS 3765]
        iny                             ; [MS 3766]
        sta (LOWTR),y                   ; [MS 3767] FOURTH ZERO FOR DEF FUNC.

        iny                             ; [MS 3769]
        sta (LOWTR),y                   ; [MS 3770]
FINPTR:                                 ; [MS 3771]
        lda LOWTR                       ; [MS 3771]
        clc                             ; [MS 3772]
        adc #2                          ; [MS 3773]
        ldy LOWTR+1                     ; [MS 3774]
        bcc FINNOW                      ; [MS 3775]
        iny                             ; [MS 3776]
FINNOW:                                 ; [MS 3777]
        sta VARPNT                      ; [MS 3777 STWD]
        sty VARPNT+1                    ; [MS 3777 STWD] THIS IS IT.
        rts                             ; [MS 3778]
; [MS 3780] ==== MULTIPLE DIMENSION CODE. ====
FMAPTR:                                 ; [MS 3781]
        lda COUNT                       ; [MS 3781]
        asl a                           ; [MS 3782]
        adc #5                          ; [MS 3783] POINT TO ENTRIES. C CLR'D BY ASL.
        adc LOWTR                       ; [MS 3784]
        ldy LOWTR+1                     ; [MS 3785]
        bcc JSRGM                       ; [MS 3786]
        iny                             ; [MS 3787]
JSRGM:                                  ; [MS 3788]
        sta ARYPNT                      ; [MS 3788 STWD]
        sty ARYPNT+1                    ; [MS 3788 STWD]
        rts                             ; [MS 3789]

N32768:                                 ; [MS 3791]
        .byte 144, 128, 0, 0            ; [MS 3791] -32768.

; [MS 3793]
; [MS 3794] INTIDX READS A FORMULA FROM THE CURRENT POSITION AND
; [MS 3795] TURNS IT INTO A POSITIVE INTEGER
; [MS 3796] LEAVING THE RESULT IN FACMO&LO. NEGATIVE ARGUMENTS
; [MS 3797] ARE NOT ALLOWED.
; [MS 3798]
INTIDX:                                 ; [MS 3799]
        jsr CHRGET                      ; [MS 3799]
        jsr FRMEVL                      ; [MS 3800] GET A NUMBER
POSINT:                                 ; [MS 3801]
        jsr CHKNUM                      ; [MS 3801]
        lda FACSGN                      ; [MS 3802]
        bmi NONONO                      ; [MS 3803] IF NEGATIVE, BLOW HIM OUT.
AYINT:                                  ; [MS 3804]
        lda FACEXP                      ; [MS 3804]
        cmp #144                        ; [MS 3805] FAC .GT. 32767?
        bcc QINTGO                      ; [MS 3806]
        lda #<N32768                    ; [MS 3807 LDWDI]
        ldy #>N32768                    ; [MS 3807 LDWDI] GET ADDR OF -32768.
        jsr FCOMP                       ; [MS 3808] SEE IF FAC=[[Y,A]].
NONONO:                                 ; [MS 3809]
        bne IQERR                       ; [MS 3809] NO, FAC IS TOO BIG. [OURS] via IQERR: FCERR is out of branch range past it
QINTGO:                                 ; [MS 3810]
        jmp QINT                        ; [MS 3810] GO TO QINT AND SHOVE IT.
; [MS 3811]
; [MS 3812] FORMAT OF ARRAYS IN CORE.
; [MS 3813]
; [MS 3814] DESCRIPTOR:
; [MS 3815] LOWBYTE = FIRST CHARACTER.
; [MS 3816] HIGHBYTE = SECOND CHARACTER (200 BIT IS STRING FLAG).
; [MS 3817] LENGTH OF ARRAY IN CORE IN BYTES (INCLUDES EVERYTHING).
; [MS 3818] NUMBER OF DIMENSIONS.
; [MS 3819] FOR EACH DIMENSION STARTING WITH THE FIRST A LIST
; [MS 3820] (2 BYTES EACH) OF THE MAX INDICE+1
; [MS 3821] THE VALUES
; [MS 3822]
ISARY:                                  ; [MS 3823]
        lda DIMFLG                      ; [MS 3823]

        ora INTFLG                      ; [MS 3825]
        pha                             ; [MS 3826] SAVE [DIMFLG] FOR RECURSION.
        lda VALTYP                      ; [MS 3827]
        pha                             ; [MS 3828] SAVE [VALTYP] FOR RECURSION.
        ldy #0                          ; [MS 3829] SET NUMBER OF DIMENSIONS TO ZERO.
INDLOP:                                 ; [MS 3830]
        tya                             ; [MS 3830] SAVE NUMBER OF DIMS.
        pha                             ; [MS 3831]
        lda VARNAM+1                    ; [MS 3832 PSHWD]
        pha                             ; [MS 3832 PSHWD]
        lda VARNAM                      ; [MS 3832 PSHWD]
        pha                             ; [MS 3832 PSHWD] SAVE LOOKS.
        jsr INTIDX                      ; [MS 3833] EVALUATE INDICE INTO FACMO&LO.
        pla                             ; [MS 3834 PULWD]
        sta VARNAM                      ; [MS 3834 PULWD]
        pla                             ; [MS 3834 PULWD]
        sta VARNAM+1                    ; [MS 3834 PULWD] GET BACK ALL... WE'RE HOME.
        pla                             ; [MS 3835] (# OF DIMS).
        tay                             ; [MS 3836]
        tsx                             ; [MS 3837]
        lda 258,x                       ; [MS 3838]
        pha                             ; [MS 3839] PUSH DIMFLG AND VALTYP FURTHER.
        lda 257,x                       ; [MS 3840]
        pha                             ; [MS 3841]
        lda INDICE                      ; [MS 3842] PUT INDICE ONTO STACK.
        sta 258,x                       ; [MS 3843] UNDER DIMFLG AND VALTYP.
        lda INDICE+1                    ; [MS 3844]
        sta 257,x                       ; [MS 3845]
        iny                             ; [MS 3846] INCREMENT # OF DIMS.
        jsr CHRGOT                      ; [MS 3847] GET TERMINATING CHARACTER.
        cmp #44                         ; [MS 3848] A COMMA?
        beq INDLOP                      ; [MS 3849] YES.
        sty COUNT                       ; [MS 3850] SAVE COUNT OF DIMS.
        jsr CHKCLS                      ; [MS 3851] MUST BE CLOSED PAREN.
        pla                             ; [MS 3852]
        sta VALTYP                      ; [MS 3853] GET VALTYP AND
        pla                             ; [MS 3854]

        sta INTFLG                      ; [MS 3856]
        and #127                        ; [MS 3857]
        sta DIMFLG                      ; [MS 3858] DIMFLG OFF STACK.
        ldx ARYTAB                      ; [MS 3859] PLACE TO START SEARCH.
        lda ARYTAB+1                    ; [MS 3860]
        jmp LOPFDA                      ; [OURS] step over the pinned entry point
        ALIGN $E199
IQERR:  jmp FCERR                       ; [OURS] [RM] $E199 IQERR: ?ILLEGAL QUANTITY ERROR (Oregon Trail's & library JMPs here)
LOPFDA:                                 ; [MS 3861]
        stx LOWTR                       ; [MS 3861]
        sta LOWTR+1                     ; [MS 3862]
        cmp STREND+1                    ; [MS 3863] END OF ARRAYS?
        bne LOPFDV                      ; [MS 3864]
        cpx STREND                      ; [MS 3865]
        beq NOTFDD                      ; [MS 3866] A FINE THING! NO ARRAY!.
LOPFDV:                                 ; [MS 3867]
        ldy #0                          ; [MS 3867]
        lda (LOWTR),y                   ; [MS 3868]
        iny                             ; [MS 3869]
        cmp VARNAM                      ; [MS 3870] COMPARE HIGH ORDERS.
        bne NMARY1                      ; [MS 3871] NO WAY IS IT THIS. GET OUT OF HERE.
        lda VARNAM+1                    ; [MS 3872]
        cmp (LOWTR),y                   ; [MS 3873] LOW ORDERS?
        beq GOTARY                      ; [MS 3874] WELL, HERE IT IS !!
NMARY1:                                 ; [MS 3875]
        iny                             ; [MS 3875]
        lda (LOWTR),y                   ; [MS 3876] GET LENGTH.
        clc                             ; [MS 3877]
        adc LOWTR                       ; [MS 3878]
        tax                             ; [MS 3879]
        iny                             ; [MS 3880]
        lda (LOWTR),y                   ; [MS 3881]
        adc LOWTR+1                     ; [MS 3882]
        bcc LOPFDA                      ; [MS 3883] ALWAYS BRANCHES.
BSERR:                                  ; [MS 3884]
        ldx #ERRBS                      ; [MS 3884] GET BAD SUB ERROR NUMBER.
        .byte $2C                       ; [MS 3885 SKIP2]
FCERR:                                  ; [MS 3886]
        ldx #ERRFC                      ; [MS 3886] TOO BIG. "FUNCTION CALL" ERROR.
ERRGO3:                                 ; [MS 3887]
        jmp ERROR                       ; [MS 3887]
GOTARY:                                 ; [MS 3888]
        ldx #ERRDD                      ; [MS 3888] PERHAPS A "RE-DIMENSION" ERROR
        lda DIMFLG                      ; [MS 3889] TEST THE DIMFLG
        bne ERRGO3                      ; [MS 3890]
        jsr FMAPTR                      ; [MS 3891]
        lda COUNT                       ; [MS 3892] GET NUMBER OF DIMS INPUT.
        ldy #4                          ; [MS 3893]
        cmp (LOWTR),y                   ; [MS 3894] # OF DIMS THE SAME?
        bne BSERR                       ; [MS 3895] SAME SO GO GET DEFINITION.
        jmp GETDEF                      ; [MS 3896]

; [MS 3898]
; [MS 3899] HERE WHEN VARIABLE IS NOT FOUND IN THE ARRAY TABLE.
; [MS 3900]
; [MS 3901] BUILDING AN ENTRY.
; [MS 3902]
; [MS 3903] PUT DOWN THE DESCRIPTOR.
; [MS 3904] SETUP NUMBER OF DIMENSIONS.
; [MS 3905] MAKE SURE THERE IS ROOM FOR THE NEW ENTRY.
; [MS 3906] REMEMBER "VARPNT".
; [MS 3907] TALLY=4.
; [MS 3908] SKIP 2 LOCS FOR LATER FILL IN OF SIZE.
; [MS 3909] LOOP: GET AN INDICE
; [MS 3910] PUT DOWN NUMBER+1 AND INCREMENT VARPTR.
; [MS 3911] TALLY=TALLY*NUMBER+1.
; [MS 3912] DECREMENT NUMBER-DIMS.
; [MS 3913] BNE LOOP
; [MS 3914] CALL "REASON" WITH [Y,A] REFLECTING LAST LOC OF VARIABLE.
; [MS 3915] UPDATE STREND.
; [MS 3916] ZERO ALL.
; [MS 3917] MAKE TALLY INCLUDE MAXDIMS AND DESCRIPTOR.
; [MS 3918] PUT DOWN TALLY.
; [MS 3919] IF CALLED BY DIMENSION, RETURN.
; [MS 3920] OTHERWISE INDEX INTO THE VARIABLE AS IF IT
; [MS 3921] WERE FOUND ON THE INITIAL SEARCH.
; [MS 3922]
NOTFDD:                                 ; [MS 3923]
        jsr FMAPTR                      ; [MS 3923] FORM ARYPNT.
        jsr REASON                      ; [MS 3924]
        lda #0                          ; [MS 3925]
        tay                             ; [MS 3926]
        sta CURTOL+1                    ; [MS 3927]


        ldx #5                          ; [MS 3931]
        lda VARNAM                      ; [MS 3932] THIS CODE ONLY WORKS FOR INTPRC=1
        sta (LOWTR),y                   ; [MS 3933] IF ADDPRC=1.

        bpl NOTFLT                      ; [MS 3935]
        dex                             ; [MS 3936]
NOTFLT:                                 ; [MS 3937]
        iny                             ; [MS 3937]
        lda VARNAM+1                    ; [MS 3938]
        sta (LOWTR),y                   ; [MS 3939]
        bpl STOMLT                      ; [MS 3940]
        dex                             ; [MS 3941]

        dex                             ; [MS 3943]
STOMLT:                                 ; [MS 3944]
        stx CURTOL                      ; [MS 3944]
        lda COUNT                       ; [MS 3945]
        iny                             ; [MS 3946]
        iny                             ; [MS 3946]
        iny                             ; [MS 3946]
        sta (LOWTR),y                   ; [MS 3947] SAVE NUMBER OF DIMENSIONS.
LOPPTA:                                 ; [MS 3948]
        ldx #11                         ; [MS 3948] DEFAULT SIZE.
        lda #0                          ; [MS 3949]
        bit DIMFLG                      ; [MS 3950]
        bvc NOTDIM                      ; [MS 3951] NOT IN A DIM STATEMENT.
        pla                             ; [MS 3952] GET LOW ORDER OF INDICE.
        clc                             ; [MS 3953]
        adc #1                          ; [MS 3954]
        tax                             ; [MS 3955]
        pla                             ; [MS 3956] GET HIGH PART OF INDICE.
        adc #0                          ; [MS 3957]
NOTDIM:                                 ; [MS 3958]
        iny                             ; [MS 3958]
        sta (LOWTR),y                   ; [MS 3959] STORE HIGH PART OF INDICE.
        iny                             ; [MS 3960]
        txa                             ; [MS 3961]
        sta (LOWTR),y                   ; [MS 3962] STORE LOW ORDER OF INDICE.
        jsr UMULT                       ; [MS 3963] [X,A]=[CURTOL]*[LOWTR,Y]
        stx CURTOL                      ; [MS 3964] SAVE NEW TALLY.
        sta CURTOL+1                    ; [MS 3965]
        ldy INDEX                       ; [MS 3966]
        dec COUNT                       ; [MS 3967] ANY MORE INDICES LEFT?
        bne LOPPTA                      ; [MS 3968] YES.
        adc ARYPNT+1                    ; [MS 3969]
        bcs OMERR1                      ; [MS 3970] OVERFLOW.
        sta ARYPNT+1                    ; [MS 3971] COMPUTE WHERE TO ZERO.
        tay                             ; [MS 3972]
        txa                             ; [MS 3973]
        adc ARYPNT                      ; [MS 3974]
        bcc GREASE                      ; [MS 3975]
        iny                             ; [MS 3976]
        beq OMERR1                      ; [MS 3977]
GREASE:                                 ; [MS 3978]
        jsr REASON                      ; [MS 3978] GET ROOM.
        sta STREND                      ; [MS 3979 STWD]
        sty STREND+1                    ; [MS 3979 STWD] NEW END OF STORAGE.
        lda #0                          ; [MS 3980] STORING [ACCA] IS FASTER THAN CLEAR.
        inc CURTOL+1                    ; [MS 3981]
        ldy CURTOL                      ; [MS 3982]
        beq DECCUR                      ; [MS 3983]
ZERITA:                                 ; [MS 3984]
        dey                             ; [MS 3984]
        sta (ARYPNT),y                  ; [MS 3985]
        bne ZERITA                      ; [MS 3986] NO. CONTINUE.
DECCUR:                                 ; [MS 3987]
        dec ARYPNT+1                    ; [MS 3987]
        dec CURTOL+1                    ; [MS 3988]
        bne ZERITA                      ; [MS 3989] DO ANOTHER BLOCK.
        inc ARYPNT+1                    ; [MS 3990] BUMP BACK UP. WILL USE LATER.
        sec                             ; [MS 3991]
        lda STREND                      ; [MS 3992] RESTORE [ACCA].
        sbc LOWTR                       ; [MS 3993] DETERMINE LENGTH.
        ldy #2                          ; [MS 3994]
        sta (LOWTR),y                   ; [MS 3995] LOW.
        lda STREND+1                    ; [MS 3996]
        iny                             ; [MS 3997]
        sbc LOWTR+1                     ; [MS 3998]
        sta (LOWTR),y                   ; [MS 3999] HIGH.
        lda DIMFLG                      ; [MS 4000]
        bne DIMRTS                      ; [MS 4001] BYE.
        iny                             ; [MS 4002]
; [MS 4003]
; [MS 4004] AT THIS POINT [LOWTR,Y] POINTS BEYOND THE SIZE TO THE NUMBER OF
; [MS 4005] DIMENSIONS. STRATEGY:
; [MS 4006] NUMDIM=NUMBER OF DIMENSIONS.
; [MS 4007] CURTOL=0.
; [MS 4008] INLPNM:GET A NEW INDICE.
; [MS 4009] MAKE SURE INDICE IS NOT TOO BIG.
; [MS 4010] MULTIPLY CURTOL BY CURMAX.
; [MS 4011] ADD INDICE TO CURTOL.
; [MS 4012] NUMDIM=NUMDIM-1.
; [MS 4013] BNE	INLPNM.
; [MS 4014] USE [CURTOL]*4 AS OFFSET.
; [MS 4015]
GETDEF:                                 ; [MS 4016]
        lda (LOWTR),y                   ; [MS 4016]
        sta COUNT                       ; [MS 4017] SAVE A COUNTER.
        lda #0                          ; [MS 4018] ZERO [CURTOL].
        sta CURTOL                      ; [MS 4019]
INLPNM:                                 ; [MS 4020]
        sta CURTOL+1                    ; [MS 4020]
        iny                             ; [MS 4021]
        pla                             ; [MS 4022] GET LOW INDICE.
        tax                             ; [MS 4023]
        sta INDICE                      ; [MS 4024]
        pla                             ; [MS 4025] AND THE HIGH PART
        sta INDICE+1                    ; [MS 4026]
        cmp (LOWTR),y                   ; [MS 4027] COMPARE WITH MAX INDICE.
        bcc INLPN2                      ; [MS 4028]
        bne BSERR7                      ; [MS 4029] IF GREATER, "BAD SUBSCRIPT" ERROR.
        iny                             ; [MS 4030]
        txa                             ; [MS 4031]
        cmp (LOWTR),y                   ; [MS 4032]
        bcc INLPN1                      ; [MS 4033]
BSERR7:                                 ; [MS 4034]
        jmp BSERR                       ; [MS 4034]
OMERR1:                                 ; [MS 4035]
        jmp OMERR                       ; [MS 4035]
INLPN2:                                 ; [MS 4036]
        iny                             ; [MS 4036]
INLPN1:                                 ; [MS 4037]
        lda CURTOL+1                    ; [MS 4037] DON'T MULTIPLY IF CURTOL=0.
        ora CURTOL                      ; [MS 4038]
        clc                             ; [MS 4039] PREPARE TO GET INDICE BACK.
        beq ADDIND                      ; [MS 4040] GET HIGH PART OF INDICE BACK.
        jsr UMULT                       ; [MS 4041] MULTIPLY [CURTOL] BY [LOWTR,Y,Y+1].
        txa                             ; [MS 4042]
        adc INDICE                      ; [MS 4043] ADD IN [INDICE].
        tax                             ; [MS 4044]
        tya                             ; [MS 4045]
        ldy INDEX1                      ; [MS 4046]
ADDIND:                                 ; [MS 4047]
        adc INDICE+1                    ; [MS 4047]
        stx CURTOL                      ; [MS 4048]
        dec COUNT                       ; [MS 4049] ANY MORE?
        bne INLPNM                      ; [MS 4050] YES.
        sta CURTOL+1                    ; [MS 4051] FIX ARRAY BUG ****


        ldx #5                          ; [MS 4055] THIS CODE ONLY WORKS FOR INTPRC=1
        lda VARNAM                      ; [MS 4056] IF ADDPRC=1.
        bpl NOTFL1                      ; [MS 4057]
        dex                             ; [MS 4058]
NOTFL1:                                 ; [MS 4059]
        lda VARNAM+1                    ; [MS 4059]
        bpl STOML1                      ; [MS 4060]
        dex                             ; [MS 4061]

        dex                             ; [MS 4063]
STOML1:                                 ; [MS 4064]
        stx ADDEND                      ; [MS 4064]
        lda #0                          ; [MS 4065]
        jsr UMULTD                      ; [MS 4066] ON RTS, A&Y=HI . X=LO.
        txa                             ; [MS 4067]
        adc ARYPNT                      ; [MS 4068]
        sta VARPNT                      ; [MS 4069]
        tya                             ; [MS 4070]
        adc ARYPNT+1                    ; [MS 4071]
        sta VARPNT+1                    ; [MS 4072]
        tay                             ; [MS 4073]
        lda VARPNT                      ; [MS 4074]
DIMRTS:                                 ; [MS 4075]
        rts                             ; [MS 4075] RETURN TO CALLER.
; [MS 4076] ==== INTEGER ARITHMETIC ROUTINES. ====
; [MS 4077] TWO BYTE UNSIGNED INTEGER MULTIPLY.
; [MS 4078] THIS IS FOR MULTIPLY DIMENSIONED ARRAYS.
; [MS 4079] [X,Y]=[X,A]=[CURTOL]*[LOWTR,Y,Y+1].
; [MS 4112] ==== FRE FUNCTION AND INTEGER TO FLOATING ROUTINES. ====
FRE:                                    ; [MS 4113]
        lda VALTYP                      ; [MS 4113]
        beq NOFREF                      ; [MS 4114]
        jsr FREFAC                      ; [MS 4115]
NOFREF:                                 ; [MS 4116]
        jsr GARBA2                      ; [MS 4116]
        sec                             ; [MS 4117]
        lda FRETOP                      ; [MS 4118] WE WANT
        sbc STREND                      ; [MS 4119] [FRETOP]-[STREND].
        tay                             ; [MS 4120]
        lda FRETOP+1                    ; [MS 4121]
        sbc STREND+1                    ; [MS 4122]

        jmp GIVAYF                      ; [OURS] FRE fell into GIVAYF; GIVAYF now sits on Applesoft's $E2F2
        ALIGN $E2F2                     ; [OURS] [RM] GIVAYF, POS and SNGFLT on Applesoft's addresses
GIVAYF:                                 ; [MS 4124]
        ldx #0                          ; [MS 4124]
        stx VALTYP                      ; [MS 4125]
        sta FACHO                       ; [MS 4126 STWD]
        sty FACHO+1                     ; [MS 4126 STWD]
        ldx #144                        ; [MS 4127] SET EXPONENT TO 2^16.
        jmp FLOATS                      ; [MS 4128] TURN IT TO A FLOATING PNT #.

POS:                                    ; [MS 4130]
        ldy TRMPOS                      ; [MS 4130] GET POSITION.
SNGFLT:                                 ; [MS 4131]
        lda #0                          ; [MS 4131]
        beq GIVAYF                      ; [MS 4132 BEQA] FLOAT IT.
; [MS 4134] ==== SIMPLE-USER-DEFINED-FUNCTION CODE. ====
; [MS 4135]
; [MS 4136] NOTE ONLY SINGLE ARGUMENTS ARE ALLOWED TO FUNCTIONS
; [MS 4137] AND FUNCTIONS MUST BE OF THE SINGLE LINE FORM:
; [MS 4138] DEF FNA(X)=X^2+X-2
; [MS 4139] NO STRINGS CAN BE INVOLVED WITH THESE FUNCTIONS.
; [MS 4140]
; [MS 4141] IDEA: CREATE A SIMPLE VARIABLE ENTRY
; [MS 4142] WHOSE FIRST CHARACTER HAS THE 200 BIT SET.
; [MS 4143] THE VALUE WILL BE:
; [MS 4144]
; [MS 4145] A TEXT PNTR TO THE FORMULA.
; [MS 4146] A PNTR TO THE ARGUMENT VARIABLE.
; [MS 4147]
; [MS 4148] FUNCTION NAMES CAN BE LIKE "FNA4".
; [MS 4149]
; [MS 4150]
; [MS 4151] SUBROUTINE TO SEE IF WE ARE IN DIRECT MODE.
; [MS 4152] AND COMPLAIN IF SO.
; [MS 4153]
        ALIGN $E306                     ; [OURS] [RM] ERRDIR on Applesoft's address (Microsoft's SNGFLT is a byte shorter)
ERRDIR:                                 ; [MS 4154]
        ldx CURLIN+1                    ; [MS 4154] DIR MODE HAS [CURLIN]=0,255
        inx                             ; [MS 4155] SO NOW, IS RESULT ZERO?
        bne DIMRTS                      ; [MS 4156] YES.
        ldx #ERRID                      ; [MS 4157] INPUT DIRECT ERROR CODE.
        .byte $2C                       ; [MS 4158 SKIP2]
ERRGUF:                                 ; [MS 4159]
        ldx #ERRUF                      ; [MS 4159] USER DEFINED FUNCTION NEVER DEFINED
ERRGO1:                                 ; [MS 4160]
        jmp ERROR                       ; [MS 4160]

DEF:                                    ; [MS 4162]
        jsr GETFNM                      ; [MS 4162] GET A PNTR TO THE FUNCTION.
        jsr ERRDIR                      ; [MS 4163]
        jsr CHKOPN                      ; [MS 4164] MUST HAVE "(".
        lda #128                        ; [MS 4165]
        sta SUBFLG                      ; [MS 4166] PROHIBIT SUBSCRIPTED VARIABLES.
        jsr PTRGET                      ; [MS 4167] GET PNTR TO ARGUMENT.
        jsr CHKNUM                      ; [MS 4168] IS IT A NUMBER?
        jsr CHKCLS                      ; [MS 4169] MUST HAVE ")"
        lda #EQULTK                     ; [MS 4170 SYNCHK]
        jsr SYNCHR                      ; [MS 4170 SYNCHK] MUST HAVE "=".
        pha                             ; [MS 4171] PUT CRAZY BYTE ON.
        lda VARPNT+1                    ; [MS 4172 PSHWD]
        pha                             ; [MS 4172 PSHWD]
        lda VARPNT                      ; [MS 4172 PSHWD]
        pha                             ; [MS 4172 PSHWD]
        lda TXTPTR+1                    ; [MS 4173 PSHWD]
        pha                             ; [MS 4173 PSHWD]
        lda TXTPTR                      ; [MS 4173 PSHWD]
        pha                             ; [MS 4173 PSHWD]
        jsr DATA                        ; [MS 4174]
        jmp DEFFIN                      ; [MS 4175]
; [MS 4176]
; [MS 4177] SUBROUTINE TO GET A PNTR TO A FUNCTION NAME.
; [MS 4178]
GETFNM:                                 ; [MS 4179]
        lda #FNTK                       ; [MS 4179 SYNCHK]
        jsr SYNCHR                      ; [MS 4179 SYNCHK] MUST START WITH FN.
        ora #128                        ; [MS 4180] PUT FUNCTION BIT ON.
        sta SUBFLG                      ; [MS 4181]
        jsr PTRGT2                      ; [MS 4182] GET POINTER TO FUNCTION OR CREATE ANEW.
        sta DEFPNT                      ; [MS 4183 STWD]
        sty DEFPNT+1                    ; [MS 4183 STWD]
        jmp CHKNUM                      ; [MS 4184] MAKE SURE IT'S NOT A STRING AND RETURN.

FNDOER:                                 ; [MS 4186]
        jsr GETFNM                      ; [MS 4186] GET THE FUNCTION'S NAME.
        lda DEFPNT+1                    ; [MS 4187 PSHWD]
        pha                             ; [MS 4187 PSHWD]
        lda DEFPNT                      ; [MS 4187 PSHWD]
        pha                             ; [MS 4187 PSHWD]
        jsr PARCHK                      ; [MS 4188] EVALUATE PARAMETER.
        jsr CHKNUM                      ; [MS 4189]
        pla                             ; [MS 4190 PULWD]
        sta DEFPNT                      ; [MS 4190 PULWD]
        pla                             ; [MS 4190 PULWD]
        sta DEFPNT+1                    ; [MS 4190 PULWD]
        ldy #2                          ; [MS 4191]
        lda (DEFPNT),y                  ; [MS 4192] GET POINTER TO VARIABLE.
        sta VARPNT                      ; [MS 4193] SAVE VARIABLE POINTER.
        tax                             ; [MS 4194]
        iny                             ; [MS 4195]
        lda (DEFPNT),y                  ; [MS 4196]
        beq ERRGUF                      ; [MS 4197]
        sta VARPNT+1                    ; [MS 4198]
        iny                             ; [MS 4199] SINCE DEF USES ONLY 4.
DEFSTF:                                 ; [MS 4200]
        lda (VARPNT),y                  ; [MS 4200]
        pha                             ; [MS 4201] PUSH IT ALL ON STACK.
        dey                             ; [MS 4202] SINCE WE ARE RECURSING MAYBE.
        bpl DEFSTF                      ; [MS 4203]
        ldy VARPNT+1                    ; [MS 4204]
        jsr MOVMF                       ; [MS 4205] PUT CURRENT FAC INTO OUR ARG VARIABLE.
        lda TXTPTR+1                    ; [MS 4206 PSHWD]
        pha                             ; [MS 4206 PSHWD]
        lda TXTPTR                      ; [MS 4206 PSHWD]
        pha                             ; [MS 4206 PSHWD] SAVE TEXT POINTER.
        lda (DEFPNT),y                  ; [MS 4207] PNTR TO FUNCTION.
        sta TXTPTR                      ; [MS 4208]
        iny                             ; [MS 4209]
        lda (DEFPNT),y                  ; [MS 4210]
        sta TXTPTR+1                    ; [MS 4211]
        lda VARPNT+1                    ; [MS 4212 PSHWD]
        pha                             ; [MS 4212 PSHWD]
        lda VARPNT                      ; [MS 4212 PSHWD]
        pha                             ; [MS 4212 PSHWD] SAVE VARIABLE POINTER.
        jsr FRMNUM                      ; [MS 4213] EVALUATE FORMULA AND CHECK NUMERIC.
        pla                             ; [MS 4214 PULWD]
        sta DEFPNT                      ; [MS 4214 PULWD]
        pla                             ; [MS 4214 PULWD]
        sta DEFPNT+1                    ; [MS 4214 PULWD]
        jsr CHRGOT                      ; [MS 4215]
        beq *+5                         ; [MS 4216 JNE]
        jmp SNERR                       ; [MS 4216 JNE] IT DIDN'T TERMINATE. HUH?
        pla                             ; [MS 4217 PULWD]
        sta TXTPTR                      ; [MS 4217 PULWD]
        pla                             ; [MS 4217 PULWD]
        sta TXTPTR+1                    ; [MS 4217 PULWD] RESTORE TEXT PNTR.
DEFFIN:                                 ; [MS 4218]
        ldy #0                          ; [MS 4218]
        pla                             ; [MS 4219] GET OLD ARG VALUE OFF STACK
        sta (DEFPNT),y                  ; [MS 4220] AND PUT IT BACK IN VARIABLE.
        pla                             ; [MS 4221]
        iny                             ; [MS 4222]
        sta (DEFPNT),y                  ; [MS 4223]
        pla                             ; [MS 4224]
        iny                             ; [MS 4225]
        sta (DEFPNT),y                  ; [MS 4226]
        pla                             ; [MS 4227]
        iny                             ; [MS 4228]
        sta (DEFPNT),y                  ; [MS 4229]

        pla                             ; [MS 4231]
        iny                             ; [MS 4232]
        sta (DEFPNT),y                  ; [MS 4233]
DEFRTS:                                 ; [MS 4234]
        rts                             ; [MS 4234]
; [MS 4236] ==== STRING FUNCTIONS. ====
; [MS 4237]
; [MS 4238] THE STR$ FUNCTION TAKES A NUMBER AND GIVES A STRING
; [MS 4239] WITH THE CHARACTERS THE OUTPUT OF THE NUMBER
; [MS 4240] WOULD HAVE GIVEN.
; [MS 4241]
STR:                                    ; [MS 4242]
        jsr CHKNUM                      ; [MS 4242] ARG HAS TO BE NUMERIC.
        ldy #0                          ; [MS 4243]
        jsr FOUTC                       ; [MS 4244] DO ITS OUTPUT.
        pla                             ; [MS 4245]
        pla                             ; [MS 4246]
TIMSTR:                                 ; [MS 4247]
        jmp STRSP                       ; [MS 4247-4248] [OURS] STR$'s space skip is out of line (STRSP), so this keeps Microsoft's six bytes
        .byte $02, $02, $02             ; [OURS] and the routines after it keep Applesoft's addresses
; [MS 4249]
; [MS 4250] "STRINI" GET STRING SPACE FOR THE CREATION OF A STRING AND
; [MS 4251] CREATES A DESCRIPTOR FOR IT IN "DSCTMP".
; [MS 4252]
STRINI:                                 ; [MS 4253]
        ldx FACMO                       ; [MS 4253 LDXY]
        ldy FACMO+1                     ; [MS 4253 LDXY] GET FACMO TO STORE IN DSCPNT.
        stx DSCPNT                      ; [MS 4254 STXY]
        sty DSCPNT+1                    ; [MS 4254 STXY] RETAIN THE DESCRIPTOR POINTER.
STRSPA:                                 ; [MS 4255]
        jsr GETSPA                      ; [MS 4255] GET STRING SPACE.
        stx DSCTMP+1                    ; [MS 4256 STXY]
        sty 0+(DSCTMP+1)+1              ; [MS 4256 STXY] SAVE LOCATION.
        sta DSCTMP                      ; [MS 4257] SAVE LENGTH.
        rts                             ; [MS 4258] ALL DONE.
; [MS 4259]
; [MS 4260] "STRLT2" TAKES THE STRING LITERAL WHOSE FIRST CHARACTER
; [MS 4261] IS POINTED TO BY [Y,A] AND BUILDS A DESCRIPTOR FOR IT.
; [MS 4262] THE DESCRIPTOR IS INITIALLY BUILT IN "DSCTMP", BUT "PUTNEW"
; [MS 4263] TRANSFERS IT INTO A TEMPORARY AND LEAVES A POINTER
; [MS 4264] AT THE TEMPORARY IN FACMO&LO. THE CHARACTERS OTHER THAN
; [MS 4265] ZERO THAT TERMINATE THE STRING SHOULD BE SET UP IN "CHARAC"
; [MS 4266] AND "ENDCHR". IF THE TERMINATOR IS A QUOTE, THE QUOTE IS SKIPPED
; [MS 4267] OVER. LEADING QUOTES SHOULD BE SKIPPED BEFORE JSR. ON RETURN
; [MS 4268] THE CHARACTER AFTER THE STRING LITERAL IS POINTED TO
; [MS 4269] BY [STRNG2].
; [MS 4270]
STRLIT:                                 ; [MS 4271]
        ldx #34                         ; [MS 4271] ASSUME STRING ENDS ON QUOTE.
        stx CHARAC                      ; [MS 4272]
        stx ENDCHR                      ; [MS 4273]
STRLT2:                                 ; [MS 4274]
        sta STRNG1                      ; [MS 4274 STWD]
        sty STRNG1+1                    ; [MS 4274 STWD] SAVE POINTER TO STRING.
        sta DSCTMP+1                    ; [MS 4275 STWD]
        sty 0+(DSCTMP+1)+1              ; [MS 4275 STWD] IN CASE NO STRCPY.
        ldy #255                        ; [MS 4276] INITIALIZE CHARACTER COUNT.
STRGET:                                 ; [MS 4277]
        iny                             ; [MS 4277]
        lda (STRNG1),y                  ; [MS 4278] GET CHARACTER.
        beq STRFI1                      ; [MS 4279] IF ZERO.
        cmp CHARAC                      ; [MS 4280] THIS TERMINATOR?
        beq STRFIN                      ; [MS 4281] YES.
        cmp ENDCHR                      ; [MS 4282]
        bne STRGET                      ; [MS 4283] LOOK FURTHER.
STRFIN:                                 ; [MS 4284]
        cmp #34                         ; [MS 4284] QUOTE?
        beq STRFI2                      ; [MS 4285]
STRFI1:                                 ; [MS 4286]
        clc                             ; [MS 4286] NO, BACK UP.
STRFI2:                                 ; [MS 4287]
        sty DSCTMP                      ; [MS 4287] RETAIN COUNT.
        tya                             ; [MS 4288]
        adc STRNG1                      ; [MS 4289] WISHING TO SET [TXTPTR].
        sta STRNG2                      ; [MS 4290]
        ldx STRNG1+1                    ; [MS 4291]
        bcc STRST2                      ; [MS 4292]
        inx                             ; [MS 4293]
STRST2:                                 ; [MS 4294]
        stx STRNG2+1                    ; [MS 4294]
        lda STRNG1+1                    ; [MS 4295] IF PAGE 0, COPY SINCE IT IS EITHER
; [MS 4296] A STRING CONSTANT IN BUF OR A STR$
; [MS 4297] RESULT IN LOFBUF

        beq STRCP                       ; [MS 4299]
        cmp #2                          ; [MS 4300]
        bne PUTNEW                      ; [MS 4301]
STRCP:                                  ; [MS 4302]
        tya                             ; [MS 4302]
        jsr STRINI                      ; [MS 4303]
        ldx STRNG1                      ; [MS 4304 LDXY]
        ldy STRNG1+1                    ; [MS 4304 LDXY]
        jsr MOVSTR                      ; [MS 4305] MOVE STRING.
; [MS 4306]
; [MS 4307] SOME STRING FUNCTION IS RETURNING A RESULT IN DSCTMP.
; [MS 4308] SETUP A TEMP DESCRIPTOR WITH DSCTMP IN IT.
; [MS 4309] PUT A POINTER TO THE DESCRIPTOR IN FACMO&LO AND FLAG THE
; [MS 4310] RESULT AS TYPE STRING.
; [MS 4311]
PUTNEW:                                 ; [MS 4312]
        ldx TEMPPT                      ; [MS 4312] POINTER TO FIRST FREE TEMP.
        cpx #<(TEMPST+STRSIZ*NUMTMP)    ; [MS 4313]
        bne PUTNW1                      ; [MS 4314]
        ldx #ERRST                      ; [MS 4315] STRING TEMPORARY ERROR.
ERRGO2:                                 ; [MS 4316]
        jmp ERROR                       ; [MS 4316] GO TELL HIM.
PUTNW1:                                 ; [MS 4317]
        lda DSCTMP                      ; [MS 4317]
        sta 0,x                         ; [MS 4318]
        lda DSCTMP+1                    ; [MS 4319]
        sta 1,x                         ; [MS 4320]
        lda DSCTMP+2                    ; [MS 4321]
        sta 2,x                         ; [MS 4322]
        ldy #0                          ; [MS 4323]
        stx FACMO                       ; [MS 4324 STXY]
        sty FACMO+1                     ; [MS 4324 STXY]
        sty FACOV                       ; [MS 4325]
        dey                             ; [MS 4326]
        sty VALTYP                      ; [MS 4327] TYPE IS "STRING".
        stx LASTPT                      ; [MS 4328] SET POINTER TO LAST-USED TEMP.
        inx                             ; [MS 4329]
        inx                             ; [MS 4330]
        inx                             ; [MS 4331] POINT FURTHER.
        stx TEMPPT                      ; [MS 4332] SAVE POINTER TO NEXT TEMP IF ANY.
        rts                             ; [MS 4333] ALL DONE.

; [MS 4335]
; [MS 4336] GETSPA - GET SPACE FOR CHARACTER STRING.
; [MS 4337] MAY FORCE GARBAGE COLLECTION.
; [MS 4338]
; [MS 4339] # OF CHARACTERS (BYTES) IN ACCA.
; [MS 4340] RETURNS WITH POINTER IN [Y,X]. OTHERWISE (IF CAN'T GET
; [MS 4341] SPACE) BLOWS OFF TO "OUT OF STRING SPACE" TYPE ERROR.
; [MS 4342] ALSO PRESERVES [ACCA] AND SETS [FRESPC]=[Y,X]=PNTR AT SPACE.
; [MS 4343]
GETSPA:                                 ; [MS 4344]
        lsr GARBFL                      ; [MS 4344] SIGNAL NO GARBAGE COLLECTION YET.
TRYAG2:                                 ; [MS 4345]
        pha                             ; [MS 4345] SAVE FOR LATER.
        eor #255                        ; [MS 4346]
        sec                             ; [MS 4347] ADD ONE TO COMPLETE NEGATION.
        adc FRETOP                      ; [MS 4348]
        ldy FRETOP+1                    ; [MS 4349]
        bcs TRYAG3                      ; [MS 4350]
        dey                             ; [MS 4351]
TRYAG3:                                 ; [MS 4352]
        cpy STREND+1                    ; [MS 4352] COMPARE HIGH ORDERS.
        bcc GARBAG                      ; [MS 4353] MAKE ROOM FOR MORE.
        bne STRFRE                      ; [MS 4354] SAVE NEW FRETOP.
        cmp STREND                      ; [MS 4355] COMPARE LOW ORDERS.
        bcc GARBAG                      ; [MS 4356] CLEAN UP.
STRFRE:                                 ; [MS 4357]
        sta FRETOP                      ; [MS 4357 STWD]
        sty FRETOP+1                    ; [MS 4357 STWD] SAVE NEW [FRETOP].
        sta FRESPC                      ; [MS 4358 STWD]
        sty FRESPC+1                    ; [MS 4358 STWD] PUT IT THERE OLD MAN.
        tax                             ; [MS 4359] PRESERVE A IN X.
        pla                             ; [MS 4360] GET COUNT BACK IN ACCA.
        rts                             ; [MS 4361] ALL DONE.
GARBAG:                                 ; [MS 4362]
        ldx #ERROM                      ; [MS 4362] "OUT OF STRING SPACE"
        lda GARBFL                      ; [MS 4363]
        bmi ERRGO2                      ; [MS 4364]
        jsr GARBA2                      ; [MS 4365]
        lda #128                        ; [MS 4366]
        sta GARBFL                      ; [MS 4367]
        pla                             ; [MS 4368] GET BACK STRING LENGTH.
        bne TRYAG2                      ; [MS 4369] ALWAYS BRANCHES.
GARBA2:                                 ; [MS 4370] START FROM TOP DOWN.

        ldx MEMSIZ                      ; [MS 4374]
        lda MEMSIZ+1                    ; [MS 4375]
FNDVAR:                                 ; [MS 4376]
        stx FRETOP                      ; [MS 4376] LIKE SO.
        sta FRETOP+1                    ; [MS 4377]
        ldy #0                          ; [MS 4378]
        sty GRBPNT+1                    ; [MS 4379]
        sty GRBPNT                      ; [MS 4380] BOTH BYTES SET TO ZERO (FIX BUG)
        lda STREND                      ; [MS 4381 LDWX]
        ldx STREND+1                    ; [MS 4381 LDWX]
        sta GRBTOP                      ; [MS 4382 STWX]
        stx GRBTOP+1                    ; [MS 4382 STWX]
        lda #<TEMPST                    ; [MS 4383 LDWXI]
        ldx #>TEMPST                    ; [MS 4383 LDWXI]
        sta INDEX1                      ; [MS 4384 STWX]
        stx INDEX1+1                    ; [MS 4384 STWX]
TVAR:                                   ; [MS 4385]
        cmp TEMPPT                      ; [MS 4385] DONE WITH TEMPS?
        beq SVARS                       ; [MS 4386] YEP.
        jsr DVAR                        ; [MS 4387]
        beq TVAR                        ; [MS 4388] LOOP.
SVARS:                                  ; [MS 4389]
        lda #6+ADDPRC                   ; [MS 4389]
        sta FOUR6                       ; [MS 4390]
        lda VARTAB                      ; [MS 4391 LDWX]
        ldx VARTAB+1                    ; [MS 4391 LDWX] GET START OF SIMPLE VARIABLES.
        sta INDEX1                      ; [MS 4392 STWX]
        stx INDEX1+1                    ; [MS 4392 STWX]
SVAR:                                   ; [MS 4393]
        cpx ARYTAB+1                    ; [MS 4393] DONE WITH SIMPLE VARIABLES?
        bne SVARGO                      ; [MS 4394] NO.
        cmp ARYTAB                      ; [MS 4395]
        beq ARYVAR                      ; [MS 4396] YEP.
SVARGO:                                 ; [MS 4397]
        jsr DVARS                       ; [MS 4397] DO IT , AGAIN.
        beq SVAR                        ; [MS 4398] LOOP.
ARYVAR:                                 ; [MS 4399]
        sta ARYPNT                      ; [MS 4399 STWX]
        stx ARYPNT+1                    ; [MS 4399 STWX] SAVE FOR ADDITION.
        lda #STRSIZ                     ; [MS 4400]
        sta FOUR6                       ; [MS 4401]
ARYVA2:                                 ; [MS 4402]
        lda ARYPNT                      ; [MS 4402 LDWX]
        ldx ARYPNT+1                    ; [MS 4402 LDWX] GET THE POINTER TO VARIABLE.
ARYVA3:                                 ; [MS 4403]
        cpx STREND+1                    ; [MS 4403] DONE WITH ARRAYS?
        bne ARYVGO                      ; [MS 4404] NO.
        cmp STREND                      ; [MS 4405]
        bne *+5                         ; [MS 4406 JEQ]
        jmp GRBPAS                      ; [MS 4406 JEQ] YES, GO FINISH UP.
ARYVGO:                                 ; [MS 4407]
        sta INDEX1                      ; [MS 4407 STWX]
        stx INDEX1+1                    ; [MS 4407 STWX]
        ldy #1-ADDPRC                   ; [MS 4408]

        lda (INDEX1),y                  ; [MS 4410]
        tax                             ; [MS 4411]
        iny                             ; [MS 4412]
        lda (INDEX1),y                  ; [MS 4413]
        php                             ; [MS 4414]
        iny                             ; [MS 4415]
        lda (INDEX1),y                  ; [MS 4416]
        adc ARYPNT                      ; [MS 4417]
        sta ARYPNT                      ; [MS 4418] FORM POINTER TO NEXT ARRAY VAR.
        iny                             ; [MS 4419]
        lda (INDEX1),y                  ; [MS 4420]
        adc ARYPNT+1                    ; [MS 4421]
        sta ARYPNT+1                    ; [MS 4422]
        plp                             ; [MS 4423]
        bpl ARYVA2                      ; [MS 4424]

        txa                             ; [MS 4426]
        bmi ARYVA2                      ; [MS 4427]
        iny                             ; [MS 4428]
        lda (INDEX1),y                  ; [MS 4429]
        ldy #0                          ; [MS 4430] RESET INDEX Y.
        asl a                           ; [MS 4431]
        adc #5                          ; [MS 4432] CARRY IS OFF AND OFF AFTER ADD.
        adc INDEX1                      ; [MS 4433]
        sta INDEX1                      ; [MS 4434]
        bcc ARYGET                      ; [MS 4435]
        inc INDEX1+1                    ; [MS 4436]
ARYGET:                                 ; [MS 4437]
        ldx INDEX1+1                    ; [MS 4437]
ARYSTR:                                 ; [MS 4438]
        cpx ARYPNT+1                    ; [MS 4438] END OF THE ARRAY?
        bne GOGO                        ; [MS 4439]
        cmp ARYPNT                      ; [MS 4440]
        beq ARYVA3                      ; [MS 4441] YES.
GOGO:                                   ; [MS 4442]
        jsr DVAR                        ; [MS 4442]
        beq ARYSTR                      ; [MS 4443] CYCLE.
GRBRT2:                                 ; [OURS] GRBPAS's exit, kept here; the rest of DVARS (Microsoft's) is moved to the end
        ldx INDEX1+1                    ; [MS 4482]   of BASIC so CAT and what follows sit at Applesoft's addresses
        ldy #0                          ; [MS 4483]
        rts                             ; [MS 4484] DONE.
; [MS 4485]
; [MS 4486] HERE WHEN MADE ONE COMPLETE PASS THROUGH STRING VARIABLES.
; [MS 4487]
GRBPAS:                                 ; [MS 4488]
        lda GRBPNT+1                    ; [MS 4488] VARIABLE POINTER.
        ora GRBPNT                      ; [MS 4489]
        beq GRBRT2                      ; [MS 4490] ALL DONE. [OURS] the copy above
        lda SIZE                        ; [MS 4491]
        and #4                          ; [MS 4492] LEAVES C OFF.
        lsr a                           ; [MS 4493]
        tay                             ; [MS 4494]
        sta SIZE                        ; [MS 4495]
        lda (GRBPNT),y                  ; [MS 4496]
; [MS 4497] NOTE: GRBTOP=LOWTR SO NO NEED TO SET LOWTR.
        adc LOWTR                       ; [MS 4498]
        sta HIGHTR                      ; [MS 4499]
        lda LOWTR+1                     ; [MS 4500]
        adc #0                          ; [MS 4501]
        sta HIGHTR+1                    ; [MS 4502]
        lda FRETOP                      ; [MS 4503 LDWX]
        ldx FRETOP+1                    ; [MS 4503 LDWX]
        sta HIGHDS                      ; [MS 4504 STWX]
        stx HIGHDS+1                    ; [MS 4504 STWX] WHERE IT ALL GOES.
        jsr BLTUC                       ; [MS 4505]
        ldy SIZE                        ; [MS 4506]
        iny                             ; [MS 4507]
        lda HIGHDS                      ; [MS 4508] GET POSITION OF START OF RESULT.
        sta (GRBPNT),y                  ; [MS 4509]
        tax                             ; [MS 4510]
        inc HIGHDS+1                    ; [MS 4511]
        lda HIGHDS+1                    ; [MS 4512]
        iny                             ; [MS 4513]
        sta (GRBPNT),y                  ; [MS 4514] CHANGE ADDR OF STRING IN VAR.
        jmp FNDVAR                      ; [MS 4515] GO TO FNDVAR WITH SOMETHING FOR
; [MS 4516] [FRETOP].
; [MS 4517]
; [MS 4518] THE FOLLOWING ROUTINE CONCATENATES TWO STRINGS.
; [MS 4519] THE FAC CONTAINS THE FIRST ONE AT THIS POINT.
; [MS 4520] [TXTPTR] POINTS TO THE + SIGN.
; [MS 4521]
; [OURS] routines of ours in the room DVARS left, then CAT on Applesoft's address
STRSP:                                  ; [OURS] [RM] STR$ has no space in front of a positive number either (Applesoft II manual, STR$)
        lda LOFBUF                      ; [OURS]
        cmp #' '                        ; [OURS]
        bne STRSP1                      ; [OURS] a "-": keep it
        lda #<FBUFFR                    ; [OURS] the string after the space
        ldy #>FBUFFR                    ; [OURS]
        jmp STRLIT                      ; [OURS]
STRSP1:                                 ; [OURS]
        lda #<LOFBUF                    ; [MS 4247 LDWDI]
        ldy #>LOFBUF                    ; [MS 4247 LDWDI]
        jmp STRLIT                      ; [MS 4248]
        ALIGN $E597                     ; [OURS] [RM] CAT and the string and math routines after it sit on Applesoft's addresses from here
CAT:                                    ; [MS 4522]
        lda FACLO                       ; [MS 4522] PSH HIGH ORDER ONTO STACK.
        pha                             ; [MS 4523]
        lda FACMO                       ; [MS 4524] AND THE LOW.
        pha                             ; [MS 4525]
        jsr EVAL                        ; [MS 4526] CAN COME BACK HERE SINCE
; [MS 4527] OPERATOR IS KNOWN.
        jsr CHKSTR                      ; [MS 4528] RESULT MUST BE STRING.
        pla                             ; [MS 4529]
        sta STRNG1                      ; [MS 4530] GET HIGH ORDER OF OLD DESC.
        pla                             ; [MS 4531]
        sta STRNG1+1                    ; [MS 4532]
        ldy #0                          ; [MS 4533]
        lda (STRNG1),y                  ; [MS 4534] GET LENGTH OF OLD STRING.
        clc                             ; [MS 4535]
        adc (FACMO),y                   ; [MS 4536]
        bcc SIZEOK                      ; [MS 4537] RESULT IS LESS THAN 256.
        ldx #ERRLS                      ; [MS 4538] ERROR "LONG STRING".
        jmp ERROR                       ; [MS 4539]
SIZEOK:                                 ; [MS 4540]
        jsr STRINI                      ; [MS 4540] INITIALIZE STRING.
        jsr MOVINS                      ; [MS 4541] MOVE IT.
        lda DSCPNT                      ; [MS 4542 LDWD]
        ldy DSCPNT+1                    ; [MS 4542 LDWD] GET POINTER TO SECOND.
        jsr FRETMP                      ; [MS 4543] FREE IT.
        jsr MOVDO                       ; [MS 4544]
        lda STRNG1                      ; [MS 4545 LDWD]
        ldy STRNG1+1                    ; [MS 4545 LDWD]
        jsr FRETMP                      ; [MS 4546]
        jsr PUTNEW                      ; [MS 4547]
        jmp TSTOP                       ; [MS 4548] "CAT" REENTERS FORM EVAL AT TSTOP.

MOVINS:                                 ; [MS 4550]
        ldy #0                          ; [MS 4550] GET ADDR OF STRING.
        lda (STRNG1),y                  ; [MS 4551]
        pha                             ; [MS 4552]
        iny                             ; [MS 4553]
        lda (STRNG1),y                  ; [MS 4554]
        tax                             ; [MS 4555]
        iny                             ; [MS 4556]
        lda (STRNG1),y                  ; [MS 4557]
        tay                             ; [MS 4558]
        pla                             ; [MS 4559]
MOVSTR:                                 ; [MS 4560]
        stx INDEX                       ; [MS 4560 STXY]
        sty INDEX+1                     ; [MS 4560 STXY]
MOVDO:                                  ; [MS 4561]
        tay                             ; [MS 4561]
        beq MVDONE                      ; [MS 4562]
        pha                             ; [MS 4563]
MOVLP:                                  ; [MS 4564]
        dey                             ; [MS 4564]
        lda (INDEX),y                   ; [MS 4565]
        sta (FRESPC),y                  ; [MS 4566]
QMOVE:                                  ; [MS 4567]
        tya                             ; [MS 4567]
        bne MOVLP                       ; [MS 4568]
        pla                             ; [MS 4569]
MVDONE:                                 ; [MS 4570]
        clc                             ; [MS 4570]
        adc FRESPC                      ; [MS 4571]
        sta FRESPC                      ; [MS 4572]
        bcc MVSTRT                      ; [MS 4573]
        inc FRESPC+1                    ; [MS 4574]
MVSTRT:                                 ; [MS 4575]
        rts                             ; [MS 4575]
; [MS 4576]
; [MS 4577] "FRETMP" IS PASSED A STRING DESCRIPTOR PNTR IN [Y,A].
; [MS 4578] A CHECK IS MADE TO SEE IF THE STRING DESCRIPTOR POINTS TO THE LAST
; [MS 4579] TEMPORARY DESCRIPTOR ALLOCATED BY PUTNEW.
; [MS 4580] IF SO, THE TEMPORARY IS FREED UP BY THE UPDATING OF [TEMPPT].
; [MS 4581] IF A TEMP IS FREED UP, A FURTHER CHECK SEES IF THE STRING DATA THAT
; [MS 4582] THAT STRING TEMP PNT'D TO IS THE LOWEST PART OF STRING SPACE IN USE.
; [MS 4583] IF SO, [FRETOP] IS UPDATED TO REFLECT THE FACT THE FACT THAT THE SPACE
; [MS 4584] IS NO LONGER IN USE.
; [MS 4585] THE ADDR OF THE ACTUAL STRING IS RETURNED IN [Y,X] AND
; [MS 4586] ITS LENGTH IN ACCA.
; [MS 4587]
FRESTR:                                 ; [MS 4588]
        jsr CHKSTR                      ; [MS 4588] MAKE SURE ITS A STRING.
FREFAC:                                 ; [MS 4589]
        lda FACMO                       ; [MS 4589 LDWD]
        ldy FACMO+1                     ; [MS 4589 LDWD] FREE UP STR PNT'D TO BY FAC.
FRETMP:                                 ; [MS 4590]
        sta INDEX                       ; [MS 4590 STWD]
        sty INDEX+1                     ; [MS 4590 STWD] GET LENGTH FOR LATER.
        jsr FRETMS                      ; [MS 4591] FREE UP THE TEMPORARY DESC.
        php                             ; [MS 4592] SAVE CODES.
        ldy #0                          ; [MS 4593] PREP TO GET STUFF.
        lda (INDEX),y                   ; [MS 4594] GET COUNT AND
        pha                             ; [MS 4595] SAVE IT.
        iny                             ; [MS 4596]
        lda (INDEX),y                   ; [MS 4597]
        tax                             ; [MS 4598] SAVE LOW ORDER.
        iny                             ; [MS 4599]
        lda (INDEX),y                   ; [MS 4600]
        tay                             ; [MS 4601] SAVE HIGH ORDER.
        pla                             ; [MS 4602]
        plp                             ; [MS 4603] RETURN STATUS.
        bne FRETRT                      ; [MS 4604]
        cpy FRETOP+1                    ; [MS 4605] STRING IS LAST ONE IN?
        bne FRETRT                      ; [MS 4606]
        cpx FRETOP                      ; [MS 4607]
        bne FRETRT                      ; [MS 4608]
        pha                             ; [MS 4609]
        clc                             ; [MS 4610]
        adc FRETOP                      ; [MS 4611]
        sta FRETOP                      ; [MS 4612]
        bcc FREPLA                      ; [MS 4613]
        inc FRETOP+1                    ; [MS 4614]
FREPLA:                                 ; [MS 4615]
        pla                             ; [MS 4615] GET COUNT BACK.
FRETRT:                                 ; [MS 4616]
        stx INDEX                       ; [MS 4616 STXY]
        sty INDEX+1                     ; [MS 4616 STXY] SAVE FOR LATER USE.
        rts                             ; [MS 4617]
FRETMS:                                 ; [MS 4618]
        cpy LASTPT+1                    ; [MS 4618] LAST ENTRY TO TEMP?
        bne FRERTS                      ; [MS 4619]
        cmp LASTPT                      ; [MS 4620]
        bne FRERTS                      ; [MS 4621]
        sta TEMPPT                      ; [MS 4622]
        sbc #STRSIZ                     ; [MS 4623] POINT TO LAST ONE.
        sta LASTPT                      ; [MS 4624] UPDATE TEMP PNTR.
        ldy #0                          ; [MS 4625] ALSO CLEARS ZFLG SO WE DO REST OF FRETMP.
FRERTS:                                 ; [MS 4626]
        rts                             ; [MS 4626] ALL DONE.
; [MS 4627]
; [MS 4628] CHR$(#) CREATES A STRING WHICH CONTAINS AS ITS ONLY
; [MS 4629] CHARACTER THE ASCII EQUIVALENT OF THE INTEGER ARGUMENT (#)
; [MS 4630] WHICH MUST BE .LT. 255.
; [MS 4631]
CHR:                                    ; [MS 4632]
        jsr CONINT                      ; [MS 4632] GET INTEGER IN RANGE.
        txa                             ; [MS 4633]
        pha                             ; [MS 4634]
        lda #1                          ; [MS 4635] ONE-CHARACTER STRING.
        jsr STRSPA                      ; [MS 4636] GET SPACE FOR STRING.
        pla                             ; [MS 4637]
        ldy #0                          ; [MS 4638]
        sta (DSCTMP+1),y                ; [MS 4639]
        pla                             ; [MS 4640] GET RID OF "CHKNUM" RETURN ADDR.
        pla                             ; [MS 4641]
RLZRET:                                 ; [MS 4642]
        jmp PUTNEW                      ; [MS 4642] SETUP FAC TO POINT TO DESC.
; [MS 4643]
; [MS 4644] THE FOLLOWING IS THE LEFT$($,#) FUNCTION.
; [MS 4645] IT TAKES THE LEFTMOST # CHARACTERS OF THE STRING.
; [MS 4646] IF # .GT. THE LEN OF THE STRING, IT RETURNS THE WHOLE STRING.
; [MS 4647]
LEFT:                                   ; [MS 4648]
        jsr PREAM                       ; [MS 4648] TEST PARAMETERS.
        cmp (DSCPNT),y                  ; [MS 4649]
        tya                             ; [MS 4650]
RLEFT:                                  ; [MS 4651]
        bcc RLEFT1                      ; [MS 4651]
        lda (DSCPNT),y                  ; [MS 4652]
        tax                             ; [MS 4653] PUT LENGTH INTO X.
        tya                             ; [MS 4654] ZERO A, THE OFFSET.
RLEFT1:                                 ; [MS 4655]
        pha                             ; [MS 4655] SAVE OFFSET.
RLEFT2:                                 ; [MS 4656]
        txa                             ; [MS 4656]
RLEFT3:                                 ; [MS 4657]
        pha                             ; [MS 4657] SAVE LENGTH.
        jsr STRSPA                      ; [MS 4658] GET SPACE.
        lda DSCPNT                      ; [MS 4659 LDWD]
        ldy DSCPNT+1                    ; [MS 4659 LDWD]
        jsr FRETMP                      ; [MS 4660]
        pla                             ; [MS 4661]
        tay                             ; [MS 4662]
        pla                             ; [MS 4663]
        clc                             ; [MS 4664]
        adc INDEX                       ; [MS 4665] COMPUTE WHERE TO COPY.
        sta INDEX                       ; [MS 4666]
        bcc PULMOR                      ; [MS 4667]
        inc INDEX+1                     ; [MS 4668]
PULMOR:                                 ; [MS 4669]
        tya                             ; [MS 4669]
        jsr MOVDO                       ; [MS 4670] GO MOVE IT.
        jmp PUTNEW                      ; [MS 4671]
RIGHT:                                  ; [MS 4672]
        jsr PREAM                       ; [MS 4672]
        clc                             ; [MS 4673] [LENGTH DES'D]-[LENGTH]-1.
        sbc (DSCPNT),y                  ; [MS 4674]
        eor #255                        ; [MS 4675] NEGATE.
        jmp RLEFT                       ; [MS 4676]
; [MS 4677]
; [MS 4678] MID ($,#) RETURNS STRING WITH CHARS FROM # POSITION
; [MS 4679] ONWARD. IF # .GT. LEN ($) THEN RETURN NULL STRING.
; [MS 4680] MID ($,#,#) RETURNS STRING WITH CHARACTERS FROM
; [MS 4681] # POSITION FOR #2 CHARACTERS. IF #2 GOES PAST END OF STRING
; [MS 4682] RETURN AS MUCH AS POSSIBLE.
; [MS 4683]
MID:                                    ; [MS 4684]
        lda #255                        ; [MS 4684] DEFAULT.
        sta FACLO                       ; [MS 4685] SAVE FOR LATER COMPARE.
        jsr CHRGOT                      ; [MS 4686] GET CURRENT CHARACTER.
        cmp #41                         ; [MS 4687] IS IT A RIGHT PAREN )?
        beq MID2                        ; [MS 4688] NO THIRD PARAM.
        jsr CHKCOM                      ; [MS 4689] MUST HAVE COMMA.
        jsr GETBYT                      ; [MS 4690] GET THE LENGTH INTO "FACLO".
MID2:                                   ; [MS 4691]
        jsr PREAM                       ; [MS 4691] CHECK IT OUT.
        beq GOFUC                       ; [MS 4692] THERE IS NO POSTION 0
        dex                             ; [MS 4693] COMPUTE OFFSET.
        txa                             ; [MS 4694]
        pha                             ; [MS 4695] PRSERVE AWHILE.
        clc                             ; [MS 4696]
        ldx #0                          ; [MS 4697]
        sbc (DSCPNT),y                  ; [MS 4698] GET LENGTH OF WHAT'S LEFT.
        bcs RLEFT2                      ; [MS 4699] GIVE NULL STRING.
        eor #255                        ; [MS 4700] IN SUB C WAS 0 SO JUST COMPLEMENT.
        cmp FACLO                       ; [MS 4701] GREATER THAN WHAT'S DESIRED?
        bcc RLEFT3                      ; [MS 4702] NO, COPY THAT MUCH.
        lda FACLO                       ; [MS 4703] GET LENGTH OF WHAT'S DESIRED.
        bcs RLEFT3                      ; [MS 4704] COPY IT.

; [MS 4706]
; [MS 4707] USED BY RIGHT$, LEFT$, MID$ FOR PARAMETER CHECKING AND SETUP.
; [MS 4708]
PREAM:                                  ; [MS 4709]
        jsr CHKCLS                      ; [MS 4709] PARAM LIST SHOULD END.
        pla                             ; [MS 4710] GET THE RETURN ADDRESS INTO
        tay                             ; [MS 4711] [JMPER+1,Y]
        pla                             ; [MS 4712]
        sta JMPER+1                     ; [MS 4713]
        pla                             ; [MS 4714] GET RID OF FINGO'S JSR RET ADDR.
        pla                             ; [MS 4715]
        pla                             ; [MS 4716] GET LENGTH.
        tax                             ; [MS 4717]
        pla                             ; [MS 4718 PULWD]
        sta DSCPNT                      ; [MS 4718 PULWD]
        pla                             ; [MS 4718 PULWD]
        sta DSCPNT+1                    ; [MS 4718 PULWD]
        lda JMPER+1                     ; [MS 4719] PUT RETURN ADDRESS BACK ON
        pha                             ; [MS 4720]
        tya                             ; [MS 4721]
        pha                             ; [MS 4722]
        ldy #0                          ; [MS 4723]
        txa                             ; [MS 4724]
        rts                             ; [MS 4725]
; [MS 4726]
; [MS 4727] THE FUNCTION LEN($) RETURNS THE LENGTH OF THE STRING
; [MS 4728] PASSED AS AN ARGUMENT.
; [MS 4729]
LEN:                                    ; [MS 4730]
        jsr LEN1                        ; [MS 4730]
        jmp SNGFLT                      ; [MS 4731]
LEN1:                                   ; [MS 4732]
        jsr FRESTR                      ; [MS 4732] FREE UP STRING.
        ldx #0                          ; [MS 4733]
        stx VALTYP                      ; [MS 4734] FORCE NUMERIC.
        tay                             ; [MS 4735] SET CODES ON LENGTH.
        rts                             ; [MS 4736] DONE.
; [MS 4737]
; [MS 4738] THE FOLLOWING IS THE ASC($) FUNCTION. IT RETURNS
; [MS 4739] AN INTEGER WHICH IS THE DECIMAL ASCII EQUIVALENT.
; [MS 4740]
ASC:                                    ; [MS 4741]
        jsr LEN1                        ; [MS 4741]
        beq GOFUC                       ; [MS 4742] NULL STRING, BAD ARG.
        ldy #0                          ; [MS 4743]
        lda (INDEX1),y                  ; [MS 4744] GET CHARACTER.
        tay                             ; [MS 4745]
        jmp SNGFLT                      ; [MS 4746]
GOFUC:                                  ; [MS 4747]
        jmp FCERR                       ; [MS 4747] YES.

GTBYTC:                                 ; [MS 4749]
        jsr CHRGET                      ; [MS 4749]
GETBYT:                                 ; [MS 4750]
        jsr FRMNUM                      ; [MS 4750] READ FORMULA INTO FAC.
CONINT:                                 ; [MS 4751]
        jsr POSINT                      ; [MS 4751] CONVERT THE FAC TO A SINGLE BYTE INT.
        ldx FACMO                       ; [MS 4752]
        bne GOFUC                       ; [MS 4753] RESULT MUST BE .LE. 255.
        ldx FACLO                       ; [MS 4754]
CHRGO2:                                 ; [MS 4755]
        jmp CHRGOT                      ; [MS 4755] SET CONDITION CODES ON TERMINATOR.
; [MS 4756]
; [MS 4757] THE "VAL" FUNCTION TAKES A STRING AND TURNS IT INTO
; [MS 4758] A NUMBER BY INTERPRETING THE ASCII DIGITS ETCQ
; [MS 4759] EXCEPT FOR THE PROBLEM THAT A TERMINATOR MUST BE SUPPLIED
; [MS 4760] BY REPLACING THE CHARACTER BEYOND THE STRING, VAL IS MERELY
; [MS 4761] A CALL TO FLOATING POINT INPUT ("FIN").
; [MS 4762]
VAL:                                    ; [MS 4763]
        jsr LEN1                        ; [MS 4763] DO SETUP. SET RESULT=NUMERIC.
        bne *+5                         ; [MS 4764 JEQ]
        jmp ZEROFC                      ; [MS 4764 JEQ] ZERO THE FAC ON A NULL STRING
        ldx TXTPTR                      ; [MS 4765 LDXY]
        ldy TXTPTR+1                    ; [MS 4765 LDXY]
        stx STRNG2                      ; [MS 4766 STXY]
        sty STRNG2+1                    ; [MS 4766 STXY] SAVE FOR LATER.
        ldx INDEX1                      ; [MS 4767]
        stx TXTPTR                      ; [MS 4768]
        clc                             ; [MS 4769]
        adc INDEX1                      ; [MS 4770]
        sta INDEX2                      ; [MS 4771]
        ldx INDEX1+1                    ; [MS 4772]
        stx TXTPTR+1                    ; [MS 4773]
        bcc VAL2                        ; [MS 4774] NO CARRY, NO INC.
        inx                             ; [MS 4775]
VAL2:                                   ; [MS 4776]
        stx INDEX2+1                    ; [MS 4776]
        ldy #0                          ; [MS 4777]
        lda (INDEX2),y                  ; [MS 4778] PRESERVE CHARACTER.
        pha                             ; [MS 4779]
        lda #0                          ; [MS 4780] SET A TERMINATOR.
        sta (INDEX2),y                  ; [MS 4781]
        jsr CHRGOT                      ; [MS 4782] GET CHARACTER PNT'D TO AND SET FLAGS.
        jsr FIN                         ; [MS 4783]
        pla                             ; [MS 4784] GET PRES'D CHARACTER.
        ldy #0                          ; [MS 4785]
        sta (INDEX2),y                  ; [MS 4786] STUFF IT BACK.
ST2TXT:                                 ; [MS 4787]
        ldx STRNG2                      ; [MS 4787 LDXY]
        ldy STRNG2+1                    ; [MS 4787 LDXY]
        stx TXTPTR                      ; [MS 4788 STXY]
        sty TXTPTR+1                    ; [MS 4788 STXY]
VALRTS:                                 ; [MS 4789]
        rts                             ; [MS 4789] ALL DONE WITH STRINGS.
; [MS 4791] ==== PEEK, POKE, AND FNWAIT. ====

GETNUM:                                 ; [MS 4793]
        jsr FRMNUM                      ; [MS 4793] GET ADDRESS.
        jsr GETADR                      ; [MS 4794] GET THAT LOCATION.
COMBYT:                                 ; [MS 4795]
        jsr CHKCOM                      ; [MS 4795] CHECK FOR A COMMA.
        jmp GETBYT                      ; [MS 4796] GET SOMETHING TO STORE AND RETURN.
GETADR:                                 ; [MS 4797]
;       lda FACSGN                      ; [MS 4797] EXAMINE SIGN. [OURS] [RM] Applesoft takes -65535 to 65535 and counts a negative from 65536 (CALL -936 = CALL 64600, Applesoft II manual, CALL): QINT's signed result already has that in its low 16 bits
;       bmi GOFUC                       ; [MS 4798] FUNCTION CALL ERROR. [OURS] [RM] Applesoft takes -65535 to 65535 and counts a negative from 65536 (CALL -936 = CALL 64600, Applesoft II manual, CALL): QINT's signed result already has that in its low 16 bits
        lda FACEXP                      ; [MS 4799] EXAMINE EXPONENT.
        cmp #145                        ; [MS 4800]
        bcs GOFUC                       ; [MS 4801] FUNCTION CALL ERROR.
        jsr QINT                        ; [MS 4802] INTEGERIZE IT.
        lda FACMO                       ; [MS 4803 LDWD]
        ldy FACMO+1                     ; [MS 4803 LDWD]
        sty POKER                       ; [MS 4804]
        sta POKER+1                     ; [MS 4805]
        rts                             ; [MS 4806] IT'S DONE !.

PEEK:                                   ; [MS 4808]
        lda POKER+1                     ; [MS 4808 PSHWD]
        pha                             ; [MS 4808 PSHWD]
        lda POKER                       ; [MS 4808 PSHWD]
        pha                             ; [MS 4808 PSHWD]
        jsr GETADR                      ; [MS 4809]
        ldy #0                          ; [MS 4810]
; [MS 4815] GIVE HIM ZERO FOR AN ANSWER.
GETCON:                                 ; [MS 4816]
        lda (POKER),y                   ; [MS 4816] GET THAT BYTE.
        tay                             ; [MS 4817]
DOSGFL:                                 ; [MS 4818]
        pla                             ; [MS 4818 PULWD]
        sta POKER                       ; [MS 4818 PULWD]
        pla                             ; [MS 4818 PULWD]
        sta POKER+1                     ; [MS 4818 PULWD]
        jmp SNGFLT                      ; [MS 4819] FLOAT IT.

POKE:                                   ; [MS 4821]
        jsr GETNUM                      ; [MS 4821]
        txa                             ; [MS 4822]
        ldy #0                          ; [MS 4823]
        sta (POKER),y                   ; [MS 4824] STORE VALUE AWAY.
        rts                             ; [MS 4825] SCANNED  EVERYTHING.

; [MS 4827] THE WAIT LOCATION,MASK1,MASK2 STATEMENT WAITS UNTIL THE CONTENTS
; [MS 4828] OF LOCATION IS NONZERO WHEN XORED WITH MASK2
; [MS 4829] AND THEN ANDED WITH MASK1. IF MASK2 IS NOT PRESENT, IT
; [MS 4830] IS ASSUMED TO BE ZERO.

FNWAIT:                                 ; [MS 4832]
        jsr GETNUM                      ; [MS 4832]
        stx ANDMSK                      ; [MS 4833]
        ldx #0                          ; [MS 4834]
        jsr CHRGOT                      ; [MS 4835]
        beq ZSTORD                      ; [MS 4836]
        jsr COMBYT                      ; [MS 4837] GET MASK2.
STORDO:                                 ; [MS 4838]
        stx EORMSK                      ; [MS 4838]
        ldy #0                          ; [MS 4839]
WAITER:                                 ; [MS 4840]
        lda (POKER),y                   ; [MS 4840]
        eor EORMSK                      ; [MS 4841]
        and ANDMSK                      ; [MS 4842]
        beq WAITER                      ; [MS 4843]
ZERRTS:                                 ; [MS 4844]
        rts                             ; [MS 4844] GOT A NONZERO.
; [MS 4845] ==== FLOATING POINT MATH PACKAGE CONFIGURATION. ====

; [MS 4847] RADIX 8: numbers below are octal in Microsoft's text; !!!! ALERT !!!!
; [MS 4848] THROUGHOUT THE MATH PACKAGE.
; [MS 4849]
; [MS 4850] THE FLOATING POINT FORMAT IS AS FOLLOWS:
; [MS 4851]
; [MS 4852] THE SIGN IS THE FIRST BIT OF THE MANTISSA.
; [MS 4853] THE MANTISSA IS 24 BITS LONG.
; [MS 4854] THE BINARY POINT IS TO THE LEFT OF THE MSB.
; [MS 4855] NUMBER = MANTISSA * 2 ^ EXPONENT.
; [MS 4856] THE MANTISSA IS POSITIVE WITH A ONE ASSUMED TO BE WHERE THE SIGN BIT IS.
; [MS 4857] THE SIGN OF THE EXPONENT IS THE FIRST BIT OF THE EXPONENT.
; [MS 4858] THE EXPONENT IS STORED IN EXCESS 200, I.E. WITH A BIAS OF +200.
; [MS 4859] SO, THE EXPONENT IS A SIGNED 8-BIT NUMBER WITH 200 ADDED TO IT.
; [MS 4860] AN EXPONENT OF ZERO MEANS THE NUMBER IS ZERO.
; [MS 4861] THE OTHER BYTES MAY NOT BE ASSUMED TO BE ZERO.
; [MS 4862] TO KEEP THE SAME NUMBER IN THE FAC WHILE SHIFTING,
; [MS 4863] TO SHIFT RIGHT, EXP:=EXP+1
; [MS 4864] TO SHIFT LEFT,	EXP:=EXP-1
; [MS 4865]
; [MS 4866] IN MEMORY THE NUMBER LOOKS LIKE THIS:
; [MS 4867] [THE EXPONENT AS A SIGNED NUMBER +200]
; [MS 4868] [THE SIGN BIT IN 7, BITS 2-8 OF MANTISSA ARE IN BITS 6-0].
; [MS 4869] (REMEMBER BIT 1 OF MANTISSA IS ALWAYS A ONE.)
; [MS 4870] [BITS 9-16 OF THE MANTISSA]
; [MS 4871] [BITS 17-24] OF THE MANTISSA]
; [MS 4872]
; [MS 4873] ARITHMETIC ROUTINE CALLING CONVENTIONS:
; [MS 4874]
; [MS 4875] FOR ONE ARGUMENT FUNCTIONS:
; [MS 4876] THE ARGUMENT IS IN THE FAC.
; [MS 4877] THE RESULT IS LEFT IN THE FAC.
; [MS 4878] FOR TWO ARGUMENT OPERATIONS:
; [MS 4879] THE FIRST ARGUMENT IS IN ARG (ARGEXP,HO,MO,LO AND ARGSGN).
; [MS 4880] THE SECOND ARGUMENT IS IN THE FAC.
; [MS 4881] THE RESULT IS LEFT IN THE FAC.
; [MS 4882]
; [MS 4883] THE "T" ENTRY POINTS TO THE TWO-ARGUMENT OPERATIONS HAVE BOTH ARGUMENTS
; [MS 4884] SETUP IN THE RESPECTIVE REGISTERS. BEFORE CALLING ARG MAY HAVE BEEN
; [MS 4885] POPPED OFF THE STACK AND INTO ARG, FOR EXAMPLE.
; [MS 4886] THE OTHER ENTRY POINT ASSUMES [Y,A] POINTS TO THE ARGUMENT
; [MS 4887] SOMEWHERE IN MEMORY. IT IS UNPACKED INTO ARG BY "CONUPK".
; [MS 4888]
; [MS 4889] ON THE STACK, THE SGN IS PUSHED ON FIRST, THE LO,MO,HO AND FINALLY EXP.
; [MS 4890] NOTE ALL THINGS ARE KEPT UNPACKED IN ARG, FAC AND ON THE STACK.
; [MS 4891]
; [MS 4892] IT IS ONLY WHEN SOMETHING IS STORED AWAY THAT IT IS PACKED TO FOUR
; [MS 4893] BYTES. THE UNPACKED FORMAT HAS A SGN BYTE REFLECTING THE SIGN OF THE
; [MS 4894] NUMBER (POSITIVE=0, NEGATIVE=-1) A HO,MO AND LO WITH THE HIGH BIT
; [MS 4895] OF THE HO TURNED ON. THE EXP IS THE SAME AS STORED FORMAT.
; [MS 4896] THIS IS DONE FOR SPEED OF OPERATION.
; [MS 4897]
; [MS 4899] ==== FLOATING POINT ADDITION AND SUBTRACTION. ====
FADDH:                                  ; [MS 4900]
        lda #<FHALF                     ; [MS 4900 LDWDI]
        ldy #>FHALF                     ; [MS 4900 LDWDI] ENTRY TO ADD 1/2.
        jmp FADD                        ; [MS 4901] UNPACK AND GO ADD IT.
FSUB:                                   ; [MS 4902]
        jsr CONUPK                      ; [MS 4902] UNPACK ARGUMENT INTO ARG.
FSUBT:                                  ; [MS 4903]
        lda FACSGN                      ; [MS 4903]
        eor #$FF                        ; [MS 4904] COMPLEMENT IT.
        sta FACSGN                      ; [MS 4905]
        eor ARGSGN                      ; [MS 4906] COMPLEMENT ARISGN.
        sta ARISGN                      ; [MS 4907]
        lda FACEXP                      ; [MS 4908] SET CODES ON FACEXP.
        jmp FADDT                       ; [MS 4909] [Y]=ARGEXP..
ZSTORD = STORDO                         ; [MS 4912]

FADD5:                                  ; [MS 4942]
        jsr SHIFTR                      ; [MS 4942] DO A LONG SHIFT.
        bcc FADD4                       ; [MS 4943] CONTINUE WITH ADDITION.
FADD:                                   ; [MS 4944]
        jsr CONUPK                      ; [MS 4944]
FADDT:                                  ; [MS 4945]
        bne *+5                         ; [MS 4945 JEQ]
        jmp MOVFA                       ; [MS 4945 JEQ] IF FAC=0, RESULT IS IN ARG.
        ldx FACOV                       ; [MS 4946]
        stx OLDOV                       ; [MS 4947]
        ldx #ARGEXP                     ; [MS 4948] DEFAULT IS SHIFT ARGUMENT.
        lda ARGEXP                      ; [MS 4949] IF ARG=0, FAC IS RESULT.
FADDC:                                  ; [MS 4950]
        tay                             ; [MS 4950] ALSO COPY ACCA INTO ACCY.
        beq ZERRTS                      ; [MS 4951] RETURN.
        sec                             ; [MS 4952]
        sbc FACEXP                      ; [MS 4953]
        beq FADD4                       ; [MS 4954] NO SHIFTING.
        bcc FADDA                       ; [MS 4955] BR IF ARGEXP.LT.FACEXP.
        sty FACEXP                      ; [MS 4956] RESULTING EXPONENT.
        ldy ARGSGN                      ; [MS 4957] SINCE ARG IS BIGGER, IT'S
        sty FACSGN                      ; [MS 4958] SIGN IS SIGN OF RESULT.
        eor #$FF                        ; [MS 4959] SHIFT A NEGATIVE NUMBER OF PLACES.
        adc #0                          ; [MS 4960] COMPLETE NEGATION. W/ C=1.
        ldy #0                          ; [MS 4961] ZERO OLDOV.
        sty OLDOV                       ; [MS 4962]
        ldx #FAC                        ; [MS 4963] SHIFT THE FAC INSTEAD.
        bne FADD1                       ; [MS 4964]
FADDA:                                  ; [MS 4965]
        ldy #0                          ; [MS 4965]
        sty FACOV                       ; [MS 4966]
FADD1:                                  ; [MS 4967]
        cmp #256-7                      ; [MS 4967] FOR SPEED AND NECESSITY.  GETS
; [MS 4968] MOST LIKELY CASE TO SHIFTR FASTEST
; [MS 4969] AND ALLOWS SHIFTING OF NEG NUMS
; [MS 4970] BY "QINT".
        bmi FADD5                       ; [MS 4971] SHIFT BIG.
        tay                             ; [MS 4972]
        lda FACOV                       ; [MS 4973] SET FACOV.
        lsr 1,x                         ; [MS 4974] GETS 0 IN MOST SIG BIT.
        jsr ROLSHF                      ; [MS 4975] DO THE ROLLING.
FADD4:                                  ; [MS 4976]
        bit ARISGN                      ; [MS 4976] GET RESULTING SIGN.
        bpl FADD2                       ; [MS 4977] IF POSITIVE, ADD.
; [MS 4978] CARRY IS CLEAR.
FADD3:                                  ; [MS 4979]
        ldy #FACEXP                     ; [MS 4979]
        cpx #ARGEXP                     ; [MS 4980] FAC IS BIGGER.
        beq SUBIT                       ; [MS 4981]
        ldy #ARGEXP                     ; [MS 4982] ARG IS BIGGER.
SUBIT:                                  ; [MS 4983]
        sec                             ; [MS 4983]
        eor #$FF                        ; [MS 4984]
        adc OLDOV                       ; [MS 4985]
        sta FACOV                       ; [MS 4986]
        lda 3+ADDPRC,y                  ; [MS 4987]
        sbc 3+ADDPRC,x                  ; [MS 4988]
        sta FACLO                       ; [MS 4989]
        lda 2+ADDPRC,y                  ; [MS 4990]
        sbc 2+ADDPRC,x                  ; [MS 4991]
        sta FACMO                       ; [MS 4992]

        lda 2,y                         ; [MS 4994]
        sbc 2,x                         ; [MS 4995]
        sta FACMOH                      ; [MS 4996]
        lda 1,y                         ; [MS 4997]
        sbc 1,x                         ; [MS 4998]
        sta FACHO                       ; [MS 4999]
FADFLT:                                 ; [MS 5000]
        bcs NORMAL                      ; [MS 5000] HERE IF SIGNS DIFFER. IF CARRY,
; [MS 5001] FAC IS SET OK.
        jsr NEGFAC                      ; [MS 5002] NEGATE [FAC].
NORMAL:                                 ; [MS 5003]
        ldy #0                          ; [MS 5003]
        tya                             ; [MS 5004]
        clc                             ; [MS 5005]
NORM3:                                  ; [MS 5006]
        ldx FACHO                       ; [MS 5006]
        bne NORM1                       ; [MS 5007]
        ldx FACHO+1                     ; [MS 5008] SHIFT 8 BITS AT A TIME FOR SPEED.
        stx FACHO                       ; [MS 5009]

        ldx FACMOH+1                    ; [MS 5011]
        stx FACMOH                      ; [MS 5012]
        ldx FACMO+1                     ; [MS 5013]
        stx FACMO                       ; [MS 5014]
        ldx FACOV                       ; [MS 5015]
        stx FACLO                       ; [MS 5016]
        sty FACOV                       ; [MS 5017]
        adc #8                          ; [MS 5018]
        cmp #8*ADDPRC+$18               ; [MS 5019]
        bne NORM3                       ; [MS 5020]
ZEROFC:                                 ; [MS 5021]
        lda #0                          ; [MS 5021] NOT NEED BY NORMAL BUT BY OTHERS.
ZEROF1:                                 ; [MS 5022]
        sta FACEXP                      ; [MS 5022] NUMBER MUST BE ZERO.
ZEROML:                                 ; [MS 5023]
        sta FACSGN                      ; [MS 5023] MAKE SIGN POSITIVE.
        rts                             ; [MS 5024] ALL DONE.
FADD2:                                  ; [MS 5025]
        adc OLDOV                       ; [MS 5025]
        sta FACOV                       ; [MS 5026]
        lda FACLO                       ; [MS 5027]
        adc ARGLO                       ; [MS 5028]
        sta FACLO                       ; [MS 5029]
        lda FACMO                       ; [MS 5030]
        adc ARGMO                       ; [MS 5031]
        sta FACMO                       ; [MS 5032]

        lda FACMOH                      ; [MS 5034]
        adc ARGMOH                      ; [MS 5035]
        sta FACMOH                      ; [MS 5036]
        lda FACHO                       ; [MS 5037]
        adc ARGHO                       ; [MS 5038]
        sta FACHO                       ; [MS 5039]
        jmp SQUEEZ                      ; [MS 5040] GO ROUND IF SIGNS SAME.

NORM2:                                  ; [MS 5042]
        adc #1                          ; [MS 5042] DECREMENT SHIFT COUNT.
        asl FACOV                       ; [MS 5043] SHIFT ALL LEFT ONE BIT.
        rol FACLO                       ; [MS 5044]
        rol FACMO                       ; [MS 5045]

        rol FACMOH                      ; [MS 5047]
        rol FACHO                       ; [MS 5048]
NORM1:                                  ; [MS 5049]
        bpl NORM2                       ; [MS 5049] IF MSB=0 SHIFT AGAIN.
        sec                             ; [MS 5050]
        sbc FACEXP                      ; [MS 5051]
        bcs ZEROFC                      ; [MS 5052]
        eor #$FF                        ; [MS 5053]
        adc #1                          ; [MS 5054] COMPLEMENT.
        sta FACEXP                      ; [MS 5055]
SQUEEZ:                                 ; [MS 5056]
        bcc RNDRTS                      ; [MS 5056] BITS TO SHIFT?
RNDSHF:                                 ; [MS 5057]
        inc FACEXP                      ; [MS 5057]
        beq OVERR                       ; [MS 5058]
        ror FACHO                       ; [MS 5059]

        ror FACMOH                      ; [MS 5061]
        ror FACMO                       ; [MS 5062]
        ror FACLO                       ; [MS 5063]
        ror FACOV                       ; [MS 5064]
RNDRTS:                                 ; [MS 5065]
        rts                             ; [MS 5065] ALL DONE ADDING.

NEGFAC:                                 ; [MS 5067]
        lda FACSGN                      ; [MS 5067 COM]
        eor #$FF                        ; [MS 5067 COM]
        sta FACSGN                      ; [MS 5067 COM] COMPLEMENT FAC	 ENTIRELY.
NEGFCH:                                 ; [MS 5068]
        lda FACHO                       ; [MS 5068 COM]
        eor #$FF                        ; [MS 5068 COM]
        sta FACHO                       ; [MS 5068 COM] COMPLEMENT JUST THE NUMBER.

        lda FACMOH                      ; [MS 5070 COM]
        eor #$FF                        ; [MS 5070 COM]
        sta FACMOH                      ; [MS 5070 COM]
        lda FACMO                       ; [MS 5071 COM]
        eor #$FF                        ; [MS 5071 COM]
        sta FACMO                       ; [MS 5071 COM]
        lda FACLO                       ; [MS 5072 COM]
        eor #$FF                        ; [MS 5072 COM]
        sta FACLO                       ; [MS 5072 COM]
        lda FACOV                       ; [MS 5073 COM]
        eor #$FF                        ; [MS 5073 COM]
        sta FACOV                       ; [MS 5073 COM]
        inc FACOV                       ; [MS 5074]
        bne INCFRT                      ; [MS 5075]
INCFAC:                                 ; [MS 5076]
        inc FACLO                       ; [MS 5076]
        bne INCFRT                      ; [MS 5077]
        inc FACMO                       ; [MS 5078]
        bne INCFRT                      ; [MS 5079] IF NO CARRY, RETURN.

        inc FACMOH                      ; [MS 5081]
        bne INCFRT                      ; [MS 5082]
        inc FACHO                       ; [MS 5083] CARRY INCREMENT.
INCFRT:                                 ; [MS 5084]
        rts                             ; [MS 5084]

OVERR:                                  ; [MS 5086]
        ldx #ERROV                      ; [MS 5086]
        jmp ERROR                       ; [MS 5087] TELL USER.
; [MS 5088]
; [MS 5089] "SHIFTR" SHIFTS [X+1:X+3] [-ACCA]  BITS RIGHT.
; [MS 5090] SHIFTS BYTES TO START WITH IF POSSIBLE.
; [MS 5091]
MULSHF:                                 ; [MS 5092]
        ldx #<(RESHO-1)                 ; [MS 5092] ENTRY POINT FOR MULTIPLIER.
SHFTR2:                                 ; [MS 5093]
        ldy 3+ADDPRC,x                  ; [MS 5093] SHIFT BYTES FIRST.
        sty FACOV                       ; [MS 5094]

        ldy 3,x                         ; [MS 5096]
        sty 4,x                         ; [MS 5097]
        ldy 2,x                         ; [MS 5098] GET MO.
        sty 3,x                         ; [MS 5099] STORE LO.
        ldy 1,x                         ; [MS 5100] GET HO.
        sty 2,x                         ; [MS 5101] STORE MO.
        ldy BITS                        ; [MS 5102]
        sty 1,x                         ; [MS 5103] STORE HO.
SHIFTR:                                 ; [MS 5104]
        adc #8                          ; [MS 5104]
        bmi SHFTR2                      ; [MS 5105]
        beq SHFTR2                      ; [MS 5106]
        sbc #8                          ; [MS 5107] C CAN BE EITHER 1,0 AND IT WORKS.
        tay                             ; [MS 5108]
        lda FACOV                       ; [MS 5109]
        bcs SHFTRT                      ; [MS 5110] EQUIV TO BEQ HERE.

SHFTR3:                                 ; [MS 5112]
        asl 1,x                         ; [MS 5112]
        bcc SHFTR4                      ; [MS 5113]
        inc 1,x                         ; [MS 5114]
SHFTR4:                                 ; [MS 5115]
        ror 1,x                         ; [MS 5115]
        ror 1,x                         ; [MS 5116] YES, TWO OF THEM.

ROLSHF:                                 ; [MS 5125]

        ror 2,x                         ; [MS 5127]
        ror 3,x                         ; [MS 5128]
        ror 4,x                         ; [MS 5129] ONE MO TIME.


        ror a                           ; [MS 5152] ROTATE ARGUMENT 1 BIT RIGHT.

SHFTR7:                                 ; [MS 5160]
        iny                             ; [MS 5160]
        bne SHFTR3                      ; [MS 5161] $$$ ( MOST EXPENSIVE ! )
SHFTRT:                                 ; [MS 5162]
        clc                             ; [MS 5162] CLEAR OUTPUT OF FACOV.
        rts                             ; [MS 5163]
; [MS 5165] ==== NATURAL LOG FUNCTION. ====
; [MS 5166]
; [MS 5167] CALCULATION IS BY:
; [MS 5168] LN(F*2^N)=(N+LOG2(F))*LN(2)
; [MS 5169] AN APPROXIMATION POLYNOMIAL IS USED TO CALCULATE LOG2(F).
; [MS 5170] CONSTANTS USED BY LOG:
FONE:                                   ; [MS 5171]
        .byte $81                       ; [MS 5171] 1.0
        .byte 0                         ; [MS 5172]
        .byte 0                         ; [MS 5173]
        .byte 0                         ; [MS 5174]
        .byte 0                         ; [MS 5175]



LOGCN2:                                 ; [MS 5192]
        .byte 3                         ; [MS 5192] DEGREE-1
        .byte $7F                       ; [MS 5193] .43425594188
        .byte $5E                       ; [MS 5194]
        .byte $56                       ; [MS 5195]
        .byte $CB                       ; [MS 5196]
        .byte $79                       ; [MS 5197]
        .byte $80                       ; [MS 5198] .57658454134
        .byte $13                       ; [MS 5199]
        .byte $9B                       ; [MS 5200]
        .byte $0B                       ; [MS 5201]
        .byte $64                       ; [MS 5202]
        .byte $80                       ; [MS 5203] .96180075921
        .byte $76                       ; [MS 5204]
        .byte $38                       ; [MS 5205]
        .byte $93                       ; [MS 5206]
        .byte $16                       ; [MS 5207]
        .byte $82                       ; [MS 5208] 2.8853900728
        .byte $38                       ; [MS 5209]
        .byte $AA                       ; [MS 5210]
        .byte $3B                       ; [MS 5211]
        .byte $20                       ; [MS 5212]
SQRHLF:                                 ; [MS 5213]
        .byte $80                       ; [MS 5213] SQR(0.5)
        .byte $35                       ; [MS 5214]
        .byte 4                         ; [MS 5215]
        .byte $F3                       ; [MS 5216]
        .byte $34                       ; [MS 5217]
SQRTWO:                                 ; [MS 5218]
        .byte $81                       ; [MS 5218] SQR(2.0)
        .byte $35                       ; [MS 5219]
        .byte 4                         ; [MS 5220]
        .byte $F3                       ; [MS 5221]
        .byte $34                       ; [MS 5222]
NEGHLF:                                 ; [MS 5223]
        .byte $80                       ; [MS 5223] -1/2
        .byte $80                       ; [MS 5224]
        .byte 0                         ; [MS 5225]
        .byte 0                         ; [MS 5226]
        .byte 0                         ; [MS 5227]
LOG2:                                   ; [MS 5228]
        .byte $80                       ; [MS 5228] LN(2)
        .byte $31                       ; [MS 5229]
        .byte $72                       ; [MS 5230]

        .byte $17                       ; [MS 5232]
        .byte $F8                       ; [MS 5233]

LOG:                                    ; [MS 5235]
        jsr SIGN                        ; [MS 5235] IS IT POSITIVE?
        beq LOGERR                      ; [MS 5236]
        bpl LOG1                        ; [MS 5237]
LOGERR:                                 ; [MS 5238]
        jmp FCERR                       ; [MS 5238] CAN'T TOLERATE NEG OR ZERO.
LOG1:                                   ; [MS 5239]
        lda FACEXP                      ; [MS 5239] GET EXPONENT INTO ACCA.
        sbc #$7F                        ; [MS 5240] REMOVE BIAS. (CARRY IS OFF)
        pha                             ; [MS 5241] SAVE AWHILE.
        lda #$80                        ; [MS 5242]
        sta FACEXP                      ; [MS 5243] RESULT IS FAC IN RANGE [0.5,1].
        lda #<SQRHLF                    ; [MS 5244 LDWDI]
        ldy #>SQRHLF                    ; [MS 5244 LDWDI] GET POINTER TO SQR(0.5).

; [MS 5246] CALCULATE (F-SQR(.5))/(F+SQR(.5))

        jsr FADD                        ; [MS 5248] ADD TO FAC.
        lda #<SQRTWO                    ; [MS 5249 LDWDI]
        ldy #>SQRTWO                    ; [MS 5249 LDWDI] GET SQR(2.).
        jsr FDIV                        ; [MS 5250]
        lda #<FONE                      ; [MS 5251 LDWDI]
        ldy #>FONE                      ; [MS 5251 LDWDI]
        jsr FSUB                        ; [MS 5252]
        lda #<LOGCN2                    ; [MS 5253 LDWDI]
        ldy #>LOGCN2                    ; [MS 5253 LDWDI]
        jsr POLYX                       ; [MS 5254] EVALUATE APPROXIMATION POLYNOMIAL.
        lda #<NEGHLF                    ; [MS 5255 LDWDI]
        ldy #>NEGHLF                    ; [MS 5255 LDWDI] ADD IN LAST CONSTANT.
        jsr FADD                        ; [MS 5256]
        pla                             ; [MS 5257] GET EXPONENT BACK.
        jsr FINLOG                      ; [MS 5258] ADD IT IN.
MULLN2:                                 ; [MS 5259]
        lda #<LOG2                      ; [MS 5259 LDWDI]
        ldy #>LOG2                      ; [MS 5259 LDWDI] MULTIPLY RESULT BY LOG(2.0).
; [MS 5260] JMP	FMULT		;MULTIPLY TOGETHER.
; [MS 5262] ==== FLOATING MULTIPLICATION AND DIVISION. ====
; [MS 5263] MULTIPLICATION		FAC:=ARG*FAC.
FMULT:                                  ; [MS 5264]
        jsr CONUPK                      ; [MS 5264] UNPACK THE CONSTANT INTO ARG FOR USE.
FMULTT:                                 ; [MS 5265]
        bne *+5                         ; [MS 5265 JEQ]
        jmp MULTRT                      ; [MS 5265 JEQ] IF FAC=0, RETURN. FAC IS SET.
        jsr MULDIV                      ; [MS 5266] FIX UP THE EXPONENTS.
        lda #0                          ; [MS 5267] TO CLEAR RESULT.
        sta RESHO                       ; [MS 5268]

        sta RESMOH                      ; [MS 5270]
        sta RESMO                       ; [MS 5271]
        sta RESLO                       ; [MS 5272]
        lda FACOV                       ; [MS 5273]
        jsr MLTPLY                      ; [MS 5274]
        lda FACLO                       ; [MS 5275] MLTPLY ARG BY FACLO.
        jsr MLTPLY                      ; [MS 5276]
        lda FACMO                       ; [MS 5277] MLTPLY ARG BY FACMO.
        jsr MLTPLY                      ; [MS 5278]

        lda FACMOH                      ; [MS 5280]
        jsr MLTPLY                      ; [MS 5281]
        lda FACHO                       ; [MS 5282] MLTPLY ARG BY FACHO.
        jsr MLTPL1                      ; [MS 5283]
        jmp MOVFR                       ; [MS 5284] MOVE RESULT INTO FAC,
; [MS 5285] NORMALIZE RESULT, AND RETURN.
MLTPLY:                                 ; [MS 5286]
        bne *+5                         ; [MS 5286 JEQ]
        jmp MULSHF                      ; [MS 5286 JEQ] SHIFT RESULT RIGHT 1 BYTE.
MLTPL1:                                 ; [MS 5287]
        lsr a                           ; [MS 5287]
        ora #$80                        ; [MS 5288]
MLTPL2:                                 ; [MS 5289]
        tay                             ; [MS 5289]
        bcc MLTPL3                      ; [MS 5290] IT MULT BIT=0, JUST SHIFT.
        clc                             ; [MS 5291]
        lda RESLO                       ; [MS 5292]
        adc ARGLO                       ; [MS 5293]
        sta RESLO                       ; [MS 5294]
        lda RESMO                       ; [MS 5295]
        adc ARGMO                       ; [MS 5296]
        sta RESMO                       ; [MS 5297]

        lda RESMOH                      ; [MS 5299]
        adc ARGMOH                      ; [MS 5300]
        sta RESMOH                      ; [MS 5301]
        lda RESHO                       ; [MS 5302]
        adc ARGHO                       ; [MS 5303]
        sta RESHO                       ; [MS 5304]
MLTPL3:                                 ; [MS 5305]
        ror RESHO                       ; [MS 5305]

        ror RESMOH                      ; [MS 5307]
        ror RESMO                       ; [MS 5308]
        ror RESLO                       ; [MS 5309]
        ror FACOV                       ; [MS 5310] SAVE FOR ROUNDING.
        tya                             ; [MS 5311]
        lsr a                           ; [MS 5312] CLEAR MSB SO WE GET A CLOSER TO 0.
        bne MLTPL2                      ; [MS 5313] SLOW AS A TURTLE !
MULTRT:                                 ; [MS 5314]
        rts                             ; [MS 5314]

; [MS 5316] ROUTINE TO UNPACK MEMORY INTO ARG.
CONUPK:                                 ; [MS 5317]
        sta INDEX1                      ; [MS 5317 STWD]
        sty INDEX1+1                    ; [MS 5317 STWD]
        ldy #3+ADDPRC                   ; [MS 5318]
        lda (INDEX1),y                  ; [MS 5319]
        sta ARGLO                       ; [MS 5320]
        dey                             ; [MS 5321]
        lda (INDEX1),y                  ; [MS 5322]
        sta ARGMO                       ; [MS 5323]
        dey                             ; [MS 5324]

        lda (INDEX1),y                  ; [MS 5326]
        sta ARGMOH                      ; [MS 5327]
        dey                             ; [MS 5328]
        lda (INDEX1),y                  ; [MS 5329]
        sta ARGSGN                      ; [MS 5330]
        eor FACSGN                      ; [MS 5331]
        sta ARISGN                      ; [MS 5332]
        lda ARGSGN                      ; [MS 5333]
        ora #$80                        ; [MS 5334]
        sta ARGHO                       ; [MS 5335]
        dey                             ; [MS 5336]
        lda (INDEX1),y                  ; [MS 5337]
        sta ARGEXP                      ; [MS 5338]
        lda FACEXP                      ; [MS 5339] SET CODES OF FACEXP.
        rts                             ; [MS 5340]

; [MS 5342] CHECK SPECIAL CASES AND ADD EXPONENTS FOR FMULT, FDIV.
MULDIV:                                 ; [MS 5343]
        lda ARGEXP                      ; [MS 5343] EXP OF ARG=0?
MLDEXP:                                 ; [MS 5344]
        beq ZEREMV                      ; [MS 5344] SO WE GET ZERO EXPONENT.
        clc                             ; [MS 5345]
        adc FACEXP                      ; [MS 5346] RESULT IS IN ACCA.
        bcc TRYOFF                      ; [MS 5347] FIND [C] XOR [N].
        bmi GOOVER                      ; [MS 5348] OVERFLOW IF BITS MATCH.
        clc                             ; [MS 5349]
        .byte $2C                       ; [MS 5350 SKIP2]
TRYOFF:                                 ; [MS 5351]
        bpl ZEREMV                      ; [MS 5351] UNDERFLOW.
        adc #$80                        ; [MS 5352] ADD BIAS.
        sta FACEXP                      ; [MS 5353]
        bne *+5                         ; [MS 5354 JEQ]
        jmp ZEROML                      ; [MS 5354 JEQ] ZERO THE REST OF IT.
        lda ARISGN                      ; [MS 5355]
        sta FACSGN                      ; [MS 5356] ARISGN IS RESULT'S SIGN.
        rts                             ; [MS 5357] DONE.
MLDVEX:                                 ; [MS 5358]
        lda FACSGN                      ; [MS 5358] GET SIGN.
        eor #$FF                        ; [MS 5359] COMPLEMENT IT.
        bmi GOOVER                      ; [MS 5360]
ZEREMV:                                 ; [MS 5361]
        pla                             ; [MS 5361] GET ADDR OFF STACK.
        pla                             ; [MS 5362]
        jmp ZEROFC                      ; [MS 5363] UNDERFLOW.
GOOVER:                                 ; [MS 5364]
        jmp OVERR                       ; [MS 5364] OVERFLOW.

; [MS 5366] MULTIPLY FAC BY 10.
MUL10:                                  ; [MS 5367]
        jsr MOVAF                       ; [MS 5367] COPY FAC INTO ARG.
        tax                             ; [MS 5368]
        beq MUL10R                      ; [MS 5369] IF [FAC]=0, GOT ANSWER.
        clc                             ; [MS 5370]
        adc #2                          ; [MS 5371] AUGMENT EXP BY 2.
        bcs GOOVER                      ; [MS 5372] OVERFLOW.
FINML6:                                 ; [MS 5373]
        ldx #0                          ; [MS 5373]
        stx ARISGN                      ; [MS 5374] SIGNS ARE SAME.
        jsr FADDC                       ; [MS 5375] ADD TOGETHER.
        inc FACEXP                      ; [MS 5376] MULTIPLY BY TWO.
        beq GOOVER                      ; [MS 5377] OVERFLOW.
MUL10R:                                 ; [MS 5378]
        rts                             ; [MS 5378]

; [MS 5380] DIVIDE FAC BY 10.
TENZC:                                  ; [MS 5381]
        .byte $84                       ; [MS 5381]
        .byte $20                       ; [MS 5382]
        .byte 0                         ; [MS 5383]
        .byte 0                         ; [MS 5384]
        .byte 0                         ; [MS 5385]
DIV10:                                  ; [MS 5386]
        jsr MOVAF                       ; [MS 5386] MOVE FAC TO ARG.
        lda #<TENZC                     ; [MS 5387 LDWDI]
        ldy #>TENZC                     ; [MS 5387 LDWDI] POINT TO CONSTANT OF 10.0
        ldx #0                          ; [MS 5388] SIGNS ARE BOTH POSITIVE.
FDIVF:                                  ; [MS 5389]
        stx ARISGN                      ; [MS 5389]
        jsr MOVFM                       ; [MS 5390] PUT IT INTO FAC.
        jmp FDIVT                       ; [MS 5391] SKIP OVER NEXT TWO BYTES.
FDIV:                                   ; [MS 5392]
        jsr CONUPK                      ; [MS 5392] UNPACK CONSTANT.
FDIVT:                                  ; [MS 5393]
        beq DV0ERR                      ; [MS 5393] CAN'T DIVIDE BY ZERO !
; [MS 5394] (NOT ENOUGH ROOM TO STORE RESULT.)
        jsr ROUND                       ; [MS 5395] TAKE FACOV INTO ACCT IN FAC.
        lda #0                          ; [MS 5396] NEGATE FACEXP.
        sec                             ; [MS 5397]
        sbc FACEXP                      ; [MS 5398]
        sta FACEXP                      ; [MS 5399]
        jsr MULDIV                      ; [MS 5400] FIX UP EXPONENTS.
        inc FACEXP                      ; [MS 5401] SCALE IT RIGHT.
        beq GOOVER                      ; [MS 5402] OVERFLOW.
        ldx #256-3-ADDPRC               ; [MS 5403] SETUP PROCEDURE.
        lda #1                          ; [MS 5404]
DIVIDE:                                 ; [MS 5405] THIS IS THE BEST CODE IN THE WHOLE PILE.
        ldy ARGHO                       ; [MS 5406] SEE WHAT RELATION HOLDS.
        cpy FACHO                       ; [MS 5407]
        bne SAVQUO                      ; [MS 5408] [C]=0,1. N(C=0)=0.

        ldy ARGMOH                      ; [MS 5410]
        cpy FACMOH                      ; [MS 5411]
        bne SAVQUO                      ; [MS 5412]
        ldy ARGMO                       ; [MS 5413]
        cpy FACMO                       ; [MS 5414]
        bne SAVQUO                      ; [MS 5415]
        ldy ARGLO                       ; [MS 5416]
        cpy FACLO                       ; [MS 5417]
SAVQUO:                                 ; [MS 5418]
        php                             ; [MS 5418]
        rol a                           ; [MS 5419] SAVE RESULT.
        bcc QSHFT                       ; [MS 5420] IF NOT DONE, CONTINUE.
        inx                             ; [MS 5421]
        sta RESLO,x                     ; [MS 5422]
        beq LD100                       ; [MS 5423]
        bpl DIVNRM                      ; [MS 5424] NOTE THIS REQ 1 MO RAM THEN NECESS.
        lda #1                          ; [MS 5425]
QSHFT:                                  ; [MS 5426]
        plp                             ; [MS 5426] RETURN CONDITION CODES.
        bcs DIVSUB                      ; [MS 5427] FAC .LE. ARG.
SHFARG:                                 ; [MS 5428]
        asl ARGLO                       ; [MS 5428] SHIFT ARG ONE PLACE LEFT.
        rol ARGMO                       ; [MS 5429]

        rol ARGMOH                      ; [MS 5431]
        rol ARGHO                       ; [MS 5432]
        bcs SAVQUO                      ; [MS 5433] SAVE A RESULT OF ONE FOR THIS POSITION
; [MS 5434] AND DIVIDE.
        bmi DIVIDE                      ; [MS 5435] IF MSB ON, GO DECIDE WHETHER TO SUB.
        bpl SAVQUO                      ; [MS 5436]
DIVSUB:                                 ; [MS 5437]
        tay                             ; [MS 5437] NOTICE C MUST BE ON HERE.
        lda ARGLO                       ; [MS 5438]
        sbc FACLO                       ; [MS 5439]
        sta ARGLO                       ; [MS 5440]
        lda ARGMO                       ; [MS 5441]
        sbc FACMO                       ; [MS 5442]
        sta ARGMO                       ; [MS 5443]

        lda ARGMOH                      ; [MS 5445]
        sbc FACMOH                      ; [MS 5446]
        sta ARGMOH                      ; [MS 5447]
        lda ARGHO                       ; [MS 5448]
        sbc FACHO                       ; [MS 5449]
        sta ARGHO                       ; [MS 5450]
        tya                             ; [MS 5451]
        jmp SHFARG                      ; [MS 5452]
LD100:                                  ; [MS 5453]
        lda #$40                        ; [MS 5453] ONLY WANT TWO MORE BITS.
        bne QSHFT                       ; [MS 5454] ALWAYS BRANCHES.
DIVNRM:                                 ; [MS 5455]
        asl a                           ; [MS 5455]
        asl a                           ; [MS 5455]
        asl a                           ; [MS 5455]
        asl a                           ; [MS 5455]
        asl a                           ; [MS 5455]
        asl a                           ; [MS 5455] GET LAST TWO BITS INTO MSB AND B6.
        sta FACOV                       ; [MS 5456]
        plp                             ; [MS 5457] TO GET GARBAGE OFF STACK.
        jmp MOVFR                       ; [MS 5458] MOVE RESULT INTO FAC, THEN
; [MS 5459] NORMALIZE RESULT AND RETURN.
DV0ERR:                                 ; [MS 5460]
        ldx #ERRDV0                     ; [MS 5460]
        jmp ERROR                       ; [MS 5461]
; [MS 5463] ==== FLOATING POINT MOVEMENT ROUTINES. ====
; [MS 5464] MOVE RESULT TO FAC.
MOVFR:                                  ; [MS 5465]
        lda RESHO                       ; [MS 5465]
        sta FACHO                       ; [MS 5466]

        lda RESMOH                      ; [MS 5468]
        sta FACMOH                      ; [MS 5469]
        lda RESMO                       ; [MS 5470]
        sta FACMO                       ; [MS 5471]
        lda RESLO                       ; [MS 5472] MOVE LO AND SGN.
        sta FACLO                       ; [MS 5473]
        jmp NORMAL                      ; [MS 5474] ALL DONE.

; [MS 5476] MOVE MEMORY INTO FAC (UNPACKED).
MOVFM:                                  ; [MS 5477]
        sta INDEX1                      ; [MS 5477 STWD]
        sty INDEX1+1                    ; [MS 5477 STWD]
        ldy #3+ADDPRC                   ; [MS 5478]
        lda (INDEX1),y                  ; [MS 5479]
        sta FACLO                       ; [MS 5480]
        dey                             ; [MS 5481]
        lda (INDEX1),y                  ; [MS 5482]
        sta FACMO                       ; [MS 5483]
        dey                             ; [MS 5484]

        lda (INDEX1),y                  ; [MS 5486]
        sta FACMOH                      ; [MS 5487]
        dey                             ; [MS 5488]
        lda (INDEX1),y                  ; [MS 5489]
        sta FACSGN                      ; [MS 5490]
        ora #$80                        ; [MS 5491]
        sta FACHO                       ; [MS 5492]
        dey                             ; [MS 5493]
        lda (INDEX1),y                  ; [MS 5494]
        sta FACEXP                      ; [MS 5495] LEAVE SWITCHES SET ON EXP.
        sty FACOV                       ; [MS 5496]
        rts                             ; [MS 5497]

; [MS 5499] MOVE NUMBER FROM FAC TO MEMORY.
MOV2F:                                  ; [MS 5500]
        ldx #TEMPF2                     ; [MS 5500]
        .byte $2C                       ; [MS 5501 SKIP2]
MOV1F:                                  ; [MS 5502]
        ldx #TEMPF1                     ; [MS 5502]
MOVML:                                  ; [MS 5503]
        ldy #0                          ; [MS 5503]
        beq MOVMF                       ; [MS 5504] ALWAYS BRANCHES.
MOVVF:                                  ; [MS 5505]
        ldx FORPNT                      ; [MS 5505 LDXY]
        ldy FORPNT+1                    ; [MS 5505 LDXY]
MOVMF:                                  ; [MS 5506]
        jsr ROUND                       ; [MS 5506]
        stx INDEX1                      ; [MS 5507 STXY]
        sty INDEX1+1                    ; [MS 5507 STXY]
        ldy #3+ADDPRC                   ; [MS 5508]
        lda FACLO                       ; [MS 5509]
        sta (INDEX),y                   ; [MS 5510]
        dey                             ; [MS 5511]
        lda FACMO                       ; [MS 5512]
        sta (INDEX),y                   ; [MS 5513]
        dey                             ; [MS 5514]

        lda FACMOH                      ; [MS 5516]
        sta (INDEX),y                   ; [MS 5517]
        dey                             ; [MS 5518]
        lda FACSGN                      ; [MS 5519] INCLUDE SIGN IN HO.
        ora #$7F                        ; [MS 5520]
        and FACHO                       ; [MS 5521]
        sta (INDEX),y                   ; [MS 5522]
        dey                             ; [MS 5523]
        lda FACEXP                      ; [MS 5524]
        sta (INDEX),y                   ; [MS 5525]
        sty FACOV                       ; [MS 5526] ZERO IT SINCE ROUNDED.
        rts                             ; [MS 5527] [Y]=0.

; [MS 5529] MOVE ARG INTO FAC.
MOVFA:                                  ; [MS 5530]
        lda ARGSGN                      ; [MS 5530]
MOVFA1:                                 ; [MS 5531]
        sta FACSGN                      ; [MS 5531]
        ldx #4+ADDPRC                   ; [MS 5532]
MOVFAL:                                 ; [MS 5533]
        lda ARGEXP-1,x                  ; [MS 5533]
        sta FACEXP-1,x                  ; [MS 5534]
        dex                             ; [MS 5535]
        bne MOVFAL                      ; [MS 5536]
        stx FACOV                       ; [MS 5537]
        rts                             ; [MS 5538]

; [MS 5540] MOVE FAC INTO ARG.
MOVAF:                                  ; [MS 5541]
        jsr ROUND                       ; [MS 5541]
MOVEF:                                  ; [MS 5542]
        ldx #5+ADDPRC                   ; [MS 5542]
MOVAFL:                                 ; [MS 5543]
        lda FACEXP-1,x                  ; [MS 5543]
        sta ARGEXP-1,x                  ; [MS 5544]
        dex                             ; [MS 5545]
        bne MOVAFL                      ; [MS 5546]
        stx FACOV                       ; [MS 5547] ZERO IT SINCE ROUNDED.
MOVRTS:                                 ; [MS 5548]
        rts                             ; [MS 5548]

ROUND:                                  ; [MS 5550]
        lda FACEXP                      ; [MS 5550] ZERO?
        beq MOVRTS                      ; [MS 5551] YES. DONE ROUNDING.
        asl FACOV                       ; [MS 5552] ROUND?
        bcc MOVRTS                      ; [MS 5553] NO. MSB OFF.
INCRND:                                 ; [MS 5554]
        jsr INCFAC                      ; [MS 5554] YES, ADD ONE TO LSB(FAC).
        bne MOVRTS                      ; [MS 5555] NO CARRY MEANS DONE.
        jmp RNDSHF                      ; [MS 5556] SQUEEZ MSB IN AND RTS.
; [MS 5557] NOTE [C]=1 SINCE INCFAC DOESNT TOUCH C.
; [MS 5559] ==== SIGN, SGN, FLOAT, NEG, ABS. ====

; [MS 5561] PUT SIGN OF FAC IN ACCA.
SIGN:                                   ; [MS 5562]
        lda FACEXP                      ; [MS 5562]
        beq SIGNRT                      ; [MS 5563] IF NUMBER IS ZERO, SO IS RESULT.
FCSIGN:                                 ; [MS 5564]
        lda FACSGN                      ; [MS 5564]
FCOMPS:                                 ; [MS 5565]
        rol a                           ; [MS 5565]
        lda #$FF                        ; [MS 5566] ASSUME NEGATIVE.
        bcs SIGNRT                      ; [MS 5567]
        lda #1                          ; [MS 5568] GET +1.
SIGNRT:                                 ; [MS 5569]
        rts                             ; [MS 5569]

; [MS 5571] SGN FUNCTION.
SGN:                                    ; [MS 5572]
        jsr SIGN                        ; [MS 5572]

; [MS 5574] FLOAT THE SIGNED INTEGER IN ACCA.
FLOAT:                                  ; [MS 5575]
        sta FACHO                       ; [MS 5575] PUT [ACCA] IN HIGH ORDER.
        lda #0                          ; [MS 5576]
        sta FACHO+1                     ; [MS 5577]
        ldx #$88                        ; [MS 5578] GET THE EXPONENT.

; [MS 5580] FLOAT THE SIGNED NUMBER IN FAC.
FLOATS:                                 ; [MS 5581]
        lda FACHO                       ; [MS 5581]
        eor #$FF                        ; [MS 5582]
        rol a                           ; [MS 5583] GET COMP OF SIGN IN CARRY.
FLOATC:                                 ; [MS 5584]
        lda #0                          ; [MS 5584] ZERO [ACCA] BUT NOT CARRY.
        sta FACLO                       ; [MS 5585]

        sta FACMO                       ; [MS 5587]
FLOATB:                                 ; [MS 5588]
        stx FACEXP                      ; [MS 5588]
        sta FACOV                       ; [MS 5589]
        sta FACSGN                      ; [MS 5590]
        jmp FADFLT                      ; [MS 5591]

; [MS 5593] ABSOLUTE VALUE OF FAC.
ABS:                                    ; [MS 5594]
        lsr FACSGN                      ; [MS 5594]
        rts                             ; [MS 5595]

; [MS 5598] ==== COMPARE TWO NUMBERS. ====
; [MS 5599] A=1 IF ARG .LT. FAC.
; [MS 5600] A=0 IF ARG=FAC.
; [MS 5601] A=-1 IF ARG .GT. FAC.
FCOMP:                                  ; [MS 5602]
        sta INDEX2                      ; [MS 5602]
FCOMPN:                                 ; [MS 5603]
        sty INDEX2+1                    ; [MS 5603]
        ldy #0                          ; [MS 5604]
        lda (INDEX2),y                  ; [MS 5605] HAS ARGEXP.
        iny                             ; [MS 5606] BUMP PNTR UP.
        tax                             ; [MS 5607] SAVE A IN X AND RESET CODES.
        beq SIGN                        ; [MS 5608]
        lda (INDEX2),y                  ; [MS 5609]
        eor FACSGN                      ; [MS 5610] SIGNS THE SAME.
        bmi FCSIGN                      ; [MS 5611] SIGNS DIFFER SO RESULT IS
; [MS 5612] SIGN OF FAC AGAIN.
FOUTCP:                                 ; [MS 5613]
        cpx FACEXP                      ; [MS 5613]
        bne FCOMPC                      ; [MS 5614]
        lda (INDEX2),y                  ; [MS 5615]
        ora #$80                        ; [MS 5616]
        cmp FACHO                       ; [MS 5617]
        bne FCOMPC                      ; [MS 5618]
        iny                             ; [MS 5619]

        lda (INDEX2),y                  ; [MS 5621]
        cmp FACMOH                      ; [MS 5622]
        bne FCOMPC                      ; [MS 5623]
        iny                             ; [MS 5624]
        lda (INDEX2),y                  ; [MS 5625]
        cmp FACMO                       ; [MS 5626]
        bne FCOMPC                      ; [MS 5627]
        iny                             ; [MS 5628]
        lda #$7F                        ; [MS 5629]
        cmp FACOV                       ; [MS 5630]
        lda (INDEX2),y                  ; [MS 5631]
        sbc FACLO                       ; [MS 5632] GET ZERO IF EQUAL.
        beq QINTRT                      ; [MS 5633]
FCOMPC:                                 ; [MS 5634]
        lda FACSGN                      ; [MS 5634]
        bcc FCOMPD                      ; [MS 5635]
        eor #$FF                        ; [MS 5636]
FCOMPD:                                 ; [MS 5637]
        jmp FCOMPS                      ; [MS 5637] A PART OF SIGN SETS ACCA UP.

; [MS 5640] ==== GREATEST INTEGER FUNCTION. ====
; [MS 5641] QUICK GREATEST INTEGER FUNCTION.
; [MS 5642] LEAVES INT(FAC) IN FACHO&MO&LO SIGNED.
; [MS 5643] ASSUMES FAC .LT. 2^23 = 8388608
QINT:                                   ; [MS 5644]
        lda FACEXP                      ; [MS 5644]
        beq CLRFAC                      ; [MS 5645] IF ZERO, GOT IT.
        sec                             ; [MS 5646]
        sbc #8*ADDPRC+$98               ; [MS 5647] GET NUMBER OF PLACES TO SHIFT.
        bit FACSGN                      ; [MS 5648]
        bpl QISHFT                      ; [MS 5649]
        tax                             ; [MS 5650]
        lda #$FF                        ; [MS 5651]
        sta BITS                        ; [MS 5652] PUT 377 IN WHEN SHFTR SHIFTS BYTES.
        jsr NEGFCH                      ; [MS 5653] TRULY NEGATE QUANTITY IN FAC.
        txa                             ; [MS 5654]
QISHFT:                                 ; [MS 5655]
        ldx #FAC                        ; [MS 5655]
        cmp #256-7                      ; [MS 5656]
        bpl QINT1                       ; [MS 5657] IF NUMBER OF PLACES .GE. 7
; [MS 5658] SHIFT 1 PLACE AT A TIME.
        jsr SHIFTR                      ; [MS 5659] START SHIFTING BYTES, THEN BITS.
        sty BITS                        ; [MS 5660] ZERO BITS SINCE ADDER WANTS ZERO.
QINTRT:                                 ; [MS 5661]
        rts                             ; [MS 5661]
QINT1:                                  ; [MS 5662]
        tay                             ; [MS 5662] PUT COUNT IN COUNTER.
        lda FACSGN                      ; [MS 5663]
        and #$80                        ; [MS 5664] GET SIGN BIT.
        lsr FACHO                       ; [MS 5665] SAVE FIRST SHIFTED BYTE.
        ora FACHO                       ; [MS 5666]
        sta FACHO                       ; [MS 5667]
        jsr ROLSHF                      ; [MS 5668] SHIFT THE REST.
        sty BITS                        ; [MS 5669] ZERO [BITS].
        rts                             ; [MS 5670]

; [MS 5672] GREATEST INTEGER FUNCTION.
INT:                                    ; [MS 5673]
        lda FACEXP                      ; [MS 5673]
        cmp #8*ADDPRC+$98               ; [MS 5674]
        bcs INTRTS                      ; [MS 5675] FORGET IT.
        jsr QINT                        ; [MS 5676]
        sty FACOV                       ; [MS 5677] CLR OVERFLOW BYTE.
        lda FACSGN                      ; [MS 5678]
        sty FACSGN                      ; [MS 5679] MAKE FAC LOOK POSITIVE.
        eor #$80                        ; [MS 5680] GET COMPLEMENT OF SIGN IN CARRY.
        rol a                           ; [MS 5681]
        lda #8*ADDPRC+$98               ; [MS 5682]
        sta FACEXP                      ; [MS 5683]
        lda FACLO                       ; [MS 5684]
        sta INTEGR                      ; [MS 5685]
        jmp FADFLT                      ; [MS 5686]
CLRFAC:                                 ; [MS 5687]
        sta FACHO                       ; [MS 5687] MAKE IT REALLY ZERO.
        sta FACMOH                      ; [MS 5688]
        sta FACMO                       ; [MS 5689]
        sta FACLO                       ; [MS 5690]
        tay                             ; [MS 5691]
INTRTS:                                 ; [MS 5692]
        rts                             ; [MS 5692]
; [MS 5694] ==== FLOATING POINT INPUT ROUTINE. ====
; [MS 5695] NUMBER INPUT IS LEFT IN FAC.
; [MS 5696] AT ENTRY [TXTPTR] POINTS TO THE FIRST CHARACTER IN A TEXT BUFFER.
; [MS 5697] THE FIRST CHARACTER IS ALSO IN ACCA. FIN PACKS THE DIGITS
; [MS 5698] INTO THE FAC AS AN INTEGER AND KEEPS TRACK OF WHERE THE
; [MS 5699] DECIMAL POINT IS. [DPTFLG] TELL WHETHER A DP HAS BEEN
; [MS 5700] SEEN. [DECCNT] IS THE NUMBER OF DIGITS AFTER THE DP.
; [MS 5701] AT THE END [DECCNT] AND THE EXPONENT ARE USED TO
; [MS 5702] DETERMINE HOW MANY TIMES TO MULTIPLY OR DIVIDE BY TEN
; [MS 5703] TO GET THE CORRECT NUMBER.
FIN:                                    ; [MS 5704]
        ldy #0                          ; [MS 5704] ZERO FACSGN&SGNFLG.
        ldx #9+ADDPRC                   ; [MS 5705] ZERO EXP AND HO (AND MOH).
FINZLP:                                 ; [MS 5706]
        sty DECCNT,x                    ; [MS 5706] ZERO MO AND LO.
        dex                             ; [MS 5707] ZERO TENEXP AND EXPSGN
        bpl FINZLP                      ; [MS 5708] ZERO DECCNT, DPTFLG.
        bcc FINDGQ                      ; [MS 5709] FLAGS STILL SET FROM CHRGET.
        cmp #'-'                        ; [MS 5710] A NEGATIVE SIGN?
        bne QPLUS                       ; [MS 5711] NO, TRY PLUS SIGN.
        stx SGNFLG                      ; [MS 5712] IT'S NEGATIVE. (X=377).
        beq FINC                        ; [MS 5713] ALWAYS BRANCHES.
QPLUS:                                  ; [MS 5714]
        cmp #'+'                        ; [MS 5714] PLUS SIGN?
        bne FIN1                        ; [MS 5715] YES, SKIP IT.
FINC:                                   ; [MS 5716]
        jsr CHRGET                      ; [MS 5716]
FINDGQ:                                 ; [MS 5717]
        bcc FINDIG                      ; [MS 5717]
FIN1:                                   ; [MS 5718]
        cmp #'.'                        ; [MS 5718] THE DP?
        beq FINDP                       ; [MS 5719] NO KIDDING.
        cmp #'E'                        ; [MS 5720] EXPONENT FOLLOWS.
        bne FINE                        ; [MS 5721] NO.
; [MS 5722] HERE TO CHECK FOR SIGN OF EXP.
        jsr CHRGET                      ; [MS 5723] YES. GET ANOTHER.
        bcc FNEDG1                      ; [MS 5724] IT IS A DIGIT. (EASIER THAN
; [MS 5725] BACKING UP POINTER.)
        cmp #MINUTK                     ; [MS 5726] MINUS?
        beq FINEC1                      ; [MS 5727] NEGATE.
        cmp #'-'                        ; [MS 5728] MINUS SIGN?
        beq FINEC1                      ; [MS 5729]
        cmp #PLUSTK                     ; [MS 5730] PLUS?
        beq FINEC                       ; [MS 5731]
        cmp #'+'                        ; [MS 5732] PLUS SIGN?
        beq FINEC                       ; [MS 5733]
        bne FINEC2                      ; [MS 5734]
FINEC1:                                 ; [MS 5735]
        ror EXPSGN                      ; [MS 5735] TURN IT ON.
FINEC:                                  ; [MS 5736]
        jsr CHRGET                      ; [MS 5736] GET ANOTHER.
FNEDG1:                                 ; [MS 5737]
        bcc FINEDG                      ; [MS 5737] IT IS A DIGIT.
FINEC2:                                 ; [MS 5738]
        bit EXPSGN                      ; [MS 5738]
        bpl FINE                        ; [MS 5739]
        lda #0                          ; [MS 5740]
        sec                             ; [MS 5741]
        sbc TENEXP                      ; [MS 5742]
        jmp FINE1                       ; [MS 5743]
FINDP:                                  ; [MS 5744]
        ror DPTFLG                      ; [MS 5744]
        bit DPTFLG                      ; [MS 5745]
        bvc FINC                        ; [MS 5746]
FINE:                                   ; [MS 5747]
        lda TENEXP                      ; [MS 5747]
FINE1:                                  ; [MS 5748]
        sec                             ; [MS 5748]
        sbc DECCNT                      ; [MS 5749] GET NUMBER OF PLACES TO SHIFT.
        sta TENEXP                      ; [MS 5750]
        beq FINQNG                      ; [MS 5751] NEGATE?
        bpl FINMUL                      ; [MS 5752] POSITIVE SO MULTIPLY.
FINDIV:                                 ; [MS 5753]
        jsr DIV10                       ; [MS 5753]
        inc TENEXP                      ; [MS 5754] DONE?
        bne FINDIV                      ; [MS 5755] NO.
        beq FINQNG                      ; [MS 5756] YES.
FINMUL:                                 ; [MS 5757]
        jsr MUL10                       ; [MS 5757]
        dec TENEXP                      ; [MS 5758] DONE?
        bne FINMUL                      ; [MS 5759] NO
FINQNG:                                 ; [MS 5760]
        lda SGNFLG                      ; [MS 5760]
        bmi NEGXQS                      ; [MS 5761] IF POSITIVE, RETURN.
        rts                             ; [MS 5762]
NEGXQS:                                 ; [MS 5763]
        jmp NEGOP                       ; [MS 5763] OTHERWISE, NEGATE AND RETURN.

FINDIG:                                 ; [MS 5765]
        pha                             ; [MS 5765]
        bit DPTFLG                      ; [MS 5766]
        bpl FINDG1                      ; [MS 5767]
        inc DECCNT                      ; [MS 5768]
FINDG1:                                 ; [MS 5769]
        jsr MUL10                       ; [MS 5769]
        pla                             ; [MS 5770] GET IT BACK.
        sec                             ; [MS 5771]
        sbc #'0'                        ; [MS 5772]
        jsr FINLOG                      ; [MS 5773] ADD IT IN.
        jmp FINC                        ; [MS 5774]

FINLOG:                                 ; [MS 5776]
        pha                             ; [MS 5776]
        jsr MOVAF                       ; [MS 5777] SAVE FAC FOR LATER.
        pla                             ; [MS 5778]
        jsr FLOAT                       ; [MS 5779] FLOAT THE VALUE IN ACCA.
        lda ARGSGN                      ; [MS 5780]
        eor FACSGN                      ; [MS 5781]
        sta ARISGN                      ; [MS 5782] RESULTANT SIGN.
        ldx FACEXP                      ; [MS 5783] SET SIGNS ON THING TO ADD.
        jmp FADDT                       ; [MS 5784] ADD TOGETHER AND RETURN.

; [MS 5786] HERE PACK IN THE NEXT DIGIT OF THE EXPONENT.
; [MS 5787] MULTIPLY THE OLD EXP BY 10 AND ADD IN THE NEXT
; [MS 5788] DIGIT. NOTE: EXP OVERFLOW IS NOT CHECKED FOR.
FINEDG:                                 ; [MS 5789]
        lda TENEXP                      ; [MS 5789] GET EXP SO FAR.
        cmp #$0A                        ; [MS 5790] WILL RESULT BE .GE. 100?
        bcc MLEX10                      ; [MS 5791]
        lda #$64                        ; [MS 5792] GET 100.
        bit EXPSGN                      ; [MS 5793]
        bmi MLEXMI                      ; [MS 5794] IF NEG EXP, NO CHK FOR OVERR.
        jmp OVERR                       ; [MS 5795]
MLEX10:                                 ; [MS 5796]
        asl a                           ; [MS 5796] MULT BY 2 TWICE
        asl a                           ; [MS 5797]
        clc                             ; [MS 5798] POSSIBLE SHIFT OUT OF HIGH.
        adc TENEXP                      ; [MS 5799] LIKE MULTIPLYING BY FIVE.
        asl a                           ; [MS 5800] AND NOW BY TEN.
        clc                             ; [MS 5801]
        ldy #0                          ; [MS 5802]
        adc (TXTPTR),y                  ; [MS 5803]
        sec                             ; [MS 5804]
        sbc #'0'                        ; [MS 5805]
MLEXMI:                                 ; [MS 5806]
        sta TENEXP                      ; [MS 5806] SAVE RESULT.
        jmp FINEC                       ; [MS 5807]
; [MS 5809] ==== FLOATING POINT OUTPUT ROUTINE. ====



NZ0999:                                 ; [MS 5825]
        .byte $9B                       ; [MS 5825] 99999999.9499
        .byte $3E                       ; [MS 5826]
        .byte $BC                       ; [MS 5827]
        .byte $1F                       ; [MS 5828]
        .byte $FD                       ; [MS 5829]
NZ9999:                                 ; [MS 5830]
        .byte $9E                       ; [MS 5830] 999999999.499
        .byte $6E                       ; [MS 5831]
        .byte $6B                       ; [MS 5832]
        .byte $27                       ; [MS 5833]
        .byte $FD                       ; [MS 5834]
NZMIL:                                  ; [MS 5835]
        .byte $9E                       ; [MS 5835] 10^9
        .byte $6E                       ; [MS 5836]
        .byte $6B                       ; [MS 5837]
        .byte $28                       ; [MS 5838]
        .byte 0                         ; [MS 5839]
; [MS 5840] ENTRY TO LINPRT.
INPRT:                                  ; [MS 5841]
        lda #<INTXT                     ; [MS 5841 LDWDI]
        ldy #>INTXT                     ; [MS 5841 LDWDI]
        jsr STROU2                      ; [MS 5842]
        lda CURLIN+1                    ; [MS 5843]
        ldx CURLIN                      ; [MS 5844]
LINPRT:                                 ; [MS 5845]
        sta FACHO                       ; [MS 5845 STWX]
        stx FACHO+1                     ; [MS 5845 STWX]
        ldx #$90                        ; [MS 5846] EXPONENT OF 16.
        sec                             ; [MS 5847] NUMBER IS POSITIVE.
        jsr FLOATC                      ; [MS 5848]
        jsr FOUT                        ; [MS 5849]
STROU2:                                 ; [MS 5850]
        jmp STROUT                      ; [MS 5850] PRINT AND RETURN.

FOUT:                                   ; [MS 5852]
        ldy #1                          ; [MS 5852]
FOUTC:                                  ; [MS 5853]
        lda #' '                        ; [MS 5853] PRINT SPACE IF POSITIVE.
        bit FACSGN                      ; [MS 5854]
        bpl FOUT1                       ; [MS 5855]
        lda #'-'                        ; [MS 5856]
FOUT1:                                  ; [MS 5857]
        sta FBUFFR-1,y                  ; [MS 5857] STORE THE CHARACTER.
        sta FACSGN                      ; [MS 5858] MAKE FAC POS FOR QINT.
        sty FBUFPT                      ; [MS 5859] SAVE FOR LATER.
        iny                             ; [MS 5860]
        lda #'0'                        ; [MS 5861] GET ZERO TO TYPE IF FAC=0.
        ldx FACEXP                      ; [MS 5862]
        bne *+5                         ; [MS 5863 JEQ]
        jmp FOUT19                      ; [MS 5863 JEQ]
        lda #0                          ; [MS 5864]
        cpx #$80                        ; [MS 5865] IS NUMBER .LT. 1.0 ?
        beq FOUT37                      ; [MS 5866] NO.
        bcs FOUT7                       ; [MS 5867]
FOUT37:                                 ; [MS 5868]
        lda #<NZMIL                     ; [MS 5868 LDWDI]
        ldy #>NZMIL                     ; [MS 5868 LDWDI] MULTIPLY BY 10^6.
        jsr FMULT                       ; [MS 5869]
        lda #256-3*ADDPRC-6             ; [MS 5870]
FOUT7:                                  ; [MS 5871]
        sta DECCNT                      ; [MS 5871] SAVE COUNT OR ZERO IT.
FOUT4:                                  ; [MS 5872]
        lda #<NZ9999                    ; [MS 5872 LDWDI]
        ldy #>NZ9999                    ; [MS 5872 LDWDI]
        jsr FCOMP                       ; [MS 5873] IS NUMBER .GT. 999999.499 ?
; [MS 5874] OR 999999999.499?
        beq BIGGES                      ; [MS 5875]
        bpl FOUT9                       ; [MS 5876] YES. MAKE IT SMALLER.
FOUT3:                                  ; [MS 5877]
        lda #<NZ0999                    ; [MS 5877 LDWDI]
        ldy #>NZ0999                    ; [MS 5877 LDWDI]
        jsr FCOMP                       ; [MS 5878] IS NUMBER .GT. 99999.9499 ?
; [MS 5879] OR 99999999.9499?
        beq FOUT38                      ; [MS 5880]
        bpl FOUT5                       ; [MS 5881] YES. DONE MULTIPLYING.
FOUT38:                                 ; [MS 5882]
        jsr MUL10                       ; [MS 5882] MAKE IT BIGGER.
        dec DECCNT                      ; [MS 5883]
        bne FOUT3                       ; [MS 5884] SEE IF THAT DOES IT.
; [MS 5885] THIS ALWAYS GOES.
FOUT9:                                  ; [MS 5886]
        jsr DIV10                       ; [MS 5886] MAKE IT SMALLER.
        inc DECCNT                      ; [MS 5887]
        bne FOUT4                       ; [MS 5888] SEE IF THAT DOES IT.
; [MS 5889] THIS ALWAYS GOES.

FOUT5:                                  ; [MS 5891]
        jsr FADDH                       ; [MS 5891] ADD A HALF TO ROUND UP.
BIGGES:                                 ; [MS 5892]
        jsr QINT                        ; [MS 5892]
        ldx #1                          ; [MS 5893] DECIMAL POINT COUNT.
        lda DECCNT                      ; [MS 5894]
        clc                             ; [MS 5895]
        adc #3*ADDPRC+7                 ; [MS 5896] SHOULD NUMBER BE PRINTED IN E NOTATION?
; [MS 5897] IE, IS NUMBER .LT. .01 ?
        bmi FOUTPI                      ; [MS 5898] YES.
        cmp #3*ADDPRC+8                 ; [MS 5899] IS IT .GT. 999999 (999999999)?
        bcs FOUT6                       ; [MS 5900] YES. USE E NOTATION.
        adc #$FF                        ; [MS 5901] NUMBER OF PLACES BEFORE DECIMAL POINT.
        tax                             ; [MS 5902] PUT INTO ACCX.
        lda #2                          ; [MS 5903] NO E NOTATION.
FOUTPI:                                 ; [MS 5904]
        sec                             ; [MS 5904]
FOUT6:                                  ; [MS 5905]
        sbc #2                          ; [MS 5905] EFFECTIVELY ADD 5 TO ORIG EXP.
        sta TENEXP                      ; [MS 5906] THAT IS THE EXPONENT TO PRINT.
        stx DECCNT                      ; [MS 5907] NUMBER OF DECIMAL PLACES.
        txa                             ; [MS 5908]
        beq FOUT39                      ; [MS 5909]
        bpl FOUT8                       ; [MS 5910] SOME PLACES BEFORE DEC PNT.
FOUT39:                                 ; [MS 5911]
        ldy FBUFPT                      ; [MS 5911] GET POINTER TO OUTPUT.
        lda #'.'                        ; [MS 5912] PUT IN "."
        iny                             ; [MS 5913]
        sta FBUFFR-1,y                  ; [MS 5914]
        txa                             ; [MS 5915]
        beq FOUT16                      ; [MS 5916]
        lda #'0'                        ; [MS 5917] GET THE ENSUING ZERO.
        iny                             ; [MS 5918]
        sta FBUFFR-1,y                  ; [MS 5919]
FOUT16:                                 ; [MS 5920]
        sty FBUFPT                      ; [MS 5920] SAVE FOR LATER.
FOUT8:                                  ; [MS 5921]
        ldy #0                          ; [MS 5921]
FOUTIM:                                 ; [MS 5922]
        ldx #$80                        ; [MS 5922] FIRST PASS THRU, ACCX HAS MSB SET.
FOUT2:                                  ; [MS 5923]
        lda FACLO                       ; [MS 5923]
        clc                             ; [MS 5924]
        adc FOUTBL+2+ADDPRC,y           ; [MS 5925]
        sta FACLO                       ; [MS 5926]
        lda FACMO                       ; [MS 5927]
        adc FOUTBL+1+ADDPRC,y           ; [MS 5928]
        sta FACMO                       ; [MS 5929]

        lda FACMOH                      ; [MS 5931]
        adc FOUTBL+1,y                  ; [MS 5932]
        sta FACMOH                      ; [MS 5933]
        lda FACHO                       ; [MS 5934]
        adc FOUTBL,y                    ; [MS 5935]
        sta FACHO                       ; [MS 5936]
        inx                             ; [MS 5937] IT WAS DONE YET ANOTHER TIME.
        bcs FOUT41                      ; [MS 5938]
        bpl FOUT2                       ; [MS 5939]
        bmi FOUT40                      ; [MS 5940]
FOUT41:                                 ; [MS 5941]
        bmi FOUT2                       ; [MS 5941]
FOUT40:                                 ; [MS 5942]
        txa                             ; [MS 5942]
        bcc FOUTYP                      ; [MS 5943] CAN USE ACCA AS IS.
        eor #$FF                        ; [MS 5944] FIND 11.-[A].
        adc #$0A                        ; [MS 5945] C IS STILL ON TO COMPLETE NEGATION.
; [MS 5946] AND WILL ALWAYS BE ON AFTER.
FOUTYP:                                 ; [MS 5947]
        adc #'0'-1                      ; [MS 5947] GET A CHARACTER TO PRINT.
        iny                             ; [MS 5948]
        iny                             ; [MS 5948]
        iny                             ; [MS 5948]
        iny                             ; [MS 5948] BUMP POINTER UP.
        sty FDECPT                      ; [MS 5949]
        ldy FBUFPT                      ; [MS 5950]
        iny                             ; [MS 5951] POINT TO PLACE TO STORE OUTPUT.
        tax                             ; [MS 5952]
        and #$7F                        ; [MS 5953] GET RID OF MSB.
        sta FBUFFR-1,y                  ; [MS 5954]
        dec DECCNT                      ; [MS 5955]
        bne STXBUF                      ; [MS 5956] NOT TIME FOR DP YET.
        lda #'.'                        ; [MS 5957]
        iny                             ; [MS 5958]
        sta FBUFFR-1,y                  ; [MS 5959] STORE DP.
STXBUF:                                 ; [MS 5960]
        sty FBUFPT                      ; [MS 5960] STORE PNTR FOR LATER.
        ldy FDECPT                      ; [MS 5961]
FOUTCM:                                 ; [MS 5962]
        txa                             ; [MS 5962] COMPLEMENT ACCX
        eor #$FF                        ; [MS 5963] COMPLEMENT ACCA.
        and #$80                        ; [MS 5964] SAVE ONLY MSB.
        tax                             ; [MS 5965]
        cpy #<(FDCEND-FOUTBL)           ; [MS 5966]

        bne FOUT2                       ; [MS 5970] CONTINUE WITH OUTPUT.
FOULDY:                                 ; [MS 5971]
        ldy FBUFPT                      ; [MS 5971] GET BACK OUTPUT PNTR.
FOUT11:                                 ; [MS 5972]
        lda FBUFFR-1,y                  ; [MS 5972] REMOVE TRAILING ZEROES.
        dey                             ; [MS 5973]
        cmp #'0'                        ; [MS 5974]
        beq FOUT11                      ; [MS 5975]
        cmp #'.'                        ; [MS 5976]
        beq FOUT12                      ; [MS 5977] RUN INTO DP. STOP.
        iny                             ; [MS 5978] SOMETHING ELSE. SAVE IT.
FOUT12:                                 ; [MS 5979]
        lda #'+'                        ; [MS 5979]
        ldx TENEXP                      ; [MS 5980]
        beq FOUT17                      ; [MS 5981] NO EXPONENT TO OUTPUT.
        bpl FOUT14                      ; [MS 5982]
        lda #0                          ; [MS 5983]
        sec                             ; [MS 5984]
        sbc TENEXP                      ; [MS 5985]
        tax                             ; [MS 5986]
        lda #'-'                        ; [MS 5987] EXPONENT IS NEGATIVE.
FOUT14:                                 ; [MS 5988]
        sta FBUFFR-1+2,y                ; [MS 5988] STORE SIGN OF EXP
        lda #'E'                        ; [MS 5989]
        sta FBUFFR-1+1,y                ; [MS 5990] STORE THE "E" CHARACTER.
        txa                             ; [MS 5991]
        ldx #'0'-1                      ; [MS 5992]
        sec                             ; [MS 5993]
FOUT15:                                 ; [MS 5994]
        inx                             ; [MS 5994] MOVE CLOSER TO OUTPUT VALUE.
        sbc #$0A                        ; [MS 5995] SUBTRACT 10.
        bcs FOUT15                      ; [MS 5996] NOT NEGATIVE YET.
        adc #'0'+$0A                    ; [MS 5997] GET SECOND OUTPUT CHARACTER.
        sta FBUFFR-1+4,y                ; [MS 5998] STORE HIGH DIGIT.
        txa                             ; [MS 5999]
        sta FBUFFR-1+3,y                ; [MS 6000] STORE	LOW DIGIT.
        lda #0                          ; [MS 6001] PUT IN TERMINATOR.
        sta FBUFFR-1+5,y                ; [MS 6002]
        beq FOUT20                      ; [MS 6003 BEQA] RETURN. (ALWAYS BRANCHES).
FOUT19:                                 ; [MS 6004]
        sta FBUFFR-1,y                  ; [MS 6004] STORE THE CHARACTER.
FOUT17:                                 ; [MS 6005]
        lda #0                          ; [MS 6005] A TERMINATOR.
        sta FBUFFR-1+1,y                ; [MS 6006]
FOUT20:                                 ; [MS 6007]
        jmp FOUTSP                      ; [MS 6007] [OURS] FOUT's space skip is out of line (FOUTSP): Microsoft's four bytes kept here
        .byte $02                       ; [OURS]
FPWRRT:                                 ; [MS 6008]
        rts                             ; [MS 6008] ALL DONE.
FHALF:                                  ; [MS 6009]
        .byte $80                       ; [MS 6009] 1/2
        .byte 0                         ; [MS 6010]
ZERO:                                   ; [MS 6011]
        .byte 0                         ; [MS 6011]
        .byte 0                         ; [MS 6012]
        .byte 0                         ; [MS 6013]

; [MS 6015] POWER OF TEN TABLE



FOUTBL:                                 ; [MS 6037]
        .byte $FA                       ; [MS 6037] -100,000,000
        .byte $0A                       ; [MS 6038]
        .byte $1F                       ; [MS 6039]
        .byte 0                         ; [MS 6040]
        .byte 0                         ; [MS 6041] 10,000,000
        .byte $98                       ; [MS 6042]
        .byte $96                       ; [MS 6043]
        .byte $80                       ; [MS 6044]
        .byte $FF                       ; [MS 6045] -1,000,000
        .byte $F0                       ; [MS 6046]
        .byte $BD                       ; [MS 6047]
        .byte $C0                       ; [MS 6048]
        .byte 0                         ; [MS 6049] 100,000
        .byte 1                         ; [MS 6050]
        .byte $86                       ; [MS 6051]
        .byte $A0                       ; [MS 6052]
        .byte $FF                       ; [MS 6053] -10,000
        .byte $FF                       ; [MS 6054]
        .byte $D8                       ; [MS 6055]
        .byte $F0                       ; [MS 6056]
        .byte 0                         ; [MS 6057] 1000
        .byte 0                         ; [MS 6058]
        .byte 3                         ; [MS 6059]
        .byte $E8                       ; [MS 6060]
        .byte $FF                       ; [MS 6061] -100
        .byte $FF                       ; [MS 6062]
        .byte $FF                       ; [MS 6063]
        .byte $9C                       ; [MS 6064]
        .byte 0                         ; [MS 6065] 10
        .byte 0                         ; [MS 6066]
        .byte 0                         ; [MS 6067]
        .byte $0A                       ; [MS 6068]
        .byte $FF                       ; [MS 6069] -1
        .byte $FF                       ; [MS 6070]
        .byte $FF                       ; [MS 6071]
        .byte $FF                       ; [MS 6072]
FDCEND:                                 ; [MS 6073]


; [MS 6102] ==== EXPONENTIATION AND SQUARE ROOT FUNCTION. ====
; [MS 6103] SQUARE ROOT FUNCTION --- SQR(A)
; [MS 6104] USE SQR(X)=X^.5
SQR:                                    ; [MS 6105]
        jsr MOVAF                       ; [MS 6105] MOVE FAC INTO ARG.
        lda #<FHALF                     ; [MS 6106 LDWDI]
        ldy #>FHALF                     ; [MS 6106 LDWDI]
        jsr MOVFM                       ; [MS 6107] PUT MEMORY INTO FAC.
; [MS 6108] LAST THING FETCHED IS FACEXP. INTO ACCX.
; [MS 6109] JMP	FPWRT		;FALL INTO FPWRT.

; [MS 6111] EXPONENTIATION ---  X^Y.
; [MS 6112] N.B.  0^0=1
; [MS 6113] FIRST CHECK IF Y=0. IF SO, THE RESULT IS 1.
; [MS 6114] NEXT CHECK IF X=0. IF SO THE RESULT IS 0.
; [MS 6115] THEN CHECK IF X.GT.0. IF NOT CHECK THAT Y IS AN INTEGER.
; [MS 6116] IF SO, NEGATE X, SO THAT LOG DOESN'T GIVE FCERR.
; [MS 6117] IF X IS NEGATIVE AND Y IS ODD, NEGATE THE RESULT
; [MS 6118] RETURNED BY EXP.
; [MS 6119] TO COMPUTE THE RESULT USE X^Y=EXP((Y*LOG(X)).
FPWRT:                                  ; [MS 6120]
        beq EXP                         ; [MS 6120] IF FAC=0, JUST EXPONENTIATE THAT.
        lda ARGEXP                      ; [MS 6121] IS X=0?
        bne FPWRT1                      ; [MS 6122]
        jmp ZEROF1                      ; [MS 6123] ZERO FAC.
FPWRT1:                                 ; [MS 6124]
        ldx #<TEMPF3                    ; [MS 6124 LDXYI]
        ldy #>TEMPF3                    ; [MS 6124 LDXYI] SAVE FOR LATER IN A TEMP.
        jsr MOVMF                       ; [MS 6125]
; [MS 6126] Y=0 ALREADY. GOOD IN CASE NO ONE CALLS INT.
        lda ARGSGN                      ; [MS 6127]
        bpl FPWR1                       ; [MS 6128] NO PROBLEMS IF X.GT.0.
        jsr INT                         ; [MS 6129] INTEGERIZE THE FAC.
        lda #<TEMPF3                    ; [MS 6130 LDWDI]
        ldy #>TEMPF3                    ; [MS 6130 LDWDI] GET ADDR OF COMPERAND.
        jsr FCOMP                       ; [MS 6131] EQUAL?
        bne FPWR1                       ; [MS 6132] LEAVE X NEG. LOG WILL BLOW HIM OUT.
; [MS 6133] A=-1 AND Y IS IRRELEVANT.
        tya                             ; [MS 6134] NEGATE X. MAKE POSITIVE.
        ldy INTEGR                      ; [MS 6135] GET EVENNESS.
FPWR1:                                  ; [MS 6136]
        jsr MOVFA1                      ; [MS 6136] ALTERNATE ENTRY POINT.
        tya                             ; [MS 6137]
        pha                             ; [MS 6138] SAVE EVENNESS FOR LATER.
        jsr LOG                         ; [MS 6139] FIND LOG.
        lda #<TEMPF3                    ; [MS 6140 LDWDI]
        ldy #>TEMPF3                    ; [MS 6140 LDWDI] MULTIPLY FAC TIMES LOG(X).
        jsr FMULT                       ; [MS 6141]
        jsr EXP                         ; [MS 6142] EXPONENTIATE THE FAC.
        pla                             ; [MS 6143]
        lsr a                           ; [MS 6144] IS IT EVEN?
        bcc NEGRTS                      ; [MS 6145] YES. OR X.GT.0.
; [MS 6146] NEGATE THE NUMBER IN FAC.
NEGOP:                                  ; [MS 6147]
        lda FACEXP                      ; [MS 6147]
        beq NEGRTS                      ; [MS 6148]
        lda FACSGN                      ; [MS 6149 COM]
        eor #$FF                        ; [MS 6149 COM]
        sta FACSGN                      ; [MS 6149 COM]
NEGRTS:                                 ; [MS 6150]
        rts                             ; [MS 6150]

; [MS 6153] ==== EXPONENTIATION FUNCTION. ====
; [MS 6154] FIRST SAVE THE ORIGINAL ARGUMENT AND MULTIPLY THE FAC BY
; [MS 6155] LOG2(E). THE RESULT IS USED TO DETERMINE IF OVERFLOW
; [MS 6156] WILL OCCUR SINCE EXP(X)=2^(X*LOG2(E)) WHERE
; [MS 6157] LOG2(E)=LOG(E) BASE 2. THEN SAVE THE INTEGER PART OF
; [MS 6158] THIS TO SCALE THE ANSWER AT THE END. SINCE
; [MS 6159] 2^Y=2^INT(Y)*2^(Y-INT(Y)) AND 2^INT(Y) IS EASY TO COMPUTE.
; [MS 6160] NOW COMPUTE 2^(X*LOG2(E)-INT(X*LOG2(E)) BY
; [MS 6161] P(LN(2)*(INT(X*LOG2(E))+1)-X) WHERE P IS AN APPROXIMATION
; [MS 6162] POLYNOMIAL. THE RESULT IS THEN SCALED BY THE POWER OF 2
; [MS 6163] PREVIOUSLY SAVED.

LOGEB2:                                 ; [MS 6165]
        .byte $81                       ; [MS 6165] LOG(E) BASE 2.
        .byte $38                       ; [MS 6166]
        .byte $AA                       ; [MS 6167]
        .byte $3B                       ; [MS 6168]
        .byte $29                       ; [MS 6169]





EXPCON:                                 ; [MS 6204]
        .byte 7                         ; [MS 6204] DEGREE-1
        .byte $71                       ; [MS 6205] .000021498763697
        .byte $34                       ; [MS 6206]
        .byte $58                       ; [MS 6207]
        .byte $3E                       ; [MS 6208]
        .byte $56                       ; [MS 6209]
        .byte $74                       ; [MS 6210] .00014352314036
        .byte $16                       ; [MS 6211]
        .byte $7E                       ; [MS 6212]
        .byte $B3                       ; [MS 6213]
        .byte $1B                       ; [MS 6214]
        .byte $77                       ; [MS 6215] .0013422634824
        .byte $2F                       ; [MS 6216]
        .byte $EE                       ; [MS 6217]
        .byte $E3                       ; [MS 6218]
        .byte $85                       ; [MS 6219]
        .byte $7A                       ; [MS 6220] .0096140170119
        .byte $1D                       ; [MS 6221]
        .byte $84                       ; [MS 6222]
        .byte $1C                       ; [MS 6223]
        .byte $2A                       ; [MS 6224]
        .byte $7C                       ; [MS 6225] .055505126860
        .byte $63                       ; [MS 6226]
        .byte $59                       ; [MS 6227]
        .byte $58                       ; [MS 6228]
        .byte $0A                       ; [MS 6229]
        .byte $7E                       ; [MS 6230] .24022638462
        .byte $75                       ; [MS 6231]
        .byte $FD                       ; [MS 6232]
        .byte $E7                       ; [MS 6233]
        .byte $C6                       ; [MS 6234]
        .byte $80                       ; [MS 6235] .69314718608
        .byte $31                       ; [MS 6236]
        .byte $72                       ; [MS 6237]
        .byte $18                       ; [MS 6238]
        .byte $10                       ; [MS 6239]
        .byte $81                       ; [MS 6240] 1.0
        .byte 0                         ; [MS 6241]
        .byte 0                         ; [MS 6242]
        .byte 0                         ; [MS 6243]
        .byte 0                         ; [MS 6244]

EXP:                                    ; [MS 6246]
        lda #<LOGEB2                    ; [MS 6247 LDWDI]
        ldy #>LOGEB2                    ; [MS 6247 LDWDI] MULTIPLY BY LOG(E) BASE 2.
        jsr FMULT                       ; [MS 6248]
        lda FACOV                       ; [MS 6249]
        adc #$50                        ; [MS 6250]
        bcc STOLD                       ; [MS 6251]
        jsr INCRND                      ; [MS 6252]
STOLD:                                  ; [MS 6253]
        sta OLDOV                       ; [MS 6253]
        jsr MOVEF                       ; [MS 6254] TO SAVE IN ARG WITHOUT ROUND.
        lda FACEXP                      ; [MS 6255]
        cmp #$88                        ; [MS 6256] IF ABS(FAC) .GE. 128, TOO BIG.
        bcc EXP1                        ; [MS 6257]
GOMLDV:                                 ; [MS 6258]
        jsr MLDVEX                      ; [MS 6258] OVERFLOW OR OVERFLOW.
EXP1:                                   ; [MS 6259]
        jsr INT                         ; [MS 6259]
        lda INTEGR                      ; [MS 6260] GET LOW PART.
        clc                             ; [MS 6261]
        adc #$81                        ; [MS 6262]
        beq GOMLDV                      ; [MS 6263] OVERFLOW OR OVERFLOW !!
        sec                             ; [MS 6264]
        sbc #1                          ; [MS 6265] SUBTRACT 1.
        pha                             ; [MS 6266] SAVE A WHILE.
        ldx #4+ADDPRC                   ; [MS 6267] PREP TO SWAP FAC AND ARG.
SWAPLP:                                 ; [MS 6268]
        lda ARGEXP,x                    ; [MS 6268]
        ldy FACEXP,x                    ; [MS 6269]
        sta FACEXP,x                    ; [MS 6270]
        sty ARGEXP,x                    ; [MS 6271]
        dex                             ; [MS 6272]
        bpl SWAPLP                      ; [MS 6273]
        lda OLDOV                       ; [MS 6274]
        sta FACOV                       ; [MS 6275]
        jsr FSUBT                       ; [MS 6276]
        jsr NEGOP                       ; [MS 6277] NEGATE FAC.
        lda #<EXPCON                    ; [MS 6278 LDWDI]
        ldy #>EXPCON                    ; [MS 6278 LDWDI]
        jsr POLY                        ; [MS 6279]
        lda #0                          ; [MS 6280 CLR]
        sta ARISGN                      ; [MS 6280 CLR] MULTIPLY BY POSITIVE 1.0.
        pla                             ; [MS 6281] GET SCALE FACTOR.
        jsr MLDEXP                      ; [MS 6282] MODIFY FACEXP AND CHECK FOR OVERFLOW.
        rts                             ; [MS 6283] HAS TO DO JSR DUE TO PULAS IN MULDIV.


; [MS 6287] ==== POLYNOMIAL EVALUATOR AND THE RANDOM NUMBER GENERATOR. ====
; [MS 6288] EVALUATE P(X^2)*X
; [MS 6289] POINTER TO DEGREE IS IN [Y,A].
; [MS 6290] THE CONSTANTS FOLLOW THE DEGREE.
; [MS 6291] FOR X=FAC, COMPUTE:
; [MS 6292] C0*X+C1*X^3+C2*X^5+C3*X^7+...+C(N)*X^(2*N+1)
POLYX:                                  ; [MS 6293]
        sta POLYPT                      ; [MS 6293 STWD]
        sty POLYPT+1                    ; [MS 6293 STWD] RETAIN POLYNOMIAL POINTER FOR LATER.
        jsr MOV1F                       ; [MS 6294] SAVE FAC IN FACTMP.
        lda #TEMPF1                     ; [MS 6295]
        jsr FMULT                       ; [MS 6296] COMPUTE X^2.
        jsr POLY1                       ; [MS 6297] COMPUTE P(X^2).
        lda #<TEMPF1                    ; [MS 6298 LDWDI]
        ldy #>TEMPF1                    ; [MS 6298 LDWDI]
        jmp FMULT                       ; [MS 6299] MULTIPLY BY FAC AGAIN.

; [MS 6301] POLYNOMIAL EVALUATOR.
; [MS 6302] POINTER TO DEGREE IS IN [Y,A].
; [MS 6303] COMPUTE:
; [MS 6304] C0+C1*X+C2*X^2+C3*X^3+C4*X^4+...+C(N-1)*X^(N-1)+C(N)*X^N.
POLY:                                   ; [MS 6305]
        sta POLYPT                      ; [MS 6305 STWD]
        sty POLYPT+1                    ; [MS 6305 STWD]
POLY1:                                  ; [MS 6306]
        jsr MOV2F                       ; [MS 6306] SAVE FAC.
        lda (POLYPT),y                  ; [MS 6307]
        sta DEGREE                      ; [MS 6308]
        ldy POLYPT                      ; [MS 6309]
        iny                             ; [MS 6310]
        tya                             ; [MS 6311]
        bne POLY3                       ; [MS 6312]
        inc POLYPT+1                    ; [MS 6313]
POLY3:                                  ; [MS 6314]
        sta POLYPT                      ; [MS 6314]
        ldy POLYPT+1                    ; [MS 6315]
POLY2:                                  ; [MS 6316]
        jsr FMULT                       ; [MS 6316]
        lda POLYPT                      ; [MS 6317 LDWD]
        ldy POLYPT+1                    ; [MS 6317 LDWD] GET CURRENT POINTER.
        clc                             ; [MS 6318]
        adc #4+ADDPRC                   ; [MS 6319]
        bcc POLY4                       ; [MS 6320]
        iny                             ; [MS 6321]
POLY4:                                  ; [MS 6322]
        sta POLYPT                      ; [MS 6322 STWD]
        sty POLYPT+1                    ; [MS 6322 STWD]
        jsr FADD                        ; [MS 6323] ADD IN CONSTANT.
        lda #<TEMPF2                    ; [MS 6324 LDWDI]
        ldy #>TEMPF2                    ; [MS 6324 LDWDI] MULTIPLY THE ORIGINAL FAC.
        dec DEGREE                      ; [MS 6325] DONE?
        bne POLY2                       ; [MS 6326]
RANDRT:                                 ; [MS 6327]
        rts                             ; [MS 6327] YES.

; [MS 6329] PSUEDO-RANDOM NUMBER GENERATOR.
; [MS 6330] IF ARG=0, THE LAST RANDOM NUMBER GENERATED IS RETURNED.
; [MS 6331] IF ARG .LT. 0, A NEW SEQUENCE OF RANDOM NUMBERS IS
; [MS 6332] STARTED USING THE ARGUMENT.
; [MS 6333] TO FORM THE NEXT RANDOM NUMBER IN THE SEQUENCE,
; [MS 6334] MULTIPLY THE PREVIOUS RANDOM NUMBER BY A RANDOM CONSTANT
; [MS 6335] AND ADD IN ANOTHER RANDOM CONSTANT. THE THEN HO
; [MS 6336] AND LO BYTES ARE SWITCHED, THE EXPONENT IS PUT WHERE
; [MS 6337] IT WILL BE SHIFTED IN BY NORMAL, AND THE EXPONENT IN THE FAC
; [MS 6338] IS SET TO 200 SO THE RESULT WILL BE LESS THAN 1. THIS
; [MS 6339] IS THEN NORMALIZED AND SAVED FOR THE NEXT TIME.
; [MS 6340] THE HO AND LOW BYTES WERE SWITCHED SO THERE WILL BE A
; [MS 6341] RANDOM CHANCE OF GETTING A NUMBER LESS THAN OR GREATER
; [MS 6342] THAN .5 .

RMULZC:                                 ; [MS 6344]
        .byte $98                       ; [MS 6344]
        .byte $35                       ; [MS 6345]
        .byte $44                       ; [MS 6346]
        .byte $7A                       ; [MS 6347]
RADDZC:                                 ; [MS 6348]
        .byte $68                       ; [MS 6348]
        .byte $28                       ; [MS 6349]
        .byte $B1                       ; [MS 6350]
        .byte $46                       ; [MS 6351]

RND:                                    ; [MS 6353]
        jsr SIGN                        ; [MS 6353] GET SIGN INTO ACCX.

        tax                             ; [MS 6355] GET INTO ACCX, SINCE "MOVFM" USES ACCX.
        bmi RND1                        ; [MS 6356] START NEW SEQUENCE IF NEGATIVE.

QSETNR:                                 ; [MS 6372]
        lda #<RNDX                      ; [MS 6372 LDWDI]
        ldy #>RNDX                      ; [MS 6372 LDWDI] GET LAST ONE INTO FAC.
        jsr MOVFM                       ; [MS 6373]

        txa                             ; [MS 6375] FAC WAS ZERO?
        beq RANDRT                      ; [MS 6376] RESTORE LAST ONE.
        lda #<RMULZC                    ; [MS 6377 LDWDI]
        ldy #>RMULZC                    ; [MS 6377 LDWDI] MULTIPLY BY RANDOM CONSTANT.
        jsr FMULT                       ; [MS 6378]
        lda #<RADDZC                    ; [MS 6379 LDWDI]
        ldy #>RADDZC                    ; [MS 6379 LDWDI]
        jsr FADD                        ; [MS 6380] ADD RANDOM CONSTANT.
RND1:                                   ; [MS 6381]
        ldx FACLO                       ; [MS 6381]
        lda FACHO                       ; [MS 6382]
        sta FACLO                       ; [MS 6383]
        stx FACHO                       ; [MS 6384] REVERSE HO AND LO.

STRNEX:                                 ; [MS 6390]
        lda #0                          ; [MS 6390 CLR]
        sta FACSGN                      ; [MS 6390 CLR] MAKE NUMBER POSITIVE.
        lda FACEXP                      ; [MS 6391] PUT EXP WHERE IT WILL
        sta FACOV                       ; [MS 6392] BE SHIFTED IN BY NORMAL.
        lda #$80                        ; [MS 6393]
        sta FACEXP                      ; [MS 6394] MAKE RESULT BETWEEN 0 AND 1.
        jsr NORMAL                      ; [MS 6395] NORMALIZE.
        ldx #<RNDX                      ; [MS 6396 LDXYI]
        ldy #>RNDX                      ; [MS 6396 LDXYI]
GMOVMF:                                 ; [MS 6397]
        jmp MOVMF                       ; [MS 6397] PUT NEW ONE INTO MEMORY.

; [MS 6400] ==== SINE, COSINE AND TANGENT FUNCTIONS. ====

; [MS 6402] COSINE FUNCTION.
; [MS 6403] USE COS(X)=SIN(X+PI/2)
COS:                                    ; [MS 6404]
        lda #<PI2                       ; [MS 6404 LDWDI]
        ldy #>PI2                       ; [MS 6404 LDWDI] PNTR TO PI/2.
        jsr FADD                        ; [MS 6405] ADD IT IN.
; [MS 6406] FALL INTO SIN.


; [MS 6409] SINE FUNCTION.
; [MS 6410] USE IDENTITIES TO GET FAC IN QUADRANTS I OR IV.
; [MS 6411] THE FAC IS DIVIDED BY 2*PI AND THE INTEGER PART IS IGNORED
; [MS 6412] BECAUSE SIN(X+2*PI)=SIN(X). THEN THE ARGUMENT CAN BE COMPARED
; [MS 6413] WITH PI/2 BY COMPARING THE RESULT OF THE DIVISION
; [MS 6414] WITH PI/2/(2*PI)=1/4.
; [MS 6415] IDENTITIES ARE THEN USED TO GET THE RESULT IN QUADRANTS
; [MS 6416] I OR IV. AN APPROXIMATION POLYNOMIAL IS THEN USED TO
; [MS 6417] COMPUTE SIN(X).
SIN:                                    ; [MS 6418]
        jsr MOVAF                       ; [MS 6418]
        lda #<TWOPI                     ; [MS 6419 LDWDI]
        ldy #>TWOPI                     ; [MS 6419 LDWDI] GET PNTR TO DIVISOR.
        ldx ARGSGN                      ; [MS 6420] GET SIGN OF RESULT.
        jsr FDIVF                       ; [MS 6421]
        jsr MOVAF                       ; [MS 6422] GET RESULT INTO ARG.
        jsr INT                         ; [MS 6423] INTEGERIZE FAC.
        lda #0                          ; [MS 6424 CLR]
        sta ARISGN                      ; [MS 6424 CLR] ALWAYS HAVE THE SAME SIGN.
        jsr FSUBT                       ; [MS 6425] KEEP ONLY THE FRACTIONAL PART.
        lda #<FR4                       ; [MS 6426 LDWDI]
        ldy #>FR4                       ; [MS 6426 LDWDI] GET PNTR TO 1/4.
        jsr FSUB                        ; [MS 6427] COMPUTE 1/4-FAC.
        lda FACSGN                      ; [MS 6428] SAVE SIGN FOR LATER.
        pha                             ; [MS 6429]
        bpl SIN1                        ; [MS 6430] FIRST QUADRANT.
        jsr FADDH                       ; [MS 6431] ADD 1/2 TO FAC.
        lda FACSGN                      ; [MS 6432] SIGN IS NEGATIVE?
        bmi SIN2                        ; [MS 6433]
        lda TANSGN                      ; [MS 6434 COM]
        eor #$FF                        ; [MS 6434 COM]
        sta TANSGN                      ; [MS 6434 COM] QUADRANTS II AND III COME HERE.
SIN1:                                   ; [MS 6435]
        jsr NEGOP                       ; [MS 6435] IF POSITIVE, NEGATE IT.
SIN2:                                   ; [MS 6436]
        lda #<FR4                       ; [MS 6436 LDWDI]
        ldy #>FR4                       ; [MS 6436 LDWDI] POINTER TO 1/4.
        jsr FADD                        ; [MS 6437] ADD IT IN.
        pla                             ; [MS 6438] GET ORIGINAL QUADRANT.
        bpl SIN3                        ; [MS 6439]
        jsr NEGOP                       ; [MS 6440] IF NEGATIVE, NEGATE RESULT.
SIN3:                                   ; [MS 6441]
        lda #<SINCON                    ; [MS 6441 LDWDI]
        ldy #>SINCON                    ; [MS 6441 LDWDI]
GPOLYX:                                 ; [MS 6442]
        jmp POLYX                       ; [MS 6442] DO APPROXIMATION POLYNOMIAL.


; [MS 6445] TANGENT FUNCTION.
TAN:                                    ; [MS 6446]
        jsr MOV1F                       ; [MS 6446] MOVE FAC INTO TEMPORARY.
        lda #0                          ; [MS 6447 CLR]
        sta TANSGN                      ; [MS 6447 CLR] REMEMBER WHETHER TO NEGATE.
        jsr SIN                         ; [MS 6448] COMPUTE THE SIN.
        ldx #<TEMPF3                    ; [MS 6449 LDXYI]
        ldy #>TEMPF3                    ; [MS 6449 LDXYI]
        jsr GMOVMF                      ; [MS 6450] PUT SIGN INTO OTHER TEMP.
        lda #<TEMPF1                    ; [MS 6451 LDWDI]
        ldy #>TEMPF1                    ; [MS 6451 LDWDI]
        jsr MOVFM                       ; [MS 6452] PUT THIS MEMORY LOC INTO FAC.
        lda #0                          ; [MS 6453 CLR]
        sta FACSGN                      ; [MS 6453 CLR] START OFF POSITIVE.
        lda TANSGN                      ; [MS 6454]
        jsr COSC                        ; [MS 6455] COMPUTE COSINE.
        lda #<TEMPF3                    ; [MS 6456 LDWDI]
        ldy #>TEMPF3                    ; [MS 6456 LDWDI] ADDRESS OF SINE VALUE.
GFDIV:                                  ; [MS 6457]
        jmp FDIV                        ; [MS 6457] DIVIDE SINE BY COSINE AND RETURN.
COSC:                                   ; [MS 6458]
        pha                             ; [MS 6458]
        jmp SIN1                        ; [MS 6459]

PI2:                                    ; [MS 6461]
        .byte $81                       ; [MS 6461] PI/2
        .byte $49                       ; [MS 6462]
        .byte $0F                       ; [MS 6463]
        .byte $DB-ADDPRC                ; [MS 6464]
        .byte $A2                       ; [MS 6465]
TWOPI:                                  ; [MS 6466]
        .byte $83                       ; [MS 6466] 2*PI.
        .byte $49                       ; [MS 6467]
        .byte $0F                       ; [MS 6468]
        .byte $DB-ADDPRC                ; [MS 6469]
        .byte $A2                       ; [MS 6470]
FR4:                                    ; [MS 6471]
        .byte $7F                       ; [MS 6471] 1/4
        .byte 0                         ; [MS 6472]
        .byte 0                         ; [MS 6473]
        .byte 0                         ; [MS 6474]
        .byte 0                         ; [MS 6475]



