; [MS 6541] ==== ARCTANGENT FUNCTION. ====
; [MS 6542] USE IDENTITIES TO GET ARG BETWEEN 0 AND 1 AND THEN USE AN
; [MS 6543] APPROXIMATION POLYNOMIAL TO COMPUTE ARCTAN(X).
ATN:                                    ; [MS 6544]
        lda FACSGN                      ; [MS 6544] WHAT IS SIGN?
        pha                             ; [MS 6545] (MEANWHILE SAVE FOR LATER.)
        bpl ATN1                        ; [MS 6546]
        jsr NEGOP                       ; [MS 6547] IF NEGATIVE, NEGATE FAC.
; [MS 6548] USE ARCTAN(X)=-ARCTAN(-X) .
ATN1:                                   ; [MS 6549]
        lda FACEXP                      ; [MS 6549]
        pha                             ; [MS 6550] SAVE THIS TOO FOR LATER.
        cmp #$81                        ; [MS 6551] SEE IF FAC .GE. 1.0 .
        bcc ATN2                        ; [MS 6552] IT IS LESS THAN 1.
        lda #<FONE                      ; [MS 6553 LDWDI]
        ldy #>FONE                      ; [MS 6553 LDWDI] GET PNTR TO 1.0 .
        jsr FDIV                        ; [MS 6554] COMPUTE RECIPROCAL.
; [MS 6555] USE ARCTAN(X)=PI/2-ARCTAN(1/X) .
ATN2:                                   ; [MS 6556]
        lda #<ATNCON                    ; [MS 6556 LDWDI]
        ldy #>ATNCON                    ; [MS 6556 LDWDI] PNTR TO ARCTAN CONSTANTS.
        jsr POLYX                       ; [MS 6557]
        pla                             ; [MS 6558]
        cmp #$81                        ; [MS 6559] WAS ORIGINAL ARGUMENT .LT. 1 ?
        bcc ATN3                        ; [MS 6560] YES.
        lda #<PI2                       ; [MS 6561 LDWDI]
        ldy #>PI2                       ; [MS 6561 LDWDI]
        jsr FSUB                        ; [MS 6562] SUBTRACT ARCTAGN FROM PI/2.
ATN3:                                   ; [MS 6563]
        pla                             ; [MS 6563] WAS ORIGINAL ARGUMENT POSITIVE?
        bpl ATN4                        ; [MS 6564] YES.
        jmp NEGOP                       ; [MS 6565] IF NEGATIVE, NEGATE RESULT.
ATN4:                                   ; [MS 6566]
        rts                             ; [MS 6566] ALL DONE.




