; [MS 6670] ==== SYSTEM INITIALIZATION CODE. ====
; [MS 6671] RADIX 10: numbers below are decimal in Microsoft's text; IN ALL NON-MATH-PACKAGE CODE.
; [MS 6672] THIS INITIALIZES THE BASIC INTERPRETER FOR THE M6502 AND SHOULD BE
; [MS 6673] LOCATED WHERE IT WILL BE WIPED OUT IN RAM IF CODE IS ALL IN RAM.

; [MS 6676] SO ZEROING AT TXTTAB DOESN'T PREVENT
; [MS 6677] RESTARTING INIT
INITAT:                                 ; [MS 6678]
        inc CHRGET+7                    ; [MS 6678] INCREMENT THE WHOLE TXTPTR.
        bne CHZGOT                      ; [MS 6679]
        inc CHRGET+8                    ; [MS 6680]
CHZGOT:                                 ; [MS 6681]
        lda 60000                       ; [MS 6681] A LOAD WITH AN EXT ADDR.
        cmp #':'                        ; [MS 6682] IS IT A ":"?
        bcs CHZRTS                      ; [MS 6683] IT IS .GE. ":"
        cmp #' '                        ; [MS 6684] SKIP SPACES.
        beq INITAT                      ; [MS 6685]
        sec                             ; [MS 6686]
        sbc #'0'                        ; [MS 6687] ALL CHARS .GT. "9" HAVE RET'D SO
        sec                             ; [MS 6688]
        sbc #256-'0'                    ; [MS 6689] SEE IF NUMERIC.
; [MS 6690] TURN CARRY ON IF NUMERIC.
; [MS 6691] ALSO, SETZ IF NULL.
CHZRTS:                                 ; [MS 6692]
        rts                             ; [MS 6692] RETURN TO CALLER.

        .byte 128                       ; [MS 6694] LOADED OR FROM ROM.
        .byte 79                        ; [MS 6695] THE INITIAL RANDOM NUMBER.
        .byte 199                       ; [MS 6696]
        .byte 82                        ; [MS 6697]
        .byte 88                        ; [MS 6698]


; [MS 6701] [OURS] TYPAUT (the "A" answer to MEMORY SIZE? printed "WRITTEN BY WEILAND & GATES") is gone with the question.
INIT:                                   ; [MS 6703]
        ldx #255                        ; [MS 6705] MAKE IT LOOK DIRECT IN CASE OF
        stx CURLIN+1                    ; [MS 6706] ERROR MESSAGE.
        ldx #507-256                    ; [MS 6708]
        txs                             ; [MS 6709]
        lda #<INIT                      ; [MS 6711 LDWDI]
        ldy #>INIT                      ; [MS 6711 LDWDI] ALLOW RESTART.
        sta START+1                     ; [MS 6712 STWD]
        sty 0+(START+1)+1               ; [MS 6712 STWD]
        sta RDYJSR+1                    ; [MS 6713 STWD]
        sty 0+(RDYJSR+1)+1              ; [MS 6713 STWD] RTS HERE ON ERRORS.
;       lda #<AYINT                     ; [MS 6714 LDWDI] [OURS] not kept: $06-$09 are free in Applesoft
;       ldy #>AYINT                     ; [MS 6714 LDWDI] [OURS] not kept: $06-$09 are free in Applesoft
;       sta ADRAYI                      ; [MS 6715 STWD] [OURS] not kept: $06-$09 are free in Applesoft
;       sty ADRAYI+1                    ; [MS 6715 STWD] [OURS] not kept: $06-$09 are free in Applesoft
;       lda #<GIVAYF                    ; [MS 6716 LDWDI] [OURS] not kept: $06-$09 are free in Applesoft
;       ldy #>GIVAYF                    ; [MS 6716 LDWDI] [OURS] not kept: $06-$09 are free in Applesoft
;       sta ADRGAY                      ; [MS 6717 STWD] [OURS] not kept: $06-$09 are free in Applesoft
;       sty ADRGAY+1                    ; [MS 6717 STWD] [OURS] not kept: $06-$09 are free in Applesoft
        lda #76                         ; [MS 6718] JMP INSTRUCTION.
; [MS 6719] MAKE AN INST.

        sta START                       ; [MS 6721]
        sta RDYJSR                      ; [MS 6722]
        sta JMPER                       ; [MS 6723]

        sta USRPOK                      ; [MS 6725]
        lda #<FCERR                     ; [MS 6726 LDWDI]
        ldy #>FCERR                     ; [MS 6726 LDWDI]
        sta USRPOK+1                    ; [MS 6727 STWD]
        sty 0+(USRPOK+1)+1              ; [MS 6727 STWD]
;       lda #40                         ; [MS 6728] THESE MUST BE NON-ZERO SO CHEAD WILL [OURS] not kept: no LINWID/NCMWID
;       sta LINWID                      ; [MS 6729] WORK AFTER MOVING A NEW LINE IN BUF [OURS] not kept: no LINWID/NCMWID
; [MS 6730] INTO THE PROGRAM
;       lda #NCMPOS                     ; [MS 6731] [OURS] not kept: no LINWID/NCMWID
;       sta NCMWID                      ; [MS 6732] [OURS] not kept: no LINWID/NCMWID
        ldx #<(RNDX+4-CHRGET)           ; [MS 6733]
MOVCHG:                                 ; [MS 6734]
        lda INITAT-1,x                  ; [MS 6734]
        sta CHRGET-1,x                  ; [MS 6735] MOVE TO RAM.
        dex                             ; [MS 6736]
        bne MOVCHG                      ; [MS 6737]
        lda #STRSIZ                     ; [MS 6738]
        sta FOUR6                       ; [MS 6739]
        txa                             ; [MS 6740] SET CONST IN RAM.
        sta BITS                        ; [MS 6741]

        sta LASTPT+1                    ; [MS 6744]

        pha                             ; [MS 6747] PUT ZERO AT THE END OF THE STACK
; [MS 6748] SO FNDFOR WILL STOP

        sta CNTWFL                      ; [MS 6750] BE TALKATIVE.

        inx                             ; [MS 6752] MAKE [X]=1
        stx BUF-3                       ; [MS 6753] SET PRE-BUF BYTES NON-ZERO FOR CHEAD
        stx BUF-4                       ; [MS 6754]

;       jsr CRDO                        ; [MS 6756] TYPE A CR. [OURS] not kept: no CR at start
        ldx #TEMPST                     ; [MS 6757]
        stx TEMPPT                      ; [MS 6758] SET UP STRING TEMPORARIES.
; [OURS] [RM] Applesoft asks nothing at start and finds the top of RAM itself (Applesoft II
; manual, Appendix L: $73-$74 "set to the highest RAM memory location available"). Microsoft's
; MEMORY SIZE? and TERMINAL WIDTH? questions, its memory test (which overwrote every byte from
; $0801 up, a loader's code included) and its banner are gone. This test leaves memory as it was:
; it complements the first byte of each page, checks it, and puts it back.
        lda #0                          ; [OURS]
        sta LINNUM                      ; [OURS]
        tay                             ; [OURS] Y = 0 throughout
        lda #>RAMLOC                    ; [OURS] from the program's own page up
        sta LINNUM+1                    ; [OURS]
MEMPG:                                  ; [OURS]
        lda (LINNUM),y                  ; [OURS]
        eor #$FF                        ; [OURS]
        sta (LINNUM),y                  ; [OURS]
        cmp (LINNUM),y                  ; [OURS] did this page keep it?
        php                             ; [OURS]
        eor #$FF                        ; [OURS]
        sta (LINNUM),y                  ; [OURS] put the byte back
        plp                             ; [OURS]
        bne MEMTOP                      ; [OURS] no RAM here: the top is this page
        inc LINNUM+1                    ; [OURS]
        lda LINNUM+1                    ; [OURS]
        cmp #$C0                        ; [OURS] the I/O page: RAM ends here on a ][ Plus
        bne MEMPG                       ; [OURS]
MEMTOP:                                 ; [OURS]
        lda LINNUM                      ; [MS 6814 LDWD]
        ldy LINNUM+1                    ; [MS 6814 LDWD] GET SIZE OF MEMORY INPUT.
        sta MEMSIZ                      ; [MS 6818 STWD]
        sty MEMSIZ+1                    ; [MS 6818 STWD] THIS IS THE SIZE OF MEMORY.
        sta FRETOP                      ; [MS 6819 STWD]
        sty FRETOP+1                    ; [MS 6819 STWD] TOP OF STRINGS TOO.
        ldx #<2048                      ; [MS 6874 LDXYI]
        ldy #>2048                      ; [MS 6874 LDXYI]
        stx TXTTAB                      ; [MS 6875 STXY]
        sty TXTTAB+1                    ; [MS 6875 STXY]
        ldy #0                          ; [MS 6876]
        tya                             ; [MS 6877]
        sta (TXTTAB),y                  ; [MS 6878] SET UP TEXT TABLE.
        inc TXTTAB                      ; [MS 6879]

        bne QROOM                       ; [MS 6881]
        inc TXTTAB+1                    ; [MS 6882]
QROOM:                                  ; [MS 6883]
        lda TXTTAB                      ; [MS 6883 LDWD]
        ldy TXTTAB+1                    ; [MS 6883 LDWD] PREPARE TO USE "REASON".
        jsr REASON                      ; [MS 6884]
        jsr SCRTCH                      ; [MS 6899] SET UP EVERYTHING ELSE.
        lda #<STROUT                    ; [MS 6903 LDWDI]
        ldy #>STROUT                    ; [MS 6903 LDWDI]
        sta RDYJSR+1                    ; [MS 6904 STWD]
        sty 0+(RDYJSR+1)+1              ; [MS 6904 STWD]
        lda #<READY                     ; [MS 6905 LDWDI]
        ldy #>READY                     ; [MS 6905 LDWDI]
        sta START+1                     ; [MS 6906 STWD]
        sty 0+(START+1)+1               ; [MS 6906 STWD]
        lda #<$E003                     ; [OURS] [RM] the Autostart soft entry vector: RESET returns here,
        sta $3F2                        ; [OURS] to BASIC with the program kept; normally $E003, with the
        lda #>$E003                     ; [OURS] power-up byte the vector's high byte EOR $A5 (Apple II
        sta $3F3                        ; [OURS] Reference Manual 1979, Autostart ROM special locations)
        eor #$A5                        ; [OURS]
        sta $3F4                        ; [OURS]
        jmp (START+1)                   ; [MS 6907]

; [OURS] Applesoft statements and functions not written yet: one $02 each (the missing-routine log names them).
TR_DEL:                                 ; [OURS] $85 DEL
        .byte $02                       ; [OURS]
TR_GR:                                  ; [OURS] $88 GR
        .byte $02                       ; [OURS]
TR_PRNUM:                               ; [OURS] $8A PR#
        .byte $02                       ; [OURS]
TR_INNUM:                               ; [OURS] $8B IN#
        .byte $02                       ; [OURS]
TR_PLOT:                                ; [OURS] $8D PLOT
        .byte $02                       ; [OURS]
TR_HLIN:                                ; [OURS] $8E HLIN
        .byte $02                       ; [OURS]
TR_VLIN:                                ; [OURS] $8F VLIN
        .byte $02                       ; [OURS]
TR_HGR2:                                ; [OURS] $90 HGR2
        .byte $02                       ; [OURS]
TR_HGR:                                 ; [OURS] $91 HGR
        .byte $02                       ; [OURS]
TR_HCOLOR:                              ; [OURS] $92 HCOLOR=
        .byte $02                       ; [OURS]
TR_HPLOT:                               ; [OURS] $93 HPLOT
        .byte $02                       ; [OURS]
TR_DRAW:                                ; [OURS] $94 DRAW
        .byte $02                       ; [OURS]
TR_XDRAW:                               ; [OURS] $95 XDRAW
        .byte $02                       ; [OURS]
TR_ROT:                                 ; [OURS] $98 ROT=
        .byte $02                       ; [OURS]
TR_SCALE:                               ; [OURS] $99 SCALE=
        .byte $02                       ; [OURS]
TR_SHLOAD:                              ; [OURS] $9A SHLOAD
        .byte $02                       ; [OURS]
TR_TRACE:                               ; [OURS] $9B TRACE
        .byte $02                       ; [OURS]
TR_NOTRACE:                             ; [OURS] $9C NOTRACE
        .byte $02                       ; [OURS]
TR_COLOR:                               ; [OURS] $A0 COLOR=
        .byte $02                       ; [OURS]
TR_POP:                                 ; [OURS] $A1 POP
        .byte $02                       ; [OURS]
TR_RECALL:                              ; [OURS] $A7 RECALL
        .byte $02                       ; [OURS]
TR_STORE:                               ; [OURS] $A8 STORE
        .byte $02                       ; [OURS]
TR_SPEED:                               ; [OURS] $A9 SPEED=
        .byte $02                       ; [OURS]
TR_SCRN:                                ; [OURS] $D7 SCRN(
        .byte $02                       ; [OURS]
TR_PDL:                                 ; [OURS] [RM] $D8 PDL(aexpr): paddle aexpr's dial, 0-255 (Applesoft II manual, PDL); Applesoft's own is the same three calls
        jsr CONINT                      ; [OURS] X = the argument; over 255 or negative is ?ILLEGAL QUANTITY
        jsr PREAD                       ; [OURS] Y = the count
        jmp SNGFLT                      ; [OURS] Y as the function's value
CALL:                                   ; [OURS] [RM] CALL aexpr: a JSR to the address; -936 and 64600 are the same (Applesoft II manual, CALL)
        jsr FRMNUM                      ; [OURS]
        jsr GETADR                      ; [OURS] LINNUM = the address, negatives counted from 65536
        jmp (LINNUM)                    ; [OURS] its RTS goes back to NEWSTT, like a statement's
AMPER:                                  ; [OURS] [RM] & jumps to $3F5, the next character in A (Applesoft II manual, &)
        jmp $03F5                       ; [OURS]
; [MS 4080-4110] Microsoft's UMULT (array subscripts), moved here so GIVAYF, ERRDIR and STRLIT keep Applesoft's addresses
UMULT:                                  ; [MS 4080]
        sty INDEX                       ; [MS 4080]
        lda (LOWTR),y                   ; [MS 4081]
        sta ADDEND                      ; [MS 4082] LOW, THEN HIGH.
        dey                             ; [MS 4083]
        lda (LOWTR),y                   ; [MS 4084] PUT [LOWTR,Y,Y+1] IN FASTER MEMORY.
UMULTD:                                 ; [MS 4085]
        sta ADDEND+1                    ; [MS 4085]
        lda #16                         ; [MS 4086]
        sta DECCNT                      ; [MS 4087]
        ldx #0                          ; [MS 4088] CLR THE ACCS.
        ldy #0                          ; [MS 4089] RESULT INITIALLY ZERO.
UMULTC:                                 ; [MS 4090]
        txa                             ; [MS 4090]
        asl a                           ; [MS 4091] MULTIPLY BY TWO.
        tax                             ; [MS 4092]
        tya                             ; [MS 4093]
        rol a                           ; [MS 4094]
        tay                             ; [MS 4095]
        bcs UMOM                        ; [MS 4096] TWO MUCH !
        asl CURTOL                      ; [MS 4097]
        rol CURTOL+1                    ; [MS 4098]
        bcc UMLCNT                      ; [MS 4099] NOTHING IN THIS POSITION TO MULTIPLY.
        clc                             ; [MS 4100]
        txa                             ; [MS 4101]
        adc ADDEND                      ; [MS 4102]
        tax                             ; [MS 4103]
        tya                             ; [MS 4104]
        adc ADDEND+1                    ; [MS 4105]
        tay                             ; [MS 4106]
        bcs UMOM                        ; [MS 4107] MAN, JUST TOO MUCH !
UMLCNT:                                 ; [MS 4108]
        dec DECCNT                      ; [MS 4108] DONE?
        bne UMULTC                      ; [MS 4109] KEEP IT UP.
UMLRTS:                                 ; [MS 4110]
        rts                             ; [MS 4110] YES, ALL DONE.
UMOM:                                   ; [OURS] OMERR1 is out of branch range from here
        jmp OMERR                       ; [OURS]
; [MS 3612-3618] Microsoft's DIM, moved here so GIVAYF, ERRDIR and STRLIT keep Applesoft's addresses
DIM3:                                   ; [MS 3612]
        jsr CHKCOM                      ; [MS 3612] MUST BE A COMMA
DIM:                                    ; [MS 3613]
        tax                             ; [MS 3613] SET [ACCX] NONZERO.
; [MS 3614] [ACCA] MUST BE NONZERO TO WORK RIGHT.
DIM1:                                   ; [MS 3615]
        jsr PTRGT1                      ; [MS 3615]
DIMCON:                                 ; [MS 3616]
        jsr CHRGOT                      ; [MS 3616] GET LAST CHARACTER.
        bne DIM3                        ; [MS 3617]
        rts                             ; [MS 3618]
; [OURS] NOT, OR and AND (logical, as Applesoft's), moved here for the same reason
NOTOP:                                  ; [MS 3358] [OURS] [RM] NOT is logical in Applesoft: 1 if the value is 0, else 0 (Microsoft complemented the bits)
        lda FACEXP                      ; [OURS] a number is 0 exactly when its exponent is
        beq LOGONE                      ; [OURS]
        lda #0                          ; [OURS]
        jmp FLOAT                       ; [OURS]
LOGONE:                                 ; [OURS]
        lda #1                          ; [OURS]
        jmp FLOAT                       ; [OURS]
OROP:                                   ; [MS 3518] [OURS] [RM] AND and OR are logical in Applesoft: 1 or 0 (Microsoft worked bit by bit on integers)
        lda FACEXP                      ; [OURS] either one not 0
        ora ARGEXP                      ; [OURS]
        jmp LOGRES                      ; [OURS]
ANDOP:                                  ; [MS 3520]
        lda FACEXP                      ; [OURS] both not 0
        beq LOGRES                      ; [OURS]
        lda ARGEXP                      ; [OURS]
LOGRES:                                 ; [OURS]
        beq LOGFLT                      ; [OURS] 0: false
        lda #1                          ; [OURS] true
LOGFLT:                                 ; [OURS]
        jmp FLOAT                       ; [OURS]
FLASHB = $F3                            ; [OURS] [RM] FLASH's mask, $40 while flashing ($F0-$F3 "general use flags", Applesoft II manual Appendix L)
OUTFL:                                  ; [OURS] [RM] FLASH: a printing character also gets $40 so digits and signs flash
        cmp #$A0                        ; [OURS] too (the Monitor's mask alone leaves $A0-$BF inverse); controls as they are
        bcc OUTFL1                      ; [OURS]
        ora FLASHB                      ; [OURS]
OUTFL1:                                 ; [OURS]
        jmp OUTCH                       ; [OURS]
ST_NORMAL:                                 ; [OURS] [RM] NORMAL, INVERSE, FLASH: the output mode (Applesoft II manual); the Monitor's INVFLG $32
        ldx #$FF                        ; [OURS] $FF normal, $3F inverse, $7F flashing
        ldy #$00                        ; [OURS]
        beq SETIVF                      ; [OURS] always
ST_INVERSE:                                 ; [OURS]
        ldx #$3F                        ; [OURS]
        ldy #$00                        ; [OURS]
        beq SETIVF                      ; [OURS] always
ST_FLASH:                                  ; [OURS]
        ldx #$7F                        ; [OURS]
        ldy #$40                        ; [OURS]
SETIVF:                                 ; [OURS]
        stx $32                         ; [OURS] INVFLG
        sty FLASHB                      ; [OURS]
        rts                             ; [OURS]
ST_HOME:                                   ; [OURS] [RM] HOME: clear the text window, cursor to its top left (Applesoft II manual): the Monitor's HOME
        jmp $FC58                       ; [OURS]
ST_TEXT:                                   ; [OURS] [RM] TEXT: full-screen text, cursor to the last line (Applesoft II manual): the Monitor's
        jmp $FB39                       ; [OURS] SETTXT does exactly that
ST_VTAB:                                   ; [OURS] [RM] VTAB 1-24: the cursor to that screen line, ignoring the window;
        jsr GETBYT                      ; [OURS] other values ?ILLEGAL QUANTITY (Applesoft II manual, VTAB)
        dex                             ; [OURS]
        cpx #24                         ; [OURS]
        bcs VTABIQ                      ; [OURS]
        stx $25                         ; [OURS] CV
        jmp $FC22                       ; [OURS] the Monitor's VTAB: the line's base address
VTABIQ:                                 ; [OURS]
        jmp FCERR                       ; [OURS]
ST_HTAB:                                   ; [OURS] [RM] HTAB n: position n of the current line counting from 1; 41-80 are on the
        jsr GETBYT                      ; [OURS] next line down, and so on; HTAB 0 is position 256 (Applesoft II manual, HTAB)
        dex                             ; [OURS] column n-1 (0 gives 255)
        txa                             ; [OURS]
HTABL:                                  ; [OURS]
        cmp #40                         ; [OURS]
        bcc HTAB1                       ; [OURS]
        sbc #40                         ; [OURS] carry is set
        pha                             ; [OURS]
        inc $25                         ; [OURS] CV: a line down
        jsr $FC22                       ; [OURS]
        pla                             ; [OURS]
        jmp HTABL                       ; [OURS]
HTAB1:                                  ; [OURS]
        sta $24                         ; [OURS] CH
        rts                             ; [OURS]
ERROR:                                  ; [OURS] [RM] every error comes here (X = the code): ONERR GOTO first, then Microsoft's ERROR
        bit ERRFLG                      ; [OURS] [RM] ONERR GOTO on, and a program running?
        bpl ERRGO                       ; [OURS]
        ldy CURLIN+1                    ; [OURS]
        iny                             ; [OURS] $FF: direct mode, so the message as usual
        beq ERRGO                       ; [OURS]
        jmp HANDLERR                    ; [OURS]
ERRGO:                                  ; [OURS]
        jmp ERRNRM                      ; [OURS]

DOAGIN:                                 ; [MS 2874]
        bit ERRFLG                      ; [OURS] [RM] under ONERR GOTO a bad INPUT response is error 254,
        bpl DOAGN1                      ; [OURS] not the ?REENTER message (Applesoft II manual, ONERR GOTO)
        ldx #254                        ; [OURS]
        jmp ERROR                       ; [OURS]
DOAGN1:                                 ; [OURS]
        lda #<TRYAGN                    ; [MS 2874 LDWDI]
        ldy #>TRYAGN                    ; [MS 2874 LDWDI]
        jsr STROUT                      ; [MS 2875] PRINT "?REDO FROM START".
        lda OLDTXT                      ; [MS 2876 LDWD]
        ldy OLDTXT+1                    ; [MS 2876 LDWD] POINT AT START
        sta TXTPTR                      ; [MS 2877 STWD]
        sty TXTPTR+1                    ; [MS 2877 STWD] OF THIS CURRENT LINE.
        rts                             ; [MS 2878] GO TO "NEWSTT".
ONERR:                                  ; [OURS] [RM] ONERR GOTO linenum: from now on an error jumps to linenum
        lda #$80                        ; [OURS] instead of a message (Applesoft II manual 1981 (A2L0006), ONERR GOTO, RESUME and Appendix J; the 1978 edition says the same)
        sta ERRFLG                      ; [OURS]
        lda TXTPTR                      ; [OURS] TXTPTR is on the GOTO
        sta TXTPSV                      ; [OURS]
        lda TXTPTR+1                    ; [OURS]
        sta TXTPSV+1                    ; [OURS]
        lda CURLIN                      ; [OURS]
        sta CURLSV                      ; [OURS]
        lda CURLIN+1                    ; [OURS]
        sta CURLSV+1                    ; [OURS]
        tsx                             ; [OURS]
        stx REMSTK                      ; [OURS]
        jmp DATA                        ; [OURS] the GOTO itself is not run now: skip to the end of the statement
HANDLERR:                               ; [OURS] [RM] an error under ONERR GOTO: record it, then run the ONERR's GOTO
        stx ERRNUM                      ; [OURS] the code (PEEK(222))
        lda CURLIN                      ; [OURS]
        sta ERRLIN                      ; [OURS] the line (PEEK(218)+256*PEEK(219))
        lda CURLIN+1                    ; [OURS]
        sta ERRLIN+1                    ; [OURS]
        lda OLDTXT                      ; [OURS] where the failing statement starts (NEWSTT keeps it in OLDTXT)
        sta ERRPOS                      ; [OURS]
        lda OLDTXT+1                    ; [OURS]
        sta ERRPOS+1                    ; [OURS]
        tsx                             ; [OURS] find the failing statement's stack level: just above GONE3's return
HNDSCN:                                 ; [OURS]
        inx                             ; [OURS]
        beq HNDNO                       ; [OURS] not found: the message after all
        lda $0100,x                     ; [OURS]
        cmp #<(GONERT-1)                ; [OURS]
        bne HNDSCN                      ; [OURS]
        lda $0101,x                     ; [OURS]
        cmp #>(GONERT-1)                ; [OURS]
        bne HNDSCN                      ; [OURS]
        inx                             ; [OURS] X = the stack pointer before GONE3 was called
        stx ERRSTK                      ; [OURS] $DF, as the manual's fix routine expects
        txs                             ; [OURS] what the error left on the stack is dropped; GOSUB and FOR stay
        sec                             ; [OURS] TXTPTR one before the GOTO, so GONE's CHRGET reads it
        lda TXTPSV                      ; [OURS]
        sbc #1                          ; [OURS]
        sta TXTPTR                      ; [OURS]
        lda TXTPSV+1                    ; [OURS]
        sbc #0                          ; [OURS]
        sta TXTPTR+1                    ; [OURS]
        lda CURLSV                      ; [OURS]
        sta CURLIN                      ; [OURS] the ONERR statement's line, for the GOTO
        lda CURLSV+1                    ; [OURS]
        sta CURLIN+1                    ; [OURS]
        jmp GONE                        ; [OURS] run "GOTO linenum" as a statement
HNDNO:                                  ; [OURS]
        ldx ERRNUM                      ; [OURS]
        jmp ERRNRM                      ; [OURS]
RESUME:                                 ; [OURS] [RM] RESUME: run again the statement where the error happened (Applesoft II manual 1981 (A2L0006), ONERR GOTO, RESUME and Appendix J; the 1978 edition says the same)
        lda ERRPOS                      ; [OURS]
        sta TXTPTR                      ; [OURS]
        lda ERRPOS+1                    ; [OURS]
        sta TXTPTR+1                    ; [OURS]
        lda ERRLIN                      ; [OURS]
        sta CURLIN                      ; [OURS]
        lda ERRLIN+1                    ; [OURS]
        sta CURLIN+1                    ; [OURS]
        ldx ERRSTK                      ; [OURS] that statement's stack level
        txs                             ; [OURS]
        jmp NEWSTT                      ; [OURS]
; [MS 4444-4484] Microsoft's DVARS / DVAR (garbage collection), moved here from before CAT
DVARS:                                  ; [MS 4444]

        lda (INDEX1),y                  ; [MS 4446]
        bmi DVARTS                      ; [MS 4447]
        iny                             ; [MS 4448]
        lda (INDEX1),y                  ; [MS 4449]
        bpl DVARTS                      ; [MS 4450]
        iny                             ; [MS 4451]
DVAR:                                   ; [MS 4452]
        lda (INDEX1),y                  ; [MS 4452] IS LENGTH=0?
        beq DVARTS                      ; [MS 4453] YES, RETURN.
        iny                             ; [MS 4454]
        lda (INDEX1),y                  ; [MS 4455] GET LOW(ADR).
        tax                             ; [MS 4456]
        iny                             ; [MS 4457]
        lda (INDEX1),y                  ; [MS 4458]
        cmp FRETOP+1                    ; [MS 4459] COMPARE HIGHS.
        bcc DVAR2                       ; [MS 4460] IF THIS STRING'S PNTR .GE. [FRETOP]
        bne DVARTS                      ; [MS 4461] NO NEED TO MESS WITH IT FURTHER.
        cpx FRETOP                      ; [MS 4462] COMPARE LOWS.
        bcs DVARTS                      ; [MS 4463]
DVAR2:                                  ; [MS 4464]
        cmp GRBTOP+1                    ; [MS 4464]
        bcc DVARTS                      ; [MS 4465] IF THIS STRING IS BELOW PREVIOUS,
; [MS 4466] FORGET IT.
        bne DVAR3                       ; [MS 4467]
        cpx GRBTOP                      ; [MS 4468] COMPARE LOW ORDERS.
        bcc DVARTS                      ; [MS 4469] [X,A] .LE. [GRBTOP].
DVAR3:                                  ; [MS 4470]
        stx GRBTOP                      ; [MS 4470]
        sta GRBTOP+1                    ; [MS 4471]
        lda INDEX1                      ; [MS 4472 LDWX]
        ldx INDEX1+1                    ; [MS 4472 LDWX]
        sta GRBPNT                      ; [MS 4473 STWX]
        stx GRBPNT+1                    ; [MS 4473 STWX]
        lda FOUR6                       ; [MS 4474]
        sta SIZE                        ; [MS 4475]
DVARTS:                                 ; [MS 4476]
        lda FOUR6                       ; [MS 4476]
        clc                             ; [MS 4477]
        adc INDEX1                      ; [MS 4478]
        sta INDEX1                      ; [MS 4479]
        bcc GRBRTS                      ; [MS 4480]
        inc INDEX1+1                    ; [MS 4481]
GRBRTS:                                 ; [MS 4482]
        ldx INDEX1+1                    ; [MS 4482]
        ldy #0                          ; [MS 4483]
        rts                             ; [MS 4484] DONE.
FOUTSP:                                 ; [OURS] [RM] Applesoft prints numbers with no space in front (Applesoft II manual: PRINT 1;2 gives 12).
        ldy #>FBUFFR                    ; [OURS] Microsoft's FOUT puts a space there for a positive number,
        lda FBUFFR                      ; [OURS] so hand back the string after it
        cmp #' '                        ; [OURS]
        bne FOUTS1                      ; [OURS] a "-" or a digit: keep it
        lda #<(FBUFFR+1)                ; [OURS]
        rts                             ; [OURS]
FOUTS1:                                 ; [OURS]
        lda #<FBUFFR                    ; [MS 6007 LDWDI]
        rts                             ; [OURS]
HIMEM:                                  ; [OURS] [RM] HIMEM: aexpr: the top of memory for BASIC, strings included. ?OUT OF MEMORY
        jsr FRMNUM                      ; [OURS] if it is below what is in use (Applesoft II manual, HIMEM:)
        jsr GETADR                      ; [OURS] LINNUM = the address
        lda LINNUM                      ; [OURS]
        cmp STREND                      ; [OURS]
        lda LINNUM+1                    ; [OURS]
        sbc STREND+1                    ; [OURS]
        bcs HIMEM1                      ; [OURS]
        jmp OMERR                       ; [OURS]
HIMEM1:                                 ; [OURS]
        lda LINNUM                      ; [OURS]
        ldy LINNUM+1                    ; [OURS]
        sta MEMSIZ                      ; [OURS] $73-$74
        sty MEMSIZ+1                    ; [OURS]
        sta FRETOP                      ; [OURS] strings start below it
        sty FRETOP+1                    ; [OURS]
        rts                             ; [OURS]
LOMEM:                                  ; [OURS] [RM] LOMEM: aexpr: where variables start ($69-$6A); variables are cleared.
        jsr FRMNUM                      ; [OURS] ?OUT OF MEMORY at or above HIMEM:, or below the end of the
        jsr GETADR                      ; [OURS] program (Applesoft II manual, LOMEM:)
        lda LINNUM                      ; [OURS]
        cmp MEMSIZ                      ; [OURS]
        lda LINNUM+1                    ; [OURS]
        sbc MEMSIZ+1                    ; [OURS]
        bcs LOMEMX                      ; [OURS]
        lda LINNUM                      ; [OURS]
        cmp PRGEND                      ; [OURS]
        lda LINNUM+1                    ; [OURS]
        sbc PRGEND+1                    ; [OURS]
        bcc LOMEMX                      ; [OURS]
        lda LINNUM                      ; [OURS]
        ldy LINNUM+1                    ; [OURS]
        sta VARTAB                      ; [OURS]
        sty VARTAB+1                    ; [OURS]
        jmp CLEARC                      ; [OURS] variables, arrays and strings start afresh
LOMEMX:                                 ; [OURS]
        jmp OMERR                       ; [OURS]
BASWRM:                                 ; [OURS] [RM] warm start: back to BASIC with the program and variables kept
        jsr STKINI                      ; [OURS] (RESET, or Ctrl-C in the Monitor; Apple II Reference Manual 1979): a fresh
        lda #$FF                        ; [OURS] stack and string temporaries, CONT not allowed, direct mode
        sta CURLIN+1                    ; [OURS]
        jmp READY                       ; [OURS]



;UTTXT:                                 ; [MS 6913] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 13                        ; [MS 6913 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6913 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
;       .byte 12                        ; [MS 6914] ANOTHER LINE FEED. [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte "WRITTEN "                ; [MS 6915] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte "BY WEILAND & GATES"      ; [MS 6916] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 13                        ; [MS 6917 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6917 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
;       .byte 0                         ; [MS 6918] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;EMORY:                                 ; [MS 6919] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte "MEMORY SIZE"             ; [MS 6919] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 0                         ; [MS 6920] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;TYWID:                                 ; [MS 6921] [OURS] not used (Microsoft's start-up texts and its temporary stack)

;       .byte "TERMINAL "               ; [MS 6923] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte "WIDTH"                   ; [MS 6924] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 0                         ; [MS 6925] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;ORDS:                                  ; [MS 6926] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte " BYTES FREE"             ; [MS 6926] [OURS] not used (Microsoft's start-up texts and its temporary stack)

;       .byte 13                        ; [MS 6928 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6928 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
;       .byte 13                        ; [MS 6929 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6929 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line





;       .byte "APPLE BASIC V1.1"        ; [MS 6940] [OURS] not used (Microsoft's start-up texts and its temporary stack)


;       .byte 13                        ; [MS 6943 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6943 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
;       .byte "COPYRIGHT 1978 MICROSOFT" ; [MS 6944] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 13                        ; [MS 6945 ACRLF] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .byte 10                        ; [MS 6945 ACRLF] [OURS] no LF: an Apple screen takes CR as a whole new line
;       .byte 0                         ; [MS 6946] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;ASTWR:                                 ; [MS 6947] [OURS] not used (Microsoft's start-up texts and its temporary stack)
;       .res 100                        ; [MS 6948] SPACE FOR TEMP STACK. [OURS] not used (Microsoft's start-up texts and its temporary stack)

; [OURS] Microsoft's CRUNCH (with B2's keyword search), moved here from before FNDLIN; MAIN calls it.
; [OURS] It ends with its own RTS; LISTRT (LIST's RTS) stayed behind.
CRUNCH:                                 ; [MS 1785]
        ldx TXTPTR                      ; [MS 1785] SET SOURCE POINTER.
        ldy #4                          ; [MS 1786] SET DESTINATION OFFSET.
        sty DORES                       ; [MS 1787] ALLOW CRUNCHING.
; [MS 1788-1825] [OURS] Microsoft's keyword search indexed RESLST with Y, which holds 256 bytes; Applesoft's
; 107 keywords are longer than that. Rewritten with a pointer, and with Applesoft's rules (Applesoft II manual):
; spaces are dropped except in strings, REM and DATA; spaces inside a keyword are skipped ("T O" is TO);
; AT is not taken when the next character is N (ATN) or O (A TO): "FOR I=BETA TO 56" works.
KLOOP:                                  ; [MS 1788]
        lda 512,x                       ; [MS 1788]
        cmp #' '                        ; [OURS]
        bne KLOOPC                      ; [OURS]
        bit DORES                       ; [OURS] in DATA: keep the space (SLOT# on Apple's 1983 disk stores "DATA 32,...")
        bvc KLDROP                      ; [OURS]
        jmp STUFFH                      ; [OURS] (out of branch range now)
KLDROP:                                 ; [OURS]
        inx                             ; [OURS] otherwise drop it
        bne KLOOP                       ; [OURS] always
KLOOPC:                                 ; [OURS]
        sta ENDCHR                      ; [MS 1797] IF IT'S A QUOTE, THIS WILL
        cmp #34                         ; [MS 1799] QUOTE SIGN?
        bne KLNSTR                      ; [MS 1800] [OURS] as a jump: out of branch range now
        jmp STRNG                       ; [MS 1800] YES, DO SPECIAL STRING HANDLING.
KLNSTR:                                 ; [OURS]
        bit DORES                       ; [MS 1801] TEST FLAG.
        bvs STUFFH                      ; [MS 1802] NO CRUNCH, JUST STORE.
        cmp #'?'                        ; [MS 1803] A QMARK?
        bne KLOOP1                      ; [MS 1804]
        lda #PRINTK                     ; [MS 1805] YES, STUFF A "PRINT" TOKEN.
        bne STUFFH                      ; [MS 1806] ALWAYS GO TO STUFFH.
KLOOP1:                                 ; [MS 1807]
        cmp #'0'                        ; [MS 1807] SKIP NUMERICS.
        bcc MUSTCR                      ; [MS 1808]
        cmp #60                         ; [MS 1809] ":" AND ";" ARE ENTERED STRAIGHTAWAY.
        bcc STUFFH                      ; [MS 1810]
MUSTCR:                                 ; [MS 1811]
        sty BUFPTR                      ; [MS 1811] SAVE BUFFER POINTER.
        stx TXTPTR                      ; [MS 1815] the word starts here
        lda #<RESLST                    ; [OURS]
        sta INDEX                       ; [OURS]
        lda #>RESLST                    ; [OURS]
        sta INDEX+1                     ; [OURS]
        lda #0                          ; [OURS]
        sta COUNT                       ; [MS 1813] the keyword's number
KWTRY:                                  ; [OURS]
        ldx TXTPTR                      ; [OURS] back to the word's first character
        ldy #0                          ; [OURS]
KWCMP:                                  ; [OURS]
        lda 512,x                       ; [OURS]
        cmp #' '                        ; [OURS] a space inside the word: skip it
        bne KWCHR                       ; [OURS]
        inx                             ; [OURS]
        bne KWCMP                       ; [OURS] always
KWCHR:                                  ; [OURS]
        sec                             ; [MS 1820] PREPARE TO SUBSTARCT.
        sbc (INDEX),y                   ; [MS 1821] CHARACTERS EQUAL?
        beq KWNEXT                      ; [MS 1822] YES, CONTINUE SEARCH.
        cmp #128                        ; [MS 1823] NO BUT MAYBE THE END IS HERE (the last letter has bit 7).
        bne KWMISS                      ; [MS 1824] NO, TRULY UNEQUAL.
        lda COUNT                       ; [OURS] a whole keyword: AT?
        cmp #ATTK-$80                   ; [OURS]
        bne KWGOT                       ; [OURS]
        lda 513,x                       ; [OURS] the character right after AT, spaces not skipped
        cmp #'N'                        ; [OURS] ATN
        beq KWMISS                      ; [OURS]
        cmp #'O'                        ; [OURS] A TO
        beq KWMISS                      ; [OURS]
KWGOT:                                  ; [OURS]
        lda COUNT                       ; [OURS]
        ora #$80                        ; [MS 1825] the token
        bne GETBPT                      ; [OURS] always; X is on the keyword's last letter
KWNEXT:                                 ; [OURS]
        inx                             ; [OURS]
        iny                             ; [OURS]
        bne KWCMP                       ; [OURS] always
KWMISS:                                 ; [OURS] skip to the end of this keyword
        lda (INDEX),y                   ; [OURS]
        bmi KWEND                       ; [OURS]
        iny                             ; [OURS]
        bne KWMISS                      ; [OURS] always
KWEND:                                  ; [OURS]
        iny                             ; [OURS] Y = the keyword's length
        tya                             ; [OURS]
        clc                             ; [OURS]
        adc INDEX                       ; [OURS]
        sta INDEX                       ; [OURS]
        bcc KWEND1                      ; [OURS]
        inc INDEX+1                     ; [OURS]
KWEND1:                                 ; [OURS]
        inc COUNT                       ; [MS 1851] INCREMENT RES WORD COUNT.
        ldy #0                          ; [OURS]
        lda (INDEX),y                   ; [MS 1855] IS IT THE END?
        bne KWTRY                       ; [MS 1856] NO, TRY THE NEXT WORD.
        ldx TXTPTR                      ; [MS 1850] no keyword here: store the character itself
        lda 512,x                       ; [MS 1857]
GETBPT:                                 ; [MS 1826]
        ldy BUFPTR                      ; [MS 1826] GET BUFFER PNTR.
STUFFH:                                 ; [MS 1827]
        inx                             ; [MS 1827]
        iny                             ; [MS 1828]
        sta BUF-5,y                     ; [MS 1829]
        lda BUF-5,y                     ; [MS 1830]
        beq CRDONE                      ; [MS 1831] NULL IMPLIES END OF LINE.
        sec                             ; [MS 1832] PREPARE TO SUBSTARCT.
        sbc #':'                        ; [MS 1833] IS IT A ":"?
        beq COLIS                       ; [MS 1834] YES, ALLOW CRUNCHING AGAIN.
        cmp #DATATK-':'                 ; [MS 1835] IS IT A DATATK?
        bne NODATT                      ; [MS 1836] NO, SEE IF IT IS REM TOKEN.
COLIS:                                  ; [MS 1837]
        sta DORES                       ; [MS 1837] SETUP FLAG.
NODATT:                                 ; [MS 1838]
        sec                             ; [MS 1838] PREP TO SBCQ
        sbc #REMTK-':'                  ; [MS 1839] REM ONLY STOPS ON NULL.
        beq NODATR                      ; [MS 1840] [OURS] as a jump: out of branch range now
        jmp KLOOP                       ; [MS 1840] NO, CONTINUE CRUNCHING.
NODATR:                                 ; [OURS]
        sta ENDCHR                      ; [MS 1841] REM STOPS ONLY ON NULL, NOT : OR ".
STR1:                                   ; [MS 1842]
        lda 512,x                       ; [MS 1842]
        beq STUFFH                      ; [MS 1843] YES, END OF LINE, SO DONE.
        cmp ENDCHR                      ; [MS 1844] END OF GOBBLE?
        beq STUFFH                      ; [MS 1845] YES, DONE WITH STRING.
STRNG:                                  ; [MS 1846]
        iny                             ; [MS 1846] INCREMENT BUFFER POINTER.
        sta BUF-5,y                     ; [MS 1847]
        inx                             ; [MS 1848]
        bne STR1                        ; [MS 1849] PROCESS NEXT CHARACTER.
;THIS:                                  ; [MS 1850] [OURS] unused: the search above replaces it
;       ldx TXTPTR                      ; [MS 1850] RESTORE TEXT POINTER. [OURS] unused: the search above replaces it
;       inc COUNT                       ; [MS 1851] INCREMENT RES WORD COUNT. [OURS] unused: the search above replaces it
;THIS1:                                 ; [MS 1852] [OURS] unused: the search above replaces it
;       iny                             ; [MS 1852] [OURS] unused: the search above replaces it
;       lda RESLST-1,y                  ; [MS 1853] GET RES CHARACTER. [OURS] unused: the search above replaces it
;       bpl NTHIS1                      ; [MS 1854] END OF ENTRY? [OURS] unused: the search above replaces it
;       lda RESLST,y                    ; [MS 1855] YES. IS IT THE END? [OURS] unused: the search above replaces it
;       bne RESCON                      ; [MS 1856] NO, TRY THE NEXT WORD. [OURS] unused: the search above replaces it
;       lda 512,x                       ; [MS 1857] YES, END OF TABLE. GET 1ST CHR. [OURS] unused: the search above replaces it
;       bpl GETBPT                      ; [MS 1858] STORE IT AWAY (ALWAYS BRANCHES). [OURS] unused: the search above replaces it
CRDONE:                                 ; [MS 1859]
        sta BUF-3,y                     ; [MS 1859] SO THAT IF THIS IS A DIR STATEMENT
; [MS 1860] ITS END WILL LOOK LIKE END OF PROGRAM.

        dec TXTPTR+1                    ; [MS 1862]
        lda #<((BUF&255)-1)             ; [MS 1863] MAKE TXTPTR POINT TO
        sta TXTPTR                      ; [MS 1864] CRUNCHED LINE.
        rts                             ; [OURS] CRUNCH's return (was LISTRT's)

; ==== [OURS] hi-res graphics: HGR, HGR2, HCOLOR=, HPLOT ====
; [OURS] [RM] Behaviour from the Applesoft II manual 1981 (HGR, HGR2, HCOLOR, HPLOT); the screen from the Apple II
; Reference Manual 1979 (High-Resolution Graphics: 40 bytes a line, bit 0 leftmost, 7 dots a byte, the eighth bit
; picks the byte's color group; a lit dot in an even column is violet (blue with the eighth bit), odd green (red)).
; Zero page as Appendix L gives it: $E0-$E1 x, $E2 y, $E4 the color byte, $E6 the page drawn on ($20 or $40,
; the high byte of $2000/$4000), $D0-$D5 scratch; $1C (which Appendix L leaves undescribed) holds the line color.
HGRX    = $E0                           ; [OURS] [RM] x of the last dot plotted (2 bytes)
HGRY    = $E2                           ; [OURS] [RM] y of the last dot plotted
HCOLR   = $E4                           ; [OURS] [RM] HCOLOR's color byte
HPAG    = $E6                           ; [OURS] the page HPLOT draws on (Oregon Trail's library sets and reads it too)
HLCOL   = $1C                           ; [OURS] the line color: the color of the last dot plotted (the manual, HPLOT TO)
HBASL   = $26                           ; [OURS] address of the hi-res line being drawn
HBASH   = $27                           ; [OURS]
LMAJ    = $D0                           ; [OURS] a line: steps along its longer axis (at most 255)
LMIN    = $D1                           ; [OURS] steps along its shorter axis
LERR    = $D2                           ; [OURS] the shorter axis's running remainder
LCNT    = $D3                           ; [OURS] steps still to go
LDIR    = $D4                           ; [OURS] bit 7 x goes left, bit 6 y goes up, bit 0 y is the longer axis
LTMP    = $D5                           ; [OURS]

ST_HGR:                                 ; [OURS] [RM] HGR: page 1 ($2000) cleared to black, mixed graphics and text
        lda #$20                        ; [OURS]
        ldx #$54                        ; [OURS] PAGE1 ($C054)
        ldy #$53                        ; [OURS] MIXED ($C053)
        bne HGRGO                       ; [OURS] (always)
ST_HGR2:                                ; [OURS] [RM] HGR2: page 2 ($4000) cleared to black, full-screen graphics
        lda #$40                        ; [OURS]
        ldx #$55                        ; [OURS] PAGE2 ($C055)
        ldy #$52                        ; [OURS] full screen ($C052)
HGRGO:                                  ; [OURS]
        sta HPAG                        ; [OURS] HCOLOR is not changed (the manual)
        sta HBASH                       ; [OURS]
        lda $C000,x                     ; [OURS] the soft switches
        lda $C000,y                     ; [OURS]
        lda #0                          ; [OURS]
        sta HBASL                       ; [OURS]
        tay                             ; [OURS]
        ldx #$20                        ; [OURS] 32 pages of 256 bytes
HGRCLR:                                 ; [OURS]
        sta (HBASL),y                   ; [OURS]
        iny                             ; [OURS]
        bne HGRCLR                      ; [OURS]
        inc HBASH                       ; [OURS]
        dex                             ; [OURS]
        bne HGRCLR                      ; [OURS]
        lda $C057                       ; [OURS] HIRES
        lda $C050                       ; [OURS] graphics on, once the page is clear
        rts                             ; [OURS]

ST_HCOLOR:                              ; [OURS] [RM] HCOLOR= 0-7, else ?ILLEGAL QUANTITY (the manual, HCOLOR)
        jsr GETBYT                      ; [OURS] X = the value
        cpx #8                          ; [OURS]
        bcs HPLIQ                       ; [OURS]
        lda HCTAB,x                     ; [OURS]
        sta HCOLR                       ; [OURS]
        rts                             ; [OURS]
HCTAB:                                  ; [OURS] [RM] 0 black1, 1 green, 2 violet, 3 white1, 4 black2, 5 red, 6 blue, 7 white2
        .byte $00,$2A,$55,$7F,$80,$AA,$D5,$FF   ; [OURS] [RM] as they fall in an even byte (bit 0 = an even column)
HPLIQ:                                  ; [OURS]
        jmp FCERR                       ; [OURS]

ST_HPLOT:                               ; [OURS] [RM] HPLOT x,y [TO x,y ...] / HPLOT TO x,y (the manual, HPLOT)
        cmp #TOTK                       ; [OURS] HPLOT TO: a line on from the last dot plotted
        beq HPLTO                       ; [OURS]
        jsr HFNS                        ; [OURS] X = x low, Y = x high, A = y (checked)
        stx HGRX                        ; [OURS]
        sty HGRX+1                      ; [OURS]
        sta HGRY                        ; [OURS]
        lda HCOLR                       ; [OURS] this dot's color is the line color from now on, even if
        sta HLCOL                       ; [OURS] HCOLOR changes before a later HPLOT TO (the manual)
        jsr HDOT                        ; [OURS]
HPLNXT:                                 ; [OURS]
        jsr CHRGOT                      ; [OURS]
        cmp #TOTK                       ; [OURS]
        bne HPLRTS                      ; [OURS]
HPLTO:                                  ; [OURS]
        jsr CHRGET                      ; [OURS] past TO
        jsr HFNS                        ; [OURS]
        jsr HLINE                       ; [OURS] ends with the last dot at x,y
        jmp HPLNXT                      ; [OURS]
HPLRTS:                                 ; [OURS]
        rts                             ; [OURS]

HLINE:                                  ; [OURS] a line from (HGRX,HGRY) to X/Y = x, A = y, in HLCOL
        pha                             ; [OURS] keep the far end
        tya                             ; [OURS]
        pha                             ; [OURS]
        txa                             ; [OURS]
        pha                             ; [OURS]
        sec                             ; [OURS] does x move by more than 255? then go by the midpoint
        sbc HGRX                        ; [OURS]
        sta LTMP                        ; [OURS]
        tya                             ; [OURS]
        sbc HGRX+1                      ; [OURS]
        beq HLFITS                      ; [OURS] 0 to 255 right
        cmp #$FF                        ; [OURS]
        bne HLMID                       ; [OURS]
        lda LTMP                        ; [OURS]
        bne HLFITS                      ; [OURS] 1 to 255 left
HLMID:                                  ; [OURS]
        tsx                             ; [OURS]
        clc                             ; [OURS] midpoint x = (x0 + x1) / 2
        lda $0101,x                     ; [OURS]
        adc HGRX                        ; [OURS]
        sta LTMP                        ; [OURS]
        lda $0102,x                     ; [OURS]
        adc HGRX+1                      ; [OURS]
        lsr a                           ; [OURS]
        ror LTMP                        ; [OURS]
        tay                             ; [OURS]
        clc                             ; [OURS] midpoint y = (y0 + y1) / 2
        lda $0103,x                     ; [OURS]
        adc HGRY                        ; [OURS]
        ror a                           ; [OURS]
        ldx LTMP                        ; [OURS]
        jsr HLINE8                      ; [OURS]
HLFITS:                                 ; [OURS]
        pla                             ; [OURS]
        tax                             ; [OURS]
        pla                             ; [OURS]
        tay                             ; [OURS]
        pla                             ; [OURS]
HLINE8:                                 ; [OURS] the same, x moving by at most 255
        sta LMIN                        ; [OURS] (the far y, for a moment)
        txa                             ; [OURS]
        sec                             ; [OURS]
        sbc HGRX                        ; [OURS]
        sta LMAJ                        ; [OURS]
        tya                             ; [OURS]
        sbc HGRX+1                      ; [OURS]
        and #$80                        ; [OURS] bit 7: x goes left
        sta LDIR                        ; [OURS]
        beq HL8XP                       ; [OURS]
        lda #0                          ; [OURS]
        sec                             ; [OURS]
        sbc LMAJ                        ; [OURS]
        sta LMAJ                        ; [OURS] |dx|
HL8XP:                                  ; [OURS]
        lda LMIN                        ; [OURS]
        sec                             ; [OURS]
        sbc HGRY                        ; [OURS]
        bcs HL8YP                       ; [OURS]
        eor #$FF                        ; [OURS] |dy| (carry is clear: the ADC adds the 1)
        adc #1                          ; [OURS]
        tax                             ; [OURS]
        lda LDIR                        ; [OURS]
        ora #$40                        ; [OURS] bit 6: y goes up
        sta LDIR                        ; [OURS]
        txa                             ; [OURS]
HL8YP:                                  ; [OURS]
        sta LMIN                        ; [OURS]
        cmp LMAJ                        ; [OURS]
        bcc HL8X                        ; [OURS] x is the longer axis
        ldx LMAJ                        ; [OURS] y is: swap
        sta LMAJ                        ; [OURS]
        stx LMIN                        ; [OURS]
        inc LDIR                        ; [OURS] bit 0
HL8X:                                   ; [OURS]
        lda LMAJ                        ; [OURS]
        sta LCNT                        ; [OURS]
        lsr a                           ; [OURS]
        sta LERR                        ; [OURS] start half way, so the steps fall evenly
        jsr HDOT                        ; [OURS] the first dot
HL8LP:                                  ; [OURS]
        lda LCNT                        ; [OURS]
        beq HSTRTS                      ; [OURS] (an RTS)
        dec LCNT                        ; [OURS]
        lda LERR                        ; [OURS]
        clc                             ; [OURS]
        adc LMIN                        ; [OURS]
        bcs HL8MN                       ; [OURS] past 255: past LMAJ too
        cmp LMAJ                        ; [OURS]
        bcc HL8NM                       ; [OURS]
HL8MN:                                  ; [OURS]
        sbc LMAJ                        ; [OURS] (carry is set)
        sta LERR                        ; [OURS]
        lda LDIR                        ; [OURS] a step along the shorter axis
        eor #$01                        ; [OURS]
        jsr HSTEP                       ; [OURS]
        jmp HL8MJ                       ; [OURS]
HL8NM:                                  ; [OURS]
        sta LERR                        ; [OURS]
HL8MJ:                                  ; [OURS]
        lda LDIR                        ; [OURS] a step along the longer axis
        jsr HSTEP                       ; [OURS]
        jsr HDOT                        ; [OURS]
        jmp HL8LP                       ; [OURS]

HSTEP:                                  ; [OURS] one step: A bit 0 set = along y, else along x (LDIR says which way)
        lsr a                           ; [OURS]
        bcs HSTY                        ; [OURS]
        bit LDIR                        ; [OURS]
        bmi HSTXL                       ; [OURS]
        inc HGRX                        ; [OURS]
        bne HSTRTS                      ; [OURS]
        inc HGRX+1                      ; [OURS]
HSTRTS:                                 ; [OURS]
        rts                             ; [OURS]
HSTXL:                                  ; [OURS]
        lda HGRX                        ; [OURS]
        bne HSTXL1                      ; [OURS]
        dec HGRX+1                      ; [OURS]
HSTXL1:                                 ; [OURS]
        dec HGRX                        ; [OURS]
        rts                             ; [OURS]
HSTY:                                   ; [OURS]
        bit LDIR                        ; [OURS]
        bvs HSTYU                       ; [OURS]
        inc HGRY                        ; [OURS]
        rts                             ; [OURS]
HSTYU:                                  ; [OURS]
        dec HGRY                        ; [OURS]
        rts                             ; [OURS]

HDOT:                                   ; [OURS] plot the dot at (HGRX,HGRY) in HLCOL on page HPAG
        lda HGRY                        ; [OURS]
        jsr HBASE                       ; [OURS]
        lda HGRX                        ; [OURS] byte = x / 7, dot = x mod 7, a bit at a time
        ldx HGRX+1                      ; [OURS]
        bne HDOTH                       ; [OURS] x >= 256 is >= 224
        cmp #224                        ; [OURS]
        bcc HDOTL                       ; [OURS]
HDOTH:                                  ; [OURS]
        sec                             ; [OURS]
        sbc #224                        ; [OURS] 32 bytes of 7 dots
        sec                             ; [OURS]
HDOTL:                                  ; [OURS]
        rol LTMP                        ; [OURS]
        ldx #4                          ; [OURS]
HDOTLP:                                 ; [OURS]
        cmp HDIV7,x                     ; [OURS]
        bcc HDOTN                       ; [OURS]
        sbc HDIV7,x                     ; [OURS]
HDOTN:                                  ; [OURS]
        rol LTMP                        ; [OURS]
        dex                             ; [OURS]
        bpl HDOTLP                      ; [OURS]
        tax                             ; [OURS] X = the dot, 0-6
        lda LTMP                        ; [OURS]
        and #$3F                        ; [OURS]
        tay                             ; [OURS] Y = the byte, 0-39
        lsr a                           ; [OURS] carry: an odd byte
        lda HLCOL                       ; [OURS]
        bcc HDOTE                       ; [OURS]
        pha                             ; [OURS] [RM] in an odd byte the columns swap parity: a two-color
        and #$7F                        ; [OURS] pattern ($2A/$55) turns over; black and white stay
        beq HDOTO                       ; [OURS]
        cmp #$7F                        ; [OURS]
        beq HDOTO                       ; [OURS]
        pla                             ; [OURS]
        eor #$7F                        ; [OURS]
        bne HDOTE                       ; [OURS] (never zero)
HDOTO:                                  ; [OURS]
        pla                             ; [OURS]
HDOTE:                                  ; [OURS]
        eor (HBASL),y                   ; [OURS] the dot's bit and the eighth bit take the color's;
        and HMASK,x                     ; [OURS] [RM] the eighth bit picks the whole byte's color group
        eor (HBASL),y                   ; [OURS]
        sta (HBASL),y                   ; [OURS]
        rts                             ; [OURS]
HDIV7:                                  ; [OURS]
        .byte 7,14,28,56,112            ; [OURS]
HMASK:                                  ; [OURS]
        .byte $81,$82,$84,$88,$90,$A0,$C0   ; [OURS]

HBASE:                                  ; [OURS] [RM] HBASL/HBASH = line A (0-191) of page HPAG: lines 8 apart are
        pha                             ; [OURS] $80 apart, 64 apart are 40 apart, next to each other $400 apart
        and #$C0                        ; [OURS]
        sta HBASL                       ; [OURS]
        lsr a                           ; [OURS]
        lsr a                           ; [OURS]
        ora HBASL                       ; [OURS]
        lsr a                           ; [OURS]
        sta HBASL                       ; [OURS] (y / 64) * 40
        pla                             ; [OURS]
        pha                             ; [OURS]
        and #$08                        ; [OURS]
        asl a                           ; [OURS]
        asl a                           ; [OURS]
        asl a                           ; [OURS]
        asl a                           ; [OURS]
        ora HBASL                       ; [OURS]
        sta HBASL                       ; [OURS] + ((y / 8) and 1) * $80
        pla                             ; [OURS]
        pha                             ; [OURS]
        and #$07                        ; [OURS]
        asl a                           ; [OURS]
        asl a                           ; [OURS]
        sta HBASH                       ; [OURS] (y and 7) * $400
        pla                             ; [OURS]
        lsr a                           ; [OURS]
        lsr a                           ; [OURS]
        lsr a                           ; [OURS]
        lsr a                           ; [OURS]
        and #$03                        ; [OURS]
        ora HBASH                       ; [OURS] + ((y / 16) and 3) * $100
        ora HPAG                        ; [OURS]
        sta HBASH                       ; [OURS]
        rts                             ; [OURS]

; [OURS] Applesoft's hi-res entry points, each on its own address (programs' & routines call them).
        ALIGN $F6B9
HFNS:                                   ; [OURS] [RM] $F6B9 HFNS: read "x,y" (x 0-279, y 0-191, else ?ILLEGAL QUANTITY) and return
        jsr FRMNUM                      ; [OURS] X = x low, Y = x high, A = y, as HPOSN takes them (Oregon Trail's & routine
        jsr GETADR                      ; [OURS] stores X, Y and A straight after its JSR $F6B9)
        ldx LINNUM                      ; [OURS]
        ldy LINNUM+1                    ; [OURS]
        beq HFNS1                       ; [OURS] x < 256
        cpy #1                          ; [OURS]
        bne HFNSIQ                      ; [OURS]
        cpx #280-256                    ; [OURS]
        bcs HFNSIQ                      ; [OURS]
HFNS1:                                  ; [OURS]
        txa                             ; [OURS] keep x on the stack while y is read
        pha                             ; [OURS]
        tya                             ; [OURS]
        pha                             ; [OURS]
        jsr CHKCOM                      ; [OURS]
        jsr GETBYT                      ; [OURS] X = y
        cpx #192                        ; [OURS]
        bcs HFNSIQ                      ; [OURS]
        stx LINNUM                      ; [OURS]
        pla                             ; [OURS]
        tay                             ; [OURS] Y = x high
        pla                             ; [OURS]
        tax                             ; [OURS] X = x low
        lda LINNUM                      ; [OURS] A = y
        rts                             ; [OURS]
HFNSIQ:                                 ; [OURS]
        jmp FCERR                       ; [OURS] (the error resets the stack)




; [OURS] Microsoft's cassette SAVE and LOAD (reached only through the statement table) moved here
; from between CONT and RUN, to make room there for Applesoft's entry points ($DA7B and others).
; [MS 2322] RELINK THE PROGRAM

SAVE:                                   ; [MS 2324]
        sec                             ; [MS 2324] CALCLUATE PROGRAM SIZE IN POKER
        lda VARTAB                      ; [MS 2325]
        sbc TXTTAB                      ; [MS 2326]
        sta POKER                       ; [MS 2327]
        lda VARTAB+1                    ; [MS 2328]
        sbc TXTTAB+1                    ; [MS 2329]
        sta POKER+1                     ; [MS 2330]
        jsr VARTIO                      ; [MS 2331]
        jsr CQCOUT                      ; [MS 2332] WRITE PROGRAM SIZE [POKER]
        jsr PROGIO                      ; [MS 2333]
        jmp CQCOUT                      ; [MS 2334] WRITE PROGRAM.

LOAD:                                   ; [MS 2336]
        jsr VARTIO                      ; [MS 2336]
        jsr CQCSIN                      ; [MS 2337] READ SIZE OF PROGRAM INTO POKER
        clc                             ; [MS 2338]
        lda TXTTAB                      ; [MS 2339] CALCULATE VARTAB FROM SIZE AND
        adc POKER                       ; [MS 2340] TXTTAB
        sta VARTAB                      ; [MS 2341]
        sta PRGEND                        ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        lda TXTTAB+1                    ; [MS 2342]
        adc POKER+1                     ; [MS 2343]
        sta VARTAB+1                    ; [MS 2344]
        sta PRGEND+1                      ; [OURS] [RM] PRGEND follows the end of the program (Applesoft II manual, Appendix L $AF-$B0)
        jsr PROGIO                      ; [MS 2345]
        jsr CQCSIN                      ; [MS 2346] READ PROGRAM.
        lda #<TPDONE                    ; [MS 2347 LDWDI]
        ldy #>TPDONE                    ; [MS 2347 LDWDI]
        jsr STROUT                      ; [MS 2348]
        jmp FINI                        ; [MS 2349]

TPDONE:                                 ; [MS 2351]
        .byte "LOADED"                  ; [MS 2351]
        .byte 0                         ; [MS 2352]

VARTIO:                                 ; [MS 2354]
        lda #<POKER                     ; [MS 2354 LDWDI]
        ldy #>POKER                     ; [MS 2354 LDWDI]
        sta $3C                         ; [MS 2355 STWD]
        sty $3C+1                       ; [MS 2355 STWD]
        lda #<(POKER+2)                 ; [MS 2356]
        sta $3E                         ; [MS 2357 STWD]
        sty $3E+1                       ; [MS 2357 STWD]
        rts                             ; [MS 2358]
PROGIO:                                 ; [MS 2359]
        lda TXTTAB                      ; [MS 2359 LDWD]
        ldy TXTTAB+1                    ; [MS 2359 LDWD]
        sta $3C                         ; [MS 2360 STWD]
        sty $3C+1                       ; [MS 2360 STWD]
        lda VARTAB                      ; [MS 2361 LDWD]
        ldy VARTAB+1                    ; [MS 2361 LDWD]
        sta $3E                         ; [MS 2362 STWD]
        sty $3E+1                       ; [MS 2362 STWD]
        rts                             ; [MS 2363]

; [MS 6955] END $Z+START (end of Microsoft's source)

; [OURS] Applesoft addresses that the alignments above give us (programs call them)
        .assert FNDLIN = $D61A .and RUNC = $D665 .and CLEAR = $D66A .and CLEARC = $D66C .and STKINI = $D683, error, "FNDLIN-STKINI"
        .assert FOR = $D766 .and NEWSTT = $D7D2 .and NEWSTC = $D7D8 .and GOTO = $D93E .and GOTOLN = $D941, error, "FOR-GOTO"
